// Ideeënbibliotheek van Groteknut (182 ideeën).
// Eén idee per regel. Controleer wijzigingen met: node tools/validate.mjs
export default [
  {"id":"verf-in-een-zakje","title":"Verven zonder knoeien: verf in een zakje","emoji":"👆","category":"verven","summary":"Klodders verf in een dichtgeplakt zakje: je kind duwt, wrijft en tekent met een vinger, zonder één vlek op tafel.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel","muur"],"materials":[{"id":"zip-zakjes","note":"een stevig diepvrieszakje, ongeveer 20 x 25 cm"},{"id":"plakkaatverf","note":"2-3 kleuren, een paar flinke klodders"},{"id":"schilderstape","note":"om de rits dicht te plakken en het zakje vast te zetten"}],"optional":[{"id":"wattenstaafjes","note":"om lijnen mee te tekenen"},{"id":"papier","note":"een wit vel onder het zakje, dan zie je de kleuren beter"}],"steps":["Doe 3-4 flinke klodders verf in een diepvrieszakje, het liefst in twee of drie kleuren een stukje uit elkaar.","Druk de lucht er voorzichtig uit, sluit de rits en plak hem extra dicht met een strook schilderstape.","Plak het zakje aan alle kanten vast op tafel, op het blad van de kinderstoel of op het raam, op ooghoogte van je kind.","Laat je kind duwen, wrijven en kloppen: met de hele hand, met één vinger of met een wattenstaafje.","Teken samen lijnen, rondjes of een gezichtje en strijk alles weer glad: het zakje is een tekenbord dat je steeds opnieuw kunt gebruiken.","Controleer na afloop of het zakje nog heel is. Een heel zakje kan plat in de la en gaat zo nog een paar keer mee."],"ageTips":{"young":"Gebruik voor je dreumes twee zakjes in elkaar en plak ze rondom stevig vast, zodat ze niet in de mond kunnen. Benoem wat er gebeurt: duwen, plat, geel!","old":"Een driejarige kan met een wattenstaafje vormen tekenen: een rondje, een streep, de eerste letter van de eigen naam. Of mengen: wat wordt geel en blauw samen?"},"safety":["Een plastic zakje hoort niet in de mond of over het hoofd: blijf erbij en ruim het na afloop meteen op.","Controleer het zakje op lekjes en plak ook scherpe hoekjes af. Lekt het toch, dan vlekt de verf: kies afwasbare kinderverf."],"say":["Duw! Nog een keer!","Waar gaat de verf heen als je hier drukt?","Ik zie geel en blauw elkaar raken… welke kleur komt daar?","Hoe voelt het: zacht, koud, glibberig?","Je blijft maar duwen en wrijven, wat werk je goed door!"],"words":["duwen","glad","zacht","glibberig","mengen","streep","rondje"],"learn":["zintuigen","fijne-motoriek","ontdekken"],"tips":["Hang het zakje op het raam: het licht schijnt door de kleuren en je kind oefent staand met grote armbewegingen.","Geen plakkaatverf? Kook een beetje vingerverf (zie Recepten) en doe die met een paar druppels kleurstof in het zakje."],"extenders":["Teken met een watervaste stift een rondje of een kronkelweg op het zakje (dat doe jij): kan je kind de verf naar het rondje duwen of de weg volgen?","Geef iets nieuws om mee te duwen en te rollen, zoals een speelgoedautootje, een houten lepel of een blokje.","Speel ‘doe wat ik zeg’: duw het geel naar boven, maak een streep, veeg alles weg! Daarna geeft je kind jou een opdracht."],"variations":["Zoekzakje: leg een foto of plaatje onder het zakje en duw de verf weg om te ontdekken wat eronder zit.","Kleuren mengen: doe rood en geel in één zakje en kijk samen hoe er oranje ontstaat.","Herfst: kies bruin, rood en geel en leg een echt blad onder het zakje."],"themes":[],"canStay":false,"pinQuery":"verf in zakje baby"},
  {"id":"vingerverven","title":"Vingerverven op een groot vel","emoji":"🖐️","category":"verven","summary":"Smeren, kletsen en tekenen met je handen in zachte vingerverf op een groot vel: heerlijk voelen en ontdekken, voor elke leeftijd.","ageMin":1,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":15,"duration":[10,25],"supervision":2,"soloFrom":4,"cleanupMinutes":15,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"vingerverf","note":"zelfgemaakt (zie Recepten) of gekocht, 2-3 kleuren"},{"id":"groot-papier","note":"een flink vel, of een paar A4’tjes aan elkaar"},{"id":"schilderstape","note":"om het papier vast te plakken"},{"id":"oud-shirt","note":"of alleen een luier of onderbroekje aan"},{"id":"kom","note":"met lauw water en een doekje, om handen te wassen"}],"optional":[{"id":"oud-laken","note":"als knoeimat onder het papier"},{"id":"bakjes","note":"een per kleur"},{"id":"kleurstof","note":"om zelfgemaakte verf te kleuren"}],"steps":["Maak de vingerverf (zie Recepten): verwarm 60 g maizena, 500 ml koud water en 2 el suiker al roerend tot het dik is als pudding. Dat doe jij.","Laat de pap helemaal afkoelen, verdeel hem over 3 bakjes en roer er per bakje een paar druppels kleurstof door.","Plak een groot vel papier met schilderstape vast op tafel of vloer, met een knoeimat eronder.","Trek je kind een oud shirt aan en schep met een lepel een paar klodders verf op het papier.","Laat je kind smeren, kletsen, krassen en stempelen met vingers, handen en armen. Doe gerust mee!","Was de handen in de kom met lauw water en laat het vel een paar uur plat drogen."],"ageTips":{"young":"Je dreumes stopt vingers in de mond: kies dan zelfgemaakte verf zonder afwasmiddel en zet je kind in de kinderstoel met een vel op het blad. Begin met één kleur.","old":"Een kleuter kan met één vinger tekenen: een zon, een huis, de eigen naam. Of kras met een vork of ijsstokje lijnen in de verf en maak een patroon."},"safety":["Het koken doe jij, en de pap blijft lang heet: voel zelf of de verf helemaal is afgekoeld voor je kind erin mag.","Laat bij kinderen die alles in hun mond stoppen het druppeltje afwasmiddel uit het recept weg. Gekochte vingerverf is niet om te eten.","Verf en kleurstof vlekken op kleding, tafel en voegen, en klodders op de vloer zijn glad: werk op een knoeimat en veeg gemorste verf meteen op."],"say":["Klets! Nog een keer!","Hoe voelt de verf: koud, glibberig of plakkerig?","Ik zie dat je met je hele hand een grote cirkel maakt.","Wat gebeurt er als rood en geel elkaar tegenkomen?","Wat durf jij goed te voelen, met je hele hand erin!"],"words":["smeren","glibberig","klets","plakkerig","rondje","mengen","vingertop"],"learn":["zintuigen","creativiteit","fijne-motoriek"],"tips":["Verf vlak voor badtijd, in alleen een luier of onderbroekje: dan gaat iedereen daarna meteen in bad.","Zelfgemaakte vingerverf blijft een paar dagen goed in een afgesloten bakje in de koelkast.","Geen groot papier? Verf op een dienblad of tafelzeil en druk er na afloop een vel papier op: zo heb je toch een afdruk."],"extenders":["Druk een schoon vel papier op het natte schilderij, wrijf erover en trek het los: een afdruk! Daarna kan het smeren opnieuw beginnen.","Doe een nieuwe klodder in een andere kleur, bijvoorbeeld wit of geel, en ontdek samen wat er gebeurt als je die erdoor smeert.","Geef een oude kam, een afwasborstel of een sponsje om strepen, golven en stippen in de verf te maken."],"variations":["Kleuren mengen: begin met alleen geel en blauw en ontdek samen waar het groen wordt.","Geurverf: roer een snufje kaneel door de bruine verf en wat citroenrasp door de gele. Wat ruik je?","Herfst: verf in bruin, oranje en geel en knip na het drogen bladeren uit het vel."],"themes":[],"canStay":false,"pinQuery":"vingerverven peuter groot papier"},
  {"id":"yoghurtverf","title":"Eetbare yoghurtverf voor dreumesen","emoji":"🥣","category":"verven","summary":"Verven met gekleurde yoghurt op het blad van de kinderstoel: je dreumes mag smeren, kletsen én likken, want het is gewoon eten.","ageMin":1,"ageMax":2,"mess":3,"wet":false,"dirty":true,"prepMinutes":5,"duration":[10,15],"supervision":2,"soloFrom":2,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"yoghurt","note":"volle of Griekse yoghurt, ongeveer 3 el per kleur"},{"id":"kleurstof","note":"een druppel per bakje, of natuurlijke kleur van fruit"},{"id":"bakjes","note":"2-3 kleine bakjes"},{"id":"dienblad","note":"of het blad van de kinderstoel"}],"optional":[{"id":"fruit","note":"blauwe bessen of aardbeien om door de yoghurt te prakken"},{"id":"penselen","note":"een dikke, schone kwast"},{"id":"bakpapier","note":"om op het blad te leggen"},{"id":"oud-shirt","note":"of alleen een luier aan"}],"steps":["Verdeel de yoghurt over 2 of 3 bakjes, ongeveer 3 el per bakje.","Kleur elk bakje met één druppel kleurstof, of prak er wat blauwe bessen, aardbeien of een scheutje bietensap door.","Zet je dreumes in de kinderstoel met alleen een luier of een oud shirt aan, of zet een dienblad voor je kind neer.","Schep een paar klodders op het blad en laat je kind smeren, kletsen, tekenen en proeven.","Teken zelf mee met één vinger: een rondje, een streep, een lachend gezichtje.","Veeg het blad schoon met een nat doekje en ga meteen in bad: plan het vlak voor badtijd."],"ageTips":{"young":"Een eenjarige wil vooral voelen en proeven. Geef één kleur tegelijk, een klein beetje is genoeg, en benoem wat je ziet: wit, en nu roze!","old":"Een tweejarige kan met een kwast of vingertop strepen en stippen zetten, kleuren mengen of op een vel bakpapier een eigen schilderij maken."},"safety":["Yoghurt bevat melk: kies bij een melkallergie een plantaardige yoghurt of dikke appelmoes.","Kleurstof, bietensap en bessen vlekken op kleding, kinderstoel en voegen: één druppel per bakje is genoeg.","Gooi restjes na afloop weg: yoghurt die buiten de koelkast stond en waar handjes in zaten, is niet meer goed om te eten."],"say":["Smeer! Nog meer!","Hoe voelt het: koud en glad?","Mmm, proef je de aardbei?","Kijk, jouw hand maakt een roze streep.","Wat zit jij lekker te ontdekken!"],"words":["koud","glad","smeren","roze","proeven","lekker","vinger"],"learn":["zintuigen","taal","ontdekken"],"tips":["Leg een vel bakpapier op het blad van de kinderstoel: na afloop vouw je het dicht en gooi je het weg.","Natuurlijke kleuren: bietensap geeft roze, blauwe bessen paars en een snufje kurkuma geel. Ook die vlekken, dus trek oude kleren aan."],"extenders":["Geef een nieuw ‘penseel’ dat ook lekker is, zoals een stuk banaan of een zachte, gekookte broccoliroos: stempelen en proeven tegelijk.","Druk een vel papier op het besmeerde blad, wrijf erover en trek het los: een afdruk om te bewaren, en het smeren kan opnieuw beginnen.","Doe pas na een tijdje een tweede kleur erbij en benoem wat je ziet als de kleuren mengen: blauw en geel, nu wordt het groen!"],"variations":["Vla- of puddingverf: werkt net zo, maar met een andere kleur en smaak.","Proefpalet: een bakje met bessen, een met geprakte banaan en een met wortelpuree. Welke vindt je kind het lekkerst?","Zomer: zet de bakjes 20 minuten in de vriezer voor koele, dikke verf op een warme dag."],"themes":[],"canStay":false,"pinQuery":"eetbare verf yoghurt baby"},
  {"id":"groente-stempels","title":"Stempelen met groente en fruit","emoji":"🥔","category":"verven","summary":"Een paprika wordt een bloem, een halve appel een ster: stempel met groente en fruit en ontdek welke vorm erin verstopt zit.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"groente","note":"een paprika, een aardappel en een stronk bleekselderij"},{"id":"fruit","note":"een appel, dwars doorgesneden"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"bord","note":"een plat bord per kleur"},{"id":"papier","note":"of groot papier"},{"id":"mes","note":"voor jou"}],"optional":[{"id":"keukenpapier","note":"om de stempels droog te deppen"},{"id":"vork","note":"in een halve aardappel geprikt als handvat"},{"id":"oud-shirt"}],"steps":["Snijd de groente en het fruit door, dat doe jij: een paprika dwars (bloem), een appel dwars (ster) en de onderkant van de bleekselderij (roosje).","Maak een aardappelstempel: snijd een aardappel doormidden en snijd rondom een hartje of driehoek een halve centimeter weg, zodat de vorm uitsteekt.","Dep alle stempels droog met keukenpapier en doe een dun laagje verf op een paar borden, één kleur per bord.","Laat je kind een stempel in de verf drukken, even laten uitlekken en stevig op het papier zetten.","Bekijk samen elke afdruk: welke groente was dit? Zie je de ster van de appel?","Laat het vel plat drogen en gooi de gebruikte stempels weg: met verf erop zijn ze niet meer om te eten."],"ageTips":{"young":"Een tweejarige pakt een halve aardappel of appel het makkelijkst. Prik er een vork in als handvat en geef één kleur tegelijk.","old":"Een kleuter kan een patroon stempelen (ster, bloem, ster, bloem), tellen hoeveel afdrukken er op een rij passen of van de afdrukken een rups of bloemenveld maken."},"safety":["Het snijden doe jij: leg het mes daarna meteen buiten bereik.","Met verf erop is groente geen eten meer: laat je kind niet aan de stempels likken en gooi ze na afloop weg.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Druk! Kijk eens!","Wat zie je als je de appel optilt?","Welke groente maakt rondjes, en welke een bloem?","Ik zie dat je heel stevig drukt, daardoor zie je alle lijntjes.","Ruik eens aan de appel. En aan de paprika?"],"words":["stempel","afdruk","ster","bloem","doormidden","stevig","patroon"],"learn":["creativiteit","fijne-motoriek","ontdekken","rekenen"],"tips":["Gebruik restjes en kontjes uit de groentela: een prei, wortel of champignon geeft ook verrassende vormen.","Dep gesneden groente goed droog en doe niet te veel verf op het bord: dan wordt de afdruk scherper."],"extenders":["Snijd er een nieuwe stempel bij als het tempo zakt, zoals een halve champignon, een stukje prei of een wortelkontje (dat doe jij): welke vorm komt eruit?","Teken met stift een fruitmand, een vaas of een boom op een nieuw vel en laat je kind hem vol stempelen.","Doe twee kleuren naast elkaar op één bord: de stempel drukt ze dan allebei tegelijk af."],"variations":["Herfst: stempel appels en peren in rood, geel en bruin en maak er een fruitmand of herfstboom van.","Kaartjes: stempel klein op een dubbelgevouwen kaart, als bedankje of verjaardagskaart.","Raadspel: maak een afdruk en laat de ander raden welke groente of welk fruit het was."],"themes":["herfst"],"canStay":false,"pinQuery":"stempelen met groente peuter"},
  {"id":"wc-rol-stempels","title":"Stempelen met wc-rolletjes","emoji":"🌸","category":"verven","summary":"Een wc-rolletje is een stempel vol vormen: rond, ingeknepen tot hartje of met franjes als bloem. Stempel samen een bloemenveld.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"wc-rollen","note":"3 lege rolletjes"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"bord","note":"een plat bord of deksel per kleur"},{"id":"papier","note":"wit of gekleurd"},{"id":"plakband","note":"om de hartvorm vast te zetten"},{"id":"schaar","note":"voor jou, om franjes te knippen"}],"optional":[{"id":"stiften","note":"voor steeltjes en blaadjes"},{"id":"kinderschaar","note":"voor kleuters die zelf franjes knippen"},{"id":"oud-shirt"}],"steps":["Laat één rolletje zoals het is: dat stempelt rondjes.","Druk een tweede rolletje plat en duw het midden van één kant naar binnen: zo krijg je een hartje. Zet de vorm vast met plakband.","Knip een derde rolletje aan één kant rondom in, 2 cm diep (dat doe jij), en buig de franjes naar buiten: een bloem.","Doe een dun laagje verf op een paar borden en laat je kind de stempels erin dopen en stevig op het papier drukken.","Maak er samen een bloemenveld van: teken steeltjes met stift en stempel een hartje als blaadje.","Laat het vel plat drogen. Droge stempels kunnen nog een keer mee."],"ageTips":{"young":"Een tweejarige begint met het ronde rolletje: dopen, drukken, optillen. Benoem elke afdruk: rondje! Nog een rondje!","old":"Een kleuter kan zelf franjes knippen met een kinderschaar, een patroon stempelen (rond, hart, rond) of tellen hoeveel bloemen er in het veld staan."},"safety":["Het inknippen van de franjes doe jij, of je kleuter met een kinderschaar met ronde punt.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Druk! Een rondje!","Wat gebeurt er als je het rolletje platknijpt?","Hoeveel bloemen staan er al in jouw veld?","Ik zie dat de franjes allemaal kleine streepjes maken, net blaadjes van een bloem.","Je zoekt steeds een nieuw plekje om te stempelen, goed bedacht!"],"words":["rondje","hartje","bloem","franje","stempelen","plat","rij"],"learn":["creativiteit","fijne-motoriek","rekenen"],"tips":["Spaar een paar weken wc-rolletjes, of knip een keukenrolkoker in drie stukken: dan heb je meteen genoeg stempels.","Een dun laagje verf geeft scherpere vormen dan een dikke klodder. Doe liever vaker een beetje bij."],"extenders":["Knijp een nieuw rolletje in een andere vorm, zoals een ovaal, een vierkant of een driehoek, en raad samen welke afdruk eruit komt.","Stempel een lange rij rondjes en maak er met stift een rups, een trein of een ketting van.","Stempel twee keer op dezelfde plek, met een andere vorm en kleur: een hartje in een bloem, een rondje over een hartje."],"variations":["Moederdag: stempel hartjes op een dubbelgevouwen kaart en schrijf er samen een boodschap in.","Lente: maak een bloemenveld met franjebloemen en stip er met een vingertop bijtjes bij.","Aquarium: stempel blauwe en witte rondjes als luchtbelletjes op gekleurd papier en teken er vissen bij."],"themes":["lente","moederdag"],"canStay":false,"pinQuery":"stempelen met wc rolletjes"},
  {"id":"noppenfolie-afdruk","title":"Noppenfolie-afdrukken","emoji":"🐝","category":"verven","summary":"Verf de noppen van bubbeltjesplastic en druk er papier op: een honingraat vol stippen. Of wikkel de folie om een deegroller of handje.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[10,25],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"noppenfolie","note":"een stuk van ongeveer 30 x 30 cm"},{"id":"plakkaatverf","note":"bijvoorbeeld geel en oranje voor een honingraat"},{"id":"penselen","note":"een dikke kwast"},{"id":"papier","note":"of groot papier voor de rolstempel"},{"id":"schilderstape","note":"om de folie vast te zetten"}],"optional":[{"id":"deegroller","note":"om de folie omheen te plakken"},{"id":"sponsjes","note":"om de verf op te deppen"},{"id":"stiften","note":"om bijtjes te tekenen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Plak een stuk noppenfolie met de noppen naar boven vast op tafel.","Laat je kind de noppen beschilderen met een dikke kwast of een sponsje, in één of meer kleuren.","Leg een vel papier op de folie, wrijf er samen met platte handen overheen en trek het voorzichtig los.","Bekijk de afdruk: allemaal stippen! Schilder de folie opnieuw voor een tweede of derde afdruk.","Maak een rolstempel: plak noppenfolie om een deegroller, rol door een laagje verf op een bord en daarna over een lang vel.","Laat de afdrukken plat drogen en teken er met stift bijtjes of bloemen bij."],"ageTips":{"young":"Een dreumes vindt de noppen zelf al spannend: laat eerst voelen en knijpen. Wikkel daarna folie om het handje (los, met tape), doop in de verf en druk samen op het papier: klets!","old":"Een kleuter kan van de stippenvellen bijtjes en bloemen knippen, of tellen hoeveel noppen er in één rij staan. Ook leuk: met twee kleuren om en om schilderen."},"safety":["Folie om een handje of voetje maak je los vast met tape, nooit strak of met een elastiekje. Druk een voetafdruk zittend: met verf eronder is lopen spekglad.","Plastic folie hoort niet in de mond of over het gezicht: blijf erbij en ruim losse stukjes meteen op.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf."],"say":["Plop! Nog een!","Hoe voelen de bolletjes onder je vingers?","Wat denk je dat we zien als we het papier optillen?","Ik zie allemaal kleine rondjes, net een honingraat van bijen.","Wat wrijf je goed met je hele hand, alle stippen staan erop!"],"words":["bolletje","stip","rij","honingraat","rollen","afdruk","bobbelig"],"learn":["zintuigen","creativiteit","ontdekken"],"tips":["Bewaar de noppenfolie uit pakketjes: een stukje is genoeg, en na afloop spoel je het af om nog eens te gebruiken.","Leg de folie na afloop meteen in de gootsteen: de verf op de noppen blijft lang nat en vlekt."],"extenders":["Wikkel een schoon stukje folie om een blok of een plastic beker en stempel daarmee verder: grote en kleine stippen door elkaar.","Rol de deegroller met noppenfolie in een tweede kleur over een vel dat al droog is: stippen over stippen.","Leg tussendoor een schoon stuk folie neer om noppen te laten knappen: lukt het met één vinger, met twee duimen of door erop te gaan zitten?"],"variations":["Lente: maak een geel-oranje honingraat, knip er een bijenkorf uit en teken er bijtjes omheen.","Zomer: blauwe en groene stippen worden een zee vol luchtbelletjes, met vissen ernaast.","Voetstapjespad: wikkel folie om een voetje (zittend op een stoel) en druk er stapjes mee op een lange strook papier.","Slangenvel: rol de deegroller in groen en geel over een lange strook en knip er een slang uit."],"themes":["lente","zomer"],"canStay":false,"pinQuery":"noppenfolie verven peuter"},
  {"id":"autosporen","title":"Autosporen verven","emoji":"🚗","category":"verven","summary":"Rijd met speelgoedautootjes door de verf en over een groot vel: elke auto laat een ander bandenspoor achter. Daarna door de wasstraat!","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"duration":[20,30],"supervision":2,"soloFrom":4,"cleanupMinutes":15,"noise":2,"energy":2,"places":["vloer","tafel"],"materials":[{"id":"speelgoedautos","note":"een paar met verschillende banden, die vies mogen worden"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"bord","note":"een plat bord per kleur"},{"id":"groot-papier","note":"een lange strook, bijvoorbeeld oud behang"},{"id":"schilderstape","note":"om het papier vast te plakken"},{"id":"opbergbak","note":"of afwasteil, voor de wasstraat"},{"id":"water","note":"lauw, voor de wasstraat"},{"id":"afwasmiddel","note":"een scheutje voor het sopje"}],"optional":[{"id":"tandenborstel","note":"om de bandjes te poetsen"},{"id":"sponsjes"},{"id":"handdoek","note":"om de auto’s op te laten drogen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Plak een lange strook papier met schilderstape vast op de vloer of tafel, met een knoeimat eronder.","Doe een dun laagje verf op een paar borden, één kleur per bord.","Laat je kind een auto door de verf rijden en dan over het papier: vroem, daar komt het spoor!","Probeer verschillende auto’s en vergelijk de sporen: dikke en dunne banden, rechte lijnen en slingers.","Maak na afloop een wasstraat: een bak lauw water met een scheutje afwasmiddel, een sponsje en een oude tandenborstel. Je kind poetst de auto’s schoon.","Laat de auto’s drogen op een handdoek en het papier plat drogen."],"ageTips":{"young":"Geef een tweejarige één grote auto met brede banden en één kleur. Rijden en vroem roepen is het leukste; het spoor is mooi meegenomen.","old":"Een kleuter kan een route bedenken (bocht, rondje, rechtdoor), raden welke auto welk spoor maakte of de sporen met stift omtoveren tot een stad met huizen en wegen."},"safety":["Laat je kind niet alleen bij de bak sopje, ook niet bij een laagje water, en dweil gemorst water direct op: de vloer wordt glad.","Afwasmiddel prikt in de ogen en is niet om te drinken: een scheutje is genoeg en houd een doekje klaar.","Plakkaatverf vlekt op kleding en vloer: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Vroem! Daar gaat hij!","Welk spoor is van de grote auto, denk je?","Ik zie een kronkelweg en een hele rechte lijn.","Wat gebeurt er als je twee keer door de verf rijdt?","Wat poets je die banden goed, ze zijn weer helemaal schoon!"],"words":["band","spoor","bocht","rechtdoor","snel","langzaam","poetsen"],"learn":["creativiteit","ontdekken","fijne-motoriek","taal"],"tips":["Kies auto’s zonder kleine openingen of losse onderdelen: opgedroogde verf krijg je daar moeilijk uit.","Zet de wasstraat op een handdoek of dienblad: zo blijft het water op één plek."],"extenders":["Teken met stift een garage of een finishvlag aan het eind van de strook: kan je kind precies daar stoppen?","Leg een boek schuin tegen een stapeltje boeken als helling en laat een auto met verf aan de banden naar beneden rollen: hoe lang wordt het spoor?","Maak van de wasstraat een echte garage: je kind wast, droogt en ‘repareert’ elke auto, en jij komt hem daarna ophalen."],"variations":["Dierensporen: laat speelgoeddieren door de verf lopen. Wie maakt welke pootafdruk?","Wegenkaart: laat de sporen drogen en speel er de volgende dag op verder met schone auto’s.","Verkeerslicht: rijd alleen met rode, gele en groene verf en speel stoppen en rijden."],"themes":[],"canStay":false,"pinQuery":"verven met autootjes peuter"},
  {"id":"rolschilderij","title":"Rolschilderij in een doos","emoji":"🌰","category":"verven","summary":"Rol kastanjes of een balletje door klodders verf in een doos, kantel en schud: zo ontstaat een schilderij vol kronkelsporen.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"dozen","note":"een schoenendoos met deksel"},{"id":"papier","note":"op maat geknipt voor de bodem"},{"id":"plakkaatverf","note":"2-3 kleuren"},{"id":"kastanjes","note":"3-5 stuks, alleen vanaf 3 jaar"},{"id":"lepel","note":"om de verf te scheppen"}],"optional":[{"id":"bal","note":"voor kinderen onder de 3: een balletje dat niet door een wc-rolletje past"},{"id":"schilderstape","note":"om de deksel dicht te plakken"},{"id":"oud-shirt"}],"steps":["Knip een vel papier op maat en leg het in de bodem van de doos.","Laat je kind met een lepel 3-4 klodders verf op het papier scheppen, verspreid over de bodem.","Leg 3 tot 5 kastanjes in de doos, of één balletje voor kinderen onder de 3, en doe de deksel erop.","Laat je kind de doos kantelen, schudden en draaien: hoor je de kastanjes rollen?","Kijk samen naar de sporen. Nog een kleur erbij? Deksel weer dicht en verder rollen.","Haal het vel er voorzichtig uit om plat te drogen en spoel de kastanjes af onder de kraan."],"ageTips":{"young":"Gebruik voor een tweejarige één grote bal in plaats van kastanjes en plak de deksel dicht met tape. Kantel samen: naar jou, naar mij, rollen maar!","old":"Een kleuter kan voorspellen waar de kleuren terechtkomen, met meer kastanjes en kleuren werken of het gedroogde vel knippen tot herfstbladeren of een kaart."},"safety":["Kastanjes zijn klein en giftig bij opeten: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Tel ze vooraf en na afloop.","Bij flink schudden kan verf langs de deksel spatten: plak de deksel dicht en werk op een knoeimat, want plakkaatverf vlekt."],"say":["Rollen! Hoor je ze?","Waar denk je dat de kastanjes heen gaan als je de doos zo kantelt?","Ik zie een lange rode streep, helemaal van hoek naar hoek.","Wat kantel je voorzichtig, de kastanjes blijven netjes in de doos!","Hoeveel kastanjes zitten erin? Tel je mee?"],"words":["rollen","kantelen","spoor","hoek","schudden","kastanje","kronkel"],"learn":["ontdekken","creativiteit","fijne-motoriek","rekenen"],"tips":["Geen kastanjes? Rol met stevige balletjes aluminiumfolie (vanaf 3 jaar): ook die maken mooie sporen.","Hoe minder verf, hoe scherper de sporen. Begin met kleine klodders en doe er later nog wat bij."],"extenders":["Doe er een ander rollend ding bij, zoals een speelgoedautootje of een tennisbal: welk spoor maakt dat?","Geef een opdracht: kantel alleen naar voren en naar achteren. Lukt het om alleen rechte strepen te maken? En nu rondjes?","Zet muziek op: bij snelle muziek flink schudden, bij langzame muziek zachtjes kantelen."],"variations":["Herfst: rol met bruin, oranje en rood en knip van het gedroogde vel bladeren of een egel.","Twee kleuren: doe geel aan de ene kant en blauw aan de andere, en kijk waar het groen wordt.","Grote rolbaan: leg een groot vel in een verhuisdoos en laat samen een bal heen en weer rollen."],"themes":["herfst"],"canStay":false,"pinQuery":"verven met kastanjes in doos"},
  {"id":"toverzout","title":"Toverzout-schilderij","emoji":"🧂","category":"verven","summary":"Strooi zout op lijnen lijm en druppel er kleur op: kijk hoe de kleur als toverij door het zout wegloopt.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"karton","note":"stevig, bijvoorbeeld van een cornflakesdoos"},{"id":"knutsellijm","note":"witte hobbylijm, het liefst in een knijpflesje"},{"id":"zout","note":"fijn zout, een paar flinke el"},{"id":"waterverf","note":"goed nat gemaakt, of water met een paar druppels kleurstof"},{"id":"pipet","note":"of een kwast"},{"id":"dienblad","note":"om het zout op te vangen"}],"optional":[{"id":"kleurstof","note":"een paar druppels per bakje water, als je geen waterverf hebt"},{"id":"potjes","note":"een per kleur"},{"id":"potlood","note":"om eerst een tekening voor te tekenen"},{"id":"oud-shirt"}],"steps":["Teken met potlood een eenvoudige vorm op het karton, zoals een sneeuwvlok, een slinger of de naam van je kind.","Spuit dikke lijnen lijm over de tekening. Bij een driejarige doe jij dit, of je knijpt samen.","Leg het karton op een dienblad en laat je kind zout over de lijm strooien tot alles wit is.","Kantel het karton en tik het losse zout eraf op het dienblad.","Druppel met een pipet aangelengde waterverf op de zoutlijnen en kijk hoe de kleur wegloopt.","Laat het schilderij een nacht plat drogen: daarna glinstert het zout."],"ageTips":{"young":"Zet voor een driejarige zelf de lijnen lijm, laat je kind strooien met een theelepel en geef één pipet met één kleur. Knijpen en loslaten is al een hele klus.","old":"Een kleuter kan zelf lijm spuiten, de eigen naam of een sneeuwvlok, en plannen welke kleur waar komt. Wat gebeurt er waar twee kleuren elkaar raken?"},"safety":["Zout prikt in de ogen en in wondjes: niet in de ogen wrijven en handen wassen na afloop.","Knutsellijm is niet om te eten: houd de lijmfles bij je en zet hem daarna buiten bereik.","Waterverf en kleurstof vlekken: werk op een dienblad en trek een oud shirt aan."],"say":["Knijp! Daar gaat hij!","Waar denk je dat de blauwe druppel naartoe gaat?","Hoe voelt het zout tussen je vingers: korrelig of glad?","Ik zie dat je heel voorzichtig knijpt, druppel voor druppel.","Wat gebeurt er als rood en geel elkaar raken in het zout?"],"words":["korrelig","druppel","weglopen","zout","knijpen","glinsteren","lijn"],"learn":["ontdekken","fijne-motoriek","concentratie","creativiteit"],"tips":["Doe het zout in een klein bakje met een theelepel of in een strooibus: dan belandt het meeste op het karton.","Giet het losse zout van het dienblad terug in een bakje: je kunt het een volgende keer weer gebruiken, maar niet meer voor eten.","Dun papier krult van het water; stevig karton werkt veel beter."],"extenders":["Tel samen de druppels: hoeveel heeft één lijn nodig voordat hij helemaal gekleurd is?","Strooi een snufje zout op een natte, gekleurde plek en kijk van dichtbij: wat gebeurt er met de kleur?","Druppel eens met een kwast of een wattenstaafje in plaats van met de pipet: loopt de kleur dan net zo ver?"],"variations":["Winter: maak een sneeuwvlok of sterrenhemel op donkerblauw karton met witte en lichtblauwe druppels.","Naam in toverzout: schrijf de naam van je kind met lijm (dat doe jij) en geef elke letter een eigen kleur.","Vuurwerk: spuit sterren en stralen met lijm op zwart karton en druppel er felle kleuren op."],"themes":["winter"],"canStay":false,"pinQuery":"zoutschilderij lijm waterverf kind"},
  {"id":"tape-geheim","title":"Tape-geheimschilderij","emoji":"🤫","category":"verven","summary":"Plak figuren of een naam met schilderstape, verf eroverheen en trek de tape eraf als alles droog is: er verschijnt een wit geheim patroon.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"schilderstape","note":"een rol, liefst niet te smal"},{"id":"karton","note":"of dik papier: dun papier scheurt als je de tape lostrekt"},{"id":"plakkaatverf","note":"of waterverf, een paar kleuren"},{"id":"penselen","note":"dikke kwasten"}],"optional":[{"id":"sponsjes","note":"om grote vlakken te deppen"},{"id":"oud-shirt"}],"steps":["Plak strookjes tape op het karton: een ster, een huisje, strepen of de eerste letter van de naam. Wrijf de randen goed aan.","Laat je kind het hele vel beschilderen, ook over de tape heen, in zoveel kleuren als het wil.","Laat de verf helemaal drogen, een half uur tot een uur. Ga intussen iets anders doen.","Trek samen de tape eraf, langzaam en schuin: daar is het geheim!","Bekijk het witte patroon samen en raad wat het is, of bedenk er een naam voor."],"ageTips":{"young":"Een tweejarige vindt tape plakken en lostrekken al geweldig. Vouw aan elk stuk tape een puntje om, dan pakt je kind het makkelijker, en laat je kind met een sponsje grote vlakken verven.","old":"Een kleuter plakt zelf een figuur, de letters van de eigen naam of een weg met kruispunten, en bedenkt welke kleur in welk vlak komt."},"safety":["Losgetrokken tape plakt aan vingers en belandt zo in de mond: gooi propjes meteen in een bakje.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Trek! Wat zit eronder?","Waar denk je dat de tape zit, nu alles geverfd is?","Ik zie een witte ster tussen al dat blauw!","Wat trek je de tape voorzichtig los, daardoor scheurt het karton niet.","Welke kleuren wil je over de tape heen schilderen?"],"words":["geheim","tape","plakken","lostrekken","onder","verschijnen","wit"],"learn":["fijne-motoriek","creativiteit","ontdekken"],"tips":["Trek de tape pas los als de verf droog is, anders lopen de kleuren in de witte lijnen. Een föhn op lage stand (dat doe jij) helpt bij een ongeduldig kind.","Plak de tape eerst even op je broek: dan plakt hij minder hard en scheurt het karton niet bij het lostrekken."],"extenders":["Plak na het lostrekken nieuwe tape kriskras over het vel en verf er een tweede kleur overheen: een geheim onder een geheim.","Laat je kind de witte lijnen na het lostrekken inkleuren met stift of waskrijt, of er een rij stippen in zetten.","Plak alvast een tweede vel af terwijl het eerste droogt: nu plakt je kind zelf de tape en kiest de vorm."],"variations":["Naambordje: plak de letters van de naam met tape, verf eroverheen en hang het op de kamerdeur.","Winter: plak sneeuwvlokken van drie gekruiste stroken en verf eroverheen in blauw en paars.","Stad: plak wegen en kruispunten, verf de vlakken als huizenblokken en rijd daarna met autootjes over de witte wegen."],"themes":[],"canStay":false,"pinQuery":"schilderen met schilderstape kind"},
  {"id":"geheime-tekening","title":"Geheime tekening met wit krijt","emoji":"🔍","category":"verven","summary":"Jij tekent onzichtbaar met wit waskrijt, je kind schildert er waterverf overheen en zie: de geheime tekening verschijnt.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"waskrijt","note":"een wit krijtje, of een stompje kaars"},{"id":"papier","note":"stevig wit papier"},{"id":"waterverf","note":"donkere kleuren werken het best"},{"id":"penselen","note":"een dikke kwast"},{"id":"water","note":"een bakje om de kwast in te spoelen"}],"optional":[{"id":"kleurstof","note":"een paar druppels in water, als je geen waterverf hebt"},{"id":"keukenpapier","note":"om natte plassen te deppen"},{"id":"oud-shirt"}],"steps":["Teken met wit waskrijt een geheime tekening op wit papier: een zon, een spookje, een hartje of de naam van je kind. Druk flink.","Maak de waterverf goed nat, of meng een paar druppels kleurstof met water in een bakje.","Geef het ‘lege’ vel aan je kind en vraag: zou er iets op staan?","Laat je kind met brede halen over het hele vel schilderen. Het waskrijt stoot de verf af, dus de tekening verschijnt.","Raad samen wat het is, en draai de rollen om: nu tekent je kind een geheim voor jou.","Laat het vel plat drogen op een handdoek of krant."],"ageTips":{"young":"Teken voor een driejarige grote, dikke vormen en druk flink, zodat de verrassing goed zichtbaar wordt. Gebruik donkere verf, zoals blauw of paars.","old":"Een kleuter tekent zelf een geheim voor een broertje, zusje of voor jou. Of jij schrijft een boodschap van twee woorden: herkent je kind de letters?"},"safety":["Gebruik je een stompje kaars als krijt, steek het dan niet aan en leg aanstekers en lucifers buiten bereik.","Waterverf en kleurstof vlekken op kleding en tafel: leg een knoeimat neer en trek een oud shirt aan."],"say":["Kijk! Daar komt iets!","Wat denk je dat er op dit lege vel staat?","Ik zie een rondje… en nu stralen. Wat zou het zijn?","Je schildert met grote halen over het hele vel, zo vind je het geheim.","Wil jij nu een geheim voor mij tekenen?"],"words":["geheim","onzichtbaar","tevoorschijn","krijt","verf","raden","verrassing"],"learn":["ontdekken","taal","creativiteit","samen"],"tips":["Druk stevig met het krijt en gebruik waterige, donkere verf: dan zie je de tekening het best.","Maak er een paar van tevoren, dan heb je meteen een stapeltje klaar als je kind om meer vraagt."],"extenders":["Verstop met wit krijt drie kleine tekeningetjes verspreid over één vel, zoals sterretjes of hartjes, en vertel hoeveel het er zijn: vindt je kind ze alle drie?","Teken een verhaal in stukjes op losse vellen, zoals een huis, een kat en een maan, en laat je kind ze één voor één tevoorschijn schilderen: wat gebeurt er?","Geef eerst een hint, zoals ‘het is rond en het schijnt’, en laat je kind raden voordat de kwast het geheim onthult."],"variations":["Sinterklaas: Sinterklaas laat een geheime tekening achter bij de schoen. Schildert je kind eroverheen, dan verschijnt er een mijter, een paard of een cadeautje.","Halloween: teken spookjes, een pompoen of een vleermuis en laat je kind er met paarse of zwarte verf overheen schilderen.","Schattenjacht: verstop een paar geheime tekeningen in huis, elk met een getekende aanwijzing naar de volgende."],"themes":["sinterklaas","halloween"],"canStay":false,"pinQuery":"geheime tekening waskrijt waterverf"},
  {"id":"ijsverf","title":"Schilderen met ijsverf","emoji":"🧊","category":"verven","summary":"Bevroren verfblokjes op een stokje glijden over het papier en smelten tot heldere kleuren: koel schilderen voor warme dagen.","ageMin":1,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"duration":[10,25],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"ijsblokjesvorm","note":"of een muffinvorm, voor grotere blokken"},{"id":"kleurstof","note":"een paar druppels per vakje"},{"id":"water","note":"koud, ongeveer 2 el per vakje"},{"id":"ijsstokjes","note":"een per vakje"},{"id":"huishoudfolie","note":"strak over de vorm, zodat de stokjes rechtop blijven"},{"id":"vriezer","note":"minstens 4 uur, liefst een nacht"},{"id":"papier","note":"stevig wit papier of karton"}],"optional":[{"id":"plakkaatverf","note":"een tl per vakje, voor fellere kleuren"},{"id":"fruit","note":"geprakte aardbeien of bessen met wat water, voor proefbare ijsverf"},{"id":"dienblad","note":"om op te schilderen, vangt het smeltwater op"},{"id":"oud-shirt"}],"steps":["Vul elk vakje van de vorm voor driekwart met water en roer er een paar druppels kleurstof of een tl verf door.","Span huishoudfolie strak over de vorm en prik door de folie in elk vakje een ijsstokje: zo blijft het rechtop staan.","Zet de vorm minstens 4 uur in de vriezer, liefst een nacht.","Laat de vorm vijf minuten op het aanrecht staan of houd de onderkant even onder de warme kraan: dan wippen de blokjes er makkelijk uit.","Leg een vel stevig papier op een dienblad en laat je kind schilderen met de ijsblokjes: eerst gebeurt er niets, dan smelt de kleur.","Leg de blokjes na afloop in een bakje en laat het vel plat drogen."],"ageTips":{"young":"Maak voor je dreumes ijsverf van geprakt fruit met wat water: dan mag likken. Kies een muffinvorm voor grote blokken die goed in een knuistje passen.","old":"Een kleuter kan kleuren mengen (wat gebeurt er als geel over blauw gaat?), tellen hoe lang het duurt voor een blokje gesmolten is of een zomers schilderij maken van zon en zee."},"safety":["IJsverf met kleurstof of plakkaatverf is niet om op te zuigen: geef kinderen die alles in hun mond stoppen alleen ijsverf van fruit.","Laat je dreumes niet op het ijs bijten: een los brokje ijs kan in de keel schieten. Blijf erbij.","IJs dat net uit de vriezer komt, kan aan vingers en lippen plakken: laat de blokjes eerst een paar minuten ontdooien.","Gekleurd smeltwater vlekt en maakt de vloer glad: werk op een dienblad, dweil gemorst water direct op en laat een jong kind er niet alleen mee."],"say":["Koud! Brrr!","Kijk, de kleur komt pas als het ijs smelt.","Wat denk je: smelt het ijs sneller in je hand of op het papier?","Hoe voelt het: koud, nat, glad?","Je laat het blokje steeds nieuwe rondjes draaien, wat werk je geduldig!"],"words":["koud","ijs","smelten","glad","nat","druppelen","bevroren"],"learn":["zintuigen","ontdekken","creativiteit"],"tips":["Maak de ijsverf de avond van tevoren: dan is hij precies klaar als je kind ernaar vraagt.","Met een tl plakkaatverf per vakje worden de kleuren feller dan met alleen kleurstof.","Schilder in de lege badkuip of op een dienblad: het smeltwater loopt dan niet van tafel."],"extenders":["Maak een stuk van het papier nat met een sponsje en schilder daar verder: de kleur loopt nu uit als waterverf.","Kantel het dienblad een beetje en laat een paar blokjes zelf over het papier glijden: welke kleur komt het verst?","Houd een paar blokjes achter de hand in de vriezer en haal er één nieuwe kleur bij zodra de aandacht zakt."],"variations":["Zomer: schilder een zon, de zee of een ijsje en kijk hoe snel het ijs in de warmte smelt.","Bloemenijs: vries in elk vakje een bloemblaadje mee en kijk wat er tevoorschijn komt als het smelt.","Grote ijsverf: vries een bakje gekleurd water in en schilder samen op een groot vel."],"themes":["zomer"],"canStay":false,"pinQuery":"schilderen met ijsblokjes peuter"},
  {"id":"blaasmonsters","title":"Blaasmonsters met een rietje","emoji":"👾","category":"verven","summary":"Druppel waterige verf op papier en blaas hem met een rietje alle kanten op: zo groeien er wilde monsterpoten en -haren.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"plakkaatverf","note":"aangelengd met water tot hij zo dun is als melk"},{"id":"water","note":"om de verf dun te maken"},{"id":"bakjes","note":"een per kleur"},{"id":"rietjes","note":"een per kind, een dik rietje blaast het makkelijkst"},{"id":"papier","note":"stevig wit of gekleurd papier"}],"optional":[{"id":"pipet","note":"om druppels te maken (anders een lepel)"},{"id":"stiften","note":"voor ogen, mond en tanden"},{"id":"wiebeloogjes","note":"vanaf 3 jaar, uit de buurt van jongere kinderen"},{"id":"oud-shirt"}],"steps":["Oefen eerst zonder verf: blaas door een rietje op je hand of blaas een propje papier over tafel. Blazen, niet zuigen!","Maak de verf in een bakje dun met water, ongeveer half om half, tot hij zo dun is als melk.","Druppel met een lepel of pipet een flinke druppel verf op het papier.","Laat je kind het rietje vlak boven de druppel houden en hard blazen: de verf schiet alle kanten op.","Draai het vel en blaas opnieuw, of druppel een tweede kleur ernaast.","Laat het monster drogen en teken er met stift ogen, een mond en tanden op."],"ageTips":{"young":"Een driejarige zuigt nog weleens per ongeluk. Knip een klein sneetje vlak onder de bovenkant van het rietje, dan zuigt je kind lucht in plaats van verf. Of blaas om de beurt: eerst jij, dan je kind.","old":"Een kleuter kan bedenken wat voor monster het is: hoe heet hij, wat eet hij, waar woont hij? Schrijf het verhaal erbij of maak een hele monsterfamilie."},"safety":["Blazen, niet zuigen: houd het rietje boven de druppel en niet erin. Plakkaatverf is niet om in te slikken.","Van veel hard blazen kun je duizelig worden: neem af en toe samen een pauze.","Wiebeloogjes zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Houd ze uit de buurt van jongere broertjes of zusjes."],"say":["Blazen! Harder!","Waar denk je dat de verf naartoe rent als je van deze kant blaast?","Ik zie een monster met wel tien poten!","Hoe heet jouw monster? Wat eet hij graag?","Wat blaas je lang achter elkaar, knap volgehouden!"],"words":["blazen","rietje","druppel","spetter","monster","harig","griezelig"],"learn":["creativiteit","ontdekken","taal"],"tips":["Hoe dunner de verf, hoe verder hij rent. Is de verf te dik, doe er dan een scheutje water bij.","Leg het vel op een dienblad: dan blijft de verf die van het papier rent op het blad."],"extenders":["Druppel een tweede kleur vlak naast de eerste en blaas ze naar elkaar toe: welke kleur krijgt het monster waar ze elkaar raken?","Blaas om de beurt aan hetzelfde monster, ieder met een eigen rietje: jij blaast een arm, je kind een been. Hoeveel armen krijgt het?","Houd een wedstrijdje wie de langste poot blaast en leg er blokjes naast om te meten."],"variations":["Halloween: blaas zwarte en paarse verf op oranje papier en maak er spinnen of vleermuizen van.","Herfstboom: blaas bruine verf omhoog tot takken en stip er met een vingertop rode en gele blaadjes aan.","Vuurwerk: blaas felle kleuren vanuit één punt naar buiten op zwart papier."],"themes":["halloween"],"canStay":false,"pinQuery":"blaasmonsters rietje verf"},
  {"id":"vouwvlinder","title":"Vlinder-vouwschilderij","emoji":"🦋","category":"verven","summary":"Klodders verf op één helft, dubbelvouwen, stevig aandrukken en open: er verschijnt een vlinder met twee precies dezelfde vleugels.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"papier","note":"wit of gekleurd, A4"},{"id":"plakkaatverf","note":"2-4 kleuren, niet te waterig"},{"id":"lepel","note":"of een kwast, om klodders te maken"}],"optional":[{"id":"potlood","note":"om vooraf een halve vlinder te tekenen"},{"id":"schaar","note":"om de vlindervorm uit te knippen (dat doe jij)"},{"id":"kinderschaar","note":"voor kleuters die zelf knippen"},{"id":"stiften","note":"voor een lijfje en voelsprieten"},{"id":"oud-shirt"}],"steps":["Vouw een vel papier dubbel en weer open: de vouw wordt het lijfje van de vlinder.","Laat je kind met een lepel of kwast klodders en stippen verf op één helft zetten, dicht bij de vouw.","Vouw het vel dicht en laat je kind er met platte handen overheen wrijven, van de vouw naar buiten.","Vouw het samen langzaam open: kijk, twee dezelfde vleugels!","Laat het drogen en knip er eventueel een vlindervorm uit. Teken met stift een lijfje en voelsprieten."],"ageTips":{"young":"Een tweejarige laat het vouwen aan jou over, maar wrijven en openvouwen is het spannendste. Geef één of twee kleuren en een lepel in plaats van een kwast.","old":"Een kleuter kan voorspellen waar de kleuren terechtkomen, zelf de vlindervorm knippen met een kinderschaar of een hele rij vlinders maken voor het raam."},"safety":["Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat.","Het uitknippen doe jij, of je kleuter met een kinderschaar met ronde punt."],"say":["Wrijf, wrijf! En open!","Wat denk je dat er gebeurt als we het papier openvouwen?","Ik zie aan deze kant een rode stip, en aan die kant ook!","Welke kleuren krijgt jouw vlinder?","Je wreef zo stevig, daardoor zijn de vleugels helemaal gevuld."],"words":["vouwen","openvouwen","hetzelfde","spiegelbeeld","vleugel","vlinder","helft"],"learn":["ontdekken","creativiteit","rekenen","fijne-motoriek"],"tips":["Zet de klodders dicht bij de vouw: verf aan de buitenrand loopt er bij het aandrukken snel uit.","Teken vooraf met potlood een halve vlinder tegen de vouw aan: dan weet je kind waar de verf mag."],"extenders":["Vouw het vel nog eens open, zet er nieuwe klodders in een andere kleur bij en vouw opnieuw dicht: de vlinder krijgt een tweede laag.","Druk een schoon vel op de natte vlinder en trek het los: een tweelingvlinder, net iets vager. Hoeveel afdrukken lukken er?","Zet nu eens alleen stippen of alleen strepen: hoe ziet de vlinder er na het vouwen uit?"],"variations":["Lente: maak een hele zwerm en plak de vlinders tegen het raam.","Spiegelmonster: hetzelfde trucje, maar teken er daarna ogen, tanden en voelsprieten op.","Lieveheersbeestje: alleen rode verf met zwarte stippen, en knip er een rondje uit."],"themes":["lente"],"canStay":false,"pinQuery":"vlinder vouwschilderij peuter"},
  {"id":"handafdrukken","title":"Hand- en voetafdrukken als cadeautje","emoji":"✋","category":"verven","summary":"Een handje wordt een vogel, een voetje een pinguïn: maak samen afdrukken en tover ze om tot een cadeautje om te bewaren.","ageMin":1,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"duration":[10,20],"supervision":1,"soloFrom":null,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"plakkaatverf","note":"afwasbare kinderverf, 1-3 kleuren"},{"id":"penselen","note":"een dikke kwast"},{"id":"karton","note":"stevig, wit of gekleurd, of een dubbelgevouwen kaart"},{"id":"stiften","note":"een zwarte stift om de afdruk om te toveren"},{"id":"kom","note":"met lauw water, om meteen te wassen"},{"id":"doekje","note":"en een handdoek om af te drogen"}],"optional":[{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Zet alles vooraf klaar: karton, verf, een kwast, en een kom lauw water met een doekje en handdoek ernaast.","Schilder de handpalm of voetzool van je kind met een dun, gelijkmatig laagje verf. Dat kriebelt!","Druk het handje met gespreide vingers stevig op het karton, druk elke vinger even aan en til het recht omhoog.","Was handje of voetje meteen in de kom met water, voordat je kind ergens anders aan zit.","Laat de afdruk drogen en tover hem samen om met stift: een vogel, een boom, een bloem of een rendier.","Schrijf de naam en de datum erbij: over een paar jaar zie je hoe klein dat handje was."],"ageTips":{"young":"Doe het bij je dreumes snel, op een moment dat je kind uitgerust is, en liefst met z’n tweeën: één houdt vast, één verft. Een voetafdruk lukt vaak makkelijker dan een handje dat steeds dichtknijpt.","old":"Een kleuter verft de eigen hand, bedenkt zelf wat de afdruk wordt en tekent de details. Of leg handafdrukken van het hele gezin naast elkaar: wie heeft de grootste?"},"safety":["Gebruik afwasbare kinderverf: verf hoort niet in de mond, en een dreumes stopt een hand er zo in. Was handjes meteen na de afdruk.","Een verfvoetje is spekglad: laat je kind zitten tijdens de voetafdruk en til het daarna naar de kom water.","Verf vlekt op kleding, vloerkleed en voegen: werk op een knoeimat en trek oude kleren aan."],"say":["Kriebel kriebel! Klaar? Druk!","Hoe voelt de verf op je hand: koud en glibberig?","Kijk, daar is jouw handje, met vijf vingers!","Wat zou je handje kunnen worden: een vogel, een vis of een boom?","Wat hield je je hand goed stil, daardoor is de afdruk zo duidelijk."],"words":["hand","voet","vinger","teen","afdruk","kriebelen","stil"],"learn":["zintuigen","taal","creativiteit","rekenen"],"tips":["Lukt het niet in één keer? Vegen, wassen en nog eens: leg alvast twee of drie vellen klaar.","Druk op stevig karton of een gevouwen kaart in plaats van dun papier: dat krult niet en kun je zo inlijsten.","Doe het vlak voor badtijd: dan is schoonmaken meteen geregeld."],"extenders":["Druk ook eens een vuist, de zijkant van de hand of alleen een duim: welk dier of ding kun je daarvan maken?","Draai de droge afdruk een paar keer rond en bedenk samen wat hij nog meer kan worden: op z’n kop is een hand opeens een kwal of een inktvis.","Zet er vingertopstippen bij: bijtjes rond de bloem, ballonnen aan een touwtje of sneeuw boven het rendier."],"variations":["Moederdag: een bos bloemen van handafdrukken, met getekende steeltjes en een kaartje erbij.","Vaderdag: een zwarte voetafdruk met een witte buik en een getekende snavel wordt een stoere pinguïn.","Kerst: een groene handafdruk ondersteboven wordt een kerstboom, en een bruine voetafdruk met twee handjes als gewei een rendier.","Groeikalender: maak elk jaar op dezelfde dag een afdruk en bewaar ze samen."],"themes":["moederdag","vaderdag","cadeau","kerst"],"canStay":false,"pinQuery":"handafdruk verf cadeau kind"},
  {"id":"wattenstaafjes-stippen","title":"Stippen met wattenstaafjes","emoji":"🐞","category":"verven","summary":"Dippen, stippen, nog een stip: met wattenstaafjes maak je een boom vol herfstblaadjes, bloesem of sneeuw, of een lieveheersbeestje.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"wattenstaafjes","note":"een per kleur"},{"id":"plakkaatverf","note":"2-4 kleuren op een bord"},{"id":"papier","note":"wit of gekleurd"},{"id":"stiften","note":"om vooraf een boomstam of lieveheersbeestje te tekenen"}],"optional":[{"id":"elastiekjes","note":"om 5-6 wattenstaafjes te bundelen, voor kleine handjes"},{"id":"gekleurd-papier","note":"donkerblauw voor een sneeuwboom"},{"id":"oud-shirt"}],"steps":["Teken met stift een boomstam met takken, of een groot rondje met een streep erdoor voor een lieveheersbeestje.","Doe kleine klodders verf op een bord en leg bij elke kleur een eigen wattenstaafje.","Laat je kind het wattenstaafje rechtop in de verf dippen en stippen zetten: tik, tik, tik.","Stip de boom vol blaadjes, bloesem of sneeuw. Voor een lieveheersbeestje: eerst rood stippen, en als dat droog is zwarte stippen erop.","Tel samen de stippen of zoek de grootste en de kleinste stip.","Laat het plat drogen en gooi de gebruikte wattenstaafjes weg."],"ageTips":{"young":"Een tweejarige houdt een bundeltje van 5-6 wattenstaafjes met een elastiekje erom makkelijker vast, en dat maakt grote, vrolijke stippen. Het elastiekje doe jij om.","old":"Een kleuter kan een patroon stippen (rood, geel, rood), de stippen tellen of een letter of cijfer van stippen maken. Ook een uitdaging: alleen binnen de lijnen stippen."},"safety":["Elastiekjes zijn klein en kunnen terugschieten: doe het elastiekje zelf om het bundeltje en houd het in de gaten. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Wattenstaafjes horen niet in oren of neus: geef ze alleen aan tafel en ruim ze na afloop op.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf."],"say":["Tik! Nog een stip!","Hoeveel stippen heeft jouw lieveheersbeestje al?","Ik zie rode, gele en oranje blaadjes aan de boom.","Wat stip je precies, steeds op een nieuw plekje!","Wat gebeurt er als je heel zachtjes tikt? En heel hard?"],"words":["stip","tikken","boom","blaadje","veel","weinig","rij"],"learn":["fijne-motoriek","rekenen","concentratie","creativiteit"],"tips":["Geef elke kleur een eigen wattenstaafje: dan blijven de kleuren apart en hoef je minder bij te vullen.","Geen wattenstaafjes? Een vingertop of de gum achter op een potlood stipt ook prima."],"extenders":["Teken met stift een kronkelweg van rondjes op een nieuw vel: kan je kind op elk rondje precies één stip zetten?","Gooi met een dobbelsteen en zet net zoveel stippen als er ogen boven liggen: tel ze hardop mee.","Zet om de beurt een stip en laat samen een stippenslang over het hele vel kronkelen: welke kleur komt er nu?"],"variations":["Herfst: een boom vol rode, oranje en gele stippen, met een paar gevallen blaadjes eronder.","Lente: roze en witte stippen worden een bloesemboom.","Winter: witte stippen op donkerblauw papier worden een sneeuwboom of een sneeuwbui boven een huisje."],"themes":["herfst","winter","lente"],"canStay":false,"pinQuery":"stippen met wattenstaafjes boom"},
  {"id":"keukenla-kwasten","title":"Verven met spullen uit de keukenla","emoji":"🥄","category":"verven","summary":"Een garde, een vork of een aardappelstamper als kwast: ontdek samen welke sporen al die keukenspullen maken op een groot vel.","ageMin":1,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":5,"duration":[10,25],"supervision":2,"soloFrom":4,"cleanupMinutes":15,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"plakkaatverf","note":"2-3 kleuren, een flinke laag op een bord"},{"id":"groot-papier","note":"met tape vastgeplakt op tafel of vloer"},{"id":"schilderstape","note":"om het papier vast te plakken"},{"id":"garde","note":"een kleine garde"},{"id":"vork","note":"liefst een plastic vork"},{"id":"sponsjes","note":"een droog keukensponsje"},{"id":"bord","note":"een groot bord per kleur"}],"optional":[{"id":"tandenborstel","note":"of een afwasborstel"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Plak een groot vel papier met schilderstape vast en leg er een knoeimat onder.","Zoek samen in de keukenla naar ‘kwasten’: een garde, een vork, een aardappelstamper, een sponsje, een borstel.","Doe een laagje verf op een paar grote borden, zo breed dat het keukengerei er goed in past.","Laat je kind elk ding in de verf dopen en ermee stempelen, slepen of draaien.","Vergelijk de sporen: welke maakt strepen, welke stippen, en welke rondjes?","Laat het vel drogen en zet het keukengerei meteen in een bak sopje om te weken. Was het daarna goed af."],"ageTips":{"young":"Geef je dreumes grote, stevige spullen met een dik handvat, zoals een aardappelstamper of afwasborstel. Eén ding tegelijk, en jij doet mee: klop, klop!","old":"Een kleuter kan raden welk ding welk spoor maakte, een patroon stempelen of er een tekening van maken: met de vork gras, met de garde bloemen."},"safety":["Laat messen, de rasp en de kaasschaaf in de la: zoek samen alleen spullen zonder scherpe randen.","Was het keukengerei na afloop goed af voor het weer met eten in aanraking komt, of houd een paar oude spullen apart voor knutselen.","Plakkaatverf vlekt op kleding, tafel en vloer: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Klop! Kijk eens!","Wat denk je dat de garde maakt: strepen of rondjes?","Ik zie dunne lijntjes van de vork, net gras.","Welk ding uit de la gaan we nu proberen?","Je probeert alles uit, echt een onderzoeker!"],"words":["garde","vork","stempelen","streep","stip","slepen","draaien"],"learn":["ontdekken","creativiteit","fijne-motoriek","taal"],"tips":["Laat alles na afloop even weken in een bak sopje: opgedroogde verf krijg je moeilijk uit een garde.","Koop bij de kringloopwinkel een paar goedkope keukenspullen die alleen voor knutselen zijn."],"extenders":["Haal er een nieuw ‘kwastje’ bij als de aandacht zakt, zoals een flessenborstel, een plastic beker of een deksel: wat voor spoor maakt dat?","Verdeel een nieuw vel met stift in vakken en geef elk ding een eigen vak: hier alleen vorkstrepen, daar alleen gardebloemen.","Speel nadoen: jij zet een spoor met de garde, je kind zoekt hetzelfde ding en zet er een spoor naast."],"variations":["Herfst: sleep met een vork bruine takken en stempel er met een sponsje rode en gele blaadjes aan.","Badkamerla: verf met een oude tandenborstel, een haarborstel en een kam.","Speelgoedkist: stempel met duplo, autobandjes en de pootjes van speelgoeddieren."],"themes":[],"canStay":false,"pinQuery":"verven met keukengerei peuter"},
  {"id":"waterschilderen","title":"Schilderen met alleen water","emoji":"💧","category":"verven","summary":"Een dikke kwast en een bakje water: verf de tegels, een schoolbord of bruin karton donker en kijk hoe het als toverij weer verdwijnt.","ageMin":1,"ageMax":4,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"duration":[10,20],"supervision":2,"soloFrom":null,"cleanupMinutes":2,"noise":1,"energy":1,"places":["bad","vloer","muur"],"materials":[{"id":"penselen","note":"een dikke kwast, of een kleine verfroller"},{"id":"water","note":"een laagje van een paar centimeter"},{"id":"kom","note":"of een plastic beker, niet te vol"}],"optional":[{"id":"badkuip","note":"verf op de tegels in de lege badkuip of douche"},{"id":"dozen","note":"een opengevouwen bruine doos: wordt donker en droogt weer op"},{"id":"sponsjes","note":"voor brede natte banen"},{"id":"handdoek","note":"onder het bakje en om af te drogen"}],"steps":["Kies een plek: de tegels in de lege douche of badkuip, een schoolbord, of een opengevouwen bruine doos op de vloer.","Doe een laagje water van een paar centimeter in een bakje of beker.","Geef je kind een dikke kwast en laat het de tegels, het bord of het karton ‘verven’.","Kijk samen hoe het donker wordt waar de kwast komt, en hoe het na een tijdje weer opdroogt: weg is de tekening!","Schilder om de beurt een streep, een rondje of een gezichtje en wacht tot het verdwijnt.","Droog de vloer na afloop meteen af met een handdoek."],"ageTips":{"young":"Geef je dreumes een korte, dikke kwast of een sponsje en een bakje met een heel klein laagje water. Zitten in de lege douche of op een handdoek op de vloer werkt het best.","old":"Een vierjarige kan vormen, letters of de eigen naam ‘schrijven’ en kijken welke het eerst opdroogt. Of verf samen een hele tegelwand: lukt het voordat de eerste tegel droog is?"},"safety":["Laat een jong kind nooit alleen bij water, ook niet bij een laagje in een bakje of in de lege badkuip.","Gemorst water maakt tegels en vloer glad: dweil het direct op en laat je kind in de badkuip zitten in plaats van staan."],"say":["Nat! Kijk, donker!","Waar is je streep gebleven?","Ik zie dat het karton donker wordt waar de kwast komt.","Wat denk je: droogt een grote of een kleine vlek het eerst op?","Wat schilder je lekker door, alle tegels zijn al nat!"],"words":["nat","droog","donker","licht","verdwijnen","kwast","druppel"],"learn":["ontdekken","grove-motoriek","zintuigen","taal"],"tips":["Doe het vlak voor badtijd in de lege badkuip: je kind kan daarna zo in bad.","Een kleine verfroller of een oud sponsje maakt brede banen: ideaal voor kleine handjes die nog niet precies schilderen."],"extenders":["Geef iets nieuws om mee te schilderen, zoals een oude tandenborstel, een afwasborstel of een plantenspuit: welk spoor droogt het snelst op?","Schilder zelf een grote vorm of lijn met water en laat je kind hem met de kwast nasporen voordat hij opdroogt.","Zet een paar plastic speelgoedjes neer die ook een ‘verfbeurt’ krijgen, zoals een badeend, een autootje of een emmertje."],"variations":["Zomer: zet de bruine doos bij een zonnig raam en kijk hoe snel het water daar opdroogt.","Raadspel: schilder een simpele vorm en laat je kind raden wat het is voordat hij opdroogt.","Vingerschilderen: doop alleen een vinger in het water en teken op een schoolbord of op de tegels."],"themes":["zomer"],"canStay":false,"pinQuery":"schilderen met water peuter"},
  {"id":"vuurwerk-schilderij","title":"Vuurwerkschilderij met wc-rollen","emoji":"🎆","category":"verven","summary":"Knip een wc-rolletje in tot franjes, doop het in felle verf en stempel op donker papier: boem, daar gaat je eigen vuurwerk!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"wc-rollen","note":"2-3 lege rolletjes"},{"id":"schaar","note":"voor jou, om franjes te knippen"},{"id":"plakkaatverf","note":"felle kleuren: geel, rood, roze en wit"},{"id":"gekleurd-papier","note":"zwart of donkerblauw"},{"id":"bord","note":"een plat bord per kleur"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf franjes knippen"},{"id":"wattenstaafjes","note":"voor vonkjes tussen het vuurwerk"},{"id":"oud-shirt"}],"steps":["Knip een rolletje aan één kant rondom in tot halverwege, in stroken van ongeveer een halve centimeter (dat doe jij).","Buig de franjes naar buiten tot een platte bloem of zon.","Doe een laagje felle verf op een paar borden, met per kleur een eigen rolletje.","Laat je kind de franjes in de verf dopen en op het donkere papier drukken: boem, vuurwerk!","Stempel verschillende kleuren over elkaar heen en zet met een wattenstaafje vonkjes eromheen.","Laat het plat drogen en hang het op tegen oud en nieuw."],"ageTips":{"young":"Een tweejarige drukt vooral graag: houd het bij één rolletje en één kleur en roep samen ‘boem!’ bij elke stempel.","old":"Een kleuter knipt zelf de franjes met een kinderschaar, telt af van tien tot nul voor elke stempel of maakt een hele vuurwerkshow boven een getekende stad."},"safety":["Het inknippen doe jij, of je kleuter met een kinderschaar met ronde punt.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en werk op een knoeimat."],"say":["Boem! Nog een!","Welke kleur vuurwerk maken we nu?","Ik zie een gele ster met roze stralen eromheen.","Tellen we af? Drie, twee, één… boem!","Wat druk je stevig, alle franjes staan erop!"],"words":["vuurwerk","knal","franje","stralen","fel","donker","aftellen"],"learn":["creativiteit","fijne-motoriek","rekenen"],"tips":["Felle verf op donker papier geeft het meeste effect. Dekt een kleur niet goed, meng er dan een beetje wit door.","Gebruik de rolletjes een paar keer achter elkaar zonder af te spoelen: kleuren die mengen geven juist vrolijk vuurwerk."],"extenders":["Knip een nieuw rolletje met langere of juist kortere franjes (dat doe jij): wordt het vuurwerk groter of kleiner?","Draai het rolletje een stukje rond terwijl je het op het papier drukt: zo maak je een ronddraaiende vuurwerkzon.","Stempel ook eens met een vork of met de bodem van een plastic fles: welk soort vuurwerk wordt dat?"],"variations":["Oud en nieuw: maak er een nieuwjaarskaart van voor opa en oma.","Verjaardag: stempel vuurwerk op een groot vel als feestelijke versiering.","Lente: dezelfde franjestempel in roze en geel op wit papier wordt een veld vol bloemen."],"themes":["oudennieuw"],"canStay":false,"pinQuery":"vuurwerk stempelen wc rol"},
  {"id":"inpakpapier-stempelen","title":"Zelf inpakpapier stempelen","emoji":"🎁","category":"verven","summary":"Stempel een groot vel bruin papier vol met sponsjes, kurken en vormpjes: zo pak je cadeautjes in met papier dat je zelf hebt gemaakt.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,30],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"groot-papier","note":"bruin pakpapier of de achterkant van oud behang"},{"id":"plakkaatverf","note":"2-3 kleuren, op borden"},{"id":"sponsjes","note":"in eenvoudige vormen geknipt"},{"id":"schaar","note":"voor jou, om de sponsjes te knippen"},{"id":"schilderstape","note":"om het vel vast te plakken"}],"optional":[{"id":"kurken","note":"voor stippen"},{"id":"wc-rollen","note":"voor rondjes"},{"id":"uitsteekvormpjes","note":"liefst plastic; doop de rand in de verf"},{"id":"wasknijpers","note":"als handvat voor een sponsje"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Knip een paar sponsjes in eenvoudige vormen, zoals een ster, hartje of driehoek (dat doe jij).","Plak een groot vel bruin papier met schilderstape vast op tafel of vloer.","Doe een dun laagje verf op een paar borden en leg de stempels ernaast: sponsjes, kurken, wc-rolletjes en uitsteekvormpjes.","Laat je kind het vel vol stempelen, kriskras of in rijen.","Laat het vel een paar uur plat drogen en pak er daarna samen een cadeautje mee in."],"ageTips":{"young":"Geef een tweejarige grote stempels met een handvat, zoals een wc-rolletje of een sponsje in een wasknijper, en één kleur per keer. Kriskras stempelen is prima.","old":"Een kleuter kan een patroon bedenken (ster, ster, hart), in rijen stempelen of het papier ontwerpen voor iemand speciaal: welke kleuren vindt opa mooi?"},"safety":["Kurken en kleine vormpjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: houd ze bij je en tel ze na afloop.","Metalen uitsteekvormpjes hebben een scherpe rand: kies liever plastic vormpjes.","Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en leg een knoeimat neer."],"say":["Stempel! Nog een!","Welke vorm wil je nu stempelen?","Ik zie sterren, stippen en rondjes door elkaar.","Voor wie maken we dit papier? Wat zou die persoon leuk vinden?","Wat werk je goed door, het hele vel is al bijna vol!"],"words":["stempel","ster","rondje","stip","rij","inpakken","cadeau"],"learn":["creativiteit","fijne-motoriek","rekenen","samen"],"tips":["Pakpapier, oud behang of een opengeknipte papieren tas is goedkoop en beter voor het milieu dan glanzend cadeaupapier.","Stempel een paar dagen van tevoren: de verf moet helemaal droog zijn voor je gaat inpakken."],"extenders":["Knip er een nieuwe sponsvorm bij die je kind zelf kiest, zoals een maan, een vis of de eerste letter van de naam (dat doe jij).","Geef een nieuwe opdracht: stempel nu alleen langs de randen, als een lijst, of maak een rij van de ene kant van het vel naar de andere.","Stempel met twee stempels tegelijk, in elke hand één: klap, klap, twee afdrukken!"],"variations":["Sinterklaas: stempel mijters, sterren en pepernoten (vingertopstippen) en pak er de cadeautjes mee in.","Kerst: groene kerstboompjes en gele sterren op bruin papier, of witte sneeuwvlokken op rood papier.","Verjaardag: stempel ballonnen met een wc-rolletje en teken er touwtjes onder.","Cadeaulabel: stempel ook een klein stukje karton en schrijf er de naam op."],"themes":["sinterklaas","kerst","verjaardag","cadeau"],"canStay":false,"pinQuery":"inpakpapier stempelen kind"},
  {"id":"kerstkaart-vingerafdruk","title":"Kerstkaarten met vingerafdruk-lampjes","emoji":"🎄","category":"verven","summary":"Een zwarte stiftlijn wordt een snoer, vingertoppen drukken er gekleurde lampjes aan: zo maak je samen een stralende kerstkaart.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"karton","note":"stevig wit karton, dubbelgevouwen tot een kaart"},{"id":"stiften","note":"een zwarte stift voor het snoer"},{"id":"plakkaatverf","note":"3-4 felle kleuren, kleine klodders op een bord"},{"id":"doekje","note":"om vingers tussen de kleuren af te vegen"}],"optional":[{"id":"enveloppen","note":"om de kaart te versturen"},{"id":"wattenstaafjes","note":"als je kind liever niet met de vingers verft"},{"id":"oud-shirt"}],"steps":["Vouw een stuk karton dubbel tot een kaart en teken er met zwarte stift een golvende lijn overheen: het snoer.","Doe kleine klodders verf op een bord, elke kleur apart.","Laat je kind een vingertop in de verf dopen en een afdruk zetten langs de lijn: een lampje!","Veeg de vinger af aan een doekje en kies de volgende kleur. Wissel af: rood, geel, groen, blauw.","Teken na het drogen met stift een fitting op elk lampje en kleine streepjes eromheen: zo gaan ze stralen.","Schrijf samen een wens in de kaart en doe hem op de post."],"ageTips":{"young":"Pak bij een tweejarige het handje vast, steek samen één vinger uit en druk samen. Een paar lampjes is genoeg: het drukken is het leukste.","old":"Een kleuter maakt een kleurpatroon langs het snoer, telt de lampjes of tekent zelf het snoer en de fittingen. Probeer ook sneeuwpoppen of rendieren van vingerafdrukken."},"safety":["Plakkaatverf vlekt op kleding en tafel: kies afwasbare kinderverf en veeg vingers tussendoor af aan een doekje.","Laat glitter liever weg bij jonge kinderen (ogen, mond): een gouden of zilveren stift geeft ook glans."],"say":["Druk! Een lampje!","Welke kleur krijgt het volgende lampje?","Ik zie een rood, een geel en een groen lampje naast elkaar.","Voor wie maken we deze kaart?","Wat zet je je vinger precies op de lijn, goed gekeken!"],"words":["lampje","snoer","vingertop","afdruk","rij","kerst","stralen"],"learn":["fijne-motoriek","rekenen","creativiteit","taal"],"tips":["Teken een paar kaarten tegelijk voor: dan maakt je kind er in één keer een stapel van, voor opa, oma en de juf.","Laat de kaarten open en plat drogen voor je ze dichtvouwt, anders plakken ze aan elkaar."],"extenders":["Maak samen een lijstje van wie er een kaart krijgt, zoals oma, de juf en de buren, en laat je kind voor iedereen eigen lampkleuren kiezen.","Druk naast de vingertoplampjes ook grote duimlampen: welke zijn er meer, grote of kleine?","Zet een vingerafdruk-vogeltje op het snoer en teken er pootjes en een snaveltje bij."],"variations":["Sneeuwpoppen: twee witte vingerafdrukken boven elkaar op blauw karton, met een getekend sjaaltje en neus.","Rendieren: een bruine duimafdruk met een getekend gewei en een rode stip als neus.","Kerstboom: stip met vingertoppen gekleurde ballen in een getekende boom.","Winter: witte vingerafdrukken op donker papier worden een sneeuwbui."],"themes":["kerst","winter"],"canStay":false,"pinQuery":"kerstkaart vingerafdruk lampjes"},
  {"id":"marmerpapier-scheerschuim","title":"Marmerpapier met scheerschuim","emoji":"🌀","category":"verven","summary":"Druppel kleur op een laag schuim, trek er krullen door en druk je papier erop: elk vel wordt een uniek marmerkunstwerk.","ageMin":3,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"duration":[20,30],"supervision":2,"soloFrom":4,"cleanupMinutes":15,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"scheerschuim","note":"of zelfgemaakt zeepschuim"},{"id":"dienblad","note":"met een randje"},{"id":"kleurstof","note":"of plakkaatverf, 2-3 kleuren"},{"id":"karton","note":"of dik papier, iets kleiner dan het dienblad"},{"id":"ijsstokjes","note":"om mee te roeren én af te schrapen"}],"optional":[{"id":"pipet","note":"om druppels te maken"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Spuit een laag scheerschuim van een paar centimeter op het dienblad en strijk het glad met een ijsstokje.","Laat je kind druppels kleurstof of verf over het schuim verdelen.","Trek met een ijsstokje slingers en krullen door de kleuren. Niet te veel roeren, anders wordt het één kleur.","Druk een vel karton plat op het schuim en tel samen tot vijf.","Haal het karton eraf en schraap het schuim weg met een schoon ijsstokje: daar is je marmerpatroon!","Laat het vel drogen. Er is meestal schuim genoeg voor nog twee of drie afdrukken."],"ageTips":{"young":"Voor een driejarige is druppelen en roeren het leukste deel. Doe het afdrukken en afschrapen samen en laat het eindresultaat los.","old":"Kies samen passende kleuren (bijv. blauw en groen voor ‘zee’) en knip van het gedroogde marmerpapier vissen of een kaart."},"safety":["Scheerschuim is niet om te eten en prikt in de ogen: houd een doekje klaar en was handen meteen na afloop. Kies bij een gevoelige huid zeepschuim.","Kleurstof vlekt op kleding en tafel: trek een oud shirt aan en leg een knoeimat neer."],"say":["Kijk, de rode druppel blijft bovenop het schuim liggen!","Wat gebeurt er als je met je stokje door blauw en geel gaat?","Ik zie een krul hier en een slinger daar. Welke vind jij het spannendst?","Tel je mee? Eén, twee, drie, vier, vijf… en nu héél voorzichtig optillen."],"words":["schuim","druppel","krul","slinger","afdruk","luchtig"],"learn":["creativiteit","zintuigen","ontdekken"],"tips":["Werk naast de gootsteen of in een lege badkuip: dan spoel je alles direct weg.","Zet het dienblad op een oude handdoek die het schuim opvangt dat over de rand gaat."],"extenders":["Trek met een vork of een oude kam door de kleuren in plaats van met een ijsstokje: krijg je nu strepen of krullen?","Druk kleine kaartjes of uitgeknipte vormen op het schuim, zoals een hart of een vis: elk stuk krijgt een eigen patroon.","Spuit een nieuwe laag schuim over de restjes en marmer opnieuw met een nieuwe kleur: de oude kleuren worden een zachte achtergrond."],"variations":["Herfst: maak bruin-rood-gele vellen en knip er bladeren uit.","Kerst: knip van groen-wit marmerpapier kerstboompjes voor een kaart.","Inpakpapier: marmer een groot vel en pak er een cadeautje mee in."],"themes":[],"canStay":false,"pinQuery":"marmeren met scheerschuim kind"},
  {"id":"schilderrol-gang","title":"Een eindeloze schilderrol in de gang","emoji":"🖌️","category":"verven","summary":"Rol een lange baan papier uit in de gang en schilder elke dag een stukje verder: een weg, een rivier of een trein zonder einde.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":2,"places":["vloer"],"materials":[{"id":"groot-papier","note":"een rol oud behang of pakpapier van minstens drie meter"},{"id":"schilderstape","note":"om de baan om de halve meter op de vloer vast te plakken"},{"id":"plakkaatverf","note":"afwasbare kinderverf in drie of vier kleuren"},{"id":"penselen","note":"een dikke kwast per kleur, dan heb je geen waterpotje nodig"},{"id":"muffinvorm","note":"als verfpalet: een klodder verf per vakje"},{"id":"oud-shirt"}],"optional":[{"id":"oud-laken","note":"langs de randen of onder het verfpalet"},{"id":"sponsjes","note":"voor grote vlakken, zoals lucht en water"},{"id":"waskrijt","note":"voor een dag zonder verf"},{"id":"huishoudfolie","note":"om de verf in de muffinvorm af te dekken tot morgen"}],"steps":["Rol het papier uit langs de muur van de gang en plak het om de halve meter vast met schilderstape. Houd ernaast een looppad vrij.","Doe in elk vakje van de muffinvorm een klodder verf en zet er per kleur een kwast in. Leg een vochtig doekje klaar voor de handen.","Trek je kind een oud shirt aan en bedenk samen wat de rol wordt: een lange weg, een rivier, een trein met heel veel wagons?","Begin aan het ene eind en schilder samen een stukje. Je kind kruipt en schuift met het verfpalet mee naar het volgende lege stuk.","Stop als de zin op is, ook als de rol nog niet vol is: dan is er morgen nog iets om naar uit te kijken.","Laat de verf drogen en ga de volgende dag verder waar je gebleven was. Is de rol vol? Hang die op of rol een nieuwe baan uit."],"ageTips":{"young":"Geef een tweejarige twee kleuren en een dikke kwast of een sponsje, en blijf ernaast zitten. Grote vegen en stippen maken is al genoeg; benoem wat je ziet: een lange streep!","old":"Laat je kleuter een verhaal schilderen dat elke dag verdergaat, zoals een trein die door het bos, de stad en de zee rijdt. Schrijf jij er kleine zinnetjes onder die je kind vertelt."},"safety":["Plak het papier rondom goed vast en laat niemand over natte verf of losse randen lopen: papier op een gladde vloer schuift weg.","Kies afwasbare kinderverf: plakkaatverf kan vlekken op kleding, plinten en voegen. Leg een oud laken onder het verfpalet als je vloer snel vlekt.","Blijf bij een tweejarige die nog veel proeft ernaast zitten: kinderverf is niet giftig, maar hoort niet in de mond."],"say":["Streep! Nog een streep!","Waar gaat de weg naartoe, denk je?","Kijk eens hoe lang onze rol al is! Hoeveel grote stappen is dat?","Wat heb je gisteren geschilderd? Wat komt er vandaag naast?","Jij bent helemaal tot hier gekropen en hebt het hele stuk vol geschilderd!"],"words":["lang","kort","begin","einde","verder","naast","streep","vlak"],"learn":["creativiteit","grove-motoriek","fijne-motoriek","taal"],"tips":["Zet de muffinvorm op een dienblad: dan neem je verf en kwasten in één keer mee en vang je druppels op.","Geen gang? Leg de rol langs de muur van de woonkamer of de keuken, waar jij ook bezig bent. Als er maar een lange strook vloer is.","Dek de muffinvorm tussendoor af met huishoudfolie, dan droogt de verf niet uit en kun je morgen meteen verder."],"extenders":["Schuif het verfpalet een meter op naar een leeg stuk: een nieuwe plek voelt als een nieuw begin.","Zet een rij autootjes of diertjes aan het eind van de rol en laat je kind de weg naar ze toe schilderen.","Geef nieuw gereedschap: een sponsje, een wc-rolletje als stempel of een vork om gras te maken.","Doe één nieuwe kleur in de muffinvorm, bijvoorbeeld wit, en kijk samen waar die overal terechtkomt.","Maak samen een wandeling langs de rol: wat zien we hier, wie woont daar? Vaak wil je kind dan meteen iets bijschilderen."],"variations":["Weekdagboek: schilder elke dag één ding dat je die dag hebt gedaan, zo wordt de rol een dagboek van de week.","Verjaardag: maak samen een lange welkomstbanier en hang die in de gang als de visite komt.","Oud en nieuw: schilder een lange rij vuurwerk in felle kleuren en hang de rol op oudejaarsavond als slinger op.","Krijtrol: neem op een drukke dag waskrijt of stiften in plaats van verf, dan is er bijna niets op te ruimen."],"themes":[],"canStay":true,"stayTips":"Laat de verf drogen voordat er iemand langs loopt, spoel de kwasten uit en zet de afgedekte muffinvorm hoog weg. Houd naast de rol een looppad vrij; staat de rol in de weg, haal de tape dan los, rol het papier op en leg het morgen weer neer.","pinQuery":"lange papierrol schilderen kinderen"},
  {"id":"lijf-natekenen","title":"Je eigen lijf natekenen","emoji":"🧍","category":"tekenen","summary":"Je kind gaat op een groot vel liggen, jij trekt de omtrek na en samen maak je er een levensgrote ik-tekening van.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,30],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["vloer"],"materials":[{"id":"groot-papier","note":"iets langer dan je kind, bijv. een stuk oud behang of pakpapier"},{"id":"stiften","note":"een dikke stift voor de omtrek (dat doe jij)"},{"id":"waskrijt","note":"om het lijf in te kleuren"},{"id":"schilderstape","note":"om het papier op de vloer vast te plakken"}],"optional":[{"id":"gekleurd-papier","note":"om kleren uit te knippen en op te plakken"},{"id":"lijmstift"},{"id":"touw","note":"stukjes wol als haar"}],"steps":["Rol het papier uit op de vloer, iets langer dan je kind, en plak de hoeken vast met schilderstape.","Laat je kind op het papier gaan liggen in een houding naar keuze: armen wijd, benen gespreid of als een ster.","Trek met een dikke stift langzaam de omtrek na en vertel wat je doet: nu kom ik bij je oor, nu bij je knie!","Laat je kind voorzichtig opstaan en bekijk samen de omtrek: ben jij dat? Waar zitten je handen en voeten?","Maak het lijf samen af met een gezicht, haar, kleren en schoenen. Je kind kiest de kleuren.","Teken ook wat er binnenin zit: waar klopt je hart, en waar gaat je eten naartoe?","Hang de tekening op een deur en zet de datum erbij: over een paar maanden zie je hoeveel je kind gegroeid is."],"ageTips":{"young":"Een tweejarige ligt niet lang stil: zing een liedje terwijl je tekent, of trek eerst alleen handen en voeten na. Tik daarna de lichaamsdelen aan en benoem ze: hoofd, buik, voet!","old":"Laat je kleuter jouw omtrek natekenen, of tel samen hoeveel handen lang de tekening is. Zoek in een boek op waar je hart, longen en maag zitten en teken ze erin."},"safety":["Plak het papier rondom goed vast: los papier op een gladde vloer schuift weg als je kind opstaat of eroverheen loopt.","Teken niet vlak langs het gezicht: trek het hoofd na als een ruim rondje, dan blijft de stift uit de buurt van ogen en neus."],"say":["Ik teken langs je arm… kriebelt dat?","Kijk eens, dat ben jij! Waar zijn je voeten?","Welke kleur krijgt jouw broek? En je haar?","Waar denk jij dat je hart zit? Voel maar: boem-boem.","Hoofd! Buik! Voet!"],"words":["hoofd","buik","knie","elleboog","hart","lang","binnenin"],"learn":["taal","creativiteit","fijne-motoriek"],"tips":["Geen groot papier? Plak vier tot zes A4’tjes met plakband aan elkaar of vouw een grote doos open.","Leg er een laag kranten onder als je op parket of vloerbedekking tekent: een stift die doordrukt, geeft af.","Rol de tekening op en bewaar hem: elk jaar opnieuw natekenen laat mooi zien hoe je kind groeit."],"extenders":["Knip kleren, zakken of een kroon uit gekleurd papier en laat je kind ze met de lijmstift op het lijf plakken.","Teken een tweede omtrek in een andere houding, bijvoorbeeld rennend of springend, in een andere kleur over de eerste heen.","Laat je kind ‘pleisters’ van schilderstape plakken op plekjes die weleens pijn deden, zoals een knie of een elleboog: wat gebeurde er toen?"],"variations":["Omgekeerd: je kind trekt jouw hand, voet of hele lijf na, en nu moet jij stilliggen!","Verkleden op papier: maak van het lijf een astronaut, ridder, prinses of tijger.","Familieportret: teken iedereen in huis na en hang de lijven naast elkaar op, van groot naar klein."],"themes":[],"canStay":true,"stayTips":"Hang het lijf met schilderstape op een deur, op kindhoogte, en zet een bakje waskrijt ernaast: zo tekent je kind er de volgende dagen kleren, haar of een hart bij. Zet het bakje hoog weg als er jongere kinderen rondlopen.","pinQuery":"omtrek lichaam natekenen kind"},
  {"id":"tekenen-onder-tafel","title":"Tekenen onder de tafel","emoji":"🙃","category":"tekenen","summary":"Plak papier onder het tafelblad, kruip eronder en teken op je rug: net een kunstenaar die een plafond beschildert.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["vloer"],"materials":[{"id":"groot-papier","note":"of een paar A4’tjes, samen zo groot als het tafelblad"},{"id":"schilderstape","note":"flinke stroken, om het papier onder het tafelblad te plakken"},{"id":"waskrijt","note":"dikke krijtjes; die blijven ook werken als je ze omhoog houdt"},{"id":"dekens","note":"kussens of een opgevouwen deken om op te liggen"}],"optional":[{"id":"kleurpotloden"},{"id":"zaklamp","note":"als het onder de tafel wat donker is"},{"id":"stickers","note":"om een plafond vol sterren te plakken"}],"steps":["Haal alles van de tafel af, ook het tafelkleed, en schuif de stoelen weg.","Plak een vel papier met flinke stroken schilderstape onder het tafelblad en druk alle randen goed aan.","Leg kussens of een opgevouwen deken onder de tafel, zodat je kind lekker op de rug kan liggen.","Kruip er samen onder en geef je kind een paar dikke krijtjes: kun je bij het papier?","Teken liggend: lijnen, rondjes, krassen. Vertel dat sommige kunstenaars hele plafonds beschilderen.","Neem pauzes, want je armen omhoog houden is zwaar. Schud ze los en ga daarna weer verder.","Haal het papier er voorzichtig af en bewonder samen het plafondschilderij."],"ageTips":{"young":"Plak voor een tweejarige het papier onder een lage salontafel, zodat het dichtbij is. Een dik krijtje dat in de vuist past werkt het best; lig er zelf naast en doe het voor.","old":"Geef je kleuter een opdracht: een sterrenhemel, vogels die over je heen vliegen of het plafond van een kasteel. Vergelijk daarna met tekenen aan tafel: wat was moeilijker, en waarom?"},"safety":["Afgebroken stukjes krijt kunnen op het gezicht vallen: kies dikke krijtjes en laat je kind niet met iets in de mond op de rug liggen.","Leer je kind eerst opzij te rollen en dan onder de tafel uit te kruipen, zodat het niet met het hoofd tegen het tafelblad stoot."],"say":["Kras, kras! Nog een rondje!","Kijk omhoog! Waar is je papier?","Voel je je armen? Het is zwaar werk om zo te tekenen.","Wat zie je boven je? Zullen we de lucht vol vogels tekenen?","Wat is er anders dan tekenen aan tafel, denk jij?"],"words":["onder","boven","omhoog","plafond","liggen","zwaar","kunstenaar"],"learn":["grove-motoriek","fijne-motoriek","creativiteit"],"tips":["Stiften werken op hun kop slecht, omdat de inkt van de punt wegloopt. Waskrijt en kleurpotloden blijven het wel doen.","Maak er een hut van: hang een deken over de tafel en geef je kind een zaklamp. Dan wordt tekenen een geheime missie."],"extenders":["Klop zachtjes op het tafelblad: kan je kind horen waar je klopte en daar een rondje tekenen?","Wissel van hand, of geef in elke hand een krijtje: lukt tekenen op je rug nu ook nog?","Plak een paar stickers op het papier en laat je kind ze met krijtlijnen verbinden tot sterrenbeelden of een weg."],"variations":["Grottekening: hang een deken over de tafel en teken bij zaklamplicht dieren op het plafond, net als de eerste mensen in hun grot.","Muurschildering: plak het papier tegen de muur of een deur en teken staand, met je arm zo hoog mogelijk.","Sterrenhemel: plak donker papier onder de tafel en maak er een nachtlucht van met stickers of geel krijt."],"themes":[],"canStay":true,"stayTips":"Laat het papier gerust een paar dagen onder de tafel zitten en leg een kussen en een bakje dikke krijtjes klaar: dan kruipt je kind er zo weer onder. Druk de tape elke dag even aan en laat ruimte tussen de stoelen, zodat je kind makkelijk onder de tafel uit kan.","pinQuery":"tekenen onder de tafel kind"},
  {"id":"tekenen-op-muziek","title":"Tekenen op muziek","emoji":"🎶","category":"tekenen","summary":"Zet muziek op en laat het krijtje meedansen: snel en wild bij vrolijke muziek, langzaam en zacht bij een slaapliedje.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":2,"energy":2,"places":["tafel","vloer","muur"],"materials":[{"id":"groot-papier","note":"of een paar A4’tjes aan elkaar geplakt"},{"id":"schilderstape","note":"om het papier vast te plakken, zodat het niet wegschuift"},{"id":"waskrijt","note":"dikke krijtjes; voor dreumesen blokkrijt"},{"id":"muziek","note":"een mix van snelle en langzame liedjes"}],"optional":[{"id":"stiften","note":"voor kleuters die ook dunne lijntjes willen"}],"steps":["Plak een groot vel papier met schilderstape op tafel of op de vloer, zodat het niet wegschuift.","Zet een rustig liedje op en teken samen langzaam mee: lange, zachte lijnen, als golfjes in het water.","Wissel na een minuutje naar snelle, vrolijke muziek: stippen, krassen en zigzaggen maar!","Zet de muziek af en toe stil: dan stopt het krijtje ook. Wie kan het best bevriezen?","Probeer het ook met twee handen tegelijk: in elke hand een krijtje, en dans maar over het papier.","Bekijk samen het vel: waar was de muziek snel en waar langzaam? Hang het op of gebruik het als inpakpapier."],"ageTips":{"young":"Een dreumes krast vooral, en dat is prima. Geef een dik blokkrijtje of één krijtje per vuist en wieg en stamp zelf mee op de muziek.","old":"Laat je kleuter vooraf kiezen welke kleur bij boze, blije of slaperige muziek past. Of teken met de ogen dicht en raad daarna welk stukje bij welk liedje hoort."},"safety":["Dreumesen stoppen krijtjes graag in de mond: kies dikke krijtjes die niet snel afbreken en ruim afgebroken stukjes meteen op.","Zet de muziek niet te hard: als je elkaar niet meer gewoon kunt verstaan, is het te luid voor jonge oren."],"say":["Hoor je dat? Snel, snel, snel!","Deze muziek is zacht. Kan jouw krijtje ook zacht dansen?","Ik zie allemaal kleine stipjes. Was de muziek toen snel of langzaam?","Welke kleur past bij dit liedje, denk jij?","Stop! Bevriezen… en weer verder!"],"words":["snel","langzaam","hard","zacht","golf","zigzag","stip","stop"],"learn":["creativiteit","zintuigen","grove-motoriek"],"tips":["Maak vooraf een afspeellijst met afwisselend snelle en langzame nummers, dan hoef je tijdens het tekenen niet te zoeken.","Plak het papier ook eens op de muur of een deur: staand tekenen met grote armbewegingen voelt nog meer als dansen."],"extenders":["Draai de rollen om: je kind bedient de muziek en zet hem stil, en jij moet bevriezen met je krijtje.","Teken alleen als je een bepaald geluid hoort, zoals een trommel of een zangstem, en stop zodra het weg is.","Plak een nieuw vel op de muur en teken staand verder: hoog bij hoge tonen, laag bij lage tonen."],"variations":["Kleurenmuziek: pak bij elk nieuw liedje een andere kleur en tel achteraf hoeveel liedjes je hebt gehoord.","Verfversie: doe hetzelfde met vingerverf of een dikke kwast. Leg dan wel een knoeimat neer.","Winter: teken bij rustige muziek dwarrelende sneeuwvlokken en bij snelle muziek een sneeuwstorm."],"themes":[],"canStay":false,"pinQuery":"tekenen op muziek peuter"},
  {"id":"bladeren-wrijven","title":"Bladeren wrijven: zie de nerven verschijnen","emoji":"🍂","category":"tekenen","summary":"Leg een blad onder dun papier en wrijf er met de zijkant van een krijtje over: als bij toverslag verschijnen de nerven.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"bladeren","note":"eerder verzameld; platte, niet te droge bladeren in verschillende vormen"},{"id":"papier","note":"dun wit papier, bijv. printpapier"},{"id":"waskrijt","note":"papiertje eraf gehaald, of afgebroken stukjes"},{"id":"schilderstape","note":"om het papier vast te zetten"}],"optional":[{"id":"kinderschaar","note":"om de afdrukken uit te knippen"},{"id":"kranten","note":"om de bladeren een nacht plat te drukken"}],"steps":["Haal het papiertje van een paar waskrijtjes af. Een afgebroken stuk werkt ook prima.","Leg een blad met de bobbelige onderkant naar boven op tafel: daar zitten de nerven het dikst.","Leg een vel dun papier eroverheen en plak de randen vast met schilderstape, zodat er niets verschuift.","Wrijf met de lange zijkant van het krijtje over het papier, van het midden naar buiten. Kijk: daar komt het blad!","Schuif een volgend blad onder een leeg stuk van het vel en wrijf met een andere kleur.","Vergelijk samen de afdrukken: welk blad heeft de meeste nerven? Hang het vel op of knip de bladeren uit."],"ageTips":{"young":"Plak voor een tweejarige zowel het blad als het papier vast, zodat er niets schuift. Kies grote, stevige bladeren zoals eiken- of kastanjeblad en wrijf samen, hand over hand.","old":"Laat je kleuter raden welk blad bij welke afdruk hoort, of zoek samen de namen op: eik, esdoorn, beuk. Ook leuk: wrijf één blad met twee kleuren over elkaar."},"safety":["Leg alleen bladeren klaar, geen bessen, eikels of kastanjes: die zijn niet eetbaar en klein. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Ruim kleine brokjes waskrijt meteen op: peuters stoppen ze graag in de mond."],"say":["Wrijf, wrijf… kijk, daar komt hij!","Ik zie lijntjes in het blad. Weet je hoe die heten? Nerven!","Welk blad is het grootst? En welk blad voelt het ruwst?","Wat denk je dat er gebeurt als je heel zacht wrijft? En heel hard?","Je hebt heel geduldig het hele blad laten verschijnen."],"words":["blad","nerf","steel","ruw","glad","wrijven","verschijnen"],"learn":["fijne-motoriek","ontdekken","zintuigen"],"tips":["Leg vers geraapte bladeren een nacht plat tussen kranten onder een stapel boeken: dan zijn ze droog en plat, maar nog niet knisperig.","Geen bladeren in huis? Wrijf over een deurmat, de zool van een gymschoen, een vergiet of een kam: overal zitten verborgen patronen."],"extenders":["Draai het blad om, met de gladde kant naar boven: zie je nu nog nerven? Welke kant werkt het best?","Wrijf hetzelfde blad steeds een stukje verder in een cirkel, telkens in een andere kleur: zo maak je een bladerenkrans.","Leg een blad onder het vel terwijl je kind de ogen dicht heeft: kan het voelen waar het ligt en het tevoorschijn wrijven?"],"variations":["Herfstboom: teken een stam met takken en wrijf er rondom bladeren in rood, oranje en geel bij.","Wrijfjacht door het huis: zoek dingen met reliëf, wrijf ze over en raad later samen wat wat was.","Lente: wrijf over jonge blaadjes en platte bloemen en maak er een kaart van."],"themes":["herfst"],"canStay":false,"pinQuery":"bladeren wrijven waskrijt kind"},
  {"id":"krabbelspel","title":"Het krabbelspel: maak er iets van!","emoji":"✏️","category":"tekenen","summary":"Om de beurt zet je een kras op papier en de ander tovert er iets van: wordt het een slang, een hoed of een monster?","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":1,"duration":[10,20],"supervision":1,"soloFrom":4,"cleanupMinutes":1,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"papier","note":"een stapeltje, ook de achterkant van oud printpapier"},{"id":"stiften","note":"twee kleuren: één voor de krabbel, één om af te maken"}],"optional":[{"id":"kleurpotloden","note":"om de tekening daarna in te kleuren"},{"id":"nietmachine","note":"om de vellen tot een krabbelboekje te nieten (dat doe jij)"}],"steps":["Leg een stapel papier klaar en pak allebei een stift in een andere kleur.","Zet jij een kras op het eerste vel: een krul, een zigzag of een lus. Niet nadenken, gewoon krabbelen.","Laat je kind het vel draaien en goed kijken: wat zou dit kunnen worden? Een slurf? Een golf?","Laat je kind de krabbel afmaken met de andere kleur. Vraag wat het is geworden en schrijf dat erbij.","Wissel om: nu krabbelt je kind en maak jij er iets van. Denk hardop na over wat je ziet.","Leg alle vellen naast elkaar, of maak er met de nietmachine een krabbelboekje van om later samen te lezen."],"ageTips":{"young":"Een driejarige ziet nog niet altijd iets in een kras. Draai het vel samen rond en raad hardop: is dit een staart? Van wie? Ogen en pootjes erbij tekenen is al genoeg.","old":"Laat je kleuter jouw krabbel afmaken terwijl jij tot twintig telt, of verzin samen een verhaal waarin alle krabbelfiguren meedoen."},"safety":["Stiftdopjes zijn klein en worden graag op gekauwd: leg ze op een vaste plek en houd ze weg bij jongere broertjes of zusjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Kras! Jouw beurt!","Wat zie jij in deze kras?","Als ik het vel omdraai… wordt het dan iets anders?","Van mijn krul heb jij een slakkenhuis gemaakt! Hoe kwam je op dat idee?","Hmm, wat zou ik hiervan maken? Help jij me?"],"words":["krul","lus","zigzag","omdraaien","beurt","raden","afmaken"],"learn":["creativiteit","samen","taal","fijne-motoriek"],"tips":["Houd een paar makkelijke krabbels achter de hand voor als je kind vastloopt: een cirkel met een staartje, een golflijn of een driehoek.","Er bestaan hier geen foute antwoorden: of de kras nu een draak wordt of ‘gewoon een kras’ blijft, het gaat om het fantaseren."],"extenders":["Teken vijf krabbels vooruit op losse vellen: dan kan je kind een hele stapel achter elkaar afmaken, ook als jij even iets anders doet.","Zet twee krabbels op één vel: kan je kind er samen één ding van maken?","Kies een thema voordat je krabbelt, zoals dieren, eten of de zee: elke krabbel moet daar iets van worden."],"variations":["Krabbelpost: stuur een krabbel in een envelop naar opa of oma en vraag of zij hem afmaken en terugsturen.","Vouwmonster: vouw een vel in drieën en teken om de beurt een hoofd, een lijf en benen zonder te kijken. Vouw het daarna open!","Wachtkamerspel: dit spel kan overal, met één pen en een notitieboekje in je tas."],"themes":[],"canStay":false,"pinQuery":"krabbel afmaken tekenspel kind"},
  {"id":"stad-tekenen","title":"Een stad tekenen voor je autootjes","emoji":"🚗","category":"tekenen","summary":"Teken samen wegen, een rotonde, huizen en parkeerplaatsen op een groot vel en speel daarna in je eigen stad met de autootjes.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[20,40],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer","tafel"],"materials":[{"id":"groot-papier","note":"zo groot mogelijk: oud behang, pakpapier of een opengevouwen doos"},{"id":"stiften","note":"een dikke zwarte stift voor de wegen"},{"id":"waskrijt","note":"voor gras, water en huizen"},{"id":"schilderstape","note":"om het papier op de vloer vast te plakken"},{"id":"speelgoedautos"}],"optional":[{"id":"dozen","note":"kleine doosjes als huizen of garage"},{"id":"duplo","note":"om gebouwen en bruggen langs de weg te bouwen"},{"id":"stickers","note":"als verkeersborden of stoplichten"}],"steps":["Plak een groot vel papier met schilderstape op de vloer of de salontafel.","Teken samen met een dikke stift een paar brede wegen: recht, met bochten, en een rotonde in het midden.","Bedenk wat er nog meer in jullie stad moet: je eigen huis, de winkel, een garage, een park of een vijver.","Laat je kind gras, water en huizen inkleuren. Jij tekent parkeervakken en een zebrapad.","Pak de autootjes en speel: rijd naar de bakker, parkeer bij huis en stop voor het zebrapad.","Laat de stad een paar dagen liggen of rol hem op. Je kunt er later altijd nog wegen bij tekenen."],"ageTips":{"young":"Teken voor een tweejarige zelf een paar brede wegen en laat je kind krassen in het gras en het water. Rijden en toet-toet roepen is voor een peuter het leukste deel.","old":"Laat je kleuter een plattegrond van jullie eigen buurt maken: waar staat ons huis, waar is school? Zet nummers bij de parkeervakken en parkeer er net zoveel auto’s in."},"safety":["Plak het papier rondom vast: op een gladde vloer schuift los papier weg als je kind erop rent of knielt.","Kijk de autootjes na op losse wieltjes of kapotte onderdelen als er ook kleintjes meespelen: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Vroem! Waar rijdt jouw auto naartoe?","Ik zie een lange, bochtige weg. Waar komt die uit?","Hoeveel auto’s passen er op de parkeerplaats? Zullen we tellen?","Wat moet de auto doen bij het zebrapad?","Jij hebt een hele stad bedacht, met een park én een garage!"],"words":["weg","bocht","rotonde","parkeren","links","rechts","voor","achter"],"learn":["creativiteit","taal","rekenen","fijne-motoriek"],"tips":["Gebruik schilderstape als snelweg: een strook tape op het papier of direct op de vloer is meteen een weg.","Rol de stad na het spelen op en doe er een elastiekje om: op een regenachtige dag heb je hem zo weer tevoorschijn."],"extenders":["Geef ritopdrachten: breng als taxi de knuffel naar de bakker, haal een pakje op bij de garage en parkeer daarna in vak 3.","Plak een extra vel aan de rand en bouw de stad uit met een brug, een haven of een vliegveld.","Teken verkeersborden op kleine kaartjes en zet ze rechtop tegen een blokje: stop, links, rechtdoor."],"variations":["Boerderij: teken weilanden, een sloot en een stal en speel met tractors en speelgoeddieren.","Treinbaan: teken rails met dwarsliggers en een station en laat de knuffels instappen.","Dozenstad: zet lege doosjes als huizen langs de weg en teken er ramen en deuren op."],"themes":[],"canStay":true,"stayTips":"Laat de stad met schilderstape op de vloer liggen op een plek waar niemand er steeds overheen hoeft, met de autootjes in een bak ernaast. Ligt hij in de weg, rol hem dan op met een elastiekje erom en rol hem de volgende dag weer uit.","pinQuery":"wegen tekenen groot papier autootjes"},
  {"id":"schaduw-natekenen","title":"Schaduwen natekenen","emoji":"🔦","category":"tekenen","summary":"Zet een speelgoeddier voor een zaklamp, teken zijn schaduw na op papier en kleur hem in: wordt het een dino of een olifant?","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":2,"noise":1,"energy":1,"places":["muur","vloer"],"materials":[{"id":"zaklamp","note":"of de lamp van je telefoon"},{"id":"klein-speelgoed","note":"speelgoeddieren met een duidelijke vorm, zoals een giraffe of dino"},{"id":"papier"},{"id":"stiften","note":"of een potlood om de schaduw na te trekken"},{"id":"schilderstape","note":"om het papier tegen de muur of een doos te plakken"}],"optional":[{"id":"waskrijt","note":"om de schaduwen in te kleuren"},{"id":"dozen","note":"een grote doos om het papier tegenaan te plakken"}],"steps":["Maak de kamer een beetje donker: gordijnen dicht en de grote lamp uit.","Plak een vel papier tegen de muur, op de hoogte waar je kind zittend kan tekenen, of tegen een grote doos die rechtop staat.","Zet een speelgoeddier vlak voor het papier en leg de zaklamp er een stukje voor op een stapel boeken, zodat hij op het dier schijnt.","Schuif samen met de lamp: dichterbij maakt de schaduw groot, verder weg klein. Kies de schaduw die jullie het mooist vinden.","Laat je kind naast het papier zitten en de rand van de schaduw natrekken. Wie voor de lamp zit, tekent de eigen schaduw!","Haal het dier weg en kleur de schaduw in. Raad daarna bij elkaars tekeningen: welk dier was dit?"],"ageTips":{"young":"Voor een driejarige is de zaklamp aan- en uitdoen al spannend genoeg. Kies grote dieren met een duidelijke vorm, zoals een olifant of dino, en trek de schaduw samen na, hand over hand.","old":"Laat je kleuter hetzelfde dier groot én klein natekenen door de lamp te verschuiven en vergelijk: wat is er veranderd? Of trek samen de schaduw van jouw hoofd na als profiel."},"safety":["Kijk niet recht in de zaklamp en schijn niet in elkaars ogen: een felle lamp doet van dichtbij pijn aan de ogen.","Speelgoeddiertjes zijn soms klein: houd ze weg bij jongere broertjes of zusjes, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Licht aan! Kijk, een schaduw!","Wat denk je dat er gebeurt als ik de lamp dichterbij schuif?","Ik zie een lange nek en kleine oortjes. Welk dier zou dit zijn?","Je trekt heel nauwkeurig langs de rand, steeds een stukje verder.","Waar is jouw eigen schaduw gebleven?"],"words":["schaduw","licht","donker","groot","klein","dichtbij","ver weg","rand"],"learn":["ontdekken","fijne-motoriek","concentratie"],"tips":["Een zaklamp met een smalle, felle bundel geeft de scherpste schaduw. Het lampje van je telefoon werkt ook, op een stapel boeken.","Vindt je kind het donker spannend? Laat een klein lampje aan en laat je kind zelf de zaklamp aan- en uitknippen."],"extenders":["Draai het dier een kwartslag of leg het op z’n kant: hoe ziet de schaduw er nu uit? Trek hem in een andere kleur over de eerste heen.","Zet twee dieren zo neer dat hun schaduwen elkaar raken en maak er één fantasiedier van: een giraffe met een dinostaart?","Haal iets uit de keukenla of de speelgoedkist, zoals een garde, een vork of een blokkentoren: welke schaduw is het gekst?"],"variations":["Schaduwportret: laat je kind van opzij voor de lamp zitten en trek het profiel na op papier tegen de muur.","Halloween: teken de schaduwen van spinnen en vleermuizen na op oranje papier en hang ze voor het raam.","Schaduwmemory: teken een paar schaduwen na en laat je kind daarna bij elke schaduw het juiste dier zetten."],"themes":[],"canStay":false,"pinQuery":"schaduw natekenen speelgoeddieren"},
  {"id":"kraskunst","title":"Kraskunst: regenboog onder zwart","emoji":"🎆","category":"tekenen","summary":"Kleur een vel vol felle kleuren, verstop alles onder zwart waskrijt en kras er tekeningen in: vuurwerk en sterren verschijnen!","ageMin":4,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[25,35],"supervision":3,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"karton","note":"wit karton of stevig papier; een klein vel (A5) is sneller vol"},{"id":"waskrijt","note":"felle, lichte kleuren en zwart"},{"id":"ijsstokjes","note":"om mee te krassen; een lege balpen kan ook"},{"id":"schilderstape","note":"om het vel vast te plakken, zodat het niet wegschuift"}],"optional":[{"id":"kranten","note":"als onderlegger voor de krijtkruimels"},{"id":"plakkaatverf","note":"zwart, als snellere bovenlaag (dan wordt het wel vies)"}],"steps":["Plak het karton met schilderstape vast op tafel, zodat het niet wegschuift als je hard drukt.","Laat je kind het hele vel dik inkleuren met felle kleuren, in vlakken of strepen. Er mag geen wit meer te zien zijn.","Kleur daarna alles over met zwart waskrijt en druk stevig. Wissel gerust af: het is veel werk voor kleine armen.","Kras met een ijsstokje tekeningen in het zwart: vuurwerkpijlen, sterren, krullen. De regenboog komt tevoorschijn!","Veeg de zwarte kruimels bij elkaar en hang het kunstwerk op."],"ageTips":{"young":"Voor een vierjarige is twee keer inkleuren veel. Neem een klein vel zo groot als een ansichtkaart en kleur de zwarte laag samen: jij de ene helft, je kind de andere.","old":"Laat je kleuter vooraf plannen: waar komt het vuurwerk, waar de maan? Kras ook patronen zoals stippen, zigzag en spiralen, of schrijf je naam en het nieuwe jaartal."},"safety":["Kras met een ijsstokje en niet met een satéprikker of schaarpunt: een scherpe punt schiet makkelijk uit en dan zit je zo in je hand.","Verf je de zwarte laag met plakkaatverf, kies dan afwasbare kinderverf en trek een oud shirt aan: zwart vlekt op kleding en tafel."],"say":["Ik zie geen wit meer. Wat heb je dat goed volgehouden!","Alles is zwart… wat zou eronder verstopt zitten?","Kras! Kijk, rood!","Welke kleur denk je dat er tevoorschijn komt als je hier krast?","Hoor je het krassen? Hoe voelt het in je hand?"],"words":["krassen","verstoppen","tevoorschijn","vuurwerk","fel","zwart","regenboog"],"learn":["fijne-motoriek","concentratie","creativiteit"],"tips":["Kleur de onderlaag met lichte, felle kleuren zoals geel, oranje, roze en lichtblauw: donkere kleuren zie je straks nauwelijks.","Werk op een krant: de zwarte krijtkruimels geven af op tafel, kleding en vloerbedekking, en zo vouw je ze in één keer weg.","Sneller klaar: verf de zwarte laag met plakkaatverf met een druppel afwasmiddel erdoor, dan blijft de verf beter op het krijt zitten. Laat hem helemaal drogen voordat je krast."],"extenders":["Kras met ander gereedschap: een plastic vork maakt een paar lijnen tegelijk, een kam nog meer. Welke vuurwerkpijlen worden het mooist?","Kras om de beurt een stukje van iets, zoals een oor, een staart of een dak: wie raadt het eerst wat het wordt?","Kras een doolhof of kronkelweg en laat een vinger de weg naar de uitgang zoeken."],"variations":["Oud en nieuw: kras vuurwerkpijlen en knallen in een zwarte nachtlucht en hang ze voor het raam.","Sterrenhemel: maak de onderlaag geel en oranje en kras een maan, sterren en een raket.","Onderwater: kras vissen, kwallen en zeewier in een regenboogzee.","Nieuwjaarskaart: maak een klein krasvel op een dubbelgevouwen kaart voor opa en oma."],"themes":["oudennieuw"],"canStay":false,"pinQuery":"kraskunst waskrijt zwart kind"},
  {"id":"tekening-voor-de-schoen","title":"Een tekening voor in je schoen","emoji":"👞","category":"tekenen","summary":"Maak een tekening voor Sinterklaas, leg er een wortel voor het paard bij en zing samen een liedje bij de schoen.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[10,25],"supervision":1,"soloFrom":2,"cleanupMinutes":1,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"papier","note":"of gekleurd papier, opgerold of gevouwen past het in de schoen"},{"id":"waskrijt","note":"dikke krijtjes voor de kleinsten"},{"id":"groente","note":"een wortel voor het paard"}],"optional":[{"id":"stiften","note":"voor oudere kinderen"},{"id":"stickers","note":"om de tekening te versieren"},{"id":"potlood","note":"om naam, datum en wat je kind vertelt erbij te schrijven"}],"steps":["Vertel dat Sinterklaas in het land is en dat kinderen hun schoen mogen zetten. Wat zou hij leuk vinden?","Leg papier en krijtjes klaar en laat je kind tekenen: het paard, de stoomboot, een pakje of gewoon fijne krassen.","Vraag wat er op de tekening staat en schrijf het er klein bij, samen met de naam en de datum.","Rol de tekening op of vouw hem dubbel en laat je kind hem in de schoen stoppen, met de wortel voor het paard.","Zet de schoen bij de schoorsteen, de verwarming of de voordeur en zing samen een sinterklaasliedje.","Haal ’s avonds stiekem de tekening en de wortel eruit (bewaar de tekening!) en kijk ’s ochtends samen in de schoen."],"ageTips":{"young":"Een dreumes krast vooral, en dat is precies goed. Geef één dik krijtje, zeg wat je ziet (wat een rode strepen voor Sinterklaas!) en laat je kind zelf de tekening in de schoen stoppen.","old":"Laat je kleuter een tekenbrief maken: wat wil je kind Sinterklaas vertellen? Schrijf letterlijk op wat het zegt, of laat het zelf de eerste letter van de eigen naam schrijven."},"safety":["Zet de schoen niet tegen een kachel, open haard of brandende kaarsjes: papier vat snel vlam.","Laat een dreumes niet op de rauwe wortel kauwen: een harde hap kan in de keel schieten. De wortel is voor het paard!","Dreumesen stoppen krijtjes graag in de mond: geef dikke krijtjes en ruim afgebroken stukjes meteen op."],"say":["Kras! Voor Sinterklaas!","Wat wil jij voor Sinterklaas tekenen?","Ik zie een groot rondje en lange strepen. Vertel eens, wat is dit?","Wat denk je dat het paard van de wortel vindt?","Je hebt er zo je best op gedaan. Wat zal Sinterklaas blij zijn!"],"words":["Sinterklaas","paard","schoen","wortel","pakje","zingen","dak"],"learn":["creativiteit","taal","fijne-motoriek"],"tips":["Bewaar elk jaar één schoentekening in een map met de datum erop: zo zie je mooi hoe het tekenen groeit.","Houd de verrassing in de schoen klein, zoals een mandarijn of een kleurplaat: het gaat om het spannende ritueel."],"extenders":["Maak ook een tekening voor het paard: wat eet het graag, en hoe ziet de stal eruit?","Teken een naambordje of een pijl voor bij de schoen, zodat Sinterklaas ’s nachts de goede schoen vindt.","Plak stickers op de tekening als pakjes, of teken een stapel cadeautjes en tel ze samen."],"variations":["Stoomboot: teken samen de boot op blauw papier en plak er watten bij als stoom uit de schoorsteen.","Zelf een kleurplaat maken: jij tekent de omtrek van een paard of een mijter, je kind kleurt hem in.","Pietenpad: leg papieren voetstapjes van de deur naar de schoen, alsof er ’s nachts iemand is geweest."],"themes":["sinterklaas"],"canStay":false,"pinQuery":"tekening schoen zetten sinterklaas"},
  {"id":"nat-krijt","title":"Nat krijt op zwart papier","emoji":"🖍️","category":"tekenen","summary":"Doop stoepkrijt in water en teken op zwart papier: de kleuren knallen ervan af en er stuift geen krijtstof meer.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"stoepkrijt","note":"dikke stukken in felle kleuren"},{"id":"gekleurd-papier","note":"zwart of donkerblauw"},{"id":"water","note":"een laagje van een paar centimeter"},{"id":"kom","note":"een stevig bakje dat niet snel omvalt"},{"id":"doekje","note":"voor tussendoor de handen"}],"optional":[{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"},{"id":"penselen","note":"om het papier nat te kwasten"},{"id":"suiker","note":"voor suikerwater: nog fellere kleuren"}],"steps":["Leg een knoeimat neer en zet een stevig bakje met een laagje water op tafel.","Leg een vel zwart papier klaar en geef je kind een paar stukken stoepkrijt.","Laat je kind het krijt in het water dopen en dan tekenen: kijk eens hoe fel de kleur wordt!","Maak ook eens een stukje papier nat met een natte kwast of hand en teken er met droog krijt op. Zie je het verschil?","Laat de tekening plat drogen. Droog wordt het krijt wat lichter en het kan nog een beetje afgeven.","Spoel handen en krijtjes af en laat de krijtjes een nacht drogen voordat je ze opbergt."],"ageTips":{"young":"Geef een tweejarige één dik stuk krijt en een klein bakje met maar een bodempje water. Het dopen is minstens zo leuk als het tekenen: laat dat gewoon gebeuren.","old":"Laat je kleuter vuurwerk, een sterrenhemel of een onderwaterwereld tekenen. Of onderzoek samen: wat geeft de felste kleur, krijt in water of krijt in suikerwater?"},"safety":["Laat je peuter niet alleen met het waterbakje en dweil gemorst water meteen op: een natte vloer is glad.","Krijt is niet om op te eten en krijtstof niet om in te ademen: daarom juist nat. Ruim afgebroken stukjes op, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Nat krijt kan kleuren op kleding en tafel: trek een oud shirt aan. Meestal gaat het eruit in de was, felle kleuren niet altijd."],"say":["Doop! Teken! Kijk, fel!","Wat gebeurt er met het krijt als het nat wordt?","Ik zie een knalroze lijn op het zwarte papier. Hij lijkt wel te gloeien!","Voel eens aan het krijt: is het nu zacht of hard?","Je hebt goed uitgeprobeerd wat het felst wordt: nat of droog."],"words":["nat","droog","fel","dopen","zacht","donker","gloeien"],"learn":["ontdekken","zintuigen","creativiteit","fijne-motoriek"],"tips":["Nog feller en minder vegen: leg het krijt 10 minuten in suikerwater (2 el suiker op 100 ml water) voordat je begint.","Nat krijt wordt zacht en breekt makkelijker: laat het na afloop een nacht drogen op een stuk keukenpapier.","Geen zwart papier? Neem een bruine papieren zak of een stuk karton: ook daarop knallen de kleuren."],"extenders":["Smeer met een natte vinger over een krijtlijn: lopen de kleuren in elkaar over? Maak zo een zachte lucht of een zee.","Teken een regenboog met een boog in elke kleur, of zet een rij stippen en verbind ze daarna met lijnen.","Leg het krijt plat neer en trek het over het papier: brede banen! Wissel af met de punt voor dunne lijnen."],"variations":["Vuurwerk: teken spetters en strepen in alle kleuren op zwart papier, mooi rond oud en nieuw.","Onderwaterwereld: teken vissen en kwallen op donkerblauw papier.","Badtijd: teken met nat krijt op de tegels van de lege douche of badkuip en spoel het daarna meteen weg. Probeer eerst een hoekje, want felle kleuren kunnen in de voegen blijven zitten."],"themes":[],"canStay":false,"pinQuery":"nat krijt zwart papier"},
  {"id":"folie-muur","title":"Tekenen op een foliemuur","emoji":"🖼️","category":"tekenen","summary":"Span huishoudfolie tussen twee stoelen en teken erop met stift: je ziet elkaar door je kunstwerk heen, kiekeboe!","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":5,"cleanupMinutes":2,"noise":2,"energy":1,"places":["vloer","muur"],"materials":[{"id":"huishoudfolie","note":"een brede rol"},{"id":"stoelen","note":"twee stevige stoelen, of gebruik een deuropening"},{"id":"stiften","note":"afwasbare, liefst dikke stiften"},{"id":"schilderstape","note":"om de folie aan de stoelen of de deurpost vast te zetten"}],"optional":[{"id":"knuffels","note":"om achter de folie te zetten en na te tekenen"},{"id":"zaklamp","note":"om door de tekening heen te schijnen"}],"steps":["Zet twee stevige stoelen naast elkaar, ongeveer een meter uit elkaar.","Wikkel de folie strak om beide stoelen heen, van de poten tot de rugleuning, tot er een doorzichtige muur staat. Zet de uiteinden vast met tape.","Ga aan weerskanten zitten: jij aan de ene kant, je kind aan de andere. Kiekeboe, kun je elkaar zien?","Teken met stift op de folie: krassen, rondjes, of een hoed en een snor precies op de plek van elkaars gezicht.","Zet een knuffel achter de folie en laat je kind hem natekenen door de folie heen.","Haal de folie er na afloop af, prop hem op en gooi hem meteen weg. Stift op handen gaat eraf met water en zeep."],"ageTips":{"young":"Voor een tweejarige is kiekeboe door de folie al het grootste feest. Teken samen grote krassen en rondjes en geef een dikke stift die makkelijk in de vuist past.","old":"Laat je kleuter jouw gezicht natekenen door de folie heen terwijl je stilzit, of teken samen een aquarium en laat knuffels erachter langs zwemmen."},"safety":["Huishoudfolie is plastic: houd het weg van het gezicht, laat je kind er niet in wikkelen of er alleen mee spelen en gooi losse stukken direct weg.","Kies zware stoelen die niet omvallen als je kind tegen de folie leunt of duwt, of gebruik een deuropening.","Stiftdopjes zijn klein en worden graag op gekauwd: leg ze op een vaste plek. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Kiekeboe! Ik zie jou!","Zal ik een hoed op jouw hoofd tekenen? Blijf even stil zitten…","Hoe voelt de folie: glad, koud, of een beetje plakkerig?","Wat zie je als je door jouw tekening heen kijkt?","Jij tekende precies langs de rand van de knuffel. Wat goed gekeken!"],"words":["doorzichtig","glad","voorkant","achterkant","kiekeboe","strak","door"],"learn":["creativiteit","samen","zintuigen"],"tips":["Hoe strakker de folie, hoe beter het tekent. Werkt een stift slecht op het plastic, probeer dan een andere: dikke stiften geven vaak de mooiste lijn.","Wil je de tekening bewaren? Maak een foto met je kind erachter: dan staan jullie er allebei op."],"extenders":["Doe het grote licht uit en schijn met een zaklamp door de folie: de tekening verschijnt als schaduw op de muur of deur erachter.","Teken samen één figuur, ieder aan een kant van de folie: jij het hoofd, je kind de armen, jij de benen…","Teken een doolhof op de folie en laat je kind er met een vinger doorheen gaan, terwijl jij aan de andere kant de weg wijst."],"variations":["Verfmuur: schilder met plakkaatverf en een dikke kwast op de folie. Dat wordt wel viezer, dus leg een knoeimat neer.","Raamversie: plak een stuk folie op het raam en trek na wat je buiten ziet: een boom, een auto, de kat van de buren.","Aquarium: teken vissen en waterplanten op de folie en laat knuffels erachter langs ‘zwemmen’."],"themes":[],"canStay":false,"pinQuery":"tekenen op huishoudfolie peuter"},
  {"id":"tekentafel","title":"De tekentafel: papier over de hele tafel","emoji":"🖍️","category":"tekenen","summary":"Bekleed de hele tafel met papier en zet er krijtjes op: je kind tekent, loopt weg, komt terug en tekent weer verder.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,45],"supervision":2,"soloFrom":2,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"groot-papier","note":"oud behang of pakpapier, genoeg om het hele tafelblad te bedekken"},{"id":"schilderstape","note":"om het papier rondom vast te plakken"},{"id":"waskrijt","note":"dikke krijtjes, verdeeld over een paar bakjes"},{"id":"bakjes","note":"lege yoghurtbekers of boterkuipjes, één op elke hoek van de tafel"}],"optional":[{"id":"stiften","note":"vanaf een jaar of drie; geef de dopjes een vaste plek"},{"id":"kleurpotloden","note":"voor kleuters die fijne lijntjes willen"},{"id":"stickers","note":"om op het papier te verstoppen"},{"id":"speelgoedautos","note":"om over getekende wegen te rijden"}],"steps":["Haal alles van de tafel, ook het tafelkleed, en leg er een baan papier over. Te smal? Leg er een tweede baan naast en plak de naad dicht.","Plak het papier rondom vast met schilderstape en vouw de randen om de tafelrand, zodat het niet verschuift of scheurt als je kind erop leunt.","Zet op elke hoek een bakje krijtjes, zodat je kind aan alle kanten kan beginnen.","Teken een paar ‘startjes’ op het papier: een weg die nergens heen gaat, een huis zonder ramen, een gezicht zonder mond.","Laat de tafel de rest van de dag zo liggen. Je kind tekent, loopt weg, komt terug en tekent weer verder: dat is precies de bedoeling.","Haal het papier er na een dag of een paar dagen af en knip de mooiste stukken uit om op te hangen of als inpakpapier te gebruiken."],"ageTips":{"young":"Gebruik voor een dreumes liever de salontafel, zodat je kind er staand goed bij kan. Geef dikke blokkrijtjes, teken zelf mee en benoem wat je ziet: een streep, nog een streep!","old":"Teken kleine opdrachtjes voor je kleuter: een doolhof, een rij huizen die nog ramen nodig hebben of een vak met ‘teken hier je ontbijt’. Of laat je kind opdrachtjes voor jou tekenen."},"safety":["Dreumesen stoppen krijtjes en stiftdopjes graag in de mond: geef een- en tweejarigen alleen dikke krijtjes en ruim afgebroken stukjes op. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Om bij het midden te komen, klimmen kinderen graag op een stoel of op de tafel: teken nieuwe startjes vooral langs de rand en laat je kind om de tafel heen lopen."],"say":["Kras! Nog een kras!","Ik zie een lange, kronkelige lijn. Waar gaat die naartoe?","Hier is nog een leeg plekje. Wie zou daar kunnen wonen?","Zal ik naast jouw huis een boom tekenen, of teken jij die?","Je bent alweer teruggekomen om verder te tekenen. Jij werkt echt aan een groot kunstwerk!"],"words":["lijn","rondje","kras","naast","boven","onder","leeg","vol"],"learn":["creativiteit","fijne-motoriek","taal","concentratie"],"tips":["Oud behang is ideaal: de achterkant is wit en met één rol bekleed je de tafel een paar keer.","Plak de bakjes vast met een rolletje tape eronder, dan gaan ze niet steeds om."],"extenders":["Teken een nieuw startje op een leeg plekje: een auto zonder wielen, een boom zonder blaadjes of een poes zonder staart.","Zet een paar speelgoedautootjes of diertjes op tafel: wat ze nodig hebben, zoals een weg, een hok of een vijver, tekent je kind erbij.","Wissel het tekenspul: haal de krijtjes weg en zet er stiften, kleurpotloden of één nieuwe kleur neer.","Verstop een paar stickers op het papier en laat je kind ze zoeken en er iets omheen tekenen.","Ga er zelf even bij zitten en teken iets kleins, zoals een slak of een bloem. Vaak tekent je kind dan meteen weer mee."],"variations":["Restaurant: teken borden, bestek en lekker eten op het papier en speel dat jullie uit eten gaan.","Plattegrond: teken samen jullie huis van bovenaf, met alle kamers, de bedden en de bank.","Sinterklaas of kerst: bekleed de tafel met bruin pakpapier en gebruik het na een paar dagen tekenen als inpakpapier voor de cadeautjes.","Tekenvloer: plak het papier op de vloer in plaats van op tafel, zodat je kind erop kan liggen en kruipen."],"themes":[],"canStay":true,"stayTips":"Laat het papier gerust een paar dagen liggen en zet de bakjes ’s avonds hoog weg, buiten bereik van kleine broertjes en zusjes. Eet je aan deze tafel, leg dan een theedoek over de tekening; daarna haal je die weg en tekent je kind gewoon verder.","pinQuery":"tafel bekleden met papier tekenen"},
  {"id":"tekenhuis-doos","title":"Tekenhuis: tekenen in een grote doos","emoji":"📦","category":"tekenen","summary":"Je kind kruipt in een grote doos en tekent op de binnenwanden: een eigen tekenhuis met ramen, een deur en een zaklamp als lamp.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"dozen","note":"een grote verhuisdoos of de doos van een groot apparaat, waar je kind in kan zitten"},{"id":"ducttape","note":"of brede plakband, om de bodem stevig dicht te plakken"},{"id":"schaar","note":"een stevige, om ramen uit te knippen (dat doe jij)"},{"id":"waskrijt","note":"dikke krijtjes; die werken goed op ruw karton"},{"id":"zaklamp","note":"met een dicht batterijklepje"}],"optional":[{"id":"stiften","note":"voor details op de gladde stukken karton"},{"id":"dekens","note":"een kussen of dekentje voor op de bodem"},{"id":"stickers","note":"als lampjes, sterren of een huisnummer"},{"id":"knuffels","note":"als logés in het tekenhuis"}],"steps":["Plak de onderkant van de doos stevig dicht en leg de doos op de zijkant, zodat de open kant de voordeur wordt. De flappen zijn de deuren.","Knip in elke zijwand een raam (dat doe jij): prik met de schaarpunt een gat en knip drie kanten los. De vierde kant blijft zitten als luik.","Leg een kussen op de bodem en zet een bakje krijtjes en de zaklamp in het tekenhuis.","Laat je kind naar binnen kruipen en de muren versieren: behang van strepen, schilderijtjes, een lamp aan het plafond, een poes in de vensterbank.","Kom op bezoek: klop op het luik, vraag of je binnen mag kijken en laat je kind vertellen wat er allemaal op de muren staat.","Laat het tekenhuis een paar dagen staan: elke keer dat je kind erin kruipt, komt er iets bij."],"ageTips":{"young":"Een tweejarige vindt in en uit kruipen en kiekeboe door het raam al prachtig. Knip extra grote ramen, zodat het licht is binnen, en teken door het raam mee: een rondje, nog een rondje!","old":"Laat je kleuter het huis inrichten: waar staat het bed, waar hangt de klok, wat zie je uit het raam? Of maak er een winkel van, met een loket waardoor je kunt bestellen."},"safety":["Haal nietjes en oude tape van de doos: die zitten vaak aan de flappen en zijn scherp of klein genoeg om in te slikken.","Plak de ingang nooit dicht als je kind erin zit en zet geen spullen voor de opening: je kind moet er altijd zelf in en uit kunnen.","Kies een zaklamp met een vastgeschroefd batterijklepje of plak het klepje dicht: knoopcelbatterijen zijn levensgevaarlijk bij inslikken."],"say":["Klop, klop! Wie woont hier?","Kiekeboe, door het raam!","Het is een beetje donker binnen. Wat zie je als de zaklamp aangaat?","Wat moet er nog in jouw huis? Een bed, een klok, een poes?","Jij hebt de hele muur vol getekend, tot in het kleinste hoekje!"],"words":["binnen","buiten","raam","deur","plafond","donker","licht","hoek"],"learn":["creativiteit","grove-motoriek","taal","fijne-motoriek"],"tips":["Bewaar een grote doos na een verhuizing of een nieuwe aankoop. Geen doos in huis? Witgoed- en fietsenwinkels geven vaak gratis een grote doos mee.","Zet het tekenhuis tegen de bank of een muur, dan schuift de doos niet weg als je kind erin kruipt.","Op bruin karton vallen wit, geel en lichtblauw krijt het mooist op."],"extenders":["Doe de lamp in de kamer uit en geef je kind de zaklamp: tekenen in het donker voelt als een geheime grot.","Knip een brievenbus in de deur (dat doe jij) en stop er briefjes en tekeningen doorheen: post voor de bewoner!","Plak een vel papier tegen het plafond van de doos en laat je kind op de rug liggend sterren tekenen.","Kom op bezoek met een knuffel die wil logeren: wat heeft de knuffel nodig? Een bed, een raam, een tandenborstel?","Laat je kind ook de buitenkant versieren: een voordeur met een bel, een huisnummer, bloemen langs de muur."],"variations":["Grot: teken met bruin, zwart en rood krijt dieren op de wanden, net als de eerste mensen, en verken de grot met de zaklamp.","Raket: teken knoppen, schermen en een stuur op de binnenwand en tel samen af voor de lancering.","Winter: maak er een iglo van met wit krijt aan de buitenkant en neem een knuffelpinguïn mee naar binnen.","Kerst: teken lichtjes en een kerstboom op de binnenwanden en hang er een papieren slinger in."],"themes":[],"canStay":true,"stayTips":"Zet het tekenhuis tegen een muur, waar niemand erover struikelt, en leg de krijtjes en de zaklamp in een bakje erin. Zakt de doos in, plak de hoeken dan van binnen en buiten opnieuw met tape.","pinQuery":"tekenen in grote doos kind"},
  {"id":"ganzenbord-maken","title":"Zelf een spelbord tekenen en spelen","emoji":"🎲","category":"tekenen","summary":"Teken samen een kronkelweg met vakjes, verzin bijzondere vakjes met plaatjes en speel daarna je eigen bordspel met een dobbelsteen.","ageMin":4,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[45,60],"supervision":1,"soloFrom":5,"cleanupMinutes":2,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"groot-papier","note":"minstens zo groot als twee A3’tjes, of een opengevouwen doos"},{"id":"stiften","note":"een dikke zwarte voor de weg en een paar kleuren voor de vakjes"},{"id":"dobbelsteen"},{"id":"duplo","note":"een blokje per speler als pion"}],"optional":[{"id":"potlood","note":"om de weg eerst dun voor te tekenen"},{"id":"waskrijt","note":"om gras, water en bomen in te kleuren"},{"id":"stickers","note":"als stervakjes of schatten onderweg"},{"id":"klein-speelgoed","note":"diertjes of poppetjes als pionnen"}],"steps":["Teken met een dikke stift een brede kronkelweg van start naar finish over het hele vel. Laat je kind de route bedenken: langs een berg, een rivier of een kasteel?","Verdeel de weg in vakjes met dwarse streepjes: 20 tot 30 is genoeg. Tel ze samen en zet in elk vijfde vakje het getal.","Bedenk samen een paar bijzondere vakjes en teken er een plaatje in: een glijbaan (3 terug), een raket (3 vooruit), een bed (beurt overslaan), een kikker (kwaak drie keer).","Kleur de vakjes en de omgeving in en teken bij de finish een vlag of een schat.","Kies elk een pion en speel: gooi de dobbelsteen, tel de stippen en zet net zoveel stappen. Wie is als eerste bij de finish?","Speel nog een paar rondes en pas de regels aan als jullie willen: bij je eigen spel mag dat."],"ageTips":{"young":"Houd het voor een vierjarige bij 15 tot 20 grote vakjes en twee soorten bijzondere vakjes. Tik bij het lopen elk vakje aan en tel hardop mee, dan oefent je kind tellen en stappen zetten tegelijk.","old":"Laat je kleuter de bijzondere vakjes zelf bedenken en tekenen, met een eigen regel bij elk plaatje. Speel met twee dobbelstenen en tel ze op, of teken een stiekeme afsnijweg die alleen bij een zes open is."},"safety":["Een dobbelsteen past door een wc-rolletje: berg de dobbelsteen na het spelen op als er een broertje of zusje onder de 3 rondloopt.","Kies doe-vakjes die binnen veilig zijn, zoals klappen, kwaken of op één been staan. Geen rennen of springen op de bank tussen twee beurten door."],"say":["Gooi maar! Hoeveel stippen?","Eén, twee, drie… waar kom je uit?","Je staat op de glijbaan! Weet je nog wat er dan gebeurt?","Jij hebt dit hele spel zelf bedacht. Welk vakje moet er nog bij?","Oei, terug naar start! Zullen we die regel houden of veranderen?"],"words":["start","finish","vakje","vooruit","achteruit","beurt","dobbelsteen","tellen"],"learn":["rekenen","samen","creativiteit","taal"],"tips":["Teken de weg eerst dun met potlood: dan kun je samen nog schuiven voordat alles vastligt.","Plak het bord op een opengevouwen doos: dan wordt het stevig en kun je het dubbelvouwen en bewaren.","Verliezen is voor veel kleuters nog lastig. Speel de eerste keer samen tegen het spel, of speel door tot iedereen bij de finish is."],"extenders":["Teken er een nieuw bijzonder vakje bij, zoals een draak, een brug of een snoeppot, en bedenk samen wat er gebeurt als je daar komt.","Zet een extra pion neer voor een knuffel en laat je kind ook voor de knuffel gooien, tellen en lopen.","Leg een stapeltje opdrachtkaartjes naast het bord, zoals een liedje zingen of een dier nadoen, en pak er een als je op een stervakje komt.","Spreek af dat de winnaar het volgende bijzondere vakje mag tekenen, en speel dan meteen een nieuwe ronde.","Speel terug: begin bij de finish en race in omgekeerde richting naar start."],"variations":["Dierenspel: teken een weg door de dierentuin, met in elk bijzonder vakje een dier om na te doen.","Sinterklaas: maak een route van Spanje naar Nederland, met een stoomboot, een dak en een schoorsteen als bijzondere vakjes.","Kleurenspel: kleur de vakjes om en om rood, geel en blauw en gooi met een zelfgemaakte kleurendobbelsteen in plaats van stippen.","Thuisroute: teken de weg van jullie huis naar opa en oma, school of de speeltuin, met echte plekken onderweg."],"themes":[],"canStay":true,"stayTips":"Laat het bord op tafel of op de vloer liggen met de pionnen en de dobbelsteen in een bakje erop, of vouw het dubbel en leg het op de kast. Morgen speel je verder of teken je er nieuwe vakjes bij.","pinQuery":"zelf bordspel tekenen kind"},
  {"id":"monster-dobbelspel","title":"Monsters dobbelen en tekenen","emoji":"👾","category":"tekenen","summary":"Gooi de dobbelsteen en teken wat eruit komt: drie ogen, vijf armen, één tand. Elk monster wordt anders en krijgt een naam en een verhaal.","ageMin":4,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[45,50],"supervision":3,"soloFrom":4,"cleanupMinutes":2,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"papier","note":"één vel voor de monsterkaart en een stapeltje om op te tekenen"},{"id":"stiften","note":"een dikke zwarte voor de lijnen en een paar kleuren"},{"id":"dobbelsteen"},{"id":"kleurpotloden","note":"of waskrijt, om de monsters in te kleuren"}],"optional":[{"id":"kinderschaar","note":"om de monsters uit te knippen"},{"id":"wiebeloogjes","note":"voor een paar extra gekke ogen"},{"id":"schilderstape","note":"om een monstermuur te maken"},{"id":"gekleurd-papier","note":"als donkere nacht achter de monsters"}],"steps":["Maak samen een monsterkaart: teken onder elkaar een klein plaatje van ogen, armen, benen, tanden en haren. In die volgorde ga je dobbelen.","Teken eerst een groot lijf in een vorm naar keuze: rond, vierkant, lang of een gekke klodder. Er moeten straks misschien zes ogen op passen!","Gooi de dobbelsteen voor de ogen en tel de stippen: zoveel ogen krijgt het monster. Ga zo de hele kaart af, van armen tot haren.","Kleur het monster in en bedenk samen een naam. Wat eet het, waar woont het en waar is het bang voor?","Teken zo een hele monsterfamilie. Speel je mee, dobbel dan om de beurt; ben je even met iets anders bezig, dan dobbelt je kind gewoon verder.","Leg de monsters naast elkaar of hang ze op: wie heeft de meeste ogen, wie de langste haren?"],"ageTips":{"young":"Houd het voor een vierjarige bij vier rondes: ogen, armen, benen en tanden. Tel de stippen samen hardop en tik bij elk getekend oog mee: één, twee, drie!","old":"Laat je kleuter ook de vorm dobbelen: 1 is rond, 2 vierkant, 3 een driehoek, 4 een wolk, 5 lang en 6 een hart. Of gooi met twee dobbelstenen en tel ze op: een monster met negen ogen!"},"safety":["Een dobbelsteen en wiebeloogjes passen door een wc-rolletje: ruim ze na het spelen op als er een broertje of zusje onder de 3 rondloopt.","Sommige kleuters vinden monsters spannend. Maak ze grappig (een monster dat bang is voor muizen) en stop als je kind er onrustig van wordt, zeker vlak voor het slapengaan."],"say":["Gooi maar! Hoeveel ogen worden het?","Vijf armen! Waar ga je die allemaal tekenen?","Hoe heet dit monster, en wat eet het het liefst?","Wat zou er gebeuren als jouw monster en mijn monster elkaar tegenkomen?","Je hebt alle tanden geteld en getekend, zelfs die kleine achteraan!"],"words":["monster","ogen","armen","tanden","meer","minder","evenveel","griezelig"],"learn":["rekenen","creativiteit","taal","fijne-motoriek"],"tips":["Teken de monsterkaart op een stukje karton en bewaar die bij de dobbelsteen: de volgende keer kun je meteen beginnen.","Schrijf de naam en het verhaal van elk monster op de achterkant. Na een paar keer heb je een heel monsterboek om voor te lezen."],"extenders":["Voeg een nieuwe ronde toe aan de monsterkaart: vleugels, staarten, wratten of stippen op de buik.","Gooi voor het monsterhuis: zoveel ramen, deuren en schoorstenen krijgt het huis naast het monster.","Ruil van rol: jij gooit en je kind tekent jouw monster. Daarna andersom.","Geef het monster iets te eten: gooi voor het aantal taartjes, wormen of broccoliboompjes op het monsterbord.","Laat twee monsters elkaar ontmoeten en speel met de tekeningen een gesprekje: wat zeggen ze, wat spelen ze?"],"variations":["Halloween: dobbel spoken en pompoenen in zwart en oranje, met zoveel ogen, tanden en vleermuizen als de dobbelsteen zegt, en hang ze voor het raam.","Robots dobbelen: gooi voor knoppen, antennes, wielen en lampjes en teken een hele robotfamilie.","Bloemen dobbelen: gooi voor blaadjes, bijtjes en lieveheersbeestjes en teken samen een tuin.","Kleimonster: maak het dobbelmonster van speeldeeg, met stukjes droge pasta als tanden."],"themes":["halloween"],"canStay":false,"pinQuery":"monster dobbelspel tekenen kleuter"},
  {"id":"luisteren-en-tekenen","title":"Luisteren en tekenen: teken wat je hoort","emoji":"🎧","category":"tekenen","summary":"Zet een luisterverhaal op en laat je kind tekenen wat het hoort: de beer, het bos, de storm. Een rustig moment voor jullie allebei.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"muziek","note":"een luisterverhaal of luisterboek van 20 tot 45 minuten, of rustige muziek"},{"id":"papier","note":"een stapeltje, zodat je kind steeds een nieuw vel kan pakken"},{"id":"waskrijt","note":"in een bakje binnen handbereik"}],"optional":[{"id":"kleurpotloden","note":"voor kleuters die fijn willen tekenen"},{"id":"dekens","note":"kussens of een dekentje voor een knusse luisterhoek"},{"id":"boeken","note":"het prentenboek bij het verhaal, om achteraf samen te bekijken"},{"id":"nietmachine","note":"om de tekeningen tot een boekje te nieten"}],"steps":["Kies een luisterverhaal met duidelijke personages en plekken: een dier, een reis, een avontuur. Een reeks korte verhaaltjes achter elkaar werkt ook.","Maak een rustige plek aan tafel of op een kleed met papier en krijtjes. Zet de telefoon of speaker zacht aan, een eindje verderop.","Spreek af: je tekent wat je hoort, en bij een nieuw stuk van het verhaal pak je een nieuw vel.","Start het verhaal en luister de eerste minuten samen, terwijl je zelf ook iets tekent. Daarna kun je rustig iets anders gaan doen.","Bekijk na afloop samen de tekeningen: wie is dit, wat gebeurde hier? Leg ze op volgorde van het verhaal."],"ageTips":{"young":"Kies voor een driejarige korte verhaaltjes met dieren en veel herhaling, of een verhaal dat je kind al kent. Tekent je kind iets heel anders? Prima: luisteren en krassen tegelijk is al heel wat.","old":"Laat je kleuter een strip maken: vouw een vel in vier vakken en teken het begin, twee stukjes uit het midden en het einde. Of luister elke dag een hoofdstuk van een luisterboek en teken het volgende stuk."},"safety":["Zet het geluid zacht en de speaker op een afstandje. Gebruik je een koptelefoon, kies dan een kindermodel met volumebegrenzing.","Leg snoeren van speaker en oplader buiten bereik en niet langs de tekenplek: struikelgevaar en wurggevaar.","Luister een onbekend verhaal eerst even zelf: sommige verhalen blijken spannender dan je denkt, zeker voor een driejarige."],"say":["Luister! Wie hoor je nu?","Hoe ziet die reus eruit, denk jij? Groot, klein, lief of boos?","Ik zie dat je regen hebt getekend. Hoorde je die tikken?","Welk stukje van het verhaal vond je het spannendst?","Jij hebt heel goed geluisterd: alles wat de beer meemaakte, staat op papier!"],"words":["luisteren","stil","verhaal","begin","einde","eerst","daarna"],"learn":["taal","concentratie","creativiteit"],"tips":["Draai het scherm van de telefoon om of gebruik een speaker: dan blijft het luisteren en wordt het geen kijken.","Bij de bibliotheek kun je vaak gratis luisterboeken voor kinderen lenen of online beluisteren. Zet er alvast een paar klaar voor een regenachtige middag.","Bewaar de tekeningen per verhaal in een envelop: zo maak je je eigen prentenboek bij het luisterverhaal."],"extenders":["Zet het verhaal op pauze en vraag: wat gebeurt er nu, denk je? Laat je kind dat tekenen voordat jullie verder luisteren.","Leg een nieuwe kleur neer die bij het verhaal past: blauw voor de zee, groen voor het bos, zwart voor de nacht.","Zet na het verhaal rustige muziek op en laat je kind een achtergrond bij de tekeningen maken: lucht, gras, sterren.","Laat je kind het verhaal navertellen aan een knuffel, met de tekeningen als plaatjes.","Start een tweede verhaal en laat je kind de personages uit het eerste verhaal erbij tekenen: wat zouden die ervan vinden?"],"variations":["Geluiden raden: zet geluiden van dieren of voertuigen op en teken wat je denkt dat het is. Klopt het?","Voorleestekenen: lees zelf een prentenboek voor zonder de plaatjes te laten zien en vergelijk daarna de tekeningen met het boek.","Muziekverhaal: luister naar muziek waarin dieren te horen zijn, zoals Peter en de wolf, en teken wat er volgens jou gebeurt.","Winter: kruip onder een deken met een wintersprookje en teken de sneeuw, de slee en de ijsberen waarover je hoort."],"themes":[],"canStay":false,"pinQuery":"tekenen bij luisterverhaal kind"},
  {"id":"plakmuur","title":"Plakmuur van kaftfolie","emoji":"🖐️","category":"plakken","summary":"Hang kaftfolie met de plakkant naar voren op het raam en laat je kind er snippers, veertjes en blaadjes op plakken, helemaal zonder lijm.","ageMin":1,"ageMax":4,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":2,"soloFrom":2,"cleanupMinutes":2,"noise":1,"energy":1,"places":["muur"],"materials":[{"id":"kaftfolie","note":"een vel van ongeveer 40 x 60 cm"},{"id":"schilderstape","note":"om de randen aan het raam of de muur vast te plakken"},{"id":"vloeipapier","note":"in snippers geknipt of gescheurd, in een paar kleuren"},{"id":"gekleurd-papier","note":"vierkantjes en rondjes van een paar centimeter"}],"optional":[{"id":"veren","note":"zachte veertjes"},{"id":"bladeren","note":"platte, eerder verzamelde bladeren"},{"id":"bakjes","note":"om de snippers per kleur in te doen"}],"steps":["Knip of scheur alvast een stapeltje snippers vloeipapier en gekleurd papier.","Trek de beschermlaag van de kaftfolie en plak het vel met de plakkant naar voren op het raam, op de hoogte van je kind.","Zet alle vier de randen vast met stroken schilderstape, zodat de folie niet loslaat.","Leg de snippers in een bakje naast het raam, zodat je kind er zelf bij kan.","Laat je kind snippers pakken en op de folie drukken. Voel samen eens hoe plakkerig het is!","Laat de plakmuur een paar dagen hangen en vul hem steeds aan. Lostrekken en opnieuw plakken mag ook."],"ageTips":{"young":"Geef een dreumes grote stukken die makkelijk te pakken zijn, zoals brede stroken vloeipapier of een grote veer. Doe het voor en zeg het erbij: plak! Nog een!","old":"Laat je kleuter een plaatje maken: een regenboog in de goede volgorde, een bloem of een gezicht. Of zoek eerst alle snippers in één kleur bij elkaar en plak alleen die."},"safety":["Geef een dreumes grote snippers: kleine stukjes papier en veertjes belanden makkelijk in de mond. Blijf dichtbij en haal wat in de mond verdwijnt er rustig uit.","Hang de plakmuur zo laag dat je kind er staand of zittend bij kan: zet er geen stoel of krukje bij om op te klimmen, zeker niet bij een raam dat open kan."],"say":["Plak! Nog een!","Voel eens: het plakt aan je vingers!","Ik zie de zon door het rode papiertje schijnen.","Wat gebeurt er als je de veer er weer aftrekt?","Jij hebt alle blauwe snippers bij elkaar geplakt. Wat goed gezocht!"],"words":["plakken","plakkerig","zacht","veer","licht","erop","eraf"],"learn":["fijne-motoriek","zintuigen","creativiteit"],"tips":["Knip de snippers als je kind slaapt en bewaar ze in een zakje: dan kun je meteen beginnen.","Geen kaftfolie? Plak brede plakband met de plakkant naar voren in banen naast elkaar.","Is de folie vol? Plak er een tweede vel overheen, plakkant op plakkant, knip het rond en hang het als zonnevanger voor het raam."],"extenders":["Zet een nieuw bakje neer met iets anders om te plakken, zoals grote stukken aluminiumfolie, stroken crêpepapier of een grote veer: hoe voelt dat?","Speel zoeken en lostrekken: waar is een gele snipper? Trek hem eraf en plak hem op een nieuwe plek.","Plak een vorm van schilderstape op de folie, zoals een groot rondje of een huisje, en laat je kind alleen die vorm vol plakken."],"variations":["Herfst: plak bladeren, takjes en snippers in herfstkleuren en maak er samen een boom van.","Kleurenmuur: plak alleen rode snippers en zoek daarna in huis nog meer dingen in die kleur.","Gezicht: plak een groot rond vel papier op de folie en laat je kind er ogen, een neus en een mond op plakken.","Lente: plak bloemblaadjes en groene snippers tot een bloementuin op het raam."],"themes":[],"canStay":true,"stayTips":"Laat de plakmuur een paar dagen hangen en zet het bakje snippers op een vaste plek in de buurt, zodat je kind steeds even kan bijplakken. Druk de tape elke ochtend aan en zet er geen stoel of krukje bij.","pinQuery":"plakmuur raam kaftfolie dreumes"},
  {"id":"scheurcollage","title":"Scheuren en plakken","emoji":"📰","category":"plakken","summary":"Scheur tijdschriften en gekleurd papier in snippers en plak ze op karton: zo groeit er een collage, bijvoorbeeld een herfstboom vol blaadjes.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"tijdschriften","note":"of reclamefolders, die scheuren makkelijk"},{"id":"gekleurd-papier","note":"voor een herfstboom: rood, oranje, geel en bruin"},{"id":"lijmstift"},{"id":"karton","note":"als stevige ondergrond"}],"optional":[{"id":"stiften","note":"een bruine stift voor de stam"},{"id":"bakjes","note":"om de snippers per kleur te verzamelen"},{"id":"dienblad","note":"om op te werken, dan blijven de snippers bij elkaar"}],"steps":["Leg tijdschriften en gekleurd papier klaar. Scheur zelf een strook in, zodat je kind ziet hoe het gaat.","Laat je kind stroken en snippers scheuren: groot of klein, recht of rafelig, alles is goed.","Scheur samen een stam en takken uit bruin papier en plak ze op het karton, of teken ze met stift.","Smeer met de lijmstift een plekje op het karton in en druk er een snipper op. Lijm op het karton gaat makkelijker dan op de snipper.","Vul de boom met blaadjes in herfstkleuren en plak er ook een paar onder, alsof ze naar beneden dwarrelen.","Laat de collage plat drogen onder een boek en ruim de snippers op in een bak of met stoffer en blik."],"ageTips":{"young":"Een tweejarige scheurt het makkelijkst in een strook die jij al een stukje hebt ingescheurd. Smeer zelf de lijm op het karton en laat je kind alleen de snippers erop drukken.","old":"Laat je kleuter de snippers eerst sorteren op kleur, of bewust vormen scheuren: een rondje voor de zon, een driehoek voor een dak. Ook leuk: een gezicht van tijdschriftsnippers."},"safety":["Peuters stoppen papiersnippers soms in de mond: blijf erbij en haal ze er rustig uit. Inkt van tijdschriften is niet om op te eten.","De dop van de lijmstift is klein en wordt graag op gekauwd: leg hem weg tijdens het plakken. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Krrrr! Hoor je het scheuren?","Ik zie een rafelig randje. Voel eens, is het glad of kriebelig?","Waar moet dit oranje blaadje komen?","Wat heb jij veel snippers gescheurd, helemaal zelf!","Hoeveel blaadjes vallen er al naar beneden?"],"words":["scheuren","snipper","rafelig","plakken","stam","tak","dwarrelen"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Dun papier scheurt het makkelijkst: tijdschriften en folders gaan beter dan stevig karton.","Werk op een dienblad of bakplaat: de snippers blijven bij elkaar en je ruimt alles in één keer op.","Bewaar overgebleven snippers in een zakje voor de volgende keer of voor een plakmuur."],"extenders":["Doe een scheurwedstrijd: wie scheurt de langste sliert zonder dat hij breekt? Plak de slierten als takken of regen op het karton.","Geef een zoekopdracht in het tijdschrift: scheur iets roods, iets met een dier en iets om te eten, en plak het bij de boom.","Laat je kind alleen de kleur plakken die jij noemt: nu geel, nu rood, en nu allemaal oranje blaadjes onder de boom."],"variations":["Winter: scheur wit papier en maak een besneeuwde boom of een sneeuwpop van snippers.","Kleurenmonster: scheur alles in één kleur en plak er een groot monster van, met getekende ogen.","Lente: plak een bloesemboom van roze en witte snippers."],"themes":["herfst"],"canStay":false,"pinQuery":"scheurcollage herfstboom peuter"},
  {"id":"knipsoep","title":"Knipsoep koken: de eerste keer knippen","emoji":"✂️","category":"plakken","summary":"Knip stroken papier in hapjes en kook er knipsoep van: één knip is één hap, zo oefent je kind spelenderwijs met de schaar.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":1,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"kinderschaar","note":"met ronde punt; er zijn ook scharen voor linkshandigen"},{"id":"gekleurd-papier","note":"in stroken van 2-3 cm breed (die knip jij voor)"},{"id":"pan","note":"een speelgoedpan of gewone pan als soeppan"},{"id":"lepel","note":"een grote lepel om te roeren"}],"optional":[{"id":"karton","note":"dun karton van een cornflakesdoos, in stroken: lekker stevig om te knippen"},{"id":"kom","note":"soepkommen om op te scheppen"},{"id":"speeldeeg","note":"rolletjes deeg knippen is een makkelijke eerste oefening"}],"steps":["Knip een paar vellen papier in stroken van 2 tot 3 cm breed. Dan is één knip genoeg voor een hapje.","Laat zien hoe je de schaar vasthoudt: duim in het kleine gat, vingers in het grote, duim boven. Open, dicht, open, dicht.","Houd jij de strook strak vast en laat je kind er een stukje afknippen: knip! Daar valt een hapje in de pan.","Laat je kind de strook daarna zelf vasthouden en knippen. Knip, knip, knip: de pan loopt vol.","Roer de soep om, strooi er ‘zout en peper’ in (nog meer snippers) en schep op in kommen. Eet smakelijk!","Ruim samen op: de soep gaat terug in de pan en daarna in het oud papier."],"ageTips":{"young":"Voor een driejarige is vasthouden én knippen tegelijk lastig: houd jij de strook vast en laat je kind alleen ‘happen’ met de schaar. Lukt knippen nog niet, scheur dan de soep.","old":"Teken lijnen op de stroken (recht, golvend of zigzag) en laat je kleuter erlangs knippen. Of knip soepgroenten: rondjes wortel, blokjes prei en lange slierten vermicelli."},"safety":["Gebruik een kinderschaar met ronde punt en spreek af: de schaar blijft aan tafel, we lopen er niet mee rond en na afloop gaat hij in de la.","Leg uit dat de schaar alleen papier knipt, geen haar, kleren of gordijnen, en houd scharen buiten bereik als jij er niet bij bent.","Let op de vingers van de hand die vasthoudt: die blijven naast de schaar, nooit ertussen."],"say":["Knip! Daar is een hapje!","Open, dicht, open, dicht: hoor je de schaar?","Ik zie dat je je duim bovenop houdt. Zo gaat het precies goed.","Wat voor soep koken we vandaag? Tomatensoep of regenboogsoep?","Hoeveel hapjes heb je al geknipt? Zullen we tellen?"],"words":["knippen","open","dicht","strook","hapje","soep","roeren"],"learn":["fijne-motoriek","concentratie","creativiteit"],"tips":["Met een goede kinderschaar en een strook die jij vasthoudt, kunnen veel kinderen vanaf ongeveer 2,5 jaar al knippen. Lukt het nog niet, oefen dan eerst met scheuren.","Stevig papier of dun karton knipt makkelijker dan slap papier, dat dubbelvouwt in de schaar.","Linkshandig? Kies een linkshandige kinderschaar: met een gewone schaar ziet je kind niet waar het knipt en klemt het papier."],"extenders":["Open een restaurantje: jij bent de gast en bestelt soep met lange slierten, kleine blokjes of alleen groene stukjes.","Geef een nieuwe ‘groente’ om te knippen, zoals een strook uit een folder, een oude ansichtkaart of crêpepapier: wat knipt het makkelijkst?","Tel samen de hapjes: hoeveel knippen zijn er nodig om één kom vol te krijgen?"],"variations":["Spaghetti koken: knip lange, dunne slierten en dien ze op met rode snippers als tomatensaus.","Knipkapper: teken een gezicht op een vel en knip de bovenkant in tot lange haren. Nu mag je kind de kapper zijn!","Heksensoep: knip snippers in herfstkleuren en roer er met een grote lepel een toversoep van. Mooi rond Halloween."],"themes":[],"canStay":false,"pinQuery":"knipsoep peuter leren knippen"},
  {"id":"glas-in-lood","title":"Glas-in-lood voor het raam","emoji":"🌈","category":"plakken","summary":"Plak snippers vloeipapier op kaftfolie in een lijstje van karton en hang het voor het raam: als de zon schijnt, gaat het stralen.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"kaftfolie","note":"twee stukken, iets groter dan het lijstje"},{"id":"vloeipapier","note":"in snippers of vierkantjes van een paar centimeter"},{"id":"karton","note":"of zwart papier voor het lijstje"},{"id":"schilderstape","note":"om de folie op tafel en het kunstwerk tegen het raam te plakken"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf snippers knippen"},{"id":"gekleurd-papier","note":"zwart, voor een lijstje als echt glas-in-lood"}],"steps":["Knip een lijstje uit karton: een hart, ster of rondje met een groot gat in het midden. Dat doe jij.","Trek de beschermlaag van een stuk kaftfolie en leg het met de plakkant naar boven op tafel. Zet de hoeken vast met tape.","Druk het lijstje op de plakkant, zodat het goed vastzit.","Laat je kind snippers vloeipapier in het lijstje plakken. Overlappen mag: daar ontstaan nieuwe kleuren!","Plak het tweede stuk kaftfolie er bovenop als alles vol is en knip de randen netjes bij langs het lijstje.","Hang het kunstwerk met schilderstape tegen het raam en kijk samen hoe het licht erdoorheen schijnt."],"ageTips":{"young":"Laat een tweejarige vrij plakken in een groot, rechthoekig lijstje en kies grote snippers in een paar felle kleuren. Het afplakken en ophangen doe jij.","old":"Laat je kleuter de vorm zelf tekenen en de snippers knippen, of maak een patroon: om en om rood en geel. Wat gebeurt er als blauw en geel over elkaar liggen?"},"safety":["Het gat in het lijstje steek je het makkelijkst voor met een mespunt of schaarpunt. Dat doe jij, op een snijplank en buiten bereik van je kind.","Hang het kunstwerk met tape tegen het raam, niet aan een lang touwtje bij bed of box: koordjes zijn een wurggevaar."],"say":["Plak! Rood! Nog een!","Kijk, de zon schijnt door jouw raam heen!","Wat gebeurt er als het gele papiertje over het blauwe ligt?","Ik zie dat je het hele lijstje hebt volgeplakt, tot in de hoekjes.","Welke kleur straalt het mooist als het licht erdoor schijnt, denk jij?"],"words":["doorzichtig","licht","plakkerig","overlappen","raam","stralen","kleur"],"learn":["fijne-motoriek","creativiteit","ontdekken"],"tips":["Knip vooraf een stapeltje snippers en bewaar ze per kleur in bakjes of zakjes: dan kun je zo beginnen.","Geen kaftfolie? Gebruik brede plakband met de plakkant naar boven, in banen naast elkaar."],"extenders":["Til het halfvolle kunstwerk tussendoor voorzichtig op en houd het tegen het licht: welke kleuren schijnen al mooi, en waar moet nog iets bij?","Geef een heel vel vloeipapier en laat je kind zelf snippers scheuren in de kleur die nog ontbreekt.","Plak een vorm van zwart papier in het midden, zoals een maan, een ster of een kat, en vul de ruimte eromheen met kleur."],"variations":["Kerst: knip een ster of kerstbal als lijstje en plak er rood, groen en geel in.","Halloween: maak een pompoen van oranje snippers met zwarte ogen, of een vleermuis tegen een gele maan.","Lente: maak een vlinder of bloem en hang er een hele rij van voor het raam."],"themes":["kerst","halloween","lente"],"canStay":false,"pinQuery":"glas in lood kaftfolie vloeipapier"},
  {"id":"bordjes-dieren","title":"Dieren van papieren bordjes","emoji":"🦁","category":"plakken","summary":"Met verf, papier en een beetje lijm wordt een papieren bordje een leeuw, vis, lieveheersbeestje of schildpad: welk dier kies jij?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,30],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"papieren-bordjes"},{"id":"plakkaatverf","note":"afwasbare kinderverf in de kleur van het dier"},{"id":"penselen","note":"dikke kwasten"},{"id":"gekleurd-papier","note":"voor manen, vinnen, pootjes en stippen"},{"id":"knutsellijm","note":"houdt beter op een bordje dan een lijmstift"},{"id":"stiften","note":"een zwarte stift voor ogen en mond"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf stroken knippen"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"ijsstokjes","note":"om er een handpop van te maken"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Kies samen een dier: een leeuw, vis, lieveheersbeestje of schildpad. Leg een knoeimat neer en trek een oud shirt aan.","Laat je kind het bordje verven in de kleur van het dier: geel voor de leeuw, rood voor het lieveheersbeestje, groen voor de schildpad.","Knip ondertussen de onderdelen uit gekleurd papier: stroken voor manen, vinnen en een staart, zwarte stippen of pootjes. Dat doe jij.","Laat de verf een kwartiertje drogen. Lees intussen een dierenboekje of doe samen het geluid van het dier na.","Zet stipjes lijm op het bordje en laat je kind de onderdelen erop drukken. Teken ogen en een mond met stift.","Laat het dier plat drogen en hang het op. Voor een poppenkast: plak er een ijsstokje achter als handvat."],"ageTips":{"young":"Voor een tweejarige is verven het hele feest: laat de rest gerust zitten of plak samen alleen een paar stroken. Ogen tekenen doe jij; wiebeloogjes nog niet.","old":"Laat je kleuter zelf de stroken voor de manen knippen en de stippen van het lieveheersbeestje tellen. Of verzin een eigen fantasiedier met vinnen én manen."},"safety":["Wiebeloogjes zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Teken voor jonge kinderen de ogen met stift.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf, trek een oud shirt aan en leg een knoeimat neer."],"say":["Geel! Nog meer geel!","Welk dier wordt jouw bordje? Wat heeft dat dier nodig?","Ik zie dat je helemaal tot de rand hebt geverfd.","Hoe klinkt jouw leeuw? Kan hij ook zachtjes brullen?","Hoeveel stippen heeft jouw lieveheersbeestje? Zullen we tellen?"],"words":["leeuw","manen","vin","stip","schild","rond","brullen"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Minder vies: kleur het bordje met dikke stiften of waskrijt in plaats van verf.","Knip de onderdelen alvast als je kind een dutje doet en leg ze per dier in een bakje: dan kan je peuter meteen plakken."],"extenders":["Maak er een vriendje bij dat bij het eerste dier past, zoals een babyleeuw of een visje voor de schildpad.","Teken een huis voor het dier op een groot vel, zoals een savanne, een zee of een tuin, en zet het dier erin.","Geef het dier een naam en zoek in een folder wat het lust: knip het uit en plak het bij de mond."],"variations":["Leeuw: plak stroken geel en oranje papier rondom als manen en krul ze om een potlood.","Vis: knip een punt uit het bordje als bek en plak die punt aan de achterkant vast als staart. Schubben van vloeipapier erop!","Schildpad: verf het bordje groen, plak er vierkantjes op als schild en maak een kop en pootjes van papier.","Lieveheersbeestje: verf het bordje rood en plak er zwarte stippen en een zwarte kop op. Mooi in de lente."],"themes":[],"canStay":false,"pinQuery":"dieren van papieren bordjes"},
  {"id":"wc-rol-diertjes","title":"Wc-rol-diertjes: uil, pinguïn en paashaas","emoji":"🦉","category":"plakken","summary":"Een leeg wc-rolletje wordt met verf, papier en een beetje lijm een uil, pinguïn, paashaas of spookje: knutselen met wat je anders weggooit.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[20,30],"supervision":3,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"wc-rollen","note":"één per diertje; een halve keukenrolkoker kan ook"},{"id":"plakkaatverf","note":"afwasbare kinderverf"},{"id":"penselen"},{"id":"gekleurd-papier","note":"voor oren, vleugels, snavels en buikjes"},{"id":"knutsellijm","note":"of een lijmstift"},{"id":"stiften","note":"voor ogen en snavel"}],"optional":[{"id":"wiebeloogjes"},{"id":"watten","note":"een plukje als staartje voor de paashaas"},{"id":"kinderschaar","note":"voor kleuters die zelf vleugels knippen"},{"id":"oud-shirt"}],"steps":["Kies samen een dier: een uil, pinguïn, paashaas of spookje. Leg een knoeimat neer.","Laat je kind het rolletje verven: bruin voor de uil, zwart voor de pinguïn, wit of grijs voor de haas. Laat het een kwartiertje drogen.","Vouw voor de uil de bovenrand aan de voor- en achterkant naar binnen: dan steken er twee puntoortjes uit.","Knip ondertussen vleugels, buikjes, snavels of lange oren uit gekleurd papier. Dat doe jij, of je kleuter zelf.","Laat je kind de onderdelen opplakken en ogen tekenen met een stift. Een plukje watten wordt een staartje.","Zet de diertjes op een rij in de vensterbank of maak er een hele familie van."],"ageTips":{"young":"Voor een driejarige is verven het leukste deel. Knip de onderdelen vooraf en plak ze samen op; teken grote ogen met stift als wiebeloogjes nog te priegelig zijn.","old":"Laat je kleuter zelf vleugels en oren tekenen en knippen, of een hele dierentuin plannen: welk dier heeft wat nodig? Speel daarna poppenkast met de diertjes."},"safety":["Wiebeloogjes en plukjes watten zijn klein: houd ze weg bij jongere broertjes of zusjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Plakkaatverf kan vlekken: kies afwasbare kinderverf en verf met een oud shirt aan."],"say":["Oehoe! Daar is de uil!","Verf maar rond, helemaal om het rolletje heen!","Welk dier wordt dit, denk je? Wat heeft het nodig: oren, vleugels of een snavel?","Ik zie twee puntjes bovenop. Zijn dat oren?","Je hebt aan allebei de kanten precies een vleugel geplakt."],"words":["uil","pinguïn","haas","vleugel","snavel","oren","rond"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Spaar een paar weken wc-rolletjes en keukenrolkokers in een doos. Een keukenrolkoker in tweeën geknipt geeft twee diertjes.","Minder vies: wikkel een strook gekleurd papier om het rolletje en plak die vast, in plaats van te verven."],"extenders":["Knip een rolletje doormidden voor een babydiertje en maak het samen af: welke baby hoort bij welk dier?","Maak een huisje of nest voor de diertjes van een eierdoos, een schoenendoos of een opgevouwen theedoek.","Verstop de droge diertjes in de kamer en laat je kind ze zoeken: waar zit de uil? Doe om de beurt het geluid van het dier na."],"variations":["Herfst: maak een uil met veren van bruine bladeren of gescheurd papier.","Winter: een pinguïn met een wit buikje en een sjaaltje van een reepje vilt.","Pasen: een paashaas met lange papieren oren en een staartje van watten.","Halloween: een spookje van een wit rolletje of een vleermuis met zwarte vleugels."],"themes":["herfst","winter","pasen","halloween"],"canStay":false,"pinQuery":"wc rol dieren knutselen"},
  {"id":"gekke-gezichten","title":"Gekke gezichten uit tijdschriften","emoji":"🤪","category":"plakken","summary":"Knip ogen, neuzen en monden uit tijdschriften en mix ze tot gekke gezichten: blij, boos, verbaasd of alles tegelijk!","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"tijdschriften","note":"met grote foto’s van gezichten, ook reclamefolders"},{"id":"kinderschaar"},{"id":"lijmstift"},{"id":"papier","note":"met een groot hoofd erop getekend, of een papieren bordje"}],"optional":[{"id":"stiften","note":"voor haar, oren en wenkbrauwen"},{"id":"touw","note":"stukjes wol als haar"},{"id":"bakjes","note":"om ogen, neuzen en monden apart te bewaren"}],"steps":["Blader samen door tijdschriften en zoek grote gezichten. Wie lacht er? Wie kijkt boos?","Knip ogen, neuzen en monden uit en leg ze op drie stapeltjes. Grote stukken knip jij, de rest je kleuter.","Teken een groot hoofd op een vel papier, of neem een papieren bordje.","Laat je kind kiezen: welke ogen, welke neus en welke mond? Leg alles eerst los neer en schuif tot het grappig is.","Plak alles vast met de lijmstift en teken er haar, oren of een hoed bij.","Bekijk samen het gezicht: hoe voelt dit gezicht zich? Doe het maar eens na!"],"ageTips":{"young":"Knip voor een driejarige alvast een stapeltje ogen, neuzen en monden uit. Kiezen, schuiven en plakken is genoeg werk; benoem steeds wat je ziet: ogen, een neus, een lachende mond.","old":"Laat je kleuter zelf knippen en een gezicht maken bij een gevoel: maak eens een verdrietig of een verbaasd gezicht. Of maak een monster met drie ogen en twee monden."},"safety":["Blader de tijdschriften even door voordat je kind gaat zoeken: haal pagina’s met enge of ongepaste foto’s eruit.","Gebruik een kinderschaar met ronde punt en knip zelf de moeilijke stukjes, zoals een mond met smalle lippen."],"say":["Ogen! Waar zijn de ogen?","Kijk, deze mond lacht heel breed. Hoe voelt deze persoon zich?","Wat gebeurt er als we boze ogen bij een lachende mond plakken?","Kun jij dit gezicht nadoen? En ik?","Je hebt heel goed gezocht naar precies de goede neus."],"words":["ogen","neus","mond","blij","boos","verdrietig","verbaasd","gek"],"learn":["taal","creativiteit","fijne-motoriek"],"tips":["Reclamefolders van kledingwinkels en supermarkten staan vol grote gezichten en zijn gratis.","Plak de gezichten in een schrift: zo maak je een gevoelensboekje om later samen te bekijken en na te doen."],"extenders":["Doe alle ogen, neuzen en monden in een bak en trek ze zonder te kijken: wat voor gezicht krijg je nu?","Geef het gezicht een lijf: knip er kleren, handen, schoenen of een hoed bij uit het tijdschrift.","Doe om de beurt een gezicht na en laat de ander raden welk gezicht op tafel je bedoelt."],"variations":["Gevoelensmeter: maak een blij, boos, bang en verdrietig gezicht en vraag elke dag welk gezicht bij je kind past.","Dierengezichten: knip ogen en neuzen van dieren en maak bijvoorbeeld een poes met een olifantenslurf.","Carnaval: plak het gezicht op karton, knip het uit en maak er een masker op een stokje van."],"themes":[],"canStay":false,"pinQuery":"gekke gezichten tijdschrift knippen"},
  {"id":"bladerendieren","title":"Bladerendieren: egel, vos en uil","emoji":"🦔","category":"plakken","summary":"Plak herfstbladeren op karton als stekels, vacht of veren en teken ogen en pootjes erbij: daar is je egel, vos of uil!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"bladeren","note":"eerder verzameld; platte, droge bladeren in verschillende kleuren en vormen"},{"id":"knutsellijm","note":"houdt bladeren beter vast dan een lijmstift"},{"id":"karton","note":"of stevig papier als ondergrond"},{"id":"stiften","note":"zwart, voor ogen, snuit en pootjes"}],"optional":[{"id":"penselen","note":"om de lijm uit te smeren"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"kinderschaar","note":"om bladeren in vorm te knippen"},{"id":"oud-shirt"}],"steps":["Leg de bladeren op tafel en bekijk ze samen: welke zijn puntig, welke rond, welke rood of bruin?","Teken op het karton de kop van een dier: een puntige snuit voor de egel, een vossenkop met oren, of twee grote uilenogen.","Smeer lijm op het karton waar de stekels, vacht of veren moeten komen. Met een kwast gaat het makkelijk.","Laat je kind de bladeren op de lijm drukken, een beetje over elkaar heen. Voor egelstekels wijzen de punten naar buiten.","Teken ogen, een neus en pootjes erbij en laat het dier een paar uur plat drogen onder een boek."],"ageTips":{"young":"Een tweejarige drukt graag, maar smeert nog niet precies: smeer zelf de lijm en laat je kind de bladeren erop leggen en aandrukken. Grote bladeren werken het makkelijkst.","old":"Laat je kleuter zelf kiezen welk blad bij welk dier past en tel samen de stekels. Of knip bladeren in vorm: puntige oren voor de vos, een ronde buik voor de uil."},"safety":["Gebruik alleen bladeren, geen bessen, eikels of kastanjes: die zijn niet eetbaar en klein. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Wiebeloogjes pas vanaf 3 jaar: teken voor een tweejarige de ogen met stift."],"say":["Plak! Nog een blad!","Voel eens: is dit blad glad of ruw? Knispert het?","Ik zie heel veel puntige bladeren. Zijn dat de stekels van de egel?","Welk dier heeft er een rode vacht? Wat denk jij?","Je hebt de bladeren zo dicht naast elkaar gelegd dat er geen gaatje meer is."],"words":["egel","stekel","vos","uil","puntig","knisperen","herfst"],"learn":["creativiteit","fijne-motoriek","zintuigen","taal"],"tips":["Leg vers geraapte bladeren een nacht plat tussen kranten onder een stapel boeken: dan krullen ze niet op en plakken ze beter.","Giet een klein plasje lijm op een dekseltje of bordje en laat je kind met een kwast stippen. Zo gaat er minder lijm verloren.","Natte lijmvlekken spoel je met koud water uit kleding; opgedroogde lijm laat je eerst weken."],"extenders":["Sorteer de overgebleven bladeren op kleur of grootte en laat je kind de mooiste kiezen voor een staart, oren of vleugels.","Bouw een winterhol voor de egel: plak een dikke laag bladeren rondom en teken een slapend snuitje dat er net uit piept.","Maak er een vriendje bij van dezelfde bladeren: een egelbaby, een vossenjong of een uil op een tak."],"variations":["Bladerenvis: plak bladeren als schubben op een getekende vis en maak er een herfstzee van.","Bladerenboom: plak bladeren onder een getekende boom, alsof ze net gevallen zijn.","Leeuw: plak oranje en gele bladeren rondom een getekende kop als manen."],"themes":["herfst"],"canStay":false,"pinQuery":"dieren van herfstbladeren knutselen"},
  {"id":"watten-sneeuwpop","title":"Sneeuwpop van wattenbolletjes","emoji":"⛄","category":"plakken","summary":"Plak wattenbolletjes op donker papier tot een zachte sneeuwpop met een sjaal van vilt: sneeuwpret zonder koude handen!","ageMin":2,"ageMax":4,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"watten","note":"een handvol wattenbolletjes"},{"id":"gekleurd-papier","note":"donkerblauw of zwart, plus een stukje oranje voor de neus"},{"id":"knutsellijm","note":"uitsmeren met een kwastje of wattenstaafje"},{"id":"vilt","note":"een reepje als sjaal; gekleurd papier kan ook"}],"optional":[{"id":"penselen","note":"om de lijm uit te smeren"},{"id":"stiften","note":"voor ogen, mond en knopen"},{"id":"stickers","note":"als knopen of sneeuwvlokken"},{"id":"oud-shirt"}],"steps":["Smeer lijm in de vorm van een sneeuwpop op het donkere papier: een grote cirkel onderaan, een middelste en een kleine als hoofd. Dat doe jij.","Laat je kind wattenbolletjes op de lijm drukken, tot de sneeuwpop helemaal wit en zacht is.","Trek samen een paar bolletjes uit elkaar tot plukjes en plak ze rondom als dwarrelende sneeuw.","Knip een reepje vilt als sjaal en een oranje driehoekje als wortelneus en laat je kind ze opplakken.","Teken ogen, een mond en knopen, of plak er stickers op. Laat de sneeuwpop een uur plat drogen."],"ageTips":{"young":"Een tweejarige vindt de watten voelen en aandrukken al genoeg. Smeer de lijm vooraf in grote vlakken en benoem wat je doet: zacht, wit, druk maar!","old":"Laat je vierjarige zelf de cirkels tekenen, van groot naar klein, en tellen hoeveel bolletjes er in elke cirkel passen. Of maak een hele sneeuwpoppenfamilie."},"safety":["Peuters stoppen wattenbolletjes graag in hun mond of neus: geef er een paar tegelijk en blijf erbij. Een plukje watten kan bij inslikken in de keel blijven hangen.","Knutsellijm is niet om te eten: giet een klein beetje in een dekseltje en zet de fles buiten bereik."],"say":["Zacht! Nog een!","Voel eens: is het watje zacht of hard? En is het koud, net als echte sneeuw?","Ik zie een dikke buik en een klein hoofdje.","Wat heeft onze sneeuwpop nog nodig om het warm te hebben?","Jij hebt de hele buik volgeplakt, bolletje voor bolletje."],"words":["sneeuw","zacht","wit","rond","groot","klein","sjaal","koud"],"learn":["zintuigen","fijne-motoriek","taal"],"tips":["Smeer de lijm in kleine stukjes tegelijk: dan droogt hij niet op voordat de watten erop zitten en plakt hij niet aan alles.","Maak er een kerstkaart van: vouw stevig donker papier dubbel en plak de sneeuwpop op de voorkant."],"extenders":["Geef je kind een wasknijper om de wattenbolletjes mee te pakken en op te plakken: dat is lastiger én spannender.","Knip samen een hoed, bezem of muts uit gekleurd papier en laat je kind de sneeuwpop aankleden.","Teken voetstapjes, een slee of een vogeltje in de sneeuw: wie komt er bij de sneeuwpop op bezoek?"],"variations":["Kerst: maak een kerstman met een witte baard van watten op een rood gezicht.","Schaapje: plak watten op een getekend lijf en geef het zwarte pootjes en een kopje.","Sneeuwlandschap: plak een heuvel van watten en laat er sneeuw uit een getekende wolk dwarrelen."],"themes":["winter","kerst"],"canStay":false,"pinQuery":"sneeuwpop van watten knutselen"},
  {"id":"confetti-maken","title":"Confetti maken met de perforator","emoji":"🎊","category":"plakken","summary":"Pons gaatjes in gekleurd papier en kijk wat er uit de perforator komt: zelfgemaakte confetti om op te plakken of te strooien!","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":2,"duration":[10,20],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"perforator","note":"een enkele perforator gaat lichter dan een dubbele"},{"id":"gekleurd-papier","note":"in stroken van een paar centimeter breed"},{"id":"bakjes","note":"om de confetti in te verzamelen"}],"optional":[{"id":"lijmstift","note":"om confetti op een kaart of tekening te plakken"},{"id":"papier","note":"als kaart of ondergrond"},{"id":"tijdschriften","note":"glanzende folders geven bonte confetti"},{"id":"dienblad","note":"om boven te werken, dan veeg je alles zo weer op"}],"steps":["Knip het gekleurde papier in stroken van een paar centimeter breed: die passen makkelijk in de perforator.","Laat zien hoe het werkt: strook erin schuiven, met je hele hand stevig drukken en klak!","Laat je kind gaatjes ponsen, zoveel als het wil. Open daarna samen het klepje: kijk, confetti!","Verzamel de confetti in bakjes, per kleur of lekker door elkaar.","Smeer lijmstift op een kaart of tekening en strooi er confetti op. Schud de rest eraf boven een bakje.","Bewaar de overgebleven confetti in een potje voor het volgende feest."],"ageTips":{"young":"Voor een driejarige is drukken zwaar werk: laat je kind met twee handen bovenop drukken, of zet de perforator op de grond en laat je kind er met een platte hand op leunen.","old":"Laat je kleuter tellen hoeveel gaatjes er in één strook passen, of de confetti sorteren op kleur. Pons ook eens een rij gaatjes langs de rand van een vel: een kanten kaart!"},"safety":["Confetti is klein en blijft aan vingers en lippen plakken: houd het weg bij kinderen onder de 3, want alles wat door een wc-rolletje past, is te klein voor hen.","Alleen papier in de gleuf, geen vingertoppen: laat je kind drukken met de hand plat bovenop.","Strooi confetti niet in elkaars gezicht: een snippertje in het oog prikt en is lastig weg te krijgen."],"say":["Klak! Nog een keer!","Wat denk je dat er in het klepje zit?","Ik zie gaatjes in je papier, en hier liggen de rondjes die eruit kwamen!","Wat druk je hard. Je handen worden er sterk van!","Hoeveel rode rondjes heb jij al?"],"words":["gaatje","rondje","drukken","hard","confetti","strooien","klein"],"learn":["fijne-motoriek","rekenen","concentratie"],"tips":["Gebruik dun papier: een te dikke of dubbelgevouwen strook loopt vast en kost veel kracht.","Werk boven een dienblad of in een grote doos: de confetti blijft bij elkaar en je giet hem zo in een potje.","Ligt er toch confetti op de vloer? Stofzuig het op of druk er een stuk plakband op."],"extenders":["Pons een rij gaatjes langs de rand van een strook zwart papier en houd hem tegen het raam: kleine sterretjes van licht!","Probeer ander papier, zoals een reclamefolder, oud cadeaupapier of een stukje aluminiumfolie: welke confetti glimt en welke is gestreept?","Leg de confetti in rijtjes van vijf of tien op een dienblad: hoeveel rijtjes heb je al gemaakt?"],"variations":["Verjaardag: strooi confetti op een zelfgemaakte uitnodiging of plak hem op een feestmuts.","Oud en nieuw: plak confetti als vuurwerk op zwart papier.","Carnaval: plak confetti op een masker of een papieren hoed.","Herfst: pons gaatjes in verse bladeren en maak bladerconfetti in groen, geel en rood."],"themes":["verjaardag","oudennieuw","carnaval"],"canStay":false,"pinQuery":"confetti maken perforator kind"},
  {"id":"papieren-slinger","title":"Papieren kettingslinger","emoji":"🎉","category":"plakken","summary":"Plak stroken papier tot ringen die in elkaar haken en maak samen een lange slinger: hoe lang wordt hij, en welk patroon kies je?","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,30],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"gekleurd-papier","note":"in stroken van ongeveer 3 x 20 cm"},{"id":"plakband","note":"kleine stukjes alvast aan de tafelrand plakken"},{"id":"schilderstape","note":"om de slinger op te hangen"}],"optional":[{"id":"lijmstift","note":"in plaats van plakband"},{"id":"nietmachine","note":"snel en stevig; dat doe jij"},{"id":"kinderschaar","note":"voor kleuters die zelf stroken knippen"},{"id":"tijdschriften","note":"stroken uit folders voor een bonte slinger"}],"steps":["Knip gekleurd papier in stroken van ongeveer 3 cm breed en 20 cm lang. Een kleuter kan langs een getekende lijn meeknippen.","Plak alvast een rij stukjes plakband aan de rand van de tafel, zodat je kind ze makkelijk kan pakken.","Buig de eerste strook tot een ring en plak de uiteinden op elkaar.","Steek de volgende strook door de ring, buig hem rond en plak hem dicht. Zo groeit de ketting ring voor ring.","Kies samen een patroon, bijvoorbeeld rood, geel, rood, geel… Welke kleur komt er nu?","Hang de slinger op met schilderstape, hoog en buiten bereik van baby’s, en niet bij een bed."],"ageTips":{"young":"Voor een driejarige is de ring dichtplakken lastig: houd jij de uiteinden vast en laat je kind het plakbandje erop drukken. Een korte slinger van vijf ringen is al een feest.","old":"Laat je kleuter een patroon bedenken en volhouden, zoals rood-geel-geel, en tellen: hoeveel ringen heb je nodig van de deur tot de kast?"},"safety":["Een lange slinger is net een koord: hang hem hoog op, nooit bij bed, box of kinderstoel, en laat je kind hem niet om de nek leggen.","Nietjes zijn klein en scherp: de nietmachine is voor jou, en raap losse nietjes meteen op."],"say":["Rondje! Nog een rondje!","Rood, geel, rood, geel… welke kleur komt er nu?","Kijk eens hoe lang hij al is! Hoeveel ringen zijn het?","Ik zie dat je de strook netjes door de ring hebt gestoken. Lastig, en het is je toch gelukt!","Waar zullen we de slinger ophangen?"],"words":["ring","strook","ketting","patroon","lang","langer","door"],"learn":["rekenen","fijne-motoriek","concentratie","samen"],"tips":["Snelste manier: jij zet de ringen vast met de nietmachine, je kind kiest de kleur en steekt de strook door de ring.","Begin een paar dagen voor het feest en maak een aftelketting: elke dag mag er één ring af."],"extenders":["Laat je kind op elke strook een stip, hartje of krabbel tekenen voordat hij een ring wordt: zo krijgt elke ring een eigen plaatje.","Knip stroken uit een tijdschrift of uit oude tekeningen: de slinger wordt kleurig en verrassend.","Maak ringen van twee maten, met korte en lange stroken: groot, klein, groot, klein."],"variations":["Verjaardag: maak een aftelketting met evenveel ringen als nachtjes slapen tot het feest.","Kerst: maak een rood-groene slinger voor de kerstboom of rond de deur.","Koningsdag: rood, wit, blauw en oranje, voor in de vensterbank of boven de tafel."],"themes":["verjaardag","kerst","koningsdag"],"canStay":true,"stayTips":"Bewaar de halve slinger met de losse stroken in een schoenendoos en zet die hoog weg: een lange slinger is net een koord. Pak hem elke dag even tevoorschijn voor een paar nieuwe ringen: hoe lang is hij vandaag?","pinQuery":"papieren slinger ringen kind"},
  {"id":"lampion","title":"Een lampion voor Sint-Maarten","emoji":"🏮","category":"plakken","summary":"Plak snippers vloeipapier op een fles, melkpak of pot, maak er een hengsel aan en loop zingend rond met je eigen gloeiende lampion.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":15,"duration":[20,35],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"plastic-flesjes","note":"een lege fles van 1 tot 1,5 liter; de bovenkant knip jij eraf"},{"id":"vloeipapier","note":"in snippers van een paar centimeter, in een paar kleuren"},{"id":"knutsellijm","note":"aangelengd met water: 2 delen lijm op 1 deel water"},{"id":"water"},{"id":"kom","note":"om de lijm in aan te lengen"},{"id":"penselen","note":"een brede kwast"},{"id":"plakband","note":"om de scherpe snijrand af te plakken"},{"id":"touw","note":"voor een kort hengsel"},{"id":"led-lampje","note":"een waxinelichtje op batterij of een lampionstokje met lampje"},{"id":"schaar","note":"voor jou, om de fles op maat te knippen"}],"optional":[{"id":"melkpak","note":"met uitgeknipte raampjes, in plaats van de fles"},{"id":"glazen-pot","note":"voor kleuters van 4-5 jaar: extra mooi, maar breekbaar"},{"id":"takjes","note":"een stevig stokje om de lampion aan te dragen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Knip de fles af op ongeveer 15 cm hoogte en plak een strook plakband over de scherpe rand. Dat doe jij.","Roer in een bakje 2 delen knutsellijm met 1 deel water tot een dunne lijm.","Laat je kind met een brede kwast een stukje van de fles insmeren en er snippers vloeipapier op leggen. Strijk er nog wat lijm overheen.","Werk zo rondom de hele fles. Overlappen mag: daar ontstaan nieuwe kleuren!","Laat de lampion een nacht drogen. Prik daarna bovenaan twee gaatjes tegenover elkaar en knoop er een kort hengsel aan. Dat doe jij.","Zet het ledlampje erin, doe de grote lamp uit en oefen samen de liedjes: Sint-Maarten, Sint-Maarten, de koeien hebben staarten…"],"ageTips":{"young":"Voor een tweejarige werkt een plastic fles het best: licht en niet breekbaar. Laat je kind vooral snippers op de lijm leggen en strijk jij er een laagje lijm overheen.","old":"Een kleuter van 4 of 5 kan een glazen jampot beplakken en zelf snippers knippen. Plak er zwarte figuurtjes op, zoals een maan, sterren of een kat: die steken mooi af tegen de kleuren."},"safety":["Gebruik nooit een echte kaars of een waxinelichtje met vlam: vloeipapier vat in een paar seconden vlam. Alleen een ledlampje.","Ledlampjes werken vaak op een knoopcelbatterij, die levensgevaarlijk is bij inslikken. Plak het batterijklepje dicht met tape en bewaar reservebatterijen buiten bereik.","Een glazen pot alleen voor kleuters vanaf 4 jaar, en laat er niet mee rennen: glas breekt op een stoep. Plak bij een fles de snijrand goed af.","Houd het hengsel kort en hang de lampion na afloop niet bij bed of box: touw is een wurggevaar."],"say":["Plak! Rood, en nog een!","Kijk eens wat er gebeurt als het lampje aangaat!","Waar schijnt het licht door het papier? En waar is het donkerder?","Wat heb je geduldig geplakt, helemaal rond de fles!","Zullen we samen het lampionliedje oefenen?"],"words":["lampion","licht","donker","doorschijnend","kleverig","hengsel","zingen"],"learn":["fijne-motoriek","creativiteit","taal"],"tips":["Maak de lampion minstens een dag van tevoren: de lijm moet goed droog zijn, anders plakt het vloeipapier aan handen en jas.","Lampion van een melkpak: knip er raampjes in (dat doe jij), plak de binnenkant dicht met vloeipapier en versier de buitenkant met stift.","Plak het waxinelichtje met een rolletje plakband op de bodem vast, dan schuift het niet heen en weer tijdens het lopen."],"extenders":["Zet halverwege het ledlampje er even in (dat doe jij) en doe het licht uit: waar schijnt het nog wit door? Daar mag nog een snipper.","Zing tijdens het plakken een Sint-Maartenliedje en kies bij elk nieuw liedje een andere kleur vloeipapier.","Maak van een plastic bekertje een minilampion voor een knuffel, zodat die ook mee kan in de optocht."],"variations":["Pompoenlampion: gebruik alleen oranje vloeipapier en plak er een gezichtje van zwart papier op.","Sterrenlampion: donkerblauw vloeipapier met gele sterren van papier.","Optocht in huis: doe alle lampen uit, loop met de lampions door de gang en zing bij elke deur een liedje (met een mandarijn als beloning)."],"themes":["sintmaarten"],"canStay":false,"pinQuery":"lampion maken vloeipapier peuter"},
  {"id":"plakbandkunst","title":"Tape-kunst op het raam","emoji":"🏙️","category":"plakken","summary":"Scheur stukjes schilderstape en plak er huizen, bloemen en wegen mee op het raam. Kleur de tape in en zie het licht erdoor schijnen.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["muur"],"materials":[{"id":"schilderstape","note":"een of twee rollen; verschillende kleuren of breedtes maken het extra leuk"},{"id":"stiften","note":"om de tape na het plakken in te kleuren"}],"optional":[{"id":"bakpapier","note":"om een voorraad stroken op te plakken"},{"id":"vloeipapier","note":"snippers voor gekleurde ramen in de huizen"},{"id":"kinderschaar","note":"om tape te knippen; houd een doekje klaar voor de plakkerige bladen"},{"id":"knuffels","note":"die een huis op het raam nodig hebben"}],"steps":["Scheur alvast tien stroken tape van een hand lang en plak ze met één puntje aan de rand van de tafel of de vensterbank: dat is de tapevoorraad.","Laat je kind een strook lostrekken en op het raam plakken, op een hoogte waar je kind staand bij kan. Strijk de tape samen glad.","Maak samen vormen: drie stroken worden een dak, vier stroken een huis, een paar korte stroken in een kring een bloem.","Bouw zo een hele straat: huizen met ramen, een weg eronder, bomen en een zon in de hoek. Je kind scheurt zelf of pakt uit de voorraad.","Kleur de tape in met stiften: een rood dak, een gele zon, groene bomen. Kijk samen hoe het licht door de kleuren schijnt.","Laat het kunstwerk een paar dagen hangen en plak er steeds iets bij. Haal de tape binnen een week of twee weg, dan blijft er geen lijm achter."],"ageTips":{"young":"Een tweejarige kan tape nog niet goed van de rol scheuren: zet een voorraadje stroken klaar met een omgevouwen puntje om beet te pakken. Lostrekken en plakken is al knap werk: plak! Nog een!","old":"Laat je kleuter zelf tape scheuren en uitdagingen bedenken: een flat met drie verdiepingen, de eigen naam in tapeletters, of elke dag een nieuw huis in de straat."},"safety":["Plak alleen op een hoogte waar je kind zonder klimmen bij kan: zet geen stoel of krukje voor een raam dat open kan.","Een propje tape is klein en plakkerig en kan in de keel blijven hangen: blijf bij een tweejarige dichtbij en gooi verfrommelde stukjes meteen weg."],"say":["Trek maar! Plak!","Kijk, het licht schijnt door de gele tape. Het lijkt wel een lampje!","Hoeveel stroken heb je nodig voor een dak?","Wie woont er in dit huis, denk jij?","Wat goed: je hebt die lange strook helemaal zelf van de rol gescheurd!"],"words":["strook","plakken","scheuren","recht","schuin","driehoek","vierkant","doorzichtig"],"learn":["fijne-motoriek","rekenen","creativiteit"],"tips":["Plak een vel bakpapier vol met stroken tape: daar trekt je kind ze makkelijk af, ook de volgende dag nog.","Lijmresten op het glas haal je weg met warm water en een drupje afwasmiddel.","Kijk ’s avonds even van buiten naar het raam terwijl binnen het licht aan is: dan gloeit jullie tapestraat."],"extenders":["Geef een nieuwe opdracht: maak een huis voor elke knuffel, of een garage voor de grootste auto.","Plak jouw eigen huis aan de andere kant van het raam en vraag of je kind er een weg naartoe plakt.","Leg snippers vloeipapier tegen het raam en plak er een strook tape overheen: zo krijgen de huizen gekleurde ramen.","Speel ‘ik zie, ik zie’ met de tapestraat: zie jij een huis met twee ramen? Waar is de kleinste boom?","Teken met stift poppetjes, katten en auto’s op losse stukjes tape en laat je kind ze in de straat plakken."],"variations":["Tapedoolhof: plak een doolhof op een deur of op tafel en laat een speelgoedautootje of je vinger de weg naar de uitgang zoeken.","Kerst: plak een kerstboom van groene stroken op het raam, met gekleurde stukjes tape als ballen en een ster in de top.","Lente: plak een bloemenveld met lange stelen en kleur de blaadjes in met stiften.","Schaduwspel: plak op een zonnige dag figuren op het raam en zoek samen de schaduwen op de vloer. Waar zijn ze over een uur?"],"themes":[],"canStay":true,"stayTips":"Laat de tapestraat gerust een paar dagen hangen en leg de rol met een voorraad stroken op de vensterbank, zodat je kind zo verder kan. Haal alles binnen een week of twee weg, voordat de lijm in de zon vastbakt.","pinQuery":"schilderstape raam kunst kind"},
  {"id":"plaatjesjacht","title":"Plaatjesjacht in tijdschriften en folders","emoji":"🔍","category":"plakken","summary":"Ga op jacht in folders en tijdschriften: knip alle dieren, auto’s of lekkere hapjes uit en plak ze op een verzamelvel per soort.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":3,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"tijdschriften","note":"een stapel reclamefolders, tijdschriften of een oude catalogus"},{"id":"kinderschaar"},{"id":"lijmstift"},{"id":"papier","note":"een vel per verzameling, liefst wat steviger papier"},{"id":"stiften","note":"om bovenaan elk vel een tekeningetje te zetten"}],"optional":[{"id":"bakjes","note":"om de buit per soort te bewaren tot het plakken"},{"id":"enveloppen","note":"voor losse plaatjes die tot morgen moeten wachten"},{"id":"nietmachine","note":"om de verzamelvellen tot een boek te nieten"},{"id":"groot-papier","note":"voor één grote zoekplaat"}],"steps":["Teken bovenaan een paar vellen papier een simpel plaatje, bijvoorbeeld een dier, een auto en een appel. Dat worden de verzamelvellen.","Leg de folders op tafel en kies samen wat jullie gaan zoeken. Begin met één soort, bijvoorbeeld dieren.","Laat je kind bladeren en plaatjes aanwijzen. Je kleuter knipt zelf; bij een driejarige knip jij grof uit of scheur je samen.","Sorteer de buit: welk plaatje hoort bij welk vel? Een tijger bij de dieren, een fiets bij de dingen met wielen, een kaas bij het eten.","Plak alles met de lijmstift op het juiste vel. Kriskras door elkaar mag, op een rijtje ook.","Tel aan het eind samen: welk vel is het volst? Stop de losse plaatjes in een envelop voor de volgende keer."],"ageTips":{"young":"Houd het voor een driejarige bij twee soorten, zoals dieren en eten, en knip de grootste plaatjes grof voor. Benoem wat je kind vindt: een koe! Een banaan!","old":"Laat je kleuter zelf knippen en lastigere soorten verzinnen: alles wat rood is, iets wat je kunt eten én groen is, of dingen die geluid maken. Of maak een vel per letter: alles met een b."},"safety":["Haal de nietjes uit de rug van tijdschriften en folders voordat je kind gaat bladeren. Nietjes prikken en passen door een wc-rolletje.","Blader de folders even door en haal pagina’s met ongepaste foto’s, medicijnen of drank eruit.","Gebruik een kinderschaar met ronde punt en knip zelf de moeilijke stukjes. Leg de schaar na afloop weg als er jongere kinderen rondlopen."],"say":["Een hond! Op welk vel?","Ik zie iets met wielen… zie jij het ook?","Een fiets heeft wielen. Wat heeft er nog meer wielen?","Welk vel is het volst, denk je? Zullen we tellen?","Wat heb jij goed gezocht: je vond zelfs het kleine vogeltje in de hoek!"],"words":["zoeken","knippen","plakken","dieren","wielen","eten","hetzelfde","anders"],"learn":["taal","rekenen","fijne-motoriek","concentratie"],"tips":["Supermarktfolders zitten vol eten, speelgoedfolders vol dieren en voertuigen. Bewaar ze een week in een la, dan heb je altijd een stapel klaar.","Werk op een oud tijdschrift of een dienblad als ondergrond: dan gooi je snippers en lijmrestjes in één keer weg."],"extenders":["Noem een nieuwe soort om te verzamelen en maak er een vel bij: alles wat geel is, dingen uit de keuken of iets wat vliegt.","Zet een uitdaging neer: kun je vijf verschillende honden vinden? Of iets wat groter is dan ons huis?","Laat je kind van de buit een plaat maken: een boerderij voor de dieren, een weg voor de auto’s, een gedekte tafel met het eten.","Speel winkeltje met de plaatjes: jij bestelt een appel en een fiets, je kind zoekt ze op en geeft ze aan jou.","Plak alles kriskras op één groot vel en speel daarna om de beurt: ik zie, ik zie… een kat!"],"variations":["Sinterklaas: knip uit de speelgoedfolder wat je graag zou willen en plak het op een verlanglijstje.","Herfst: zoek alles wat bij de herfst hoort, zoals regenjassen, paddenstoelen, appels en laarzen.","Kleurenboek: maak een vel per kleur en plak alles wat rood, geel of blauw is op het juiste vel.","Mijn huis: knip meubels en spullen uit een woonfolder en richt een getekend huis in."],"themes":[],"canStay":true,"stayTips":"Leg de folders, de verzamelvellen en een envelop met losse plaatjes op een dienblad en zet de schaar hoog weg. Morgen pak je het dienblad erbij en gaat de jacht gewoon verder.","pinQuery":"knippen uit folders sorteren kleuter"},
  {"id":"memory-maken","title":"Zelf memory maken en spelen","emoji":"🃏","category":"plakken","summary":"Knip kaartjes uit een cornflakesdoos, plak of teken steeds twee dezelfde plaatjes en speel daarna je eigen memoryspel.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":1,"soloFrom":4,"cleanupMinutes":2,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"karton","note":"een lege cornflakes- of crackerdoos, goed voor 12 tot 20 kaartjes"},{"id":"schaar","note":"om de kaartjes te knippen (dat doe jij)"},{"id":"stickers","note":"steeds twee dezelfde, of teken de plaatjes zelf"},{"id":"stiften","note":"om plaatjes te tekenen en in te kleuren"}],"optional":[{"id":"tijdschriften","note":"twee dezelfde folders geven in één keer veel paren"},{"id":"lijmstift","note":"om plaatjes uit folders op te plakken"},{"id":"kinderschaar","note":"voor kleuters die zelf plaatjes willen knippen"},{"id":"enveloppen","note":"om het spel in te bewaren"}],"steps":["Knip de doos open en knip er 12 tot 16 even grote kaartjes uit, ongeveer zo groot als een flinke koek. Dat doe jij.","Leg de kaartjes met de grijze binnenkant naar boven: daar komen de plaatjes op.","Maak de paren: plak op twee kaartjes steeds dezelfde sticker, of teken twee keer hetzelfde, zoals twee zonnen, twee huizen of twee gezichtjes.","Controleer samen of elk kaartje een tweeling heeft en tel de paren.","Speel memory: leg alle kaartjes omgekeerd in rijen. Draai om de beurt twee kaartjes om. Hetzelfde? Dan mag je ze houden en nog een keer.","Speel een paar rondes en tel aan het eind wie de meeste paren heeft. Bewaar het spel in een envelop."],"ageTips":{"young":"Begin met een driejarige met zes paren stickers die echt verschillen, zoals een dier, een auto en een bloem. Speel eerst met alle kaartjes open: zoek jij de tweeling van deze poes?","old":"Laat je kleuter de paren zelf tekenen, en wel precies hetzelfde: evenveel stippen, dezelfde kleuren. Maak het lastiger met 12 paren, of met paren die bij elkaar horen, zoals een hond en een bot."},"safety":["Karton knippen is zwaar werk: doe het zelf met een gewone schaar en leg die daarna buiten bereik.","Stickers en de losse restjes van het stickervel belanden makkelijk in de mond van een broertje of zusje onder de 3: ruim ze meteen op."],"say":["Draai maar om! Wat zie je?","Hetzelfde of anders? Kijk goed!","Een huis… waar lag het andere huis ook alweer?","Jij hebt onthouden waar de vis lag. Wat een geheugen!","Welk paar vind je het moeilijkst om te vinden?"],"words":["hetzelfde","anders","paar","omdraaien","onthouden","beurt","tweeling"],"learn":["concentratie","rekenen","samen","fijne-motoriek"],"tips":["Zie je aan de bedrukte achterkant welk kaartje het is? Kleur alle achterkanten met dezelfde stift of plak er een strookje schilderstape over.","Twee dezelfde supermarktfolders geven in één keer veel paren: knip uit allebei hetzelfde plaatje en plak het op.","Bewaar het spel in een envelop met een tekening erop: zo heb je een spelletje klaar voor in de wachtkamer of op visite."],"extenders":["Teken samen ter plekke een paar nieuwe paren en speel dan opnieuw met meer kaartjes.","Speel ‘wat mist er?’: leg vier paren open neer, laat je kind de ogen dichtdoen en haal er één kaartje weg.","Verstop van elk paar één kaartje in de kamer en laat je kind de tweelingen gaan zoeken.","Laat een knuffel meespelen: je kind draait ook voor de knuffel om en helpt de knuffel zoeken.","Leg de kaartjes eens in een grote kring in plaats van in rijen: dan moet je op een nieuwe manier onthouden."],"variations":["Familiememory: plak twee keer dezelfde foto’s van opa, oma, de buren en de huisdieren op karton.","Herfst: teken twee keer een eikel, een paddenstoel, een blad en een egel en speel herfstmemory.","Tellen en letters: maak paren van een cijfer en evenveel stippen, of van een letter en een plaatje dat ermee begint.","Kerst: teken twee keer een ster, een kerstbal, een boom en een cadeautje en geef het spel cadeau aan opa en oma."],"themes":[],"canStay":false,"pinQuery":"zelf memory maken karton kind"},
  {"id":"puzzel-doos","title":"Puzzels van een cornflakesdoos","emoji":"🧩","category":"plakken","summary":"Knip de voorkant van een lege doos in stukken en puzzel alles weer heel: twee stukken voor een peuter, twaalf voor een kleuter.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"verpakkingen","note":"lege dozen met een groot, duidelijk plaatje: ontbijtgranen, crackers, thee, speelgoed"},{"id":"schaar","note":"om de stukken te knippen (dat doe jij)"},{"id":"stiften","note":"om de achterkant van elke puzzel een eigen kleur te geven"},{"id":"enveloppen","note":"één per puzzel, om in te bewaren"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf een puzzel willen knippen"},{"id":"papier","note":"voor een puzzel van een eigen tekening"},{"id":"lijmstift","note":"om een tekening op de binnenkant van een doos te plakken"},{"id":"dienblad","note":"als puzzelplank die je met een halve puzzel opzij kunt zetten"}],"steps":["Knip de voorkant van een paar lege dozen los. Kies dozen met een groot, duidelijk plaatje.","Knip elke voorkant in stukken: voor een tweejarige in twee of drie rechte stukken, voor een kleuter in zes tot twaalf stukken met schuine of golvende randen.","Zet op de achterkant van alle stukken van één puzzel dezelfde gekleurde stip, dan raken de puzzels niet door elkaar.","Puzzel de eerste samen: leg een stuk neer en laat je kind zoeken wat ernaast past. Draai het stuk een kwartslag als het niet past.","Haal daarna twee of drie puzzels door elkaar en laat je kind ze sorteren op kleurstip en weer heel leggen.","Bewaar elke puzzel in een eigen envelop met de kleurstip erop."],"ageTips":{"young":"Begin voor een tweejarige met twee stukken, recht doorgeknipt, en houd een hele doos ernaast als voorbeeld. Gaat dat goed, knip dan een tweede doos in drie stukken.","old":"Laat je kleuter zelf een puzzel voor jou knippen met een kinderschaar. Of teken een eigen tekening op de grijze binnenkant van een doos en knip die in stukken: een echte eigen puzzel."},"safety":["Gebruik geen dozen van vaatwastabletten, wasmiddel of medicijnen: zo leert je kind niet dat je met die verpakkingen mag spelen.","Haal plastic binnenzakken, kruimels en nietjes uit de doos. Kauwt je peuter graag op karton, haal natte stukjes dan uit de mond.","Knip de stukken zelf met een gewone schaar en leg die daarna buiten bereik."],"say":["Waar past dit stuk? Hier?","Draai maar eens. Past het nu?","Klaar! De puzzel is weer heel!","Ik zie een stukje van een gezicht. Waar is de rest?","Je bleef zoeken tot je het goede stuk had. Wat heb je volgehouden!"],"words":["passen","draaien","stuk","heel","rand","hoek","naast","hetzelfde"],"learn":["concentratie","rekenen","fijne-motoriek","taal"],"tips":["Gooi je toch een doos weg? Knip de voorkant er even af en bewaar die in een la: zo groeit je puzzelvoorraad vanzelf.","Is een doos erg dun? Plak de voorkant eerst op een tweede stuk karton, dan worden de stukken stevig en buigen ze niet.","Bewaar alle enveloppen samen in een schoenendoos: dat is je eigen puzzelkast."],"extenders":["Haal twee of drie puzzels door elkaar en laat je kind eerst sorteren: welk stuk hoort bij welke doos?","Knip een puzzel nog één keer kleiner: twee stukken worden er vier, vier worden er acht.","Verstop de stukken in de kamer en ga samen op puzzeljacht: pas als alle stukken gevonden zijn, kun je de puzzel leggen.","Puzzel tegen de klok: tel samen tot twintig of zet een kookwekker. Lukt het voordat de tijd om is?","Ruil van rol: laat je kind een puzzel door elkaar husselen en kijk of jij de puzzel kunt leggen, met je kind als hulp."],"variations":["Eigen tekening: laat je kind een tekening op de binnenkant van een doos maken en knip die in stukken.","Fotopuzzel: plak een afgedrukte foto van de familie of het huisdier op karton en knip die in stukken.","Kerst: knip oude kerstkaarten in drie of vier stukken en puzzel ze weer heel.","Sinterklaas: knip een plaatje uit de speelgoedfolder tot een puzzel en stop die in een envelop in de schoen."],"themes":[],"canStay":false,"pinQuery":"zelf puzzel maken van doos"},
  {"id":"speeldeeg-maken","title":"Speeldeeg maken zonder koken","emoji":"🥣","category":"deeg","summary":"Weeg, roer en kneed samen je eigen zachte speeldeeg in jullie lievelingskleur: zelf maken is de helft van de pret.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[20,35],"supervision":1,"soloFrom":null,"cleanupMinutes":10,"noise":1,"energy":1,"places":["keuken","tafel"],"materials":[{"id":"bloem","note":"250 g"},{"id":"zout","note":"125 g fijn zout"},{"id":"olie","note":"2 el"},{"id":"water","note":"ca. 200 ml, kokend"},{"id":"kookplaat","note":"of waterkoker, voor het kokende water"},{"id":"kom","note":"een grote"},{"id":"lepel","note":"een stevige (houten) lepel om te roeren"},{"id":"kleurstof","note":"een paar druppels per kleur"}],"optional":[{"id":"zip-zakjes","note":"om de kleur zonder vlekken door te kneden, en om te bewaren"},{"id":"potjes","note":"afgesloten bakjes om het deeg in te bewaren"},{"id":"oud-shirt"}],"steps":["Weeg samen 250 g bloem en 125 g zout af in een grote kom. Je kind mag strooien en roeren.","Doe er 2 el olie bij, en eventueel 1 el citroensap: dan blijft het deeg langer goed.","Giet er ca. 200 ml kokend water bij en roer met een lepel tot alles samenkomt (dat doe jij; je kind kijkt op afstand).","Laat het deeg een paar minuten afkoelen. Voel eerst zelf of het niet meer heet is.","Kneed het deeg samen glad op tafel. Plakt het? Strooi er dan een beetje bloem bij.","Verdeel het in bollen, maak er een kuiltje in en druppel er kleurstof in. Kneed de kleur erdoor, het liefst in een ritszakje.","Bewaar het deeg in een afgesloten bakje of zakje in de koelkast: zo blijft het 1-2 weken goed."],"ageTips":{"young":"Een tweejarige kan vooral strooien, roeren in de droge bloem en kneden zodra het deeg lauw is. Geef je peuter een eigen klein bolletje om alvast mee te knijpen.","old":"Laat je kleuter zelf afwegen (wanneer staat de weegschaal op 250?), de lepels olie tellen en een mengkleur bedenken: wat krijg je als je geel en blauw deeg door elkaar kneedt?"},"safety":["Kokend water: dat doe jij. Zet de kom ver van de tafelrand en laat je kind pas meekneden als het deeg lauw is.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren.","Rauwe bloem kan bacteriën bevatten: proeven is niet de bedoeling. Proeft je kind veel, verhit de bloem dan eerst 5 minuten op 175 °C in de oven en laat hem afkoelen."],"say":["Kneden, kneden, kneden!","Hoe voelt het deeg nu: warm, zacht of plakkerig?","Wat denk je dat er gebeurt als we blauw en geel door elkaar kneden?","Ik zie dat het deeg rood wordt, en je handen ook een beetje!","Wat heb jij stevig gekneed, je armen zijn vast moe!"],"words":["afwegen","roeren","kneden","plakkerig","zacht","warm","mengen","bolletje"],"learn":["fijne-motoriek","rekenen","zintuigen","ontdekken"],"tips":["Kneed de kleurstof door het deeg in een ritszakje: geen vlekken op handen en tafel.","Te plakkerig? Een beetje bloem erbij. Te droog of brokkelig? Kneed er een paar druppels olie of water door.","Haal het deeg een kwartiertje voor het spelen uit de koelkast, dan is het weer lekker soepel."],"extenders":["Zet vormpjes, een deegroller en een vork klaar zodra het deeg af is: uitrollen, uitsteken en gaatjes prikken kan meteen.","Rol van elke kleur een lange slang en draai of vlecht ze samen tot een regenboogslak.","Maak één geurbol: kneed er een snufje kaneel door en laat je kind met de ogen dicht raden welke bol zo lekker ruikt."],"variations":["Sinterklaas: kneed er 1 tl speculaaskruiden door voor geurig, bruin deeg.","Kerst: maak rood en groen deeg en steek er sterren en boompjes uit.","Regenboog: verdeel het deeg in zes bolletjes en geef elk een eigen kleur."],"themes":[],"canStay":false,"pinQuery":"speeldeeg maken zonder koken"},
  {"id":"zoutdeeg","title":"Zoutdeeg-hangers en afdrukjes","emoji":"🧂","category":"deeg","summary":"Kneed zoutdeeg, steek hangers uit of maak een handafdruk, droog ze in de oven en beschilder ze: een cadeautje dat jaren meegaat.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[20,35],"supervision":1,"soloFrom":4,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"bloem","note":"200 g"},{"id":"zout","note":"100 g fijn zout"},{"id":"water","note":"±125 ml lauw water"},{"id":"kom"},{"id":"deegroller"},{"id":"uitsteekvormpjes","note":"of een glas om rondjes uit te steken"},{"id":"rietjes","note":"om een ophanggaatje te prikken"},{"id":"bakpapier"},{"id":"oven"},{"id":"plakkaatverf","note":"om te beschilderen als alles droog is"},{"id":"penselen"}],"optional":[{"id":"touw","note":"lint of touw om de hanger op te hangen"},{"id":"mes","note":"om een rondje om de handafdruk te snijden (dat doe jij)"},{"id":"knutsellijm","note":"verdund met wat water als glanslaagje"},{"id":"oud-shirt"}],"steps":["Meng samen 200 g bloem en 100 g zout in een kom. Giet er beetje bij beetje ±125 ml lauw water bij en kneed tot een stevig, glad deeg.","Rol het deeg op bakpapier uit tot ongeveer een halve centimeter dik. Voor een handafdruk maak je een plak van ruim 1 cm.","Steek vormpjes uit. Voor een handafdruk druk je de hand van je kind stevig in het deeg en snijd je er een rondje omheen (dat doe jij).","Prik met een rietje een gaatje bovenin, zodat je de hanger later kunt ophangen.","Droog alles op de bakplaat 1-3 uur in de oven op 100-120 °C (dat doe jij), of 2-3 dagen aan de lucht. Dikke stukken hebben langer nodig.","Laat alles helemaal afkoelen en beschilder het dan met plakkaatverf. Rijg er een lintje door als de verf droog is."],"ageTips":{"young":"Een tweejarige vindt kneden, prikken en vormpjes drukken het leukst. Rol jij het deeg uit; je peuter drukt de vormpjes met twee handen. Bij een handafdruk druk jij zachtjes mee terwijl jullie tot drie tellen.","old":"Laat je kleuter zelf het water afmeten en kneden, met een potlood een naam of jaartal in de achterkant krassen en bedenken welke hanger voor wie is."},"safety":["Zoutdeeg bevat veel zout: niet opeten, en giftig voor honden. Hang de hangers hoog in de kerstboom als je een hond hebt.","De oven en de bakplaat zijn heet: dat doe jij. Laat alles op de plaat afkoelen voordat je kind het pakt.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Druk! Hard drukken!","Hoe voelt het deeg: korrelig of glad?","Ik zie al je vingers in het deeg staan, zelfs je duim!","Wie krijgt deze hanger, denk je?","Wat schilder je zorgvuldig, je neemt echt de tijd."],"words":["kneden","uitrollen","uitsteken","afdruk","gaatje","korrelig","hard","drogen"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Bobbelt het deeg in de oven? Zet de oven lager (100 °C) en droog wat langer.","Een laagje verdunde knutsellijm na het verven maakt de hanger glanzend en steviger.","Overgebleven deeg blijft in een afgesloten zakje in de koelkast nog een paar dagen goed."],"extenders":["Druk patronen in de vormpjes met een vork, een rietje of de punt van een potlood: stippen, strepen of een bloemetje.","Rol kleine slangetjes en bolletjes en plak ze met een druppeltje water op de vormpjes: een neus, een hartje of een randje.","Maak van de restjes deeg een vrij kunstwerk, zoals een slak, een nestje met eitjes of een eigen fantasiedier."],"variations":["Kerst: steek sterren, boompjes en hartjes uit voor in de kerstboom.","Moederdag: maak een hartje met de vingerafdrukken van je kind en rijg er een lint door.","Herfst: rol een blad over het deeg en bekijk de nerven in de afdruk.","Naambordje: steek een groot rondje uit en kras er samen de naam van je kind in, voor op de kamerdeur."],"themes":["kerst","cadeau","moederdag"],"canStay":false,"pinQuery":"zoutdeeg hangers kind"},
  {"id":"wolkendeeg","title":"Wolkendeeg: zacht maanzand","emoji":"☁️","category":"deeg","summary":"Met alleen bloem en olie maak je wolkendeeg: zo zacht als een wolk, kruimelig als zand en toch te vormen tot taartjes en bergen.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":5,"duration":[20,40],"supervision":2,"soloFrom":3,"cleanupMinutes":15,"noise":1,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"bloem","note":"500 g"},{"id":"olie","note":"125 ml zonnebloemolie (of babyolie, dan niet om te proeven)"},{"id":"opbergbak","note":"een grote bak om in te mengen en te spelen"}],"optional":[{"id":"uitsteekvormpjes","note":"of zandvormpjes"},{"id":"plastic-bekers","note":"om taartjes mee te maken"},{"id":"lepel","note":"om te scheppen"},{"id":"klein-speelgoed","note":"diertjes of autootjes om te verstoppen"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Leg een knoeimat neer en zet een grote bak op de vloer of tafel: wolkendeeg komt overal.","Doe 500 g bloem in de bak en giet er 125 ml olie over.","Wrijf en kneed het samen met je handen door elkaar tot het kruimelig is, maar een bal blijft als je erin knijpt. Te droog? Nog een scheutje olie.","Geef bekertjes, vormpjes en lepels: bak zandtaartjes, bouw bergen en graaf tunnels.","Verstop diertjes of autootjes in het deeg en laat je kind ze weer opgraven.","Bewaar het wolkendeeg in een afgesloten bak: het blijft een paar weken goed. Veeg of zuig kruimels eerst droog op; een natte doek maakt er pap van."],"ageTips":{"young":"Een tweejarige schept en graaft het liefst. Geef één grote lepel, een beker en een paar grote diertjes, en speel in een bak met een hoge rand.","old":"Laat je kleuter zelf afmeten en mengen, een maanlandschap bouwen met kraters en een raket van een wc-rolletje, of zandtaartjes tellen en verkopen."},"safety":["Rauwe bloem kan bacteriën bevatten: niet opeten. Proeft je kind veel, verhit de bloem dan eerst 5 minuten op 175 °C in de oven, laat hem afkoelen en gebruik zonnebloemolie in plaats van babyolie.","Kruimels met olie maken de vloer glad: veeg ze direct op.","Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: verstop voor je peuter alleen grote speeltjes."],"say":["Knijp… en het blijft een bal!","Hoe voelt het: zacht, koel of een beetje vettig?","Wat gebeurt er als je de bal weer loslaat en erop drukt?","Ik zie dat je een hele hoge berg bouwt.","Graven! Wie zit daar verstopt?"],"words":["kruimelig","zacht","knijpen","graven","scheppen","vormpje","berg","verstoppen"],"learn":["zintuigen","fijne-motoriek","creativiteit","ontdekken"],"tips":["Speel op een oud laken of in de lege badkuip: schud het laken daarna uit boven de vuilnisbak of veeg de badkuip leeg met een stoffer.","Olie kan vetvlekjes geven op kleding en vloerkleed: trek oude kleren aan en speel liever op een gladde vloer.","Wolkendeeg is goedkoop: huismerkbloem en gewone zonnebloemolie werken prima."],"extenders":["Zet er een vergiet bij en duw het deeg met je handen door de gaatjes: kijk, het sneeuwt kruimels!","Strijk een stuk deeg glad en druk er sporen in met een autootje, een vork of de pootjes van een speelgoeddier: wie liep hier?","Teken een schatkaart met een kruisje, verstop een groot speeltje op die plek in de bak en laat je kind graven tot de schat gevonden is."],"variations":["Zomer: zet er schelpen en emmertjes bij en bouw een zandkasteel.","Bouwplaats: laat graafmachines en vrachtautootjes het deeg verplaatsen.","Geurdeeg: meng er 1 el kaneel of speculaaskruiden door voor een bruine, geurige versie.","Maanlandschap: druk kraters met een bal en laat een raket van een wc-rolletje landen."],"themes":[],"canStay":false,"pinQuery":"wolkendeeg maken peuter"},
  {"id":"sneeuwdeeg","title":"Sneeuwdeeg van maizena","emoji":"⛄","category":"deeg","summary":"Kneed maizena en conditioner tot koel, zijdezacht sneeuwdeeg en bouw binnen sneeuwpoppen, iglo’s en een winterlandschap voor je speelgoeddieren.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":3,"duration":[15,30],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"maizena","note":"200 g"},{"id":"conditioner","note":"100 ml; liefst mild en zonder sterke geur"},{"id":"kom","note":"of een bak om in te mengen"}],"optional":[{"id":"dienblad","note":"met randje, om op te spelen"},{"id":"klein-speelgoed","note":"pinguïns, ijsberen of andere diertjes"},{"id":"takjes","note":"als bomen of als armen voor de sneeuwpop"},{"id":"koelkast","note":"voor extra koude sneeuw"}],"steps":["Doe 200 g maizena in een kom en laat je kind er eerst in voelen: hoor je het knerpen als je knijpt?","Giet er 100 ml conditioner bij en kneed met je handen tot een zacht deeg dat aan elkaar plakt als je knijpt. Te plakkerig? Nog wat maizena erbij.","Leg het deeg 15 minuten in de koelkast als je het extra koud wilt: dan voelt het nog meer als sneeuw.","Rol balletjes en bouw samen sneeuwpoppen: een grote bal onderop, een kleine erbovenop, takjes als armen.","Zet speelgoeddieren in de sneeuw: laat ze sporen maken, een iglo bouwen of verstoppertje spelen.","Bewaar het deeg een paar dagen in een afgesloten bakje. Gooi restjes in de vuilnisbak, niet door de gootsteen."],"ageTips":{"young":"Een tweejarige vindt knijpen en verkruimelen het leukst. Speel op een dienblad met rand, geef een lepel en een bekertje en houd een doekje klaar voor de handjes.","old":"Laat je kleuter zelf afwegen (200 g maizena, 100 ml conditioner) en een heel winterdorp bouwen. Hoeveel sneeuwballen heb je nodig voor drie sneeuwpoppen?"},"safety":["Conditioner is niet om te eten en prikt in de ogen: houd een doekje klaar en was handen na afloop. Stopt je kind nog alles in de mond, kies dan eetbaar havermoutdeeg.","Gemorste maizena maakt de vloer spiegelglad: veeg het meteen op."],"say":["Brrr, koud! Voel je dat?","Hoor je het knerpen als je knijpt?","Wat gebeurt er als je een bal rolt en hem dan platdrukt?","Ik zie pootafdrukken in de sneeuw. Van wie zouden die zijn?","Wat heb je lang en geduldig gerold!"],"words":["sneeuw","koud","zijdezacht","knerpen","rollen","sneeuwpop","spoor","bovenop"],"learn":["zintuigen","fijne-motoriek","creativiteit","taal"],"tips":["Speel op een dienblad of bakplaat met rand: de kruimels blijven dan bij elkaar.","Neem de goedkoopste conditioner; zonder sterke geur is het fijner voor de huid en de neus."],"extenders":["Leg de helft van het deeg 10 minuten in de koelkast en speel intussen verder met de rest: voel daarna samen welke sneeuw het koudst is.","Strooi een laagje losse maizena over het dienblad als verse sneeuw en laat je kind er sporen, rondjes en sneeuwvlokken in tekenen.","Rol een voorraad sneeuwballetjes en gooi ze om de beurt in een beker: hoeveel gooi je er raak?"],"variations":["Poolgebied: zet pinguïns en ijsberen in de sneeuw en bouw een iglo van bolletjes.","Kerst: prik groene takjes als kerstboompjes in de sneeuw en geef de sneeuwpop een sjaaltje van vilt.","Sporen raden: laat autootjes of dierenpootjes sporen maken en raad samen van wie ze zijn."],"themes":["winter","kerst"],"canStay":false,"pinQuery":"sneeuwdeeg maizena conditioner"},
  {"id":"eetbaar-deeg","title":"Eetbaar speeldeeg voor de kleinsten","emoji":"🌾","category":"deeg","summary":"Maak zacht deeg van havermout, olie en water dat je dreumes gerust mag proeven: knijpen, prikken en platslaan zonder zorgen.","ageMin":1,"ageMax":2,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":2,"soloFrom":null,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"havermout","note":"100 g"},{"id":"blender","note":"of staafmixer, om de havermout fijn te malen"},{"id":"olie","note":"1 el zonnebloemolie"},{"id":"water","note":"±5-6 el"},{"id":"kom"}],"optional":[{"id":"dienblad","note":"of het blad van de kinderstoel"},{"id":"uitsteekvormpjes","note":"grote, zonder scherpe randjes"},{"id":"plastic-bekers","note":"om rondjes mee uit te steken"}],"steps":["Maal 100 g havermout in de blender tot fijn meel (dat doe jij).","Doe het meel in een kom met 1 el olie en voeg lepel voor lepel water toe (±5-6 el), tot je een soepel deeg hebt.","Kneed het deeg kort door en geef je dreumes een flinke bol op een dienblad of het blad van de kinderstoel.","Doe voor wat je allemaal kunt: een balletje rollen, een plat koekje slaan, gaatjes prikken met je vinger.","Geef er een bekertje of groot vormpje bij om in te drukken of rondjes mee uit te steken.","Bewaar restjes afgedekt in de koelkast en gebruik ze binnen 1-2 dagen."],"ageTips":{"young":"Een dreumes van 1 ontdekt vooral met handen en mond. Geef één bol zonder spulletjes erbij en benoem wat er gebeurt: plat, rond, een gaatje!","old":"Een tweejarige kan meehelpen met water erbij lepelen en kneden, slangetjes rollen en met een beker koekjes uitsteken. Tel ze samen: één, twee, drie!"},"safety":["Ook eetbaar deeg is plakkerig en kan in de keel blijven steken: laat je dreumes rechtop zitten en blijf erbij als er gehapt wordt.","Havermout bevat vaak sporen van gluten: kies glutenvrije havermout bij coeliakie of een glutenallergie.","Het mes van de blender is vlijmscherp: dat doe jij, en haal de stekker eruit voordat je het meel eruit schept.","Het deeg bederft snel: bewaar het in de koelkast en gooi het na 1-2 dagen weg, of eerder als het zuur ruikt."],"say":["Knijp! Zacht hè?","Plat! Nog eens!","Ik zie dat je er met je vinger een gaatje in prikt.","Hoe ruikt het? Een beetje naar pap?","Wat rol jij goed, met allebei je handen!"],"words":["zacht","plakkerig","knijpen","plat","rond","rollen","prikken","gaatje"],"learn":["zintuigen","fijne-motoriek","taal","ontdekken"],"tips":["Doe het vlak voor het badje: havermout plakt een beetje, maar veegt makkelijk af met een vochtig washandje.","Te plakkerig? Strooi er wat havermoutmeel bij. Te droog? Nog een lepel water."],"extenders":["Verstop een groot duploblok in een bol deeg en laat je dreumes het weer tevoorschijn peuteren.","Rol samen een lange slang en laat je kind er stukjes af knijpen, plukken of plat drukken.","Druk een paar ontbijtringetjes in een plat koekje van deeg en laat je dreumes ze eruit pulken: opeten mag."],"variations":["Kleurtje: kneed er een theelepel bietensap of een paar geprakte blauwe bessen door (dat vlekt wel een beetje).","Geurtje: kneed er een snufje kaneel door en ruik er samen aan.","Feestje: steek met een bekertje taartjes uit en zing samen ‘Lang zal ze leven’."],"themes":[],"canStay":false,"pinQuery":"eetbaar speeldeeg havermout dreumes"},
  {"id":"deegbakkerij","title":"Bakkertje spelen met speeldeeg","emoji":"🎂","category":"deeg","summary":"Rol, steek uit en versier: je kind is de bakker en bakt koekjes, broodjes en een verjaardagstaart met kaarsjes, en jij komt alles kopen.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,35],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"speeldeeg","note":"zelfgemaakt of gekocht, in een paar kleuren"},{"id":"deegroller","note":"of een glazen fles"},{"id":"uitsteekvormpjes","note":"of een beker en een flessendop"},{"id":"rietjes","note":"in stukjes geknipt, als kaarsjes"}],"optional":[{"id":"papieren-bordjes","note":"als taartbordjes"},{"id":"muffinvorm","note":"voor taartjes"},{"id":"ijsstokjes","note":"als taartmes, of als kaarsjes voor peuters"},{"id":"papier","note":"voor prijskaartjes"}],"steps":["Richt samen een bakkerij in: een theedoek als toonbank, bordjes, een deegroller en vormpjes.","Rol het deeg uit en steek koekjes uit, of rol balletjes tot bolletjes en broodjes.","Bak een verjaardagstaart: druk een dikke bol deeg plat op een bord en prik er stukjes rietje in als kaarsjes.","Zing samen ‘Lang zal ze leven’ en blaas de kaarsjes uit. Trek ze er dan één voor één weer uit.","Speel winkeltje: jij komt kopen. Mag ik drie koekjes? Tel ze samen uit: één, twee, drie!","Ruim op door het deeg per kleur terug te stoppen in een afgesloten bakje."],"ageTips":{"young":"Een tweejarige rolt, prikt en drukt het liefst. Geef zacht, soepel deeg en grote vormpjes, en gebruik hele rietjes of ijsstokjes als kaarsjes.","old":"Laat je kleuter prijskaartjes tekenen, bestellingen opnemen (twee rode koekjes en één taart) en het wisselgeld tellen. Hoeveel kaarsjes horen er op een taart voor een vijfjarige?"},"safety":["Speeldeeg bevat veel zout: niet opeten, en giftig voor honden; houd het buiten bereik van huisdieren. Proeft je peuter veel, kies dan eetbaar havermoutdeeg.","Stukjes rietje passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Gebruik voor je peuter hele rietjes of ijsstokjes."],"say":["Rollen, rollen… plat!","Mag ik drie koekjes, alstublieft?","Hoe oud is de jarige? Hoeveel kaarsjes moeten erop?","Ik zie dat je de koekjes netjes naast elkaar legt.","Wat bak jij een bijzondere taart, hoe heb je dat bedacht?"],"words":["bakker","rollen","uitsteken","taart","kaarsjes","kopen","alstublieft","dank je wel"],"learn":["fijne-motoriek","rekenen","taal","samen"],"tips":["Speel op een dienblad of onderlegger: kruimels deeg blijven dan bij elkaar en plakken niet in het kleed.","Geen vormpjes? Een beker, een flessendop en een vork werken net zo goed."],"extenders":["Bak een taart in lagen: leg drie platte rondjes in verschillende kleuren op elkaar en snijd de taart aan met een ijsstokje. Welke kleuren zie je?","Laat de bakker bezorgen: zet knuffels als klanten op de bank en laat je kind hun bestelling op een bordje rondbrengen.","Houd een bakwedstrijd: wie rolt het langste stokbrood en wie bouwt de hoogste taart?"],"variations":["Verjaardag: oefen het feestje met een knuffel als jarige, een taart, kaarsjes en een liedje.","Pizzeria: rol rondjes uit en beleg ze met deegballetjes en -slierten.","Sinterklaas: rol kleine bolletjes als kruidnoten en verkoop ze per zakje.","IJssalon: bolletjes deeg in een bekertje, met een rietje als lepeltje."],"themes":["verjaardag"],"canStay":false,"pinQuery":"bakkertje spelen speeldeeg"},
  {"id":"deegafdrukken","title":"Afdrukken en fossielen in deeg","emoji":"🦕","category":"deeg","summary":"Druk schelpen, blaadjes, vorken en dinopootjes in plat speeldeeg en ontdek welke patronen ze achterlaten: kun jij raden wat het was?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"speeldeeg","note":"zelfgemaakt of gekocht"},{"id":"vork","note":"voor strepen en ruitjes"},{"id":"klein-speelgoed","note":"bijv. speelgoeddino’s of andere dieren met pootjes"}],"optional":[{"id":"duplo","note":"voor stippenpatronen"},{"id":"schelpen","note":"gladde, hele schelpen"},{"id":"bladeren","note":"met dikke nerven"},{"id":"dennenappels","note":"voor een schubbenpatroon"},{"id":"deegroller","note":"om het deeg plat te rollen"}],"steps":["Rol of druk een paar flinke plakken speeldeeg plat, ongeveer 1 cm dik.","Zoek samen spullen met een mooi patroon: een schelp, een blad met dikke nerven, een vork, een duploblokje, de pootjes van een speelgoeddino.","Druk ze één voor één stevig in het deeg en haal ze er voorzichtig weer uit: kijk, een afdruk!","Speel ‘raad wat het was’: je kind doet de ogen dicht, jij maakt een afdruk en je kind raadt welk voorwerp het was.","Laat de dino’s een spoor door het deeg lopen: wie liep hier, een grote of een kleine?","Kneed het deeg weer tot een bal en begin opnieuw."],"ageTips":{"young":"Een tweejarige drukt het liefst zelf. Geef grote voorwerpen die makkelijk vast te houden zijn, zoals een duploblok of een vork, en druk samen met jouw hand eroverheen.","old":"Laat je kleuter een fossielenmuseum maken: afdrukken op een rij met een naamkaartje erbij. Of leg de voorwerpen ernaast en laat je kleuter ze bij de juiste afdruk zoeken."},"safety":["Kies gladde, hele schelpen: gebroken schelpen hebben scherpe randjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren."],"say":["Druk! En nu… optillen!","Wat zie je in de afdruk: lijntjes, rondjes of stippen?","Welk voorwerp heeft dit gemaakt, denk je?","Ik zie dat je heel voorzichtig optilt, zo blijft de afdruk mooi.","Hoe voelt de schelp: glad of ribbelig?"],"words":["afdruk","drukken","spoor","ribbels","nerven","fossiel","glad","hobbelig"],"learn":["zintuigen","ontdekken","fijne-motoriek","taal"],"tips":["Wil je een afdruk bewaren? Maak hem in zoutdeeg en laat hem drogen in de oven of aan de lucht.","Bewaar een doosje met ‘afdrukspullen’: schelpen en blaadjes van een wandeling, een oude vork en een paar blokjes."],"extenders":["Ga samen in huis op zoek naar nieuwe voorwerpen met een patroon, zoals een kam, een garde of een theezeefje.","Druk een patroon in een lange strook deeg, bijvoorbeeld streep, stip, streep, stip, en laat je kind het afmaken.","Druk allebei je hand in het deeg en vergelijk de afdrukken: wie heeft de langste vingers en wie de dikste duim?"],"variations":["Zomer: druk schelpen in het deeg voor een strand vol fossielen en zet er een speelgoedkrab bij.","Herfst: druk blaadjes, dennenappels en takjes in het deeg en bekijk de nerven en schubben.","Dinojacht: verstop speelgoeddino’s, laat sporen achter en zoek de dino bij het spoor.","Rolpatroon: rol een autootje of een vork over het deeg: wat voor spoor geeft dat?"],"themes":["zomer","herfst"],"canStay":false,"pinQuery":"afdrukken in speeldeeg peuter"},
  {"id":"deeg-egeltjes","title":"Deeg-egeltjes met spaghettistekels","emoji":"🦔","category":"deeg","summary":"Rol een egel van speeldeeg en prik er stukjes droge spaghetti in als stekels: hoeveel stekels krijgt jouw egel?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"speeldeeg","note":"een bal zo groot als een mandarijn per egel"},{"id":"pasta","note":"droge spaghetti, in stukjes van ±4 cm gebroken"}],"optional":[{"id":"rietjes","note":"in stukjes geknipt: dikker en makkelijker voor peuters"},{"id":"bladeren","note":"voor een herfstbos rond de egels"},{"id":"wiebeloogjes","note":"pas vanaf 3 jaar"}],"steps":["Breek droge spaghetti in stukjes van ongeveer 4 cm (dat doe jij) en leg ze in een bakje.","Rol samen een bal speeldeeg en knijp er aan één kant een puntje aan: de snuit van de egel.","Prik de stekels één voor één in de rug van de egel. Hoeveel passen erop?","Rol twee kleine deegbolletjes als oogjes en een iets grotere als neus, of druk de ogen in met een potlood.","Leg bladeren neer als herfstbos en zet de egels erin.","Trek de stekels er na het spelen uit, gooi gebroken stukjes weg en bewaar het deeg in een afgesloten bakje."],"ageTips":{"young":"Een tweejarige prikt makkelijker met dikkere stekels, zoals stukjes rietje. Geef ze één voor één aan en help de egel stevig vast te houden.","old":"Laat je kleuter een egelfamilie maken: een grote, een middelste en een kleine. Wie heeft de meeste stekels? Tel en vergelijk, of maak een patroon met lange en korte stekels."},"safety":["Droge spaghetti breekt in kleine, scherpe stukjes: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Blijf bij je peuter en ruim gebroken stukjes meteen op.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren.","Gebruik geen wiebeloogjes of kralen als oogjes bij kinderen onder de 3: maak de oogjes van deeg."],"say":["Prik! Nog een stekel!","Au, puntig! Hoe voelen de stekels?","Hoeveel stekels heeft jouw egel al?","Ik zie dat je de stekels heel voorzichtig rechtop zet.","Wat zou een egel eten, denk je?"],"words":["egel","stekels","prikken","puntig","rond","snuit","winterslaap"],"learn":["fijne-motoriek","rekenen","concentratie","creativiteit"],"tips":["Breek de spaghetti in een theedoek: dan vliegen er geen stukjes door de keuken.","Bewaar het deeg en de stekels samen in een afgesloten bakje: een kant-en-klaar herfstspelletje."],"extenders":["Rol kleine deegbolletjes als appeltjes en prik ze op de stekels: zo neemt de egel een wintervoorraad mee.","Gooi om de beurt met een dobbelsteen en prik er evenveel stekels in als je ogen gooit: wiens egel is het eerst vol?","Geef een tweede soort stekels, zoals stukjes rietje of kleine takjes, en ontdek samen welke het makkelijkst prikken."],"variations":["Herfst: bouw een bladerhoopje als winterslaapnest en stop de egels erin.","Verjaardag: maak een taart van deeg en prik er spaghetti in als kaarsjes.","Monsters: prik er pijpenragers met omgevouwen puntjes en rietjes in als haar en voelsprieten.","Cactus: groen deeg met spaghettistekels in een bekertje als bloempot."],"themes":["herfst"],"canStay":false,"pinQuery":"egel speeldeeg spaghetti"},
  {"id":"papier-mache","title":"Papier-maché-kommetje","emoji":"📰","category":"deeg","summary":"Plak laagjes krant met zelfgemaakt plaksel over een kom en beschilder het kommetje als het hard is: heerlijk kliederen met iets om te bewaren.","ageMin":4,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"duration":[25,35],"supervision":2,"soloFrom":5,"cleanupMinutes":15,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"kranten","note":"in repen en snippers gescheurd"},{"id":"bloem","note":"100 g, voor het plaksel"},{"id":"water","note":"200 ml, voor het plaksel"},{"id":"zout","note":"een snufje"},{"id":"kom","note":"één als mal en één voor het plaksel"},{"id":"huishoudfolie","note":"of aluminiumfolie, om de mal in te pakken"},{"id":"plakkaatverf","note":"om te beschilderen als het droog is"},{"id":"penselen"}],"optional":[{"id":"keukenpapier","note":"als witte laag, dan zie je welke laag nieuw is"},{"id":"knutsellijm","note":"verdund met wat water als glanslaagje"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Scheur samen kranten in repen en snippers van ongeveer 2 bij 5 cm. Scheuren is al een prima klus voor je kleuter.","Maak het plaksel: roer 100 g bloem met 200 ml water glad in een kom en doe er een snufje zout door.","Zet een andere kom ondersteboven op tafel en pak hem strak in met huishoudfolie.","Haal een snipper door het plaksel, strijk het overtollige plaksel eraf tussen twee vingers en plak hem op de kom. Leg de snippers dakpansgewijs over elkaar.","Plak zo 3-4 lagen over de hele kom. Wissel krant af met keukenpapier, dan zie je waar de nieuwe laag zit.","Laat het kommetje 1-2 dagen drogen op een warme plek. Haal het dan voorzichtig van de mal, trek de folie eruit en knip de rand recht (dat doe jij).","Beschilder het kommetje met plakkaatverf en laat het weer drogen."],"ageTips":{"young":"Voor een vierjarige zijn kleine snippers lastig: gebruik grotere repen en maak twee of drie lagen. Of beplak een papieren bordje als plat schaaltje, dat is sneller af.","old":"Een vijfjarige kan zelf de lagen tellen (krant, wit, krant…), een ontwerp bedenken voor het schilderen, zoals stippen, strepen of een dierengezicht, en vertellen wat er in het kommetje komt."},"safety":["Plaksel is gemaakt van rauwe bloem: niet proeven, en was handen na afloop.","Het kommetje is niet geschikt voor eten of drinken: gebruik het voor sieraden, sleutels of andere spulletjes.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Plak, strijk, nog een!","Hoe voelt het plaksel? Glibberig en koud!","Ik zie dat je de snippers netjes over elkaar legt, als dakpannen.","Hoeveel lagen hebben we nu: één, twee of drie?","Wat werk je geduldig, laagje na laagje! Wat wil jij in je kommetje bewaren?"],"words":["plaksel","glibberig","snipper","laag","scheuren","gladstrijken","drogen","hard"],"learn":["fijne-motoriek","creativiteit","concentratie","ontdekken"],"tips":["Werk op een oud laken of een opengeknipte vuilniszak: plaksel droogt op tot harde korstjes.","Gooi restjes plaksel in de vuilnisbak, niet door de gootsteen: het wordt hard in de afvoer.","Haast? Laat het kommetje drogen op de verwarming of in de zon voor het raam."],"extenders":["Pak nog een mal in met folie, zoals een omgekeerd plastic bekertje: met het restje plaksel maak je er meteen een potloodpotje bij.","Draai een reep krant met plaksel tot een ringetje en plak het op de bodem van de omgekeerde kom: zo krijgt het kommetje een voetje.","Laat je kind van de laatste snippers een collage plakken op een stuk karton, terwijl jij het kommetje afmaakt."],"variations":["Cadeau: een sieradenbakje voor mama of oma, met een glanslaagje van verdunde knutsellijm.","Vaderdag: een bakje voor sleutels of muntjes, beschilderd in papa’s lievelingskleur.","Zonder verf: plak als laatste laag vloeipapier of servetjes, dan is het kommetje meteen gekleurd."],"themes":["cadeau"],"canStay":false,"pinQuery":"papier-maché kommetje kind"},
  {"id":"deeg-monsters","title":"Deegmonsters met losse onderdelen","emoji":"👽","category":"deeg","summary":"Een bal speeldeeg en een bak vol pasta, rietjes, pijpenragers en veren: prik er de gekste monsters, beestjes en ruimtewezens mee in elkaar.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"speeldeeg","note":"zelfgemaakt of gekocht, in 2-3 kleuren"},{"id":"pasta","note":"droge penne, macaroni en stukjes spaghetti"},{"id":"rietjes","note":"in stukjes van ±5 cm geknipt"}],"optional":[{"id":"pijpenragers","note":"in stukken geknipt, met omgevouwen puntjes"},{"id":"wiebeloogjes"},{"id":"veren"},{"id":"doppen","note":"als ogen, neuzen of voeten"},{"id":"muffinvorm","note":"om alle onderdelen per soort in te zetten"},{"id":"dobbelsteen","note":"om te gooien hoeveel ogen of poten een monster krijgt"}],"steps":["Zet alle onderdelen per soort in een muffinvorm of in bakjes: pasta, stukjes rietje, pijpenragers, doppen, veren en wiebeloogjes.","Geef je kind een flinke bal speeldeeg: dat wordt het lijf van het eerste monster.","Prik er poten, armen, voelsprieten en haar in. Hoeveel ogen krijgt dit monster: één, drie of tien?","Bedenk samen een naam: wat eet het monster, waar woont het en hoe klinkt het?","Maak er een vriendje bij, een monsterbaby of een heel monstergezin, en laat ze met elkaar praten en spelen.","Haal na het spelen alle onderdelen eruit, sorteer ze terug in de bakjes en bewaar het deeg in een afgesloten bakje."],"ageTips":{"young":"Geef een driejarige dikke, makkelijke onderdelen zoals hele pijpenragers, penne en lange stukken rietje. Help bij de eerste poot en laat je kind daarna vrij prikken: elk monster is goed.","old":"Laat je kleuter een monster op bestelling maken: precies drie ogen, vier poten en twee voelsprieten. Of maak een monsterfamilie van groot naar klein en bedenk er samen een verhaal of een monsterlied bij."},"safety":["Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het buiten bereik van huisdieren.","Wiebeloogjes, doppen en stukjes pasta zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Ruim ze op als er een jonger broertje of zusje in de buurt is.","Knip de pijpenragers met een gewone schaar en vouw de scherpe puntjes van het ijzerdraad om: dat doe jij."],"say":["Prik! Nog een poot!","Hoeveel ogen krijgt jouw monster?","Wat eet dit monster het allerliefst?","Ik zie een monster met lange groene voelsprieten en een staart van veren. Hoe heet het?","Wat heb je dat bijzonder bedacht: zo’n monster heb ik nog nooit gezien!"],"words":["monster","voelsprieten","poten","prikken","zacht","stekelig","eng","lief"],"learn":["fijne-motoriek","creativiteit","taal","rekenen"],"tips":["Bewaar alle onderdelen in een doosje bij het speeldeeg: dan heb je een kant-en-klare monsterkist voor een volgende keer.","Laat je kind na afloop zelf sorteren: alle pasta in één vakje, alle rietjes in een ander. Opruimen is zo meteen een spelletje.","Speel op een onderlegger of dienblad: kruimels deeg en losse onderdelen blijven dan bij elkaar."],"extenders":["Gooi met een dobbelsteen hoeveel ogen, poten of voelsprieten het volgende monster krijgt.","Bouw een grot of huis voor de monsters van een omgekeerd bakje, een doos of een wc-rol.","Speel monsterwinkel: jij bestelt een monster met twee hoofden en een lange staart, en je kind maakt het.","Maak monstereten: rol kleine deegbolletjes en slierten ‘monsterspaghetti’ en voer de monsters.","Houd een monstershow: zet alle monsters op een rij en geef ze een naam en een prijs, zoals de engste of de liefste."],"variations":["Halloween: maak spinnen met acht pootjes van pijpenragers en spookjes van wit deeg.","Insecten: maak rupsen, bijen en lieveheersbeestjes met precies zes pootjes.","Ruimtewezens: bouw een ruimteschip van een bakje met aluminiumfolie en zet de deegwezens erin.","Herfst: prik takjes, eikels en blaadjes in het deeg voor bosmonsters."],"themes":["halloween"],"canStay":false,"pinQuery":"speeldeeg monsters losse onderdelen"},
  {"id":"deeg-ijssalon","title":"IJssalon met speeldeeg","emoji":"🍨","category":"deeg","summary":"Schep bolletjes ‘ijs’ van speeldeeg in bekertjes en hoorntjes, versier ze met spikkels en verkoop ze: de ijssalon is open!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":3,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"speeldeeg","note":"in een paar kleuren als ‘smaken’, bijv. roze, wit, bruin en groen"},{"id":"plastic-bekers","note":"of kleine bakjes, als ijsbekers"},{"id":"lepel","note":"een eetlepel of ronde maatlepel als ijsschep"}],"optional":[{"id":"papier","note":"om hoorntjes van te rollen en een prijslijst te tekenen"},{"id":"plakband","note":"om de hoorntjes dicht te plakken"},{"id":"stiften"},{"id":"eierdoos","note":"als standaard voor de hoorntjes"},{"id":"ijsstokjes","note":"voor ijsjes op een stokje"},{"id":"rietjes","note":"als wafeltje of lepeltje"}],"steps":["Zet de ijssalon op aan tafel: bakjes deeg in verschillende kleuren als smaken, bekertjes en een lepel als ijsschep.","Rol een paar hoorntjes van papier: draai een kwart vel tot een puntzak en plak hem dicht met plakband. Zet ze rechtop in een eierdoos.","Laat je kind bolletjes ijs rollen of scheppen: roze is aardbei, bruin is chocola, groen is munt.","Kom als klant langs: Mag ik een hoorntje met twee bolletjes, aardbei en chocola?","Versier het ijs met spikkels van mini-deegbolletjes, een rietje als wafeltje of een sliert wit deeg als slagroom.","Reken af met zelfgetekend papiergeld en tel samen hoeveel bolletjes er verkocht zijn.","Ruim op door elke kleur terug te stoppen in een afgesloten bakje. Gemengde kleuren worden gewoon tuttifrutti."],"ageTips":{"young":"Een tweejarige schept en stopt het liefst: geef een groot bekertje, zacht deeg en een lepel, en bestel steeds hetzelfde: één bolletje, alsjeblieft! Laat de spikkels en stukjes rietje nog weg.","old":"Laat je kleuter een prijslijst tekenen met plaatjes en getallen, bestellingen onthouden of met streepjes opschrijven en wisselgeld teruggeven. Hoeveel kost een ijsje met drie bolletjes?"},"safety":["Speeldeeg lijkt op echt ijs, maar bevat veel zout: niet opeten, en giftig voor honden. Proeft je peuter nog veel, gebruik dan eetbaar havermoutdeeg.","Let op mini-deegbolletjes en stukjes rietje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Geef een tweejarige liever hele rietjes of ijsstokjes.","Speel niet met echt kleingeld: een munt is klein en gevaarlijk als je kind er een inslikt."],"say":["Eén bolletje, alsjeblieft!","Welke smaak is dit roze ijs, denk je?","Hoeveel bolletjes wil je erop: twee of drie?","Ik zie dat je de bolletjes heel voorzichtig op elkaar stapelt.","Wat kost een ijsje bij jou?"],"words":["bolletje","hoorntje","smaak","scheppen","rond","bovenop","alsjeblieft","dank je wel"],"learn":["fijne-motoriek","taal","rekenen","samen"],"tips":["Houd de kleuren in aparte bakjes: zo blijven de smaken langer mooi.","Bewaar de papieren hoorntjes en het papiergeld in een envelop bij het deeg: de volgende keer is de ijssalon in een minuut open.","Zet knuffels in de rij als klanten: dan kan je kind ook zonder jou verder verkopen."],"extenders":["Open een ijskar: zet de ijssalon in een doos en rij langs alle knuffels om ijs te verkopen.","Bestel lastiger: drie bolletjes in drie smaken, met spikkels alleen op het middelste.","Maak ijsjes op een stokje: druk deeg om een ijsstokje en rol het door de spikkels.","Bedenk samen nieuwe smaken: wat is groen met roze stippen? Kikkerijs?","Wissel van rol: jij staat achter de toonbank en je kind komt met geld een ijsje kopen."],"variations":["Echte ijssalon: schep samen yoghurt met fruit in bekertjes en verkoop het als toetje.","Winter: maak vanille-ijs van wit sneeuwdeeg en schenk er (doe-alsof) warme chocolademelk bij.","Wolkendeeg-ijs: schep bolletjes van zacht wolkendeeg, dat lijkt nog meer op echt ijs."],"themes":["zomer"],"canStay":false,"pinQuery":"ijssalon spelen speeldeeg peuter"},
  {"id":"rijstbak","title":"Ontdekbak met gekleurde rijst","emoji":"🍚","category":"zintuigen","summary":"Scheppen, gieten en graven in een bak vol gekleurde rijst: het ritselt heerlijk, voelt fijn en er zitten diertjes in verstopt.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":false,"prepMinutes":10,"duration":[20,35],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"rijst","note":"±1 kg; gewoon wit of gekleurd (3 × 200 g, zie Recepten)"},{"id":"opbergbak","note":"met een rand van minstens 10 cm"},{"id":"plastic-bekers","note":"een paar in verschillende maten"},{"id":"lepel","note":"grote lepels of een soeplepel"},{"id":"trechter"},{"id":"klein-speelgoed","note":"diertjes of poppetjes om te verstoppen, groter dan een wc-rolletje"}],"optional":[{"id":"kleurstof","note":"om de rijst te kleuren, een paar druppels per 200 g"},{"id":"azijn","note":"1 tl per 200 g rijst, bij het kleuren"},{"id":"zip-zakjes","note":"om de rijst in te kleuren"},{"id":"bakpapier","note":"om de gekleurde rijst op te drogen"},{"id":"oud-laken","note":"onder de bak als knoeimat"},{"id":"muffinvorm","note":"om te sorteren op kleur"}],"steps":["Kleur de rijst eventueel een dag van tevoren: 200 g rijst, 1 tl azijn en wat kleurstof in een ritszakje schudden en 1-2 uur laten drogen op bakpapier.","Leg een oud laken op de vloer en zet de bak erop. Doe de rijst erin en verstop er een paar diertjes in.","Zet bekers, lepels en de trechter erbij en laat je kind eerst gewoon voelen: handen erin, ritselen, laten vallen.","Schep en giet samen: van beker naar beker, door de trechter, of een beker zo vol dat hij overloopt.","Ga samen op diertjesjacht: graaf, voel en vertel wat je vindt.","Spreek af dat de rijst in de bak blijft. Giet na afloop wat op het laken ligt terug en bewaar de rijst in een bak met deksel."],"ageTips":{"young":"Voor een tweejarige: gebruik grote bekers en grote diertjes en blijf ernaast zitten. Stopt je peuter nog veel in de mond? Neem dan havermout in plaats van rijst.","old":"Een kleuter kan sorteren op kleur in een muffinvorm, tellen hoeveel lepels er in een beker passen, of met de ogen dicht een verstopt diertje zoeken en raden wat het is."},"safety":["Droge rijst kan in de luchtpijp, neus of oren terechtkomen: blijf bij een kind onder de 3 dichtbij en stop als het rijst in de mond, neus of oren stopt.","Verstop alleen speelgoed dat niet door een wc-rolletje past: alles wat erdoor past, is te klein voor kinderen onder de 3.","Rijst op een gladde vloer rolt als knikkers onder je voeten: veeg tussendoor op en speel liefst op een laken of kleed."],"say":["Hoor je dat? Ritsel, ritsel!","Ik zie een staartje uit de rijst steken. Van wie zou dat zijn?","Hoeveel lepels heb je nodig om de beker vol te maken?","Wat giet je voorzichtig, er valt bijna niks naast!","Vol! En nu… leeg!"],"words":["scheppen","gieten","vol","leeg","ritselen","verstoppen","vinden"],"learn":["zintuigen","fijne-motoriek","ontdekken","concentratie"],"tips":["Leg een oud laken onder de bak: na afloop vouw je de hoeken naar elkaar toe en giet je de gemorste rijst zo terug.","In een afgesloten bak blijft (gekleurde) rijst maanden goed. Kook en eet hem na het spelen niet meer.","Laat gekleurde rijst helemaal droog worden voordat je ermee speelt, dan geeft hij niet af op handen en kleren."],"extenders":["Zet een lege plastic fles met de trechter erop bij de bak: lukt het om de fles tot de rand vol te scheppen?","Geef een vergiet en een zeef erbij: valt de rijst erdoorheen of blijft alles liggen?","Speel kruidenier: je kind schept rijst in bakjes en verkoopt die per lepel of per beker aan jou of een knuffel."],"variations":["Bouwplaats: rijd met graafmachientjes en vrachtwagens door de rijst en laad hem over.","Kerst: rode en groene rijst met onbreekbare kerstballen om op te graven.","Herfst: bruine en oranje rijst met dennenappels en kastanjes (kastanjes pas vanaf 3 jaar).","Zee: blauwe rijst met schelpen en plastic visjes die je eruit schept met een zeef."],"themes":[],"canStay":false,"pinQuery":"gekleurde rijst ontdekbak peuter"},
  {"id":"havermoutbak","title":"Havermout-ontdekbak voor dreumesen","emoji":"🥣","category":"zintuigen","summary":"Een ontdekbak voor de allerkleinsten: scheppen, strooien en graven in zachte havermout, en een hapje proeven mag.","ageMin":1,"ageMax":2,"mess":3,"wet":false,"dirty":false,"prepMinutes":3,"duration":[10,20],"supervision":1,"soloFrom":null,"cleanupMinutes":10,"noise":1,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"havermout","note":"±500 g, gewone vlokken"},{"id":"opbergbak","note":"of het blad van de kinderstoel voor een klein bergje"},{"id":"plastic-bekers","note":"2-3 stevige bekers"},{"id":"lepel","note":"een paar grote lepels"},{"id":"klein-speelgoed","note":"grote diertjes of duploblokken, groter dan een wc-rolletje"}],"optional":[{"id":"oud-laken","note":"onder de bak als knoeimat"},{"id":"muffinvorm","note":"om vakjes te vullen"},{"id":"zeef","note":"om ‘sneeuw’ te strooien"},{"id":"ontbijtgranen","note":"een handje erdoor voor een ander geluid"}],"steps":["Leg een oud laken op de vloer en zet de bak erop, of zet je dreumes in de kinderstoel met een paar handen havermout op het blad.","Doe de havermout in de bak en verstop er 3-4 grote diertjes of blokken in.","Ga erbij zitten en laat je kind eerst gewoon voelen: handen erin, knijpen, strooien.","Doe het scheppen voor: een lepel in de beker en dan… omkieperen! Laat je kind het nadoen.","Zoek samen de diertjes: graaf, vind en benoem ze. Waar is de koe?","Vouw het laken na afloop naar het midden toe. Gooi havermout die in een mond of op de vloer is geweest weg en bewaar de rest droog."],"ageTips":{"young":"Een dreumes van 1 jaar heeft genoeg aan één beker, één lepel en een klein bergje havermout. Benoem wat je kind doet: scheppen, strooien, weg!","old":"Een tweejarige kan bekers vullen tot ze vol zijn, de gevonden diertjes tellen of havermout door een zeef laten sneeuwen over een diertje."},"safety":["Proeven mag, maar een volle mond droge vlokken kan tot verslikken leiden: laat je kind rechtop zitten, blijf ernaast en geef zo nodig een slokje water.","Gebruik alleen grote diertjes en blokken: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Gewone havermout bevat vaak sporen van gluten: kies bij coeliakie of een glutenallergie glutenvrije havermout."],"say":["Strooi, strooi… weg!","Hoe voelt dat aan je handjes? Zacht, hè?","Ik zie een staart! Wie zit daar verstopt?","Wat ben je lang aan het scheppen. Je beker is bijna vol!"],"words":["zacht","scheppen","strooien","vol","leeg","weg","gevonden"],"learn":["zintuigen","fijne-motoriek","ontdekken","taal"],"tips":["Speel vlak voor badtijd: havermout plakt een beetje aan handjes en haar, en zo is het daarna meteen weg.","Schone, droge havermout kun je in een afgesloten bak een paar keer opnieuw gebruiken.","Een kruimeldief of stofzuiger is na afloop je beste vriend."],"extenders":["Zet een muffinvorm naast de bak en vul samen alle vakjes: een schepje hier, een schepje daar, en dan weer omkieperen.","Strijk de havermout glad en druk er sporen in met een duploblok, je hand of de pootjes van een diertje: kijk, een spoor!","Laat een tractortje of autootje door de havermout rijden en maak samen een weg, een berg en een tunnel."],"variations":["Boerderij: koe, paard en schaap in de ‘haver’, met een beker als voerbak.","Knisperbak: meng er een handje ontbijtringetjes of cornflakes door voor een ander geluid en gevoel.","Winter: zeef havermout als sneeuw over een ijsbeer of pinguïn en blaas het er weer af."],"themes":[],"canStay":false,"pinQuery":"havermout ontdekbak dreumes"},
  {"id":"zeepschuim","title":"Regenboog-zeepschuim","emoji":"🌈","category":"zintuigen","summary":"Klop samen bergen luchtig schuim in pastelkleuren en ga erin graven, smeren en diertjes redden: zacht, koel en verrassend.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":false,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"badschuim","note":"of afwasmiddel: 2-3 el per portie"},{"id":"water","note":"100 ml per portie"},{"id":"garde","note":"een (hand)mixer gaat het snelst"},{"id":"kom","note":"een kom per kleur"},{"id":"opbergbak","note":"of het lege bad"}],"optional":[{"id":"kleurstof","note":"2-3 druppels per kleur, voor pastelkleuren"},{"id":"klein-speelgoed","note":"plastic diertjes om te verstoppen"},{"id":"plastic-bekers","note":"om mee te scheppen"},{"id":"slagroom","note":"in plaats van zeepschuim als je kind nog veel in de mond stopt"}],"steps":["Doe per kleur 100 ml water en 2-3 el badschuim of afwasmiddel in een kom, en eventueel 2-3 druppels kleurstof.","Mix 1-2 minuten tot stevig schuim dat blijft staan als je de garde optilt. Mixen doe jij; je kind kijkt hoe het schuim groeit.","Schep de kleuren naast elkaar in de bak: een regenboog van schuim!","Verstop er een paar diertjes in en laat je kind ze opzoeken en ‘redden’.","Laat je kind vrij spelen: scheppen, smeren, kleuren door elkaar roeren en schuim tussen de vingers knijpen.","Spoel alles na afloop weg in de gootsteen of het bad, en spoel handen en diertjes na met schoon water."],"ageTips":{"young":"Voor een tweejarige: begin met één kleur en zet de bak in het lege bad. Stopt je peuter nog veel in de mond, gebruik dan slagroom met een drupje kleurstof.","old":"Een kleuter kan zelf het water afmeten, kleuren kiezen en voorspellen wat er gebeurt als je geel en blauw schuim mengt. Of je kind ‘wast’ alle diertjes en zet ze op een rij te drogen."},"safety":["Zeepschuim prikt in de ogen en is niet om te eten: houd een nat washandje klaar en spoel ogen met lauw water als er schuim in komt.","Schuim op de vloer maakt hem spekglad: zet de bak op een handdoek, dweil gemorst schuim en water direct op en laat je kind niet alleen bij de bak."],"say":["Kijk, het schuim groeit en groeit!","Hoe voelt het schuim tussen je vingers?","Wat denk je dat er gebeurt als je roze en blauw door elkaar roert?","Je hebt alle diertjes gevonden, wat heb je goed gezocht!","Plop! Weg!"],"words":["schuim","luchtig","zacht","bubbel","regenboog","mengen","verstoppen"],"learn":["zintuigen","ontdekken","taal","fijne-motoriek"],"tips":["Speel in de lege badkuip, vlak voor badtijd: daarna gaan schuim en kind samen onder de douche.","Met maar 2-3 druppels kleurstof per kom krijg je pastelkleuren die makkelijk wegspoelen; meer kleurstof kan handen en voegen even kleuren.","Schuim zakt na 20-30 minuten in: mix een nieuwe portie of klop het even op."],"extenders":["Geef je kind een eigen bakje met wat water, een scheutje zeep en een garde: lukt het om zelf schuim te kloppen?","Vul een ritszakje met schuim, knip er een klein hoekje af en laat je kind toefjes, stippen en slingers in de bak spuiten.","Druk een koekjesvormpje in het schuim, schep het vol en til het voorzichtig op: blijft de vorm staan?"],"variations":["Schuimzee: blauw schuim met plastic visjes, schelpen en een bootje.","Winter: wit sneeuwschuim met een ijsbeer en pinguïns.","Afwasfeest: was plastic bordjes en bekers van de poppenkeuken in het schuim."],"themes":[],"canStay":false,"pinQuery":"regenboog zeepschuim peuter"},
  {"id":"gelei-redding","title":"Diertjes redden uit de gelei","emoji":"🦖","category":"zintuigen","summary":"De diertjes zitten vast in wiebelige gelei: graaf, knijp en schep ze los. Koud, glibberig en heerlijk vies.","ageMin":1,"ageMax":4,"mess":3,"wet":true,"dirty":true,"prepMinutes":15,"duration":[10,25],"supervision":1,"soloFrom":4,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"gelatine","note":"geleipudding of gelatine voor ±1 liter (meestal 2 pakjes)"},{"id":"water","note":"volgens de verpakking, deels heet"},{"id":"kookplaat","note":"voor het hete water (dat doe jij)"},{"id":"kom","note":"een ondiepe schaal of bak"},{"id":"klein-speelgoed","note":"5-8 plastic diertjes, groter dan een wc-rolletje"},{"id":"koelkast"},{"id":"lepel"}],"optional":[{"id":"kleurstof","note":"bij gewone gelatine, een paar druppels"},{"id":"dienblad","note":"onder de schaal, vangt klodders op"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"}],"steps":["Maak de gelei volgens de verpakking. Het hete water doe jij; je kind kijkt op afstand.","Laat de gelei een kwartier afkoelen. Laat je kind intussen de diertjes in de schaal zetten.","Giet de lauwe gelei over de diertjes en zet de schaal minstens 4 uur (of een nacht) in de koelkast.","Zet de schaal op een dienblad, met een kom lauw water ernaast om geredde diertjes in te wassen.","Laat je kind de diertjes bevrijden: met de vingers graven, knijpen of met een lepel scheppen.","Gooi de gelei na afloop in de vuilnisbak en was diertjes en handjes in een warm sopje."],"ageTips":{"young":"Voor een dreumes: gebruik 3-4 grote diertjes en zet de schaal op het blad van de kinderstoel. Proeven mag. Benoem wat je kind voelt: koud, wiebel, glibberig!","old":"Een vierjarige kan tellen hoeveel diertjes er nog vastzitten, ze daarna sorteren (zee, boerderij, wild) of een reddingsverhaal bedenken: wie was het eerst vrij?"},"safety":["Het hete water en de warme gelei doe jij; laat de gelei helemaal opstijven en afkoelen voordat je kind erin mag.","Gebruik alleen grote diertjes: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Gevallen gelei is glibberig: ruim klodders direct op en laat je kind niet alleen met de schaal en de kom water.","Rode en paarse gelei vlekt op kleding, tafel en voegen: kies liever geel of groen en trek een oud shirt aan."],"say":["Wiebel, wiebel! Voel je hoe koud het is?","Ik zie een staartje uitsteken. Van wie zou dat zijn?","Hoe ga je de leeuw bevrijden: met je vingers of met de lepel?","Je bleef doorgraven tot hij los was. Wat een doorzetter!","Gered! Nog een!"],"words":["glibberig","wiebelen","koud","plakkerig","vast","los","redden"],"learn":["zintuigen","fijne-motoriek","ontdekken","taal"],"tips":["Drijven de diertjes naar boven? Giet eerst een laagje gelei, laat dat een uur opstijven, zet de diertjes erop en giet de rest erover.","Speel vlak voor badtijd of zet de schaal in de lege badkuip: dan spoel je alles zo weg.","Vegetarisch? Agar-agar werkt ook: kook het volgens de verpakking (dat doe jij)."],"extenders":["Geef een pipet of een lepeltje lauw water erbij: druppel het water op de gelei en kijk of het diertje sneller loskomt.","Druk een klodder gelei door een zeef of vergiet en kijk wat er aan de andere kant uitkomt: geleislierten!","Richt een dierenopvang in met een handdoek als bedje: je kind wast elk gered diertje, droogt het af en stopt het lekker in."],"variations":["Zee-redding: blauwe gelei met plastic visjes, een krab en een duiker.","Dino-opgraving: dinosaurussen in groene gelei, opgraven met lepels en een kwast.","Halloween: groene ‘slijmgelei’ met plastic spinnen, voor stoere kleuters."],"themes":[],"canStay":false,"pinQuery":"dieren redden uit gelei peuter"},
  {"id":"voelzak","title":"Raad wat er in de voelzak zit","emoji":"👜","category":"zintuigen","summary":"Steek je hand in de zak, voel zonder te kijken en raad wat het is: een spannend raadspel met gewone spullen uit huis.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[5,15],"supervision":1,"soloFrom":null,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"stoffen-tas","note":"of een kussensloop, niet doorzichtig"},{"id":"lepel"},{"id":"sokken","note":"een opgerolde sok"},{"id":"bal"},{"id":"duplo","note":"een groot blok"},{"id":"knuffels","note":"een kleine knuffel"}],"optional":[{"id":"sponsjes","note":"zacht én ruw"},{"id":"dennenappels","note":"voor een herfstzak"},{"id":"fruit","note":"bijv. een banaan of mandarijn"}],"steps":["Zoek 5-8 bekende voorwerpen bij elkaar, bijvoorbeeld een lepel, een sok, een bal, een blok en een knuffel.","Stop ze in de tas of kussensloop zonder dat je kind kijkt.","Laat je kind één hand in de zak steken en één ding vastpakken, zonder te kijken.","Vraag wat hij voelt: is het zacht of hard, rond of plat, koud of warm? Laat hem raden wat het is.","Haal het eruit: goed geraden? Ruil daarna van rol: nu stopt je kind iets in de zak voor jou.","Ruim op als spel: wat je geraden hebt, breng je terug naar zijn plek."],"ageTips":{"young":"Voor een tweejarige: laat de spullen eerst zien en benoem ze, en stop er dan maar 3 in. Vraag: Waar is de bal? Gluren mag, het gaat om het voelen en benoemen.","old":"Laat een kleuter eerst beschrijven en dan pas raden (‘Het is rond en hard…’) of zoek op opdracht: pak iets wat zacht is. Moeilijker: spullen die op elkaar lijken, zoals een lepel en een vork."},"safety":["Doet er een kind onder de 3 mee? Stop dan alleen spullen in de zak die niet door een wc-rolletje passen, en niets scherps of met knoopcelbatterijen.","Gebruik nooit een plastic tas als voelzak en laat je kind de kussensloop niet over het hoofd trekken (verstikking)."],"say":["Wat voel je? Is het zacht of hard?","Ik voel iets ronds… wat zou dat zijn?","Je voelde heel goed voordat je raadde. Knap!","Bal! Goed zo!","Wat denk je dat het is, als het koud en glad is?"],"words":["zacht","hard","glad","ruw","rond","koud","voelen"],"learn":["zintuigen","taal","concentratie","samen"],"tips":["Een grote sok werkt ook: daar past precies één hand in.","Neem de voelzak mee naar de wachtkamer of op visite: een spelletje dat je overal kunt doen.","Wissel de inhoud af met het seizoen, dan blijft het spannend."],"extenders":["Ga samen door het huis op jacht naar nieuwe spullen voor de zak: iets zachts, iets kouds en iets ronds.","Trek een sok over je hand en voel nog eens: lukt het raden nu nog?","Raad met je voeten: leg een paar spullen onder een handdoek en voel met blote tenen wat het is."],"variations":["Sinterklaas: wat zit er in de zak van Sinterklaas? Stop er een mandarijn, een schoen en een klein cadeautje in en zing er een liedje bij.","Herfst: een dennenappel, een blad, een takje en (vanaf 3 jaar) een kastanje.","Zoek het paar: leg één voorwerp op tafel en laat je kind het tweelingbroertje in de zak zoeken."],"themes":["sinterklaas"],"canStay":false,"pinQuery":"voelzak spel peuter"},
  {"id":"kalmeerfles","title":"Kalmeerfles: zeefles of glitterfles","emoji":"🌊","category":"zintuigen","summary":"Maak samen een fles vol golven of dwarrelende glitters: schudden, kijken en tot rust komen tot alles weer stil is.","ageMin":1,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":10,"duration":[5,15],"supervision":2,"soloFrom":null,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"plastic-flesjes","note":"stevig en doorzichtig, ±500 ml, etiket eraf"},{"id":"water"},{"id":"kleurstof","note":"blauw voor de zeefles, een paar druppels"},{"id":"olie","note":"voor de zeefles: ±1/3 van de fles"},{"id":"trechter"},{"id":"knutsellijm","note":"of lijm uit een lijmpistool, voor de dop (dat doe jij)"},{"id":"ducttape","note":"om de dop extra dicht te plakken"}],"optional":[{"id":"glitter","note":"voor een glitterfles, liefst bio-glitter; 50-100 ml glycerine (drogist) laat hem langzamer dwarrelen"},{"id":"dienblad","note":"om op te vullen, vangt gemorst water op"}],"steps":["Zet de fles met een trechter erin op een dienblad of in de gootsteen.","Vul voor een zeefles de fles voor twee derde met water en laat je kind er 2-3 druppels blauwe kleurstof bij doen.","Giet de fles verder vol met olie tot ±3 cm onder de rand. Kijk samen: de olie blijft bovenop drijven!","Vul voor een glitterfles de fles in plaats daarvan met lauw water, 1-2 el glitter en eventueel wat glycerine, zodat het langzamer dwarrelt.","Doe lijm op de schroefdraad, draai de dop er stevig op en plak er ducttape omheen. Dat doe jij; laat de lijm een paar uur drogen.","Schud, kantel en rol de fles en kijk samen hoe de golven of glitters bewegen en langzaam weer tot rust komen."],"ageTips":{"young":"Een dreumes speelt alleen met de dichte, afgeplakte fles. Rol hem over de vloer zodat je dreumes erachteraan kruipt, of schud samen: golven! En nu… stil.","old":"Een kleuter kan zelf afmeten en gieten met de trechter. Gebruik de fles als zandloper: kun je stil blijven zitten tot alle glitters beneden liggen?"},"safety":["Lijm de dop vast én plak hem af: een gewone dop krijgt een peuter zo open. Kijk de fles regelmatig na op lekken en scheurtjes en gebruik nooit glas.","Glitter hoort niet in ogen of mond: vul de fles zelf en laat je kind alleen met de dichte fles spelen.","Gemorst water en olie maken de vloer spekglad: vul de fles boven een dienblad of de gootsteen en veeg direct op."],"say":["Kijk, de olie blijft bovenop drijven!","Wat gebeurt er als je de fles heel langzaam kantelt?","Schud, schud… golven!","Zullen we samen diep ademhalen tot alle glitters beneden liggen?","Je goot heel voorzichtig, er ging bijna niets naast."],"words":["golf","drijven","zakken","dwarrelen","schudden","langzaam","stil"],"learn":["zintuigen","concentratie","ontdekken"],"tips":["Gebruik de fles als rustmoment: bij boosheid of voor het slapengaan samen kijken tot alles stil is.","Kies een fles van stevig plastic (bijvoorbeeld van sap of bronwater); dun plastic deukt en scheurt sneller.","Geen glitter in huis? Snippers aluminiumfolie of confetti dwarrelen ook mooi."],"extenders":["Doe het grote licht uit en schijn met een zaklamp door de fles: hoe zien de golven of glitters er nu uit?","Leg de fles op zijn kant en rol hem langzaam naar elkaar toe over de vloer: wat gebeurt er met de golven of glitters?","Zet muziek aan: schud de fles wild bij vrolijke muziek en wieg hem zachtjes heen en weer bij een slaapliedje."],"variations":["Zomer: een zeefles met een paar kleine schelpen of een plastic visje erin (stevig dichtplakken!).","Winter: een sneeuwfles met witte glitter en een klein plastic dennenboompje.","Druppelfles: vul water en olie zonder kleurstof, doe er pas daarna één druppel kleurstof in en kijk hoe die door de olie zakt."],"themes":["zomer","winter"],"canStay":false,"pinQuery":"kalmeerfles maken peuter"},
  {"id":"voelpad","title":"Voelpad op blote voeten","emoji":"👣","category":"zintuigen","summary":"Loop op blote voeten over knisperende folie, ploppende noppen en zachte kussens: een ontdekpad voor je voeten.","ageMin":1,"ageMax":4,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"noppenfolie","note":"een stuk van ±50 cm"},{"id":"aluminiumfolie","note":"een paar lagen dik"},{"id":"handdoek","note":"of een badmat of deurmat"},{"id":"dekens","note":"een kussen of opgevouwen deken"},{"id":"schilderstape","note":"om alles vast te plakken"}],"optional":[{"id":"karton","note":"ribbelkarton van een doos"},{"id":"kranten","note":"een paar lagen, ritselt lekker"},{"id":"sponsjes","note":"naast elkaar vastgeplakt"}],"steps":["Leg 5-6 voeltegels achter elkaar op de vloer: noppenfolie, aluminiumfolie, een handdoek, een kussen en een stuk karton.","Plak de randen vast met schilderstape, zodat niets kan schuiven.","Trek samen schoenen en sokken uit en loop het pad heel langzaam af, hand in hand.","Sta bij elke tegel even stil: hoe voelt dat? Knispert het, plopt het, is het zacht of koud?","Loop het pad nog een keer: op je tenen, achteruit of zo zwaar als een olifant.","Haal het pad weg en bewaar de noppenfolie en de folie voor een volgende keer."],"ageTips":{"young":"Een dreumes kruipt of loopt het pad aan jouw hand. Begin met drie tegels en benoem één woord per tegel: zacht, knisper, plop!","old":"Een vierjarige loopt met de ogen dicht (jij houdt een hand vast) en raadt waar de voetjes op staan. Of je kind ontwerpt zelf een nieuw pad en bepaalt de volgorde."},"safety":["Losse folie en kussens schuiven weg: plak alle randen vast, leg het pad liefst op een kleed en houd een dreumes een hand vast.","Haal kapotte stukjes folie en noppenfolie meteen weg: losse snippers horen niet in de mond (verstikking)."],"say":["Plop, plop! Hoor je dat?","Hoe voelt de folie onder je voeten: koud of warm?","Welke tegel vind jij het fijnst? En welke het gekst?","Je liep helemaal tot het eind, ook over het wiebelige kussen. Goed gedaan!","Wat denk je dat dit is, met je ogen dicht?"],"words":["zacht","ruw","glad","knisperen","wiebelig","koud","blote voeten","plop"],"learn":["zintuigen","grove-motoriek","taal"],"tips":["Speel het vlak na het badderen of aankleden, als de voetjes toch al bloot zijn.","Noppenfolie en karton uit pakketjes zijn gratis: bewaar ze in een tas voor dit spel.","Leg het pad in de gang: dan wordt het vanzelf een lange route."],"extenders":["Zoek samen nog een tegel in huis, zoals een koude bakplaat, een zachte badjas of een kurken onderzetter, en leg die erbij.","Zet muziek aan en loop over het pad: stopt de muziek, dan sta je stokstijf stil. Op welke tegel sta je nu?","Draag een knuffel op je hoofd of een opgerolde sok op een lepel over het pad: lukt het zonder iets te laten vallen?"],"variations":["Handenpad: maak voor kruipers kleine voeltegels op de vloer om met de handen te voelen.","Herfst: leg droge bladeren in een dichtgeplakt diepvrieszakje: knisperen zonder rommel.","Voelmemory: plak van elke tegel een stukje op karton en zoek met je voeten de tegel die erbij hoort."],"themes":[],"canStay":false,"pinQuery":"voelpad blote voeten peuter"},
  {"id":"zoutbak-tekenen","title":"Tekenen in een zoutbak","emoji":"🧂","category":"zintuigen","summary":"Trek met je vinger een lijn door het zout en zie de kleur tevoorschijn komen. Even schudden en je kunt opnieuw beginnen.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"dienblad","note":"met een randje"},{"id":"zout","note":"±250 g fijn zout, voor een laagje van ½ cm"},{"id":"gekleurd-papier","note":"een vel in een felle kleur, voor op de bodem"}],"optional":[{"id":"penselen","note":"een dikke kwast om mee te tekenen"},{"id":"ijsstokjes","note":"om lijnen te trekken"},{"id":"karton","note":"voorbeeldkaartjes met vormen of letters"},{"id":"trechter","note":"om het zout terug in de pot te gieten"},{"id":"suiker","note":"in plaats van zout voor een peuter die alles proeft"}],"steps":["Leg een vel gekleurd papier op de bodem van het dienblad.","Strooi er een laagje zout van ±½ cm over en schud het blad zachtjes tot het zout overal even dik ligt.","Trek met je vinger een lijn: kijk, de kleur komt tevoorschijn! Laat je kind het nadoen.","Teken samen lijnen, rondjes, zigzaggen en golven, met een vinger, een kwast of een ijsstokje.","Schud het blad zachtjes heen en weer om alles uit te gummen, en begin opnieuw.","Giet het zout na afloop via een trechter terug in een pot met deksel, zodat je het vaker kunt gebruiken."],"ageTips":{"young":"Voor een tweejarige: laat je kind vooral krassen, voelen en uitgummen. Stopt je peuter alles in de mond, gebruik dan suiker in plaats van zout.","old":"Een kleuter kan vormen natekenen van een voorbeeldkaartje, de eerste letter van de eigen naam schrijven of een doolhof tekenen voor een autootje. Of jij tekent een vorm en je kind raadt."},"safety":["Zout is niet om te eten: een paar theelepels kan voor een peuter al gevaarlijk zijn. Blijf erbij en stop als je kind ervan gaat snoepen.","Zout prikt in de ogen en in wondjes: niet in de ogen wrijven en handen wassen na afloop.","Zout is ook gevaarlijk voor honden en katten: zet de pot na het spelen buiten hun bereik."],"say":["Kijk, waar je vinger gaat, komt de kleur!","Kun jij een rondje tekenen? En nu een grote golf?","Schud, schud… weg!","Je tekent heel langzaam en precies. Ik zie een lange slingerlijn.","Hoe voelt het zout aan je vinger: korrelig of glad?"],"words":["lijn","rondje","zigzag","golf","korrelig","uitgummen","opnieuw"],"learn":["fijne-motoriek","zintuigen","creativiteit","concentratie"],"tips":["Een bakplaat met randje of het deksel van een schoenendoos werkt ook.","Zet het dienblad op een handdoek: wat ernaast valt, schud je zo terug.","Plak stroken in verschillende kleuren naast elkaar onder het zout: elke lijn wordt dan een verrassing."],"extenders":["Geef een vork als harkje en trek samen strepen, golven en ruitjes door het zout.","Maak er een samentekening van: jij tekent een rondje en je kind maakt er iets van, zoals een zon, een gezicht of een bal.","Stempel in het zout met een duploblok, de rand van een beker of je vingertoppen en raad samen welke afdruk van wat is."],"variations":["Winter: wit zout op donkerblauw papier is tekenen in de sneeuw. Teken een sneeuwpop of sporen van een vogel.","Letters oefenen: leg kaartjes met letters of cijfers naast het blad om na te tekenen.","Zandtekenen: met een laagje droog speelzand voelt en klinkt het heel anders."],"themes":[],"canStay":false,"pinQuery":"tekenen in zoutbak peuter"},
  {"id":"maizenapap","title":"Maizenapap: vloeibaar of vast?","emoji":"🌽","category":"zintuigen","summary":"Knijp erin en het wordt hard, doe je hand open en het druipt weg: maizenapap is magisch spul om mee te kliederen.","ageMin":1,"ageMax":5,"mess":3,"wet":true,"dirty":false,"prepMinutes":5,"duration":[10,25],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"maizena","note":"200 g per portie"},{"id":"water","note":"100-125 ml per portie, beetje bij beetje"},{"id":"opbergbak","note":"een ondiepe bak, of een dienblad met rand"},{"id":"lepel","note":"om te roeren en te scheppen"}],"optional":[{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"},{"id":"klein-speelgoed","note":"diertjes die langzaam wegzakken"}],"steps":["Doe 200 g maizena in de bak en laat je kind eerst het droge poeder voelen: zacht en piepend.","Giet er beetje bij beetje 100-125 ml water bij en roer met een lepel of je handen tot het overal even dik is.","Voeg een lepel maizena toe als het te dun is, of een scheutje water als het kruimelt.","Laat je kind een handje pakken en knijpen: het wordt hard! Doe je hand open en het druipt weg.","Probeer samen: tik er snel op met je vingers, duw je hand er langzaam in, rol een balletje en kijk hoe het smelt.","Laat de restjes opdrogen en gooi ze in de vuilnisbak, nooit door de gootsteen of de wc: het verstopt de afvoer."],"ageTips":{"young":"Een dreumes speelt op het blad van de kinderstoel met een paar lepels pap. Knijpen, druppen en kletsen is genoeg. Proeven kan geen kwaad: maizena is eetbaar.","old":"Een kleuter kan zelf afmeten en het water toevoegen. Laat je kind voorspellen: is het vast of vloeibaar? Lukt het om een balletje te rollen en het vast te houden voordat het wegsmelt?"},"safety":["Proeven kan geen kwaad, maar laat je dreumes er niet van eten en laat een jong kind nooit alleen met een bak pap of water.","Gemorste pap maakt de vloer spekglad: dweil het direct op, of laat het opdrogen en stofzuig het weg."],"say":["Knijp maar… hé, hij is hard!","Kijk, het druipt tussen je vingers door!","Wat denk je dat er gebeurt als je er snel op tikt? En als je langzaam duwt?","Je blijft het maar uitproberen, net een echte onderzoeker!","Plets!"],"words":["vloeibaar","vast","druipen","knijpen","hard","zacht","langzaam","snel"],"learn":["zintuigen","ontdekken","fijne-motoriek","taal"],"tips":["Speel op het blad van de kinderstoel of in de lege badkuip, vlak voor badtijd.","Opgedroogde maizena vlekt niet: borstel het zo van kleding en tafel.","Bewaar de pap afgedekt hooguit een dag. Opgedroogd? Roer er een scheutje water door."],"extenders":["Verstop een groot duploblok onderin de pap en laat je kind het opvissen: lukt het snel, of juist heel langzaam?","Houd een vergiet of zeef boven de bak, schep er pap in en kijk hoe de pap in dikke slierten naar beneden druipt.","Trek met je vinger snel een lijn door de pap en kijk goed: zie je de lijn? En nu… weg!"],"variations":["Dinomoeras: zet dinosaurusjes op de pap en kijk hoe ze langzaam wegzakken.","Glijbaan: houd het dienblad schuin en kijk hoe langzaam de pap naar beneden loopt. Wie is het eerst beneden?","Kleurenpap: roer door twee kleine porties elk een druppel kleurstof en meng ze (dat kan wel vlekken)."],"themes":[],"canStay":false,"pinQuery":"maizenapap spelen peuter"},
  {"id":"geurpotjes","title":"Geurpotjes: raad de geur","emoji":"👃","category":"zintuigen","summary":"Snuffel aan potjes met kaneel, citroen en koffie en raad wat erin zit: een spel voor je neus, met gewone keukenspullen.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[5,15],"supervision":1,"soloFrom":null,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"potjes","note":"4-6 kleine potjes, liefst niet doorzichtig"},{"id":"watten","note":"één watje per potje"},{"id":"kruiden","note":"kaneel, speculaaskruiden; ook koffie of thee"},{"id":"fruit","note":"een citroen of sinaasappel, voor de schil"},{"id":"aluminiumfolie","note":"om de potjes af te dekken"},{"id":"vork","note":"om gaatjes te prikken (dat doe jij)"}],"optional":[{"id":"papier","note":"om doorzichtige potjes in te pakken"},{"id":"plakband"}],"steps":["Kies 4-6 geuren, bijvoorbeeld kaneel, speculaaskruiden, citroenschil, sinaasappelschil en koffie.","Leg in elk potje een watje en strooi er ½ tl kruiden op, of leg er een stukje schil bij.","Dek elk potje af met aluminiumfolie en prik er met een vork 3-4 gaatjes in. Dat doe jij.","Ruik samen aan één potje tegelijk: is het lekker of vies, zoet of fris? Wat zou het zijn?","Haal de folie eraf: had je het goed? Ruik nog eens, nu je weet wat het is.","Bewaar de potjes dicht. Kruiden blijven een paar weken ruiken, schillen een paar dagen."],"ageTips":{"young":"Een tweejarige raadt nog niet, maar ruikt graag. Gebruik 2-3 geuren die je kind kent en laat het echte ding ernaast zien. Benoem: mmm, sinaasappel!","old":"Maak van elke geur twee potjes en laat je kleuter de paren zoeken: memory voor je neus. Of vraag: waar ruikt dit naar, aan welk eten of welke plek denk je?"},"safety":["Gebruik geen etherische oliën: die zijn schadelijk voor jonge kinderen, ook op de huid. Houd het bij gewone keukenkruiden.","Ruiken, niet snuiven of blazen: poeder zoals kaneel prikt in neus en ogen. Gebruik geen peper of chilipoeder.","Zet de potjes na het spelen weg: watjes en kruiden horen niet in de mond van een peuter."],"say":["Ruik maar… mmm! Wat ruik je?","Ruikt dit zoet of fris?","Waar heb je dit eerder geroken? Bij het ontbijt of in de keuken?","Je rook heel goed en dacht lang na. Knap gedaan!","Mmm, kaneel!"],"words":["ruiken","neus","zoet","zuur","fris","sterk","lekker","vies"],"learn":["zintuigen","taal","concentratie"],"tips":["Gebruik niet-doorzichtige potjes of plak ze in met papier, anders raadt je kind met de ogen.","Na 4-5 geuren ruikt je neus minder goed: ruik tussendoor even aan je eigen mouw, dan doet je neus het weer.","Een eierdoos met folie erover werkt ook: één geur per vakje."],"extenders":["Zoek samen in de keuken een nieuwe geur, zoals vanillesuiker, een theezakje of een plakje ui, en maak er een extra potje van.","Leg twee vellen neer, één met een blij en één met een vies gezichtje, en laat je kind elk potje bij lekker of vies zetten.","Ruik aan een potje en ga daarna in huis op zoek naar iets dat net zo ruikt: de zeep, een appel of de theedoos?"],"variations":["Sinterklaas: speculaaskruiden, sinaasappel, cacao en anijs. Welke geur hoort bij Sinterklaas?","Kerst: kaneel, gemalen kruidnagel, mandarijnschil en een dennentakje.","Ontbijtgeuren: koffie, thee, banaan en jam. Wie raadt wat papa of mama ’s ochtends drinkt?"],"themes":["sinterklaas","kerst"],"canStay":false,"pinQuery":"geurpotjes raden spel kind"},
  {"id":"herfst-ontdekbak","title":"Herfst-ontdekbak","emoji":"🌰","category":"zintuigen","summary":"Haal het bos naar binnen: graaf, sorteer en ritsel in een bak vol kastanjes, dennenappels, bladeren en takjes.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"opbergbak","note":"een grote platte bak of doos"},{"id":"kastanjes","note":"een paar handen vol, alleen vanaf 3 jaar"},{"id":"dennenappels","note":"verschillende maten"},{"id":"bladeren","note":"droog, in verschillende kleuren"},{"id":"takjes"},{"id":"plastic-bekers"},{"id":"lepel"}],"optional":[{"id":"muffinvorm","note":"om te sorteren"},{"id":"klein-speelgoed","note":"een plastic egel, eekhoorn of uil"},{"id":"oud-laken","note":"onder de bak tegen kruimels"},{"id":"kranten","note":"om de verzamelde spullen op te drogen"}],"steps":["Spreid de verzamelde spullen een dag van tevoren uit op een krant om te drogen en kijk ze na op beestjes, schimmel en scherpe stekels.","Doe alles in een grote platte bak en zet bekers, lepels en eventueel een muffinvorm ernaast.","Laat je kind eerst graven, voelen en ruiken: hoe voelt een dennenappel, en hoe een gladde kastanje?","Schep en giet samen: kastanjes in een beker, door de bak laten rollen, ritselende bladeren omhoog gooien.","Sorteer samen in de muffinvorm: alle kastanjes bij elkaar, alle dennenappels bij elkaar. Tel ze.","Ruim op door alles terug in de bak te doen. Met een deksel erop kun je de bak een paar weken bewaren."],"ageTips":{"young":"Voor een tweejarige: laat kastanjes en eikels weg en kies grote dennenappels, grote bladeren en dikke takjes. Ritsel en benoem samen: blad, ritsel ritsel!","old":"Een kleuter kan sorteren op grootte of kleur, een rij maken van klein naar groot, of van de spullen een gezicht of egel leggen. Hoeveel kastanjes passen er in één beker?"},"safety":["Kastanjes en eikels passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: laat ze weg bij een tweejarige.","Kastanjes en eikels zijn niet eetbaar (giftig bij opeten): spreek af dat alles uit de bak buiten de mond blijft.","Gooi bolsters met stekels, beschimmelde spullen en scherpe takjes weg, en was na het spelen handen."],"say":["Ritsel, ritsel! Hoor je de blaadjes?","Deze kastanje is glad en glimmend. Hoe voelt de dennenappel?","Waar denk je dat deze takjes vandaan komen?","Je hebt alles zo goed gesorteerd, wat heb je goed gezocht!","Ruik eens aan het blad. Waar ruikt het naar?"],"words":["ritselen","glad","ruw","prikkelig","bruin","kastanje","dennenappel","herfst"],"learn":["zintuigen","ontdekken","rekenen","taal"],"tips":["Verzamel de spullen samen op een herfstwandeling, dan begint het ontdekken al buiten.","Leg de dennenappels een nacht in de vriezer: zo ben je eventuele beestjes kwijt.","Leg de bak op een oud laken: verkruimelde blaadjes vouw je er zo in en schud je buiten uit."],"extenders":["Geef een keukentang of twee grote lepels en laat je kind de dennenappels één voor één naar een beker verhuizen.","Houd een dienblad schuin als glijbaan en laat alles om de beurt naar beneden rollen: wat rolt het verst en wat blijft liggen?","Draai een strook schilderstape met de plakkant naar buiten om de pols van je kind en plak er blaadjes en sprietjes op: een herfstarmband."],"variations":["Eekhoorntje spelen: verstop kastanjes onder de bladeren en laat de ‘eekhoorn’ zijn wintervoorraad zoeken.","Kleurenbak: alleen gele, rode en bruine blaadjes. Van welke kleur heb je er het meest?","Kerst: vervang de bladeren door dennentakjes en leg er onbreekbare kerstballen bij."],"themes":["herfst"],"canStay":false,"pinQuery":"herfst ontdekbak peuter"},
  {"id":"kleurenjacht","title":"Kleurenjacht door het huis","emoji":"🔴","category":"zintuigen","summary":"Kies een kleur en ga samen op jacht: alles wat rood is, mag mee naar het rode vel papier.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[10,25],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"gekleurd-papier","note":"een vel per kleur, bijv. rood, geel en blauw"}],"optional":[{"id":"wasmand","note":"om de buit in te verzamelen"}],"steps":["Leg een paar vellen gekleurd papier op de vloer, bijvoorbeeld rood, geel en blauw.","Kies samen één kleur en wijs iets in de kamer aan dat die kleur heeft.","Ga op jacht: je kind zoekt spullen in die kleur en legt ze op het juiste vel.","Bekijk samen de buit: wat is het, is het groot of klein, zacht of hard?","Ruim op door alles terug te brengen: waar woont de rode beker?"],"ageTips":{"young":"Begin met één kleur en leg zelf alvast drie rode dingen klaar om te vinden. Benoem alleen kleur en voorwerp: rood, een rode bal!","old":"Zoek binnen één minuut vijf dingen, of sorteer van licht- naar donkerblauw. Ook leuk: zoek iets dat rond én geel is."},"safety":["Let op kleine voorwerpen die je kind onderweg vindt, zoals munten, kraaltjes of knoopcelbatterijen: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Ik zie iets roods… zie jij het ook?","Is deze sok rood of oranje? Wat denk jij?","Je hebt al vier rode dingen gevonden. Zullen we ze tellen?","Rood! Nog een!"],"words":["rood","geel","blauw","licht","donker","hetzelfde","anders"],"learn":["taal","rekenen","grove-motoriek"],"tips":["Speel het als opruimspel: laat je kind alle blauwe spullen terugbrengen naar hun plek.","Maak een foto van elke kleurenstapel: zo heb je meteen een eigen kleurenboekje."],"extenders":["Maak het moeilijker: zoek nu iets dat rood én zacht is.","Zet een timer van één minuut: hoeveel blauwe dingen vind je voordat hij afgaat?","Laat je kind de buit op een rij leggen, van klein naar groot of van licht naar donker."],"variations":["Vormenjacht: zoek alles wat rond is, of alles wat vierkant is.","Herfst: zoek bruin, oranje en geel en leg er kastanjes en bladeren bij.","Koningsdag: zoek alles wat oranje is en maak er een oranje tentoonstelling van."],"themes":[],"canStay":false,"pinQuery":"kleuren zoeken spel peuter"},
  {"id":"schatmand","title":"Schatmand voor dreumesen","emoji":"🧺","category":"zintuigen","summary":"Een mandje vol gewone spullen van hout, metaal, stof en natuur: je dreumes pakt, voelt, rammelt en ontdekt alles in het eigen tempo.","ageMin":1,"ageMax":2,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,20],"supervision":2,"soloFrom":null,"cleanupMinutes":2,"noise":2,"energy":1,"places":["vloer"],"materials":[{"id":"mandje","note":"laag en stevig, zodat je dreumes er makkelijk in kan graaien"},{"id":"lepel","note":"een houten lepel en een metalen soeplepel"},{"id":"garde","note":"een handgarde; kijk of de draden goed vastzitten"},{"id":"pan","note":"een klein pannendeksel"},{"id":"borstels","note":"een schone, zachte haarborstel"},{"id":"doekje","note":"een washandje"},{"id":"fruit","note":"een hele sinaasappel of citroen"}],"optional":[{"id":"doekjes","note":"een zijden of katoenen sjaaltje"},{"id":"dennenappels","note":"een grote, schone dennenappel"},{"id":"beker","note":"een metalen of houten beker"},{"id":"sponsjes","note":"een grote, nieuwe spons zonder schuurkant"},{"id":"kom","note":"om dingen in en uit te doen"}],"steps":["Zoek 10-15 spullen van verschillend materiaal bij elkaar, bijvoorbeeld een houten lepel, een garde, een pannendeksel, een washandje, een borstel en een sinaasappel.","Controleer alles: niets wat door een wc-rolletje past, geen losse onderdelen of scherpe randen, en alles schoon genoeg om in de mond te stoppen.","Zet het mandje op een kleed op de vloer, zodat je dreumes er zittend goed bij kan, en ga er zelf rustig naast zitten.","Laat je kind zelf kiezen, pakken, rammelen en in de mond stoppen. Kijk vooral en help niet te snel: zelf ontdekken is het spel.","Benoem af en toe wat je ziet: die lepel is hard, het washandje is zacht, de sinaasappel rolt!","Berg de mand daarna op en zet hem pas over een paar dagen weer neer, liefst met een paar nieuwe schatten erin."],"ageTips":{"young":"Een dreumes van 1 stopt alles in de mond: dat hoort erbij. Kies dus spullen die dat mogen en begin met 6-8 dingen, zodat de mand overzichtelijk blijft.","old":"Een tweejarige stopt graag dingen in iets anders. Doe er een kom, een beker en een koker bij en vraag: past de lepel in de beker? Benoem ook hard en zacht, koud en warm."},"safety":["Kijk elk voorwerp na voordat het in de mand gaat en na elke keer spelen: haren van een borstel, draden van een garde en een steel moeten goed vastzitten. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Doe niets met een koord, ketting of riempje in de mand (wurggevaar), en niets van glas, porselein of met batterijen.","Haal een spons meteen weg als je dreumes er stukjes af bijt: dat is verstikkingsgevaar."],"say":["Wat heb je gevonden?","Zacht! Voel maar.","Ik zie dat je met de lepel op het deksel slaat. Wat een geluid!","Ruik eens aan de sinaasappel. Lekker, hè?","Je probeert alles uit. Wat ben je goed aan het ontdekken!"],"words":["zacht","hard","koud","glad","ruw","rammelen","ruiken","rollen"],"learn":["zintuigen","ontdekken","fijne-motoriek","concentratie"],"tips":["Wissel elke paar dagen een paar spullen om: zo blijft de mand nieuw zonder dat je iets hoeft te kopen.","Kies een rustige plek zonder ander speelgoed of tv: dan blijft je dreumes het langst geboeid.","Was de spullen na afloop even af, vooral wat in de mond is geweest."],"extenders":["Leg er één nieuw ding in, zoals een koude metalen beker of een zacht sjaaltje: een dreumes ontdekt het nieuwe meteen.","Verstop iets onder het washandje of een doek en laat je dreumes het zoeken: kiekeboe!","Tik twee dingen tegen elkaar: hoe klinkt hout op metaal? Laat je kind het nadoen.","Rol de sinaasappel langzaam weg over de vloer: kruipt of loopt je dreumes erachteraan?"],"variations":["Herfstmand: een grote dennenappel, een stevig blad, een sierkalebasje en een dik takje. Kastanjes en eikels liever niet: te klein en giftig.","Metaalmand: alleen spullen van metaal, zoals deksels, een kleine zeef, een soeplepel en een maatbeker: koud en glimmend.","Stoffenmand: een washandje, een sjaaltje, een wollen want, een stukje vilt en een badstof slab."],"themes":[],"canStay":false,"pinQuery":"schatmand dreumes huishoudspullen"},
  {"id":"zoekfles","title":"Zoekfles: ik zie, ik zie…","emoji":"🔍","category":"zintuigen","summary":"Verstop kleine dingetjes in een fles vol rijst, draai en schud, en zoek ze één voor één terug: een stil zoekspel dat overal mee naartoe kan.","ageMin":2,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[20,30],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"plastic-flesjes","note":"een doorzichtige fles van 0,5-1 liter met een brede hals, schoon en droog"},{"id":"rijst","note":"genoeg om de fles voor driekwart te vullen"},{"id":"trechter","note":"of een opgerold vel papier"},{"id":"klein-speelgoed","note":"10-15 kleine dingetjes die door de hals passen: diertje, gum, sleutel, schelpje"},{"id":"knutsellijm","note":"een randje op de schroefdraad"},{"id":"ducttape","note":"om de dop rondom dicht te plakken"}],"optional":[{"id":"knopen","note":"grote knopen in felle kleuren"},{"id":"kralen","note":"bijv. letterkralen"},{"id":"dienblad","note":"om boven te vullen: gemorste rijst blijft bij elkaar"},{"id":"papier","note":"voor de zoeklijst"},{"id":"stiften","note":"om de zoeklijst te tekenen"},{"id":"zaklamp","note":"om door de fles te schijnen"}],"steps":["Zoek samen 10-15 kleine dingetjes die door de hals van de fles passen, zoals een diertje, een gum, een knoop en een sleutel. De kleinste houd jij bij je.","Leg alles op een vel papier en maak er een foto van, of trek met stift de omtrek van elk ding om: dat is je zoeklijst.","Zet de fles met de trechter erin op een dienblad. Je kind schept rijst in de trechter, jij laat er af en toe een dingetje in vallen.","Vul de fles tot driekwart: er moet lucht overblijven om te schudden. Lijm de dop vast en plak er ducttape omheen (dat doe jij).","Draai, rol en schud de fles: wat zie je? Pak de zoeklijst erbij en wijs aan wat je vindt: daar is de sleutel!","Zoek om de beurt: jij noemt iets en je kind zoekt het, daarna laat je kind jou iets zoeken.","Zet de fles daarna op een vaste plek: zo heb je een zoekspel dat maanden meegaat."],"ageTips":{"young":"Bij een tweejarige doe jij de kleine dingetjes in de fles en schept je peuter de rijst. Kies dingen in heldere kleuren die je peuter kent en vraag naar één ding tegelijk: waar is de sleutel?","old":"Een driejarige kan zelf dingetjes verzamelen, met de zoeklijst zoeken en afstrepen, of vertellen wat er nog verstopt zit: iets roods, iets ronds… Wie raadt wat het is?"},"safety":["Kleine dingetjes en droge rijst zijn verstikkingsgevaar: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Doe de kleine dingen zelf in de fles en tel ze voor en na het vullen.","Plak de dop altijd rondom af met ducttape: die houdt de fles dicht terwijl de lijm droogt. Kijk de dop elke keer na voordat je kind ermee speelt.","Stop er niets scherps of met een batterij in (geen spelden, geen knoopcelbatterij): een fles kan barsten als je kind erop bijt of ermee gooit."],"say":["Ik zie, ik zie… iets roods!","Waar is de sleutel? Draai maar!","Daar! Gevonden!","Je blijft draaien en kijken tot je het vindt. Wat zoek jij goed!","Wat gebeurt er als je de fles op z’n kop houdt?"],"words":["zoeken","vinden","verstopt","draaien","schudden","bovenop","onderin","klein"],"learn":["concentratie","taal","zintuigen","fijne-motoriek"],"tips":["Neem de zoekfles mee naar de wachtkamer, in de auto of op visite: stil, schoon en klein.","Vul niet verder dan driekwart: met lucht in de fles schuiven de dingetjes beter. Te vol? Schenk er wat rijst uit voordat je de dop vastlijmt."],"extenders":["Ga op jacht in de kamer: zie je in de fles iets roods, zoek dan ook iets roods in de kamer.","Schijn met een zaklamp door de fles of zoek onder een deken: in het donker zie je ineens andere dingen.","Laat je kind een verhaal vertellen over wat er in de fles gebeurt: de eend is de sleutel kwijt…","Zet een kookwekker op één minuut: hoeveel dingen van de zoeklijst vind je voordat de bel gaat?","Zoek op kleur of vorm: eerst alles wat geel is, dan alles wat rond is."],"variations":["Kerst: doe kleine kerstdingen in de fles, zoals een belletje, een sterretje en een rood strikje, en zoek ze in de ‘sneeuw’ van rijst.","Natuurfles: verstop een eikel, een blaadje, een veertje en een steentje die je eerder buiten hebt verzameld.","Letterfles: voor oudere broers en zussen letterkralen erin, en zoek de letters van de eigen naam."],"themes":[],"canStay":false,"pinQuery":"zoekfles rijst kleine dingen"},
  {"id":"zaklampspeurtocht","title":"Zaklamp-speurtocht in het donker","emoji":"🔦","category":"zintuigen","summary":"Doe het licht uit, pak een zaklamp en zoek de plaatjes die overal in de kamer verstopt zitten: spannend, een tikje griezelig en heel gezellig.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer","muur"],"materials":[{"id":"zaklamp","note":"één per kind; het lampje van een telefoon kan ook"},{"id":"stickers","note":"10-15 stuks, of tekeningetjes op stukjes tape"},{"id":"schilderstape","note":"plak de stickers hierop, dan gaan ze zonder vlekken van de muur"},{"id":"papier","note":"als verzamelkaart"},{"id":"stiften","note":"om vakjes op de verzamelkaart te tekenen"}],"optional":[{"id":"dekens","note":"om een donkere grot over de tafel te bouwen"},{"id":"aluminiumfolie","note":"voor sterren die glinsteren in het licht"},{"id":"knuffels","note":"als schat om te verstoppen"},{"id":"muziek","note":"zachtjes spannende muziek op de achtergrond"}],"steps":["Plak 10-15 stickers op stukjes schilderstape en verstop ze in de kamer: op de muur, onder de tafel, achter een kussen, op een stoelpoot.","Teken op een vel papier evenveel vakjes als je plaatjes hebt verstopt: dat is de verzamelkaart.","Ruim de vloer op, doe de gordijnen dicht en het licht uit. Laat een klein lampje aan als je kind het donker spannend vindt.","Geef je kind de zaklamp en ga op speurtocht: schijn langs de muren, onder de tafel en achter de kussens. Wat zie je?","Plak elk gevonden plaatje in een vakje van de verzamelkaart. Hoeveel vakjes zijn er nog leeg?","Ruil van rol als de kaart vol is: je kind verstopt de plaatjes opnieuw en jij zoekt met de zaklamp.","Doe tot slot het licht aan en kijk samen of er nergens meer een plaatje hangt."],"ageTips":{"young":"Verstop de plaatjes voor een driejarige op ooghoogte en half zichtbaar, en maak het niet te donker: schemer is spannend genoeg. Zoek samen, hand in hand.","old":"Een kleuter kan zoeken met een zoeklijst waarop jij de plaatjes hebt nagetekend, tellen hoeveel er nog ontbreken en bij het verstoppen echt lastige plekken voor jou bedenken."},"safety":["Ruim speelgoed, snoeren en losse kleedjes op voordat het licht uitgaat, en verstop niets bij de trap, bij stopcontacten of op plekken waar je kind moet klimmen.","Schijn niet in elkaars ogen: spreek af dat de lamp altijd naar de muur of de vloer wijst.","Kleine zaklampjes werken soms op knoopcelbatterijen: levensgevaarlijk bij inslikken. Plak het batterijklepje dicht en leg de lampjes daarna buiten bereik."],"say":["Ssst… ik zie iets!","Schijn eens onder de tafel. Zit daar iets?","Gevonden! Nog een!","Je zocht heel rustig alle hoekjes af. Daardoor vond je ze allemaal.","Hoe voelt het in het donker: spannend of gezellig?"],"words":["donker","licht","schijnen","zoeken","achter","onder","schaduw","gevonden"],"learn":["concentratie","taal","rekenen","grove-motoriek"],"tips":["Speel aan het eind van de middag in de herfst of winter: dan is het vroeg donker en hoef je niets te verduisteren.","Geef elk kind een eigen soort stickers: dan is er geen ruzie over wie wat gevonden heeft.","Bewaar de plaatjes op hun stukjes tape op de verzamelkaart: de volgende keer ben je in een minuut klaar."],"extenders":["Verstop de plaatjes op nieuwe, lastigere plekken: hoog op de deur, laag tegen de plint, aan de onderkant van een stoel.","Verstop er een schat bij, zoals een knuffel of een briefje met een opdracht: wie de schat vindt, mag het volgende liedje kiezen.","Geef een zoekopdracht: zoek nu alleen de dieren, of alleen de groene plaatjes.","Bouw een grot van dekens over de tafel en verstop daar de laatste plaatjes.","Speel flitsen: jij laat het licht een tel op iets in de kamer schijnen en doet de lamp dan uit. Wat heeft je kind gezien?"],"variations":["Halloween: verstop spookjes, vleermuizen en pompoenen en zet zachtjes griezelmuziek op.","Winter: knip sterren uit aluminiumfolie en verstop ze: in het licht van de zaklamp glinsteren ze.","Letters: verstop de letters van de eigen naam en leg ze na het zoeken op de goede volgorde."],"themes":["winter","halloween"],"canStay":false,"pinQuery":"zaklamp speurtocht kind donker"},
  {"id":"speurtocht-plaatjes","title":"Speurtocht met een zoekkaart","emoji":"📋","category":"zintuigen","summary":"Teken een zoekkaart met iets roods, een lepel en iets zachts, en speur door je eigen huis: alles wat je vindt, gaat in de mand.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"papier","note":"één vel als zoekkaart, in 8 vakken gevouwen"},{"id":"stiften","note":"om de zoekdingen te tekenen"},{"id":"mandje","note":"of een wasmand of stoffen tas voor de buit"}],"optional":[{"id":"stickers","note":"om gevonden dingen af te vinken"},{"id":"karton","note":"als stevige onderlegger voor de zoekkaart"}],"steps":["Vouw een vel papier in 8 vakken en teken in elk vak snel iets om te zoeken: iets roods, een lepel, iets zachts, een sok, iets ronds, een boek.","Bespreek de kaart samen: wat staat er? Betekent dit wolkje iets zachts? Waar zou je een lepel kunnen vinden?","Geef je kind het mandje en ga op speurtocht door de kamer of het huis. Eén ding per vak is genoeg.","Laat je kind bij elk gevonden ding een sticker of streep in het vak zetten.","Pak de buit samen uit: klopt alles? Is de sok echt zacht? Past iets bij twee vakken tegelijk?","Laat je kind alles terugbrengen naar de goede plek: dat is meteen een tweede speurtocht.","Draai daarna de rollen om: je kind tekent of kiest een zoekkaart voor jou en controleert jouw buit."],"ageTips":{"young":"Begin voor een driejarige met 4-6 bekende dingen die je gewoon natekent: een lepel, een sok, een bal, een knuffel. Zoek in één kamer en loop samen mee.","old":"Een kleuter kan zoeken op eigenschappen (iets van hout, iets dat zwaarder is dan een appel, iets met de b van bal) en daarna zelf een kaart tekenen met lastige opdrachten voor jou."},"safety":["Spreek vooraf af waar je kind niet mag zoeken: niet in kastjes met schoonmaakmiddelen of medicijnen, niet bij de scheermesjes in de badkamer en niet op de trap.","Spreek ook af dat je kind niet klimt: wat hoger ligt dan je eigen hoofd, telt niet mee.","Teken geen breekbare of waardevolle dingen op de kaart, zoals glazen, een telefoon of een bril."],"say":["Wat staat er in dit vakje?","Iets zachts! Wat vind jij zacht?","Je dacht goed na voordat je iets pakte: is het wel echt rond?","Gevonden! Nog vier vakjes!","Waar woont de lepel? Breng je hem terug?"],"words":["zoeken","vinden","zacht","rond","hard","zwaar","licht","verzamelen"],"learn":["taal","rekenen","concentratie","grove-motoriek"],"tips":["Teken eigenschappen met een simpel teken: een rode stip voor iets roods, een wolkje voor iets zachts, een oor voor iets dat geluid maakt.","Schuif de zoekkaart in een doorzichtige plastic map en streep af met een afwasbare stift: dan kun je de kaart vaker gebruiken."],"extenders":["Zet een kookwekker op vijf minuten: hoeveel vakjes zijn er vol als de bel gaat?","Teken op de achterkant een nieuwe ronde met lastigere dingen: iets kouds, iets dat kan rollen, iets dat lekker ruikt.","Laat je kind de buit op een rij leggen: van klein naar groot, of van zacht naar hard.","Verstop een knuffel als geheime schat en teken die in het laatste vak: de speurtocht is pas klaar als de knuffel terecht is.","Maak er een ‘ik zie, ik zie’-tocht van: je kind neemt niets mee, maar wijst bij elk vak aan waar het ligt."],"variations":["Voeltocht: teken alleen gevoelens: iets zachts, iets ruws, iets kouds, iets glads, iets kriebeligs.","Opruimtocht: teken op de kaart wat er nog opgeruimd moet worden (de blokken, de knuffel, de boeken) en laat je kind alles naar de goede plek brengen.","Sinterklaas: teken dingen uit het verhaal, zoals een schoen, een wortel, een mijter en een pepernoot, en verstop ze in de kamer.","Lettertocht: zoek voor elke letter van de eigen naam iets dat met die letter begint."],"themes":[],"canStay":false,"pinQuery":"speurtocht binnen zoekkaart kind"},
  {"id":"eierdoos-speurtocht","title":"Eierdoos-speurtocht: vul elk vakje","emoji":"🥚","category":"zintuigen","summary":"Teken in elk vakje van een eierdoos een kleur of vorm en zoek in huis kleine dingen die passen: elk vakje is een nieuwe opdracht.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":2,"places":["vloer","tafel"],"materials":[{"id":"eierdoos","note":"voor 10 of 12 eieren, of twee doosjes van 6"},{"id":"stiften","note":"om in elk vakje een kleur of vorm te tekenen"}],"optional":[{"id":"gekleurd-papier","note":"rondjes om onderin de vakjes te leggen, dan zie je de kleur beter"},{"id":"wasknijpers","note":"als tangetje om de schatten te pakken"}],"steps":["Teken met stift in elk vakje van de eierdoos een kleur of een vorm: een rode stip, een blauwe stip, een rondje, een driehoek, een streep.","Bekijk samen de vakjes: wat moet hierin? Iets roods? Iets ronds? Spreek af dat elk ding in het vakje moet passen.","Ga op zoek door de kamer: je kind kiest een vakje en zoekt een klein ding dat erbij past, zoals een rode dop of een rond knoopje.","Laat je kind het gevonden ding in het vakje leggen en vertellen waarom het past: rood én klein!","Zoek door tot alle vakjes vol zijn. Bekijk de doos dan samen als een schatkist: wat was het moeilijkst om te vinden?","Laat je kind alles terugbrengen naar de plek waar het vandaan kwam, of bewaar de schatkist een dagje om te laten zien."],"ageTips":{"young":"Begin voor een driejarige met een doosje van 6 en alleen kleuren. Teken grote stippen en zoek samen in één kamer. Te groot voor het vakje? Dan mag het ernaast.","old":"Een kleuter kan opdrachten aan met twee eigenschappen (iets roods én ronds) of met letters (iets met de m van maan). Zoek dan ook buiten de kamer, door het hele huis."},"safety":["Knopen, kralen, munten en dopjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3. Speel als een jonger broertje of zusje slaapt, of ruim de schatten direct op.","Spreek af waar je kind niet mag zoeken, zoals het medicijnkastje, de schoonmaakmiddelen en de la met batterijen. Een knoopcelbatterij past precies in een vakje en is levensgevaarlijk bij inslikken."],"say":["Wat moet er in dit vakje?","Iets roods! Zie jij iets roods?","Past het? Ja! Volgende vakje.","Je dacht goed na: die knoop is rood én rond.","Welk vakje was het moeilijkst?"],"words":["vakje","passen","klein","rond","kleur","vol","leeg","zoeken"],"learn":["rekenen","taal","concentratie","fijne-motoriek"],"tips":["Teken met een dikke stift op de grijze eierdoos, of leg een rondje gekleurd papier onderin: dan zie je de kleur beter.","Spreek af dat alles terug moet naar waar het vandaan kwam: dan is opruimen het laatste spelletje."],"extenders":["Doe de doos dicht, schud alles door elkaar en laat je kind de schatten weer in het goede vakje sorteren.","Geef een wasknijper als tangetje: kun je de schatten in het vakje leggen zonder je vingers te gebruiken?","Teken aan de binnenkant van het deksel nieuwe opdrachten: iets zachts, iets van metaal, iets dat glimt.","Laat je kind jou testen: jij doet je ogen dicht, je kind legt een schat in je hand en jij raadt in welk vakje die hoort.","Ruil de rollen om: je kind tekent nieuwe kleuren en vormen in een tweede doos, en jij gaat op zoek."],"variations":["Herfst: zet een mand met eerder verzamelde natuurschatten neer en zoek daarin: iets bruins, iets ruws, iets puntigs. Kastanjes en eikels zijn niet eetbaar.","Pasen: zoek dingen in paaskleuren en vul de doos als een paasnestje.","Cijferdoos: schrijf 1 tot en met 6 in de vakjes en zoek precies zoveel kleine dingen als het cijfer zegt."],"themes":[],"canStay":false,"pinQuery":"eierdoos speurtocht kleuren kind"},
  {"id":"water-overgieten","title":"Overgieten op een dienblad","emoji":"💧","category":"water","summary":"Bekers, een trechter en een sponsje op een dienblad: gieten, vullen en knijpen tot je kind een echte watermeester is.","ageMin":1,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":3,"duration":[10,25],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"dienblad","note":"met een randje"},{"id":"water","note":"een laagje lauw water"},{"id":"plastic-bekers","note":"2-3 in verschillende maten, ook een met tuit"},{"id":"trechter"},{"id":"sponsjes","note":"een sponsje om op te deppen"},{"id":"handdoek","note":"onder het dienblad"}],"optional":[{"id":"kleurstof","note":"één druppel, dan zie je beter hoe vol een beker is"},{"id":"pipet"},{"id":"kom"}],"steps":["Leg een handdoek op tafel of op de vloer en zet het dienblad erop.","Zet 2-3 bekers, een trechter en een sponsje op het blad en vul één beker halfvol met lauw water.","Doe voor hoe je langzaam van de ene in de andere beker giet en laat je kind het proberen.","Ontdek samen: water door de trechter gieten, de spons vol laten zuigen en uitknijpen boven een lege beker.","Laat je kind gemorst water opdeppen met het sponsje en uitknijpen boven een beker: morsen hoort erbij.","Giet het water na afloop in de gootsteen en hang de handdoek te drogen."],"ageTips":{"young":"Een dreumes begint met één beker en een kom: scheppen en omkieperen is genoeg. Gebruik weinig water, zo blijft het overzichtelijk.","old":"Een kleuter kan tot een streepje vullen (zet een stip met stift), tellen hoeveel kleine bekers er in een grote passen of met een pipet een beker druppel voor druppel vullen."},"safety":["Laat een jong kind nooit alleen bij water, ook niet bij een laagje op een dienblad.","Dweil gemorst water direct op: een natte vloer is glad, zeker voor wiebelige beentjes."],"say":["Plons! Nog een keer?","Kijk, het water loopt door het gaatje van de trechter.","Welke beker is voller: deze of die?","Je giet heel langzaam en voorzichtig. Er ging bijna niks naast!","Hoe voelt de natte spons in je hand?"],"words":["gieten","vol","leeg","half","druppel","nat","knijpen","langzaam"],"learn":["fijne-motoriek","ontdekken","rekenen","concentratie"],"tips":["Geef weinig water tegelijk: liever vaak bijvullen dan een grote plas.","Trek je dreumes een oud shirt aan of speel in alleen een luier, vlak voor badtijd.","Een theedoek op het dienblad dempt het gespetter en zuigt gemorst water op."],"extenders":["Zet er een plastic flesje met een smalle hals bij: lukt het om dat met de trechter vol te gieten zonder te morsen?","Geef een plantenspuit erbij en laat je kind een lege beker vol spuiten: hoe vaak moet je knijpen?","Leg een sponsje, een washandje en een stukje keukenpapier naast elkaar: welke zuigt het meeste water op?"],"variations":["Kleuren mengen: een beker geel en een beker blauw water. Wat krijg je als je ze samen giet?","Theekransje: schenk thee (water) in kopjes voor de knuffels.","IJsblokjes: doe een paar ijsblokjes in de bekers en kijk hoe lang het duurt voordat ze gesmolten zijn."],"themes":[],"canStay":false,"pinQuery":"water overgieten dienblad peuter"},
  {"id":"speelgoed-wassen","title":"Speelgoed wassen in een sopje","emoji":"🧽","category":"water","summary":"Een bak sop, een sponsje en een oude tandenborstel: je kind schrobt de diertjes en de pop schoon, net als een grote.","ageMin":1,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"duration":[10,25],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["vloer"],"materials":[{"id":"opbergbak","note":"een afwasteil met een laagje lauw water"},{"id":"water"},{"id":"afwasmiddel","note":"een klein scheutje, of badschuim"},{"id":"sponsjes"},{"id":"tandenborstel"},{"id":"klein-speelgoed","note":"plastic diertjes, duplo of autootjes"},{"id":"handdoek","note":"om op af te drogen"}],"optional":[{"id":"poppen","note":"een plastic pop die nat mag worden"},{"id":"oud-laken","note":"een tafelzeil of douchegordijn onder de bak"},{"id":"kom","note":"met schoon water om na te spoelen"}],"steps":["Leg een handdoek of tafelzeil op de vloer en zet daar een afwasteil op met een laagje lauw water.","Doe er een klein scheutje afwasmiddel bij en klop het samen met je handen tot een sopje.","Verzamel samen ‘vies’ speelgoed: plastic diertjes, duplo, autootjes of een pop.","Laat je kind alles wassen met het sponsje en de tandenborstel: achter de oren, tussen de tenen!","Spoel het speelgoed na in een kom schoon water en leg het op een handdoek om te drogen.","Droog alles samen af, giet het water weg en hang de handdoeken te drogen."],"ageTips":{"young":"Een dreumes zit op de vloer bij een laag bakje water met één diertje en een spons. Doe het voor: wrijf, wrijf, buikje wassen! Laat de zeep weg als je kind alles in de mond stopt.","old":"Maak er een autowasstraat of dierenkliniek van: een kleuter bedenkt de stappen (inzepen, schrobben, spoelen, drogen) en houdt bij hoeveel klanten er geweest zijn."},"safety":["Laat een jong kind nooit alleen bij een bak water: een dreumes kan al in een paar centimeter water verdrinken.","Gebruik maar een scheutje afwasmiddel en houd het uit de ogen en de mond; spoel handjes na met schoon water.","Dweil gemorst water direct op: de vloer wordt glad."],"say":["Wrijf, wrijf! Schoon!","Waar zit het vuil nog? Achter zijn oren?","Hoe voelt het sopje aan je handen: glad of glibberig?","Je wast heel zorgvuldig, zelfs tussen de pootjes.","Wat moeten we eerst doen: wassen of afdrogen?"],"words":["wassen","schoon","vies","sop","schrobben","afdrogen","nat","droog"],"learn":["fijne-motoriek","zintuigen","taal","samen"],"tips":["Doe het vlak voor badtijd, of gewoon in het bad zelf.","Handig: zo worden badspeeltjes en duplo ook echt schoon.","Laat speelgoed met batterijen of geluid erbuiten."],"extenders":["Zet met een afwasbare stift stipjes ‘modder’ op een paar diertjes: lukt het je kind om ze er allemaal af te boenen?","Geef nieuw schoonmaakgereedschap: een afwasborstel, een washandje of een nagelborsteltje.","Laat je kind de schone spullen gesorteerd op de handdoek leggen om te drogen: alle dieren bij elkaar, alle blokken bij elkaar."],"variations":["Poppenwasdag: was de pop en haar kleertjes en hang ze met wasknijpers op aan een kort touw tussen twee stoelen.","Autowasstraat: rij speelgoedautootjes door het sop en daarna door een droogstraat van handdoeken.","Afwassen: was plastic bordjes en bekers van de poppenkeuken en zet ze op een rek te drogen."],"themes":[],"canStay":false,"pinQuery":"speelgoed wassen sopje peuter"},
  {"id":"bevroren-diertjes","title":"Bevroren diertjes bevrijden","emoji":"🧊","category":"water","summary":"De diertjes zitten vast in het ijs! Met lauw water, zout en een pipet smelt je kind ze los, en ontdekt het hoe ijs werkt.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"duration":[15,30],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"klein-speelgoed","note":"plastic diertjes, groter dan een wc-rolletje"},{"id":"bakjes","note":"yoghurtbekers of boterkuipjes om in te vriezen"},{"id":"water"},{"id":"vriezer"},{"id":"opbergbak","note":"een grote platte bak om in te spelen"},{"id":"plastic-bekers","note":"met lauw water"},{"id":"zout","note":"een schaaltje met een paar eetlepels"},{"id":"lepel"}],"optional":[{"id":"pipet","note":"voor gericht druppelen"},{"id":"plantenspuit","note":"met lauw water"},{"id":"handdoek","note":"onder de bak"}],"steps":["Zet de avond ervoor in elk bakje een diertje, vul het met water en zet de bakjes een nacht in de vriezer.","Laat het ijs 5 minuten liggen, haal de blokken uit de bakjes (even onder de warme kraan als het vastzit) en leg ze in de grote bak.","Zet bekertjes lauw water, een pipet, een lepel en een schaaltje zout ernaast.","Laat je kind het ijs bevrijden: lauw water erover gieten, druppelen met de pipet en zout strooien. Waar smelt het het snelst?","Juich bij elk bevrijd dier en leg het in een warm handdoeknestje om op te warmen.","Giet het smeltwater weg en droog de diertjes af."],"ageTips":{"young":"Voor een tweejarige: vries één groot dier in een groot bakje in en geef een beker lauw water en een lepel. Gieten en kijken is al spannend genoeg. Brr, koud!","old":"Een kleuter kan voorspellen wat het snelst werkt: warm water, koud water of zout? Laat je kind tellen hoeveel bekers er nodig zijn, of vries een groot blok met drie dieren op verschillende hoogtes."},"safety":["IJs dat net uit de vriezer komt, kan aan natte vingers en lippen vastvriezen: laat het eerst 5 minuten liggen en laat je kind er niet aan likken.","Zout prikt in wondjes en ogen en is niet om te eten: strooi met een lepel en was handen na afloop.","Gebruik alleen diertjes die niet door een wc-rolletje passen: kleinere zijn te klein voor kinderen onder de 3.","Laat je kind niet alleen bij het water en dweil smeltplassen direct op."],"say":["Brr, koud! Voel maar.","Kijk, het zout maakt gaatjes en geultjes in het ijs!","Wat denk je: smelt het sneller met warm of met koud water?","Je bleef maar doorgaan tot de pinguïn vrij was. Wat een doorzetter!","Vrij! Nog een!"],"words":["ijs","koud","smelten","bevriezen","druppelen","vrij","glad","nat"],"learn":["ontdekken","zintuigen","fijne-motoriek","concentratie"],"tips":["Diertjes drijven naar boven: vries eerst een laagje water, zet er na een uur het diertje op en vul daarna aan. Dan zit het mooi in het midden.","Kleine blokken (muffinvorm of ijsblokjesvorm) smelten sneller: fijn voor ongeduldige peuters.","Speel in de lege badkuip of zet de bak op een handdoek: smeltwater blijft dan waar het hoort."],"extenders":["Houd een verrassingsblok achter de hand in de vriezer en haal het tevoorschijn als de aandacht wegzakt: wie zit er nu in het ijs?","Geef een dikke kwast en een bekertje lauw water: lukt het om een gangetje naar het diertje te ‘schilderen’?","Vis de losse ijsbrokjes met een zeef of soeplepel uit het smeltwater en leg ze op een rij: welke is het eerst helemaal weg?"],"variations":["Winter: vries in een grote bak een ijsschots in met pinguïns en ijsberen en ga op poolexpeditie.","Zomer: smelt het ijs met een plantenspuit lauw water, lekker verfrissend.","Schatten bevrijden: vries duploblokken en lege schelpen in als ‘schatten’ voor een ijspiraat."],"themes":["winter"],"canStay":false,"pinQuery":"bevroren dieren bevrijden ijs"},
  {"id":"waterbaan","title":"Waterbaan op de badkamermuur","emoji":"🚿","category":"water","summary":"Plak doorgesneden flessen en trechters op de tegels en giet er water doorheen: waar komt het uit? Bouwen en spetteren tegelijk.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":15,"duration":[15,25],"supervision":2,"soloFrom":null,"cleanupMinutes":5,"noise":2,"energy":2,"places":["bad","muur"],"materials":[{"id":"plastic-flesjes","note":"3-4 lege flessen, door jou doorgesneden"},{"id":"trechter"},{"id":"ducttape","note":"plakt het best op droge tegels"},{"id":"schaar","note":"om de flessen door te knippen (voor jou)"},{"id":"badkuip","note":"het lege bad of de douchebak"},{"id":"water"},{"id":"plastic-bekers","note":"of een kannetje om mee te gieten"}],"optional":[{"id":"badspeelgoed","note":"eendjes die mee mogen glijden"},{"id":"pingpongballen","note":"om mee te laten varen (vanaf 3 jaar)"}],"steps":["Snijd 3-4 flessen in de lengte doormidden (goten) of knip de bodem eraf (trechters). Dat doe jij; plak scherpe randen af met tape.","Droog de tegels boven het lege bad of de douchebak goed af.","Plak de goten en trechters schuin onder elkaar op de tegels met stukken ducttape, zodat het water van de ene in de andere loopt.","Zet je kind in het lege bad of de douchebak, met een beker water.","Giet het water bovenin en kijk waar het naartoe stroomt. Loopt het ernaast? Verschuif samen een goot.","Haal na afloop de tape eraf en bewaar de goten en trechters voor een volgende keer."],"ageTips":{"young":"Voor een tweejarige: plak de baan laag, op ooghoogte in het bad, en gebruik grote bekers. Gieten en kijken is al genoeg: daar gaat het! Plons!","old":"Een kleuter kan meebouwen en zelf bedenken waar de volgende goot moet. Laat een pingpongballetje meevaren of tel hoe lang het water over de baan doet."},"safety":["Laat je kind nooit alleen in of bij het bad, ook niet als er alleen een laagje water in staat.","Een nat bad is glad: leg een antislipmat neer, laat je peuter liefst zitten en dweil water naast het bad direct op.","Doorgesneden plastic heeft scherpe randen: knip zelf en plak de randen af met tape.","Pingpongballetjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: laat een tweejarige liever grote badspeeltjes door de baan sturen."],"say":["Daar gaat het water! Plons!","Waar denk je dat het water heen gaat als je hier giet?","Het loopt ernaast… hoe kunnen we dat oplossen?","Wat goed bedacht om die trechter eronder te zetten!","Hoor je het klateren?"],"words":["stromen","gieten","bovenaan","onderaan","goot","trechter","schuin","plons"],"learn":["ontdekken","fijne-motoriek","samen"],"tips":["Doe het vlak voor badtijd: na de waterbaan meteen in bad.","Bewaar de goten en trechters in een tas bij het bad: de volgende keer hangt de baan er in een paar minuten.","Lijmresten van de tape haal je van de tegels met een beetje olie op een doekje."],"extenders":["Droog een stukje tegel af en plak er een extra goot bij, zodat de baan zich splitst: welke kant kiest het water?","Zet onderaan een lege beker als eindstation: hoe vaak moet je bovenin gieten voordat die vol is?","Geef een natte spons in plaats van een beker: knijp hem bovenin uit en kijk of het water de hele baan afloopt."],"variations":["Zomer: speel in je zwembroek met lauw water, een binnen-zwembaddag.","Bootjesrace: laat badeendjes of plastic doppen (vanaf 3 jaar) door de goten glijden. Welke is het eerst beneden?","Regenbui: prik gaatjes in de bodem van een bekertje en hang het bovenaan de baan."],"themes":["zomer"],"canStay":false,"pinQuery":"waterbaan in bad peuter"},
  {"id":"bellenblaas","title":"Zelf bellenblaas maken","emoji":"🧼","category":"water","summary":"Maak samen bellenblaas en buig blaasringen van pijpenragers: blazen, zwaaien en bellen vangen, gewoon binnen.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["keuken","tafel"],"materials":[{"id":"afwasmiddel","note":"100 ml"},{"id":"water","note":"600 ml"},{"id":"suiker","note":"1 el, maakt de bellen sterker"},{"id":"kom","note":"een brede kom om de ringen in te dopen"},{"id":"lepel","note":"om zacht te roeren"},{"id":"pijpenragers","note":"2-3 per kind, om blaasringen van te buigen"}],"optional":[{"id":"glazen-pot","note":"om het restje in te bewaren"},{"id":"rietjes","note":"om blazen te oefenen"},{"id":"bakjes","note":"een eigen bakje sop per kind"}],"steps":["Roer in een kom 600 ml water, 100 ml afwasmiddel en 1 el suiker zachtjes door elkaar. Niet kloppen, anders krijg je schuim.","Laat het sop als het kan een paar uur staan, bijvoorbeeld ’s ochtends maken en ’s middags blazen. Dan worden de bellen sterker.","Buig samen pijpenragers tot ringen met een steeltje: een rondje, een hartje, een grote ring. Draai de uiteinden goed om.","Oefen eerst blazen zonder sop: blaas zachtjes tegen je hand of blaas een propje papier over tafel.","Ga in de badkamer of bij de keukentegels staan, doop de ring in het sop en blaas zachtjes. Zwaaien met de ring geeft ook bellen.","Bewaar het overgebleven sop in een pot met deksel: het blijft een paar weken goed."],"ageTips":{"young":"Een tweejarige kan nog moeilijk blazen. Laat je kind de ring rondzwaaien, of jij blaast en je kind vangt, prikt en stampt de bellen kapot. Plop!","old":"Een kleuter kan zelf vormen buigen en ontdekken: wordt een vierkante ring ook een vierkante bel? Tel hoeveel bellen je in één keer blaast, of wie de grootste bel maakt."},"safety":["Bellenblaas is niet om te drinken en prikt in de ogen: oefen eerst blazen zonder sop, zodat je kind niet per ongeluk zuigt, en houd een nat washandje klaar.","Geknapte bellen maken de vloer spekglad: blaas boven het bad, de douchebak of tegels, dweil direct op en laat je kind niet alleen bij het sop.","Buig de uiteinden van de pijpenragers goed om, zodat er geen scherpe draadjes uitsteken."],"say":["Plop! Weg is de bel!","Kijk, ik zie regenboogkleuren in de bel.","Wat denk je: wordt een hartjesring ook een hartjesbel?","Je blies heel zachtjes, daardoor werd hij zo groot!","Hoeveel bellen kun jij vangen?"],"words":["bel","blazen","zachtjes","plop","rond","zweven","groot","klein"],"learn":["ontdekken","fijne-motoriek","grove-motoriek"],"tips":["Vang een bel met een natte hand: dan knapt hij niet meteen. Probeer het maar!","Blaas bellen in de badkamer vlak voor badtijd: dan is een natte vloer geen probleem.","Spoel handjes na het spelen af met water: afwasmiddel kan prikken in kleine wondjes."],"extenders":["Doop eens een vergiet, een zeef of een koekjesvormpje in het sop en zwaai ermee door de lucht: wat geeft de meeste bellen?","Speel bellentikkertje: jij blaast, je kind tikt elke bel aan voordat die de grond raakt, met een vinger, een elleboog of een teen.","Vang een bel op een dienblad dat je eerst nat hebt gemaakt met sop: hoe lang blijft de bel heel?"],"variations":["Zomer: blaas bellen boven je kind terwijl het in een ondiep bad zit, en jij blijft er natuurlijk bij.","Bellenslang: knip de bodem van een plastic flesje, trek er een oude sok over, doop hem in het sop en blaas: een lange slang van schuim (alleen blazen, niet zuigen).","Verjaardag: geef elk kind op het feestje een eigen pijpenragerring en een bakje sop."],"themes":["zomer"],"canStay":false,"pinQuery":"bellenblaas zelf maken kind"},
  {"id":"sponsbommen","title":"Sponsbommen voor in bad","emoji":"💦","category":"water","summary":"Bind repen spons samen tot een kleurige bom: vol laten zuigen, uitknijpen en pets, raak tegen de tegels!","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":2,"soloFrom":null,"cleanupMinutes":5,"noise":2,"energy":2,"places":["bad"],"materials":[{"id":"sponsjes","note":"3 per bom, liefst in verschillende kleuren en zonder schuurkant"},{"id":"schaar","note":"om de sponzen in repen te knippen (voor jou)"},{"id":"elastiekjes","note":"2 stevige per bom, of een strak geknoopt touwtje"},{"id":"badkuip"},{"id":"water","note":"een laagje in het bad"}],"optional":[{"id":"plastic-bekers","note":"als doel op de badrand"},{"id":"badspeelgoed","note":"eendjes om te raken"}],"steps":["Knip elk sponsje in de lengte in 3 repen. Dat doe jij.","Leg 9 repen in 3 laagjes van 3 op elkaar, met de kleuren door elkaar.","Bind ze in het midden strak samen met 2 elastiekjes en trek de repen uit elkaar tot een bol.","Laat de sponsbom in bad vol water zuigen en knijp hem uit: wat een straal!","Gooi samen naar een doel: een tegel, een beker op de rand of een eendje in het water. Pets!","Knijp de bommen na afloop goed uit en laat ze drogen op de rand van het bad."],"ageTips":{"young":"Een tweejarige vindt vol laten zuigen en uitknijpen het leukst. Geef je kind een bom en een beker: knijpen, gieten, nog een keer. Gooien mag naar de tegels, niet naar gezichten.","old":"Een kleuter gooit van steeds verder weg naar een doel, telt de punten of gooit om de beurt. Laat je kind zelf de repen tellen en de kleuren kiezen voordat jij ze vastbindt."},"safety":["Elastiekjes zijn klein (verstikkingsgevaar onder de 3) en kunnen terugschieten: bind ze zelf vast, kijk de bom na elk gebruik na en gooi een los elastiekje meteen weg.","Laat je kind nooit alleen in bad, ook niet bij een laagje water, en dweil gespetter naast het bad direct op.","Een volle sponsbom is zwaar: spreek af dat je naar de tegels gooit, niet naar hoofden."],"say":["Knijp! Kijk eens wat een straal!","Hoe zwaar is de bom nu hij vol water zit? En na het knijpen?","Pets! Raak!","Je bleef het proberen tot je de beker raakte. Wat een doorzetter!","Welke kleur gooi jij als volgende?"],"words":["knijpen","gooien","zwaar","licht","nat","raak","mis","druppelen"],"learn":["grove-motoriek","fijne-motoriek","zintuigen"],"tips":["Laat de bommen na het spelen goed drogen, ook vanbinnen, anders gaan ze muf ruiken. Af en toe kunnen ze mee in de wasmachine op 60 °C.","Goedkope sponsjes uit een grootverpakking zijn prima; knip een eventuele harde schuurkant eraf.","Geen elastiekjes? Een stevig touwtje dat je strak dubbel knoopt werkt ook."],"extenders":["Laat een plastic bekertje in bad drijven en knijp de sponsbom erboven uit: hoe vaak moet je knijpen voordat het bekertje zinkt?","Houd de volle bom hoog boven het water en knijp heel langzaam: hoor je het regenen? En nu een flinke plensbui!","Knijp de bom boven het bad goed leeg, laat los en duw hem meteen onder water: zie je de bubbels omhoog komen?"],"variations":["Zomer: speel met een laagje koel water in je zwempak, een verkoelend binnenbad.","Omgooispel: zet drie plastic bekers op de badrand en probeer ze eraf te gooien.","Hoeveel water? Knijp de bom uit boven een maatbeker en vergelijk wie er het meest water in had."],"themes":["zomer"],"canStay":false,"pinQuery":"sponsbommen maken bad"},
  {"id":"eendjes-vissen","title":"Eendjes vissen met een zeef","emoji":"🦆","category":"water","summary":"Laat eendjes en badspeeltjes drijven en vis ze eruit met een zeef: het water loopt eruit, het eendje blijft. Tel samen je vangst!","ageMin":1,"ageMax":4,"mess":2,"wet":true,"dirty":false,"prepMinutes":3,"duration":[10,20],"supervision":1,"soloFrom":null,"cleanupMinutes":5,"noise":2,"energy":1,"places":["bad","vloer"],"materials":[{"id":"badspeelgoed","note":"5-10 eendjes, bekertjes of ballen, groter dan een wc-rolletje"},{"id":"zeef","note":"of een soeplepel"},{"id":"opbergbak","note":"een afwasteil, of het bad met een laagje water"},{"id":"water","note":"lauw, een paar centimeter"},{"id":"kom","note":"voor de gevangen eendjes"},{"id":"handdoek"}],"optional":[{"id":"vergiet","note":"laat het water extra snel weglopen"},{"id":"oud-laken","note":"een tafelzeil of douchegordijn onder de bak"}],"steps":["Vul een afwasteil of het bad met een laagje lauw water van een paar centimeter.","Laat 5-10 badspeeltjes in het water drijven en zet een lege kom naast de bak.","Geef je kind een zeef of soeplepel en doe voor hoe je een eendje vangt en het water eruit laat lopen.","Leg elk gevangen eendje in de kom en tel samen: één, twee, drie!","Maak het spannender: maak golven met je hand of vraag om een bepaalde kleur.","Gooi alles terug en vis opnieuw. Knijp de eendjes na afloop leeg en laat alles drogen."],"ageTips":{"young":"Een dreumes (1 jaar) vist eerst met de handen of een grote soeplepel. Gebruik 3-4 grote speeltjes en benoem: eend! Nat! Gevangen!","old":"Een vierjarige vist op opdracht (alle gele, of alleen de kleine), telt de vangst of speelt om de beurt: wie heeft er na één liedje de meeste?"},"safety":["Laat een dreumes nooit alleen bij een bak water of in bad: een klein kind kan al in een paar centimeter water verdrinken.","Gebruik alleen speeltjes die niet door een wc-rolletje passen: kleinere zijn te klein voor kinderen onder de 3.","Knijpeendjes met een gaatje kunnen vanbinnen gaan schimmelen: knijp ze na het spelen leeg en laat ze drogen, of plak het gaatje dicht."],"say":["Hap! Gevangen!","Zie je het water door de gaatjes lopen?","Welke kleur ga je nu vangen?","Je hield de zeef heel stil tot het eendje erin zat. Goed gedaan!","Hoeveel eendjes hebben we al? Zullen we tellen?"],"words":["eend","vangen","drijven","gaatjes","nat","meer","minder"],"learn":["fijne-motoriek","rekenen","taal","zintuigen"],"tips":["Speel het vlak voor of tijdens het badderen: dan hoef je niets extra op te ruimen.","Geen badeendjes? Plastic bekertjes en grote deksels drijven ook.","Een gewone eetlepel is lastiger dan een zeef: een leuke uitdaging voor oudere kinderen."],"extenders":["Laat je kind de vangst één voor één terugbrengen naar het water, alleen met de zeef en zonder handen.","Open een viskraam: je kind verkoopt de gevangen eendjes aan jou, en jij bestelt er twee gele of één grote.","Ruil van rol: jij vist met de zeef en je kind maakt golven om de eendjes te laten ontsnappen."],"variations":["Kermis: zet met watervaste stift een stip onder een paar eendjes. Wie een stip vangt, mag een liedje kiezen.","IJsvissen: laat ook ijsblokjes drijven. Wat smelt er terwijl je vist?","Zee: vis plastic visjes van het wateroppervlak en schelpen van de bodem."],"themes":[],"canStay":false,"pinQuery":"eendjes vissen bad peuter"},
  {"id":"toverdrankjes","title":"Toverdrankjes brouwen","emoji":"🧪","category":"water","summary":"Gekleurd water, bloemblaadjes en een snufje kaneel: roer, druppel en bruis een echte toverdrank in je eigen ketel.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":10,"duration":[15,35],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"water"},{"id":"kleurstof","note":"2-3 kleuren, een paar druppels per beker"},{"id":"kom","note":"een grote kom als ketel en kleine bakjes voor ingrediënten"},{"id":"plastic-bekers","note":"3-4 stuks"},{"id":"lepel","note":"een grote lepel om te roeren"},{"id":"pipet"},{"id":"bloemen","note":"bloemblaadjes van uitgebloeide bloemen"},{"id":"kruiden","note":"een snufje kaneel, gedroogde kruiden of thee"},{"id":"opbergbak","note":"een grote platte bak om in te werken"}],"optional":[{"id":"baking-soda","note":"1-2 el, voor het bruisen"},{"id":"azijn","note":"een scheutje, voor het bruisen"},{"id":"bladeren","note":"voor een herfstdrankje"},{"id":"zeef","note":"om blaadjes op te vangen bij het weggieten"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Zet een grote platte bak op tafel met daarin een kom als ketel en 3-4 bekers water, elk met een paar druppels kleurstof.","Zet de ingrediënten in bakjes klaar: bloemblaadjes, blaadjes en een snufje kaneel of andere kruiden.","Laat je kind brouwen: water overgieten, druppelen met de pipet, roeren en ingrediënten erin strooien.","Bedenk samen wat het drankje doet: is het een slaapdrankje voor de knuffel of een drankje om groot van te worden?","Doe voor bruis 1-2 el baking soda in de ketel en laat je kind er een scheutje azijn bij gieten. Het bruist!","Giet het drankje na afloop weg via een zeef, gooi de blaadjes in de groenbak en spoel bak en bekers om."],"ageTips":{"young":"Een tweejarige giet en roert vooral graag. Geef 2 kleuren en een grote lepel en doe het bruisen zelf. Benoem: geel erbij… nu wordt het groen!","old":"Een kleuter kan een recept tekenen (3 druppels rood, 1 lepel blaadjes) en dat precies nabrouwen, of een naam en een toverspreuk voor het drankje bedenken."},"safety":["Een toverdrank is niet om te drinken: spreek dat vooraf af en gebruik alleen spullen die geen kwaad kunnen als er toch geproefd wordt, dus geen zeep of schoonmaakmiddel.","Gebruik alleen bloemen en blaadjes die je kent; laat giftige planten als lelietje-van-dalen, vingerhoedskruid en narcis weg.","Azijn prikt in de ogen en kleurstof vlekt op kleding, tafel en voegen: werk in de bak, met een oud shirt aan.","Laat je peuter niet alleen bij de bekers water en dweil gemorst water direct op."],"say":["Roer, roer! Wat brouw jij?","Kijk, geel en blauw samen… wat wordt het?","Wat doet jouw toverdrank als je knuffel hem krijgt?","Je hebt heel precies gedruppeld met de pipet. Knap!","Ruik eens aan de kaneel: mmm of bah?"],"words":["brouwen","roeren","druppelen","bruisen","mengen","toverdrank","ketel"],"learn":["creativiteit","ontdekken","fijne-motoriek","taal"],"tips":["Werk in een grote platte bak of in de lege badkuip: wat overloopt, blijft binnen de rand.","Bewaar uitgebloeide bloemen en blaadjes van een wandeling in een bakje: dat zijn je toveringrediënten.","Gebruik kleine beetjes baking soda en azijn, dan kun je vaker bruisen."],"extenders":["Geef een toveropdracht: tover eens een groen, een oranje of een paars drankje met alleen rood, geel en blauw water.","Zet een nieuw ingrediënt op tafel, zoals een theezakje, een schijfje citroen of een ijsblokje: wat doet het met het drankje?","Giet het drankje door een zeef in een schone beker: wat blijft er achter en hoe ziet het drankje er nu uit?"],"variations":["Halloween: groene heksensoep met plastic spinnen, geroerd met een pollepel.","Herfst: een bosdrankje met blaadjes, dennennaalden en een snufje kaneel.","Lente: bloemensoep met bloemblaadjes en verse munt.","IJsdrankje: laat gekleurde ijsblokjes in de ketel smelten en kijk hoe de kleur zich verspreidt."],"themes":["halloween","herfst"],"canStay":false,"pinQuery":"toverdrankjes brouwen peuter"},
  {"id":"schuimverf-in-bad","title":"Schilderen met schuim in bad","emoji":"🛁","category":"water","summary":"Smeer schuim op de badtegels, de badrand en je eigen buik, en spoel daarna alles weg: kliederen zonder opruimgedoe.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":null,"cleanupMinutes":5,"noise":1,"energy":1,"places":["bad","muur"],"materials":[{"id":"scheerschuim","note":"of zelfgemaakt zeepschuim (zie Recepten)"},{"id":"muffinvorm","note":"elk vakje een kleur"},{"id":"badkuip","note":"het lege bad"},{"id":"penselen","note":"dikke kwasten"},{"id":"water","note":"om af te spoelen"}],"optional":[{"id":"kleurstof","note":"een drupje per vakje"},{"id":"sponsjes","note":"om mee te schilderen"},{"id":"plantenspuit","note":"met lauw water, om de tegels schoon te spuiten"}],"steps":["Zet je kind zonder kleren of in een oude zwembroek in het lege bad, op een antislipmat.","Spuit in elk vakje van de muffinvorm een toef schuim en roer er eventueel een drupje kleurstof door.","Geef je kind een kwast of sponsje, of gewoon de handen, en laat je kind de tegels en de badrand beschilderen.","Schilder ook op buik en knieën! Benoem wat je ziet: een gele streep, een blauwe stip, een groene buik.","Spoel alles af met de douche of een beker water en ga daarna meteen in bad.","Veeg de tegels na met een doekje en spoel de muffinvorm om."],"ageTips":{"young":"Voor een tweejarige: begin met wit schuim zonder kleur en laat je kind vooral voelen en smeren. Stopt je kind alles in de mond, neem dan slagroom. Benoem: zacht! Koud! Weg!","old":"Een kleuter kan kleuren mengen (geel en blauw), vormen of de eigen naam op de tegels schrijven, of een schuimgezicht op de buik maken en dat in de spiegel bekijken."},"safety":["Scheerschuim prikt in de ogen en is niet om te eten: houd een nat washandje klaar. Voor een peuter die alles proeft: neem slagroom en spoel die goed weg.","Een bad met schuim is extra glad: laat je kind liefst zitten, op een antislipmat, en laat een jong kind nooit alleen in bad.","Bij een gevoelige huid kan scheerschuim irriteren: kies dan zelfgemaakt zeepschuim van kindershampoo."],"say":["Smeer, smeer! Hoe voelt het?","Ik zie een gele streep naast de blauwe stip.","Wat gebeurt er als je rood en geel door elkaar roert?","Je hebt de hele muur beschilderd. Wat heb je goed doorgezet!","Spoelen… weg is het! Waar is het naartoe?"],"words":["schuim","smeren","zacht","luchtig","mengen","spoelen","glad","weg"],"learn":["zintuigen","creativiteit","ontdekken","taal"],"tips":["Doe het in plaats van het gewone badmoment: na het spelen is je kind meteen schoon.","Met een plantenspuit lauw water wordt het schoonspuiten van de tegels ook een spel.","Gebruik maar een drupje kleurstof en spoel direct na: veel kleurstof kan voegen en een kunststof bad even kleuren."],"extenders":["Stempel met een sponsje of een badspeeltje in het schuim op de tegels: wat voor afdruk maakt een eendje?","Laat je kind de badspeeltjes inzepen met schuim en ze daarna met een beker water weer schoonspoelen.","Teken een weg van schuim over de badrand en laat er een bootje of eendje doorheen glijden."],"variations":["Winter: wit schuim als sneeuw. Teken sneeuwpoppen en sneeuwvlokken op de tegels.","Vormen raden: jij tekent een vorm in het schuim op de tegel, je kind raadt hem en veegt hem weg.","Verjaardag: maak een schuimtaart op de badrand met badspeeltjes als kaarsjes."],"themes":[],"canStay":false,"pinQuery":"scheerschuim verven in bad"},
  {"id":"ramen-lappen","title":"Ramen lappen met een plantenspuit","emoji":"🪟","category":"water","summary":"Spuiten, poetsen en droogwrijven: met een plantenspuit en een sponsje wordt je kind de glazenwasser van het hele huis.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":3,"duration":[20,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":2,"places":["muur"],"materials":[{"id":"plantenspuit","note":"schoon, gevuld met lauw water en één drupje afwasmiddel"},{"id":"water","note":"lauw"},{"id":"afwasmiddel","note":"één drupje, of laat het weg"},{"id":"sponsjes","note":"of een doekje om mee te poetsen"},{"id":"handdoek","note":"op de vensterbank en de vloer, en een droge om na te wrijven"}],"optional":[{"id":"opstapje","note":"voor de hogere ramen"},{"id":"papier","note":"voor een werkbriefje met alle ramen"},{"id":"potlood","note":"om af te vinken"},{"id":"kranten","note":"een prop krant om na te wrijven: het oude trucje tegen strepen"},{"id":"stiften","note":"afwasbaar, om ‘vlekken’ op het glas te tekenen"},{"id":"zaklamp","note":"voor de strepen-inspectie"}],"steps":["Vul de plantenspuit met lauw water en één drupje afwasmiddel. Leg een handdoek op de vensterbank en een op de vloer onder het raam.","Doe voor hoe het gaat: spuiten, met het sponsje in grote rondjes poetsen en droogwrijven met een droge doek.","Laat je kind beginnen bij een groot raam of de glazen deur op eigen hoogte. Pas als dat goed gaat, komt het opstapje erbij.","Teken samen een werkbriefje met een vierkantje voor elk raam dat schoon moet, zodat je kind ze één voor één kan afvinken.","Ga raam voor raam door het huis: de woonkamer, de keuken en de achterdeur. Na elk raam komt er een vinkje bij.","Doe samen de eindcontrole: kijk schuin langs het glas of er nog druppels of strepen zitten.","Wring de sponsjes uit, hang de handdoeken te drogen en dweil natte plekken op de vloer meteen droog."],"ageTips":{"young":"Doe voor een tweejarige alleen water in de spuit en kies een groot raam of de glazen deur op vloerhoogte. Spuiten is het leukste deel: dat mag zo vaak als je kind wil, en daarna poetsen jullie samen.","old":"Geef je kleuter het werkbriefje en laat de eigen route plannen: welk raam eerst? Laat je kind ook zelf de spuit bijvullen bij de kraan en speuren naar de laatste strepen."},"safety":["Was alleen dichte ramen en zet het opstapje nooit bij een open raam of een raam dat je kind zelf kan openen. Blijf binnen handbereik zolang een peuter op het opstapje staat; een kleuter die zelfstandig werkt, doet alleen de lage ramen.","Spuit niet op stopcontacten, lampen, de tv of andere apparaten, en niet in elkaars gezicht: afwasmiddel prikt in de ogen.","Gebruik een schone spuit die nooit schoonmaakmiddel of plantenvoeding heeft bevat, en vul de spuit nooit met glasreiniger: die nevel adem je kind in.","Water met zeep maakt de vloer extra glad: leg handdoeken neer en dweil gemorst water direct op."],"say":["Spuit, spuit! Poets, poets!","Waar zie je nog druppels zitten?","Hoe voelt het raam nu: glad, nat of plakkerig?","Je poetst van boven naar beneden, net als een echte glazenwasser.","Kijk eens door het schone raam: wat zie je buiten?"],"words":["spuiten","poetsen","druppels","glad","doorzichtig","schoon","strepen","glazenwasser"],"learn":["fijne-motoriek","grove-motoriek","concentratie","taal"],"tips":["Kleine handjes kunnen een grote plantenspuit nog moeilijk indrukken: een klein, leeg sprayflesje (bijvoorbeeld een reisflesje) werkt voor peuters beter.","Het hoeft niet streeploos: het gaat om spuiten, poetsen en echt meehelpen. Wrijf het raam later zelf even na als je dat wilt.","Vanaf een jaar of 4 kan je kind de lage ramen in de woonkamer of keuken afwerken terwijl jij in dezelfde ruimte kookt of werkt."],"extenders":["Teken met een afwasbare stift een paar ‘vieze vlekken’ op het glas, zoals sterren en rondjes: kan je kind ze allemaal wegpoetsen?","Doe de inspectie met een zaklamp: schijn schuin over het glas en zoek samen de laatste strepen en vingerafdrukken.","Breid het werkgebied uit: de spiegel in de gang, de koelkastdeur, de ovendeur (alleen als de oven koud is) en de tafel.","Speel glazenwassersbedrijf: jij belt (doe-alsof) of de glazenwasser ook bij de knuffels langs kan komen, en betaalt met een sticker.","Wissel van gereedschap: eerst het sponsje, dan droogwrijven met een prop krant. Welk doekje laat het glas het mooist glimmen?"],"variations":["Schuimraam: spuit wat scheerschuim op het raam, laat je kind er met de vingers in tekenen en lap het daarna samen weg.","Plantenverzorger: geef alle kamerplanten een sproeibeurt met een spuit met alleen water, zonder afwasmiddel.","Winter: teken met afwasbare stift ijsbloemen en sneeuwvlokken op het raam en laat je kind de winter weer wegspuiten."],"themes":[],"canStay":false,"pinQuery":"peuter ramen wassen plantenspuit"},
  {"id":"afwassen-aanrecht","title":"Echte afwas aan het aanrecht","emoji":"🧼","category":"water","summary":"Op een opstapje aan de gootsteen sopt, schrobt en spoelt je kind een stapel onbreekbare afwas: echt werk met echt water.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"duration":[25,45],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":2,"energy":1,"places":["keuken"],"materials":[{"id":"opstapje","note":"stevig, zodat je kind met de ellebogen boven het aanrecht uitkomt"},{"id":"water","note":"lauw: voel zelf even"},{"id":"afwasmiddel","note":"een klein scheutje"},{"id":"kinderservies","note":"of ander onbreekbaar servies: plastic bordjes, bekers en bakjes"},{"id":"sponsjes","note":"of een afwasborstel"},{"id":"handdoek","note":"theedoeken om af te drogen, en een op de vloer"}],"optional":[{"id":"opbergbak","note":"een afwasteil in de gootsteen, en een tweede bak met spoelwater"},{"id":"oud-shirt","note":"of een schort, met de mouwen opgerold"},{"id":"tandenborstel","note":"voor de randjes en hoekjes"},{"id":"garde","note":"om het sop op te kloppen tot schuim"},{"id":"pan","note":"een klein pannetje of een deksel"}],"steps":["Ruim het aanrecht rond de gootsteen leeg: messen, glas, de waterkoker en schoonmaakmiddelen gaan buiten bereik. Zet het opstapje stevig voor de gootsteen.","Doe een laagje lauw water in de gootsteen of een afwasteil, voel zelf de temperatuur en knijp er een klein scheutje afwasmiddel bij.","Zet een stapel onbreekbare afwas klaar: plastic bordjes, bekers, bakjes, houten lepels en een klein pannetje.","Laat je kind alles in het sop wassen met de spons of borstel: de binnenkant, de buitenkant en de randjes.","Spoel de afwas na in een tweede bak met schoon water en zet alles op een opgevouwen theedoek om uit te lekken.","Droog samen af en ruim op: waar wonen de bordjes, en waar de bekers?","Laat het water weglopen, dweil de vloer droog en hang de natte theedoeken te drogen."],"ageTips":{"young":"Geef een tweejarige een paar bekers en een spons en laat vooral voelen, gieten en knijpen. Afwassen en spetteren lopen nog door elkaar, en dat mag. Houd zelf een hand in de buurt van het opstapje.","old":"Laat je kleuter de afwas in een vaste volgorde doen: eerst de bekers, dan de bordjes, dan het pannetje. Laat zelf kijken of iets echt schoon is, tellen wat er op de theedoek staat en alles op de goede plek terugzetten."},"safety":["Draai zelf de kraan open en voel het water: warm kraanwater kan zo heet worden dat je kind zich brandt.","Op het opstapje kan je kind ineens overal bij: haal messen, glas, de waterkoker en schoonmaakmiddelen weg. Kook je ondertussen, gebruik dan de achterste pitten met de pannenstelen naar achteren.","Laat een jong kind nooit alleen bij een gootsteen of bak met water, en blijf binnen handbereik zolang een peuter op het opstapje staat.","Dweil gemorst water op de vloer direct op: een natte keukenvloer is glad, zeker met zeep erin."],"say":["Sop, sop! Schoon!","Waar zit nog een vies plekje?","Hoe voelt het schuim: zacht of glibberig?","Wat komt eerst: wassen, spoelen of afdrogen?","Wat werk je goed door: de hele theedoek staat al vol!"],"words":["sop","schuim","wassen","spoelen","afdrogen","nat","droog","glibberig"],"learn":["fijne-motoriek","zintuigen","concentratie","taal"],"tips":["Rol de mouwen goed op en trek een oud shirt of schort aan: natte mouwen zijn de grootste spelbreker.","Leg een handdoek op de vloer voor het opstapje: die vangt de meeste spetters op en voorkomt uitglijden.","Bewaar een vaste ‘afwasstapel’ van onbreekbaar servies: dan kan je kind meteen aan de slag terwijl jij in de keuken bezig bent."],"extenders":["Breng een nieuwe stapel ‘vieze’ afwas: het servies van de poppenkeuken, de bakjes uit de speelgoedkist of de badspeeltjes.","Geef een garde en laat je kind het sop opkloppen tot een schuimberg: hoe hoog kan de schuimtaart worden?","Doe er een vergiet, een trechter en een paar bekers bij: lukt het om een beker te vullen via de trechter?","Speel restaurant: jij bent de ober die steeds een nieuw dienblad met ‘vieze’ borden komt brengen en vraagt hoelang de afwas nog duurt.","Geef een sorteeropdracht: eerst alle lepels, dan alle bekers, en tel hoeveel bordjes er al staan uit te lekken."],"variations":["Groente schrobben: laat je kind aardappels en wortels schoonborstelen voor het avondeten.","Na de knuffelpicknick: laat je kind het theeservies van de knuffels afwassen en weer klaarzetten voor morgen.","Schoonmaakdag: was in een sopje alle duplo of de plastic bakjes uit de speelgoedkist."],"themes":[],"canStay":false,"pinQuery":"peuter helpt afwassen aanrecht"},
  {"id":"hut-bouwen","title":"Een hut bouwen in de woonkamer","emoji":"⛺","category":"bouwen","summary":"Dekens over de stoelen, kussens op de vloer en een zaklamp mee naar binnen: in je eigen hut is voorlezen extra gezellig.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[20,40],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"dekens","note":"een paar dekens of lakens, plus kussens voor op de vloer"},{"id":"stoelen","note":"2-4 stoelen, of de bank en twee stoelen"},{"id":"wasknijpers","note":"om de dekens vast te zetten"},{"id":"zaklamp","note":"of het lampje van je telefoon"}],"optional":[{"id":"knuffels","note":"als gasten"},{"id":"handdoek","note":"een theedoek als gordijn voor de deur"},{"id":"papier","note":"voor een naambordje"},{"id":"stiften"}],"steps":["Zet 2-4 stoelen in een vierkant met de rugleuningen naar buiten, of zet twee stoelen tegenover de bank.","Gooi samen een groot laken of een deken over de leuningen en zet hem vast met wasknijpers.","Laat één kant open als deur, of hang er een theedoek voor als gordijn.","Leg kussens en een dekentje op de vloer: zo wordt het een zacht nest.","Neem een zaklamp, boekjes en knuffels mee naar binnen en lees samen een verhaal bij zaklamplicht.","Laat de hut als het kan een dag staan. Opruimen? Roep ‘de storm komt!’, trek samen de dekens eraf en vouw ze op."],"ageTips":{"young":"Een tweejarige vindt een kleine, lage hut het fijnst: een deken over één stoel of over de tafel is genoeg. Speel kiekeboe met de deur.","old":"Laat je kleuter de hut zelf ontwerpen: waar komt de deur, waar het raam? Maak een naambordje en verzin samen een wachtwoord om binnen te mogen."},"safety":["Zet de stoelen stevig neer en laat je kind er niet op klimmen of aan hangen: een omvallende stoel is zwaar.","Gebruik in de hut alleen een zaklamp, nooit echte kaarsjes of een lamp die heet wordt.","Leg geen zware boeken op het dak om de deken op zijn plek te houden: die vallen zo op kleine hoofdjes."],"say":["Klop klop! Wie woont er in deze hut?","Hoe zorgen we dat de deken niet van het dak glijdt?","Binnen! Gezellig!","Wat heb je goed meegedacht over waar de deur moet.","Hoe klinkt het hier binnen? Is het stiller dan buiten de hut?"],"words":["hut","binnen","buiten","onder","donker","licht","deur","gezellig"],"learn":["grove-motoriek","creativiteit","samen","taal"],"tips":["Een hoeslaken over de tafel is in één minuut een hut die niet afglijdt.","Maak de hut vlak voor het slapengaan voor een voorleesavond, of eet er een picknick in: dat maakt het extra bijzonder."],"extenders":["Bouw er een tunnel of een tweede kamer aan met een extra deken over twee stoelen.","Doe het grote licht uit en maak met de zaklamp schaduwdieren met je handen op het dak van de hut.","Klop aan als buurvrouw, postbode of verdwaalde beer en laat je kind beslissen wie er binnen mag."],"variations":["Winter: bouw een iglo van witte lakens en lees een boekje over sneeuw en ijsberen.","Kampeerhut: leg rood papier over een zaklamp als kampvuur en zing kampliedjes.","Dierenhol: de hut is een vossenhol of berengrot, en je kind is het dier dat er woont.","Sterrenhut: prik gaatjes in een stuk karton en schijn er met de zaklamp doorheen: sterren op het dak!"],"themes":["winter"],"canStay":true,"stayTips":"Laat de hut gerust een paar dagen staan en kijk ’s avonds even of de stoelen stevig staan en de wasknijpers goed vastzitten. Heb je de stoelen of de bank nodig, haal dan alleen de dekens eraf en leg ze opgevouwen klaar: morgen staat de hut in twee minuten weer.","pinQuery":"hut bouwen woonkamer dekens"},
  {"id":"dozenauto","title":"Rijden in een dozenauto","emoji":"🚗","category":"bouwen","summary":"Maak van een grote doos een auto met bordjeswielen, een stuur en koplampen, en ga samen op reis door de kamer.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":15,"duration":[20,40],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"dozen","note":"een doos waar je kind in kan zitten, bijv. een verhuisdoos"},{"id":"papieren-bordjes","note":"vier als wielen, één als stuur"},{"id":"plakkaatverf","note":"of dikke stiften als het minder vies mag"},{"id":"penselen","note":"liefst dikke"},{"id":"ducttape","note":"of stevig plakband"},{"id":"mes","note":"of een hobbymes, om de kleppen weg te snijden (dat doe jij)"}],"optional":[{"id":"bakjes","note":"twee yoghurtbekers als koplampen"},{"id":"aluminiumfolie","note":"voor glimmende koplampen of een nummerbord"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Snijd de kleppen aan de bovenkant weg (dat doe jij) en plak ruwe randen af met ducttape.","Leg een oud laken neer en laat je kind de auto verven in de eigen lievelingskleur.","Laat de verf ±1 uur drogen. Kleur intussen de bordjes als wielen: zwart met een grijs midden.","Plak vier bordjes als wielen op de zijkanten en één als stuur aan de binnenkant van de voorkant.","Maak koplampen van yoghurtbekers of folie en teken een nummerbord met de naam van je kind.","Stap in en ga op reis: waar rijden we heen? Jij duwt de auto langzaam over de vloer."],"ageTips":{"young":"Voor een tweejarige: teken met dikke stiften in plaats van verf, dan kan je peuter meteen instappen. Zeg samen tuut-tuut en vroem.","old":"Laat je kleuter een route bedenken met wegen van schilderstape, een tankstation en een garage, en verkeersborden tekenen: stop, rechtsaf, parkeren."},"safety":["Snijd de doos als je kind niet naast je staat, snijd van je af en berg het mes meteen op.","Duw de auto alleen langzaam over een vlakke vloer en ver van de trap: een doos kantelt makkelijk.","Plakkaatverf kan vlekken op kleding en vloer: kies afwasbare kinderverf, trek een oud shirt aan en leg een knoeimat neer."],"say":["Tuut-tuut! Waar rijden we heen?","Je hebt de hele zijkant al geverfd. Je gaat maar door!","Welke kleur krijgt jouw auto?","Rood licht… stoppen! Groen licht… rijden!","Hoe klinkt jouw motor: zacht of heel hard?"],"words":["auto","wiel","stuur","rijden","stoppen","toeteren","snel","langzaam"],"learn":["creativiteit","grove-motoriek","taal","fijne-motoriek"],"tips":["Vraag in een witgoedwinkel of fietsenwinkel naar een grote lege doos: vaak krijg je er gratis een mee.","Verf een dag van tevoren: dan is de auto droog als je kind wil gaan rijden."],"extenders":["Teken samen een dashboard aan de binnenkant, met een snelheidsmeter, een knop voor de lichten en een knop voor de radio.","Maak een wasstraat van twee stoelen met theedoeken over de leuning en rijd er samen tussendoor: poetsen maar!","Speel taxi: zet knuffels als wachtende klanten door de kamer en laat je kind ze één voor één ophalen en ergens anders afzetten."],"variations":["Brandweerauto: verf hem rood, met een ladder van ijsstokjes en een slang van een oude panty of touw.","Bus of trein: zet een paar dozen achter elkaar en laat knuffels instappen met een kaartje.","Loopauto: knip de bodem eruit en maak brede schouderbanden van stof; je kind loopt met de auto om zich heen (over de schouders, nooit om de nek).","Drive-in: rijd met de dozenauto naar het loket bij de bank en bestel een boterham of een boekje."],"themes":[],"canStay":true,"stayTips":"Parkeer de droge auto op een vaste plek in de kamer, zodat je kind er elke dag weer in kan stappen. Plak losse wielen en scheurtjes meteen vast met ducttape.","pinQuery":"kartonnen doos auto maken"},
  {"id":"ballenbaan","title":"Ballenbaan van kokers op de muur","emoji":"🏓","category":"bouwen","summary":"Plak kokers schuin onder elkaar op een deur of muur en kijk hoe pingpongballetjes van boven naar beneden zigzaggen.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,30],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":2,"energy":2,"places":["muur"],"materials":[{"id":"wc-rollen","note":"6-10 wc-rolletjes en keukenrolkokers"},{"id":"schilderstape","note":"laat weinig sporen achter op muur of deur"},{"id":"pingpongballen","note":"2-5 stuks"}],"optional":[{"id":"wasmand","note":"of een bak, om de balletjes onderaan op te vangen"},{"id":"stiften","note":"om de kokers te versieren"},{"id":"kinderschaar","note":"om kokers in de lengte open te knippen tot gootjes"}],"steps":["Verzamel 6-10 kokers en knip er een paar in de lengte doormidden: zo heb je ook open gootjes.","Plak de eerste koker schuin op de deur of muur, met het hoogste punt net binnen bereik van je kind.","Plak de volgende koker eronder, schuin de andere kant op, zodat het balletje uit de eerste erin valt.","Bouw zo verder tot vlak boven de vloer en zet daar een mand of bak om de balletjes op te vangen.","Test samen met één balletje. Valt het ernaast? Schuif de koker een stukje bij.","Laat je kind de balletjes er bovenin stoppen en tel hoeveel er in de mand belanden.","Trek de tape bij het opruimen langzaam en schuin los, dan blijft de verf op de muur."],"ageTips":{"young":"Bij een tweejarige plak jij de baan en speel je samen: geef één balletje tegelijk en tel na afloop of ze er allemaal weer zijn. Een korte baan van drie kokers is genoeg.","old":"Laat je kleuter de baan zelf ontwerpen en verbouwen: hoe wordt hij langer, sneller of krijgt hij een bocht? Doe een race met twee balletjes tegelijk."},"safety":["Pingpongballetjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: speel met je peuter samen, tel ze na afloop en berg ze op.","Laat je kind niet op een stoel klimmen om bij de bovenste koker te komen: plak de baan op kindhoogte, of geef jij de balletjes aan."],"say":["Daar gaat hij… waar komt hij eruit?","Rol, rol, plof!","Wat gebeurt er als we deze koker steiler zetten?","Je hebt de koker net zo lang verschoven tot het lukte. Knap uitgezocht!","Hoeveel balletjes liggen er al in de mand?"],"words":["boven","onder","schuin","rollen","snel","langzaam","erin","eruit"],"learn":["ontdekken","concentratie","fijne-motoriek","rekenen"],"tips":["Schilderstape laat minder sporen achter dan plakband, maar test het eerst op een onopvallend plekje van je muur.","Geen pingpongballetjes? Stevige propjes aluminiumfolie rollen ook, maar zijn net zo klein: alleen samen spelen of vanaf 3 jaar."],"extenders":["Test wat er nog meer door de baan rolt: een propje papier, een klein autootje of een stukje spons?","Zet onderaan een torentje van plastic bekers: lukt het om dat om te gooien met een balletje uit de baan?","Plak een extra koker aan als zijspoor en laat je kind de baan zo verbouwen dat het balletje een nieuwe route neemt."],"variations":["Wedstrijd: bouw twee banen naast elkaar en laat twee balletjes tegelijk racen. Welke is eerst beneden?","Kleurenbaan: geef elke koker een kleur en noem de kleuren hardop terwijl het balletje erdoorheen rolt.","Autobaan voor kleuters: knip de kokers open tot gootjes en laat er kleine autootjes overheen rijden."],"themes":[],"canStay":true,"stayTips":"Laat de baan een paar dagen op de deur of muur zitten en berg de balletjes na elk spel op in een potje, buiten bereik van jongere kinderen. Druk losgeraakte tape even aan en trek alles bij het weghalen langzaam en schuin los.","pinQuery":"ballenbaan wc-rolletjes muur"},
  {"id":"flessen-bowlen","title":"Flessen bowlen","emoji":"🎳","category":"bouwen","summary":"Verzwaar lege flesjes, zet ze in een driehoek en rol ze om met een zachte bal: wie gooit ze allemaal om?","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":3,"energy":2,"places":["vloer"],"materials":[{"id":"plastic-flesjes","note":"6-10 lege flesjes van 0,5 liter met dop"},{"id":"rijst","note":"of water, een laagje van ±3 cm per flesje"},{"id":"ducttape","note":"om de doppen rondom dicht te plakken"},{"id":"bal","note":"een zachte bal"}],"optional":[{"id":"trechter","note":"om de rijst erin te gieten"},{"id":"stickers","note":"om de flesjes te versieren"},{"id":"schilderstape","note":"voor een gooilijn op de vloer en strepen op de flesjes"}],"steps":["Doe in elk flesje een laagje rijst of water van ±3 cm (dat doe jij): dan vallen ze niet vanzelf om, maar wel als je raak rolt.","Draai de doppen stevig dicht en plak ze rondom af met ducttape.","Laat je kind de flesjes versieren met stickers of strepen schilderstape.","Zet de flesjes in een driehoek op een gladde vloer, bijvoorbeeld in de gang, en plak een gooilijn van tape.","Rol de bal om de beurt naar de flesjes. Hoeveel zijn er omgevallen? Tel ze samen.","Laat je kind de flesjes weer rechtop zetten en probeer het opnieuw, of ga een stap verder naar achteren staan."],"ageTips":{"young":"Je dreumes rolt de bal vanaf een halve meter, of duwt de flesjes gewoon met de hand om; dat is net zo leuk. Begin met drie flesjes en roep samen: boem, om!","old":"Zet nummers op de flesjes en tel de punten op, of laat je kleuter de flesjes zelf in een driehoek van 1, 2, 3 zetten. Wie gooit ze allemaal in één keer om?"},"safety":["Doppen en rijst zijn te klein voor kinderen onder de 3 (alles wat door een wc-rolletje past): draai de doppen stevig dicht, plak ze rondom af en controleer ze na het spelen.","Gebruik alleen plastic flesjes, nooit glas, en een zachte bal: een harde bal stuitert zo tegen een kast of een broertje."],"say":["Boem! Om!","Hoeveel flesjes zijn er omgevallen?","Wat gebeurt er als je de bal heel zacht rolt?","Je bleef het proberen tot ze allemaal om lagen.","Zet jij ze weer rechtop?"],"words":["rollen","om","rechtop","raak","mis","hard","zacht","tellen"],"learn":["grove-motoriek","rekenen","concentratie","samen"],"tips":["Met water erin zie je het klotsen, met rijst rammelt het als ze omvallen: maak er een paar van elk.","Bewaar de flesjes in een tas: dan heb je een kant-en-klaar spel voor een regenachtige dag."],"extenders":["Probeer een andere bal: een opgerolde sok, een grote lichte bal of een sinaasappel. Waarmee gooi je de meeste flesjes om?","Rol eens anders: tussen je benen door, met je andere hand of liggend op je buik.","Leg twee opgerolde handdoeken als randen langs de baan: blijft de bal er nu netjes tussen?"],"variations":["Kleurenbowlen: geef elk flesje een kleur en noem welke kleuren er omvallen.","Dierenbowlen: plak dierengezichtjes op de flesjes en maak het geluid van elk dier dat omvalt.","Winter: teken sneeuwpopgezichtjes op de flesjes en gooi met een ‘sneeuwbal’ van een opgerolde witte sok."],"themes":[],"canStay":false,"pinQuery":"bowlen met plastic flessen peuter"},
  {"id":"torens-bouwen","title":"Torens bouwen en omgooien","emoji":"🧱","category":"bouwen","summary":"Stapel bekers, doosjes en kokers zo hoog als je kunt en gooi alles met een flinke boem weer om: voor dreumesen het allerleukste deel.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[10,25],"supervision":2,"soloFrom":2,"cleanupMinutes":2,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"plastic-bekers","note":"of lege yoghurtbekers, zo veel mogelijk"},{"id":"verpakkingen","note":"lege doosjes van bijv. cornflakes, thee of rijst"},{"id":"wc-rollen"}],"optional":[{"id":"dozen","note":"grote dozen voor een toren die hoger is dan je kind"},{"id":"bal","note":"een zachte bal om de toren om te rollen"},{"id":"duplo","note":"of andere blokken om mee te combineren"},{"id":"wasmand","note":"om alles in op te ruimen"}],"steps":["Verzamel een berg bekers, lege doosjes en kokers en leg ze midden in de kamer, op een plek zonder breekbare dingen in de buurt.","Bouw samen een eerste toren: grote doosjes onderop, kleine bovenop.","Laat je kind de toren omgooien: met de hand, met een zachte bal of door ertegenaan te kruipen. Boem!","Bouw opnieuw en tel elke laag hardop: één, twee, drie…","Probeer iets nieuws: een toren van alleen bekers, een muur, of een brug van een koker op twee doosjes.","Ruim op door alles in een wasmand of doos te gooien: ook dat is een spel."],"ageTips":{"young":"Je dreumes bouwt nog niet hoog, maar gooit graag om. Bouw jij een toren van drie of vier bekers en laat je kind slopen; daarna stapelt het er misschien zelf twee op elkaar.","old":"Daag je kleuter uit: hoe hoog wordt de toren voordat hij valt? Bouw een toren zo hoog als je kind zelf, of een kasteel met een poort waar een auto door kan."},"safety":["Gebruik alleen lichte spullen die zacht vallen: geen glas, blikken of zware boeken in de toren.","Laat je kind niet op een stoel of de bank klimmen om hoger te bouwen; wil het hoger, dan zet jij de bovenste beker erop."],"say":["Boem! Alles om!","Nog eentje erop?","Wat moet er onderop: een grote of een kleine doos?","Wat bouw je voorzichtig, hij wiebelt bijna niet.","Hoe hoog wordt jouw toren, denk je?"],"words":["hoog","laag","bovenop","onderop","wiebelen","vallen","om","groot"],"learn":["fijne-motoriek","ontdekken","rekenen","concentratie"],"tips":["Spaar een week lang doosjes en bekers in een grote doos of wasmand: dat is meteen je bouwdoos én je opruimbak.","Plak doosjes die steeds openvallen even dicht met plakband, dan stapelen ze beter."],"extenders":["Bouw om de beurt een laag, eerst jij en dan je kind: wie zet het laatste stuk erop voordat de toren valt?","Zet een knuffel bovenop de toren en bouw verder: hoe hoog kan de knuffel klimmen voordat alles omvalt?","Bouw eens met één hand of met je ogen dicht: hoe hoog kom je nu?"],"variations":["Kleurentoren: plak gekleurd papier om de bekers en bouw een regenboogtoren.","Bekerpiramide: zet bekers ondersteboven in een driehoek van 3, 2, 1 en rol hem om met een bal.","Stad: bouw een paar torens naast elkaar als flats en laat er autootjes tussendoor rijden.","Kerst: stapel groene bekers tot een kerstboom en zet er een ster van papier bovenop."],"themes":[],"canStay":false,"pinQuery":"torens bouwen met bekers peuter"},
  {"id":"parkeergarage","title":"Parkeergarage van wc-rolletjes","emoji":"🅿️","category":"bouwen","summary":"Plak wc-rolletjes in een schoenendoos, zet er nummers of kleuren bij en laat je kind elk autootje in het juiste vak parkeren.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":15,"duration":[15,30],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"wc-rollen","note":"6-12 wc-rolletjes"},{"id":"dozen","note":"een schoenendoos zonder deksel"},{"id":"plakband","note":"of ducttape"},{"id":"stiften"},{"id":"speelgoedautos","note":"die in een wc-rolletje passen"}],"optional":[{"id":"schilderstape","note":"voor nummers op de autodaken en een weg op de vloer"},{"id":"knutsellijm","note":"maakt de garage steviger (±1 uur laten drogen)"},{"id":"gekleurd-papier","note":"om de rolletjes in kleuren te beplakken"}],"steps":["Zet de schoenendoos op zijn lange kant, met de open kant naar je kind toe.","Leg een rij wc-rolletjes liggend onderin de doos en plak ze aan elkaar en aan de doos vast (dat doe jij).","Leg er een tweede en een derde rij bovenop, tot de doos vol is. Elk rolletje is een parkeerplek.","Zet met stift een nummer of kleurstip bij elk rolletje, en hetzelfde op een stukje tape op het dak van elk autootje.","Laat je kind de autootjes parkeren: welke auto hoort in welk vak?","Rijd ze er weer uit, tel de lege plekken en begin opnieuw."],"ageTips":{"young":"Werk voor een tweejarige met kleuren in plaats van cijfers: de rode auto in het rode vak. Begin met drie vakken en zeg wat je peuter doet: auto erin, auto eruit.","old":"Laat je kleuter de cijfers zelf schrijven, de auto’s op volgorde parkeren of sommetjes doen: er staan vijf auto’s in de garage en er rijden er twee weg. Hoeveel blijven er over?"},"safety":["Kleine autootjes passen door een wc-rolletje en zijn dus te klein voor kinderen onder de 3: speel met je tweejarige samen en berg de autootjes daarna op.","Zet de rolletjes vast met plakband en niet met nietjes: kleine vingers gaan graag op onderzoek in de gaten."],"say":["Waar moet de rode auto parkeren?","Auto erin! Auto eruit!","Welk nummer staat er op deze auto? Kun je hetzelfde nummer vinden?","Je zoekt heel goed tot je het juiste vak hebt gevonden.","Hoeveel plekken zijn er nog vrij?"],"words":["parkeren","erin","eruit","vol","leeg","hetzelfde","nummer","vrij"],"learn":["rekenen","fijne-motoriek","concentratie","taal"],"tips":["Plakband is handig als je meteen wilt spelen; met knutsellijm wordt de garage steviger als je hem wilt bewaren.","Spaar een paar weken wc-rolletjes in een tas, dan heb je er genoeg voor een grote garage."],"extenders":["Speel parkeerwachter: jij roept een kleur of nummer en je kind rijdt die auto zo snel mogelijk de garage uit.","Maak een slagboom van een ijsstokje met een rolletje plakband: de slagboom gaat pas open als de auto betaalt.","Laat je kind de ogen dichtdoen en rijd stiekem één auto de garage uit: welke plek is leeg, en welke auto ontbreekt er?"],"variations":["Parkeertoren: plak de rolletjes rechtop in de doos en laat de autootjes er van bovenaf in zakken.","Kleurengarage: beplak de rolletjes met gekleurd papier en parkeer op kleur.","Stal of kazerne: maak vakken voor speelgoeddieren of brandweerauto’s in plaats van gewone auto’s.","Stad: plak met schilderstape een weg van de garage door de kamer naar de bank."],"themes":[],"canStay":true,"stayTips":"Geef de garage een vaste plek, bijvoorbeeld op een lage plank of onder de salontafel, met de autootjes erin geparkeerd. Lopen er kleinere broertjes of zusjes rond, zet de kleine autootjes dan na het spelen hoog weg.","pinQuery":"parkeergarage wc-rolletjes schoenendoos"},
  {"id":"monster-voeren","title":"Voer het hongerige monster","emoji":"👾","category":"bouwen","summary":"Maak van een doos een monster met een grote mond en laat je kind het voeren met sokken, ballen en deksels: hap, nog een!","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":15,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"dozen","note":"een stevige doos met deksel, bijv. een schoenendoos of groter"},{"id":"mes","note":"of een schaar, om de mond uit te snijden (dat doe jij)"},{"id":"stiften","note":"dikke, voor het monstergezicht"},{"id":"sokken","note":"opgerold tot balletjes, als monstervoer"},{"id":"bal","note":"een paar zachte ballen"}],"optional":[{"id":"gekleurd-papier","note":"voor ogen, tanden en haar"},{"id":"lijmstift"},{"id":"schilderstape","note":"om de randen van de mond af te plakken"},{"id":"doppen","note":"alleen grote deksels van potten, die niet door een wc-rolletje passen"},{"id":"knuffels","note":"kleine knuffels als monstervoer"}],"steps":["Teken een grote mond op de voorkant van de doos, minstens 15 cm breed.","Snijd de mond uit (dat doe jij, terwijl je kind niet naast je staat) en plak de randen af met schilderstape.","Geef het monster ogen, tanden en haar: met dikke stift of plakken met gekleurd papier. Je kind mag meehelpen.","Leg het monstervoer klaar: opgerolde sokken, zachte ballen, grote deksels en kleine knuffels.","Laat je kind het monster voeren: hap! Maak smakgeluiden en laat het monster om meer vragen.","Doe het deksel open en haal alles er samen weer uit. Dan kan het monster opnieuw eten."],"ageTips":{"young":"Je dreumes stopt dingen erin en haalt ze er net zo graag weer uit. Maak de mond extra groot, laat het deksel open en zeg bij elke hap: hap! Weg! Waar is de sok?","old":"Laat je driejarige het monster voeren op bestelling: het monster wil twee ballen, of alleen gele dingen. Of gooi van een afstand en zet bij elke goede worp een stap naar achteren."},"safety":["Voer het monster alleen dingen die niet door een wc-rolletje passen: wat kleiner is, is te klein voor kinderen onder de 3. Dus grote deksels en geen flessendopjes.","Snijd de mond als je kind niet in de buurt is, snijd van je af en plak de snijranden af: dan zijn ze minder scherp."],"say":["Hap! Nog een!","Het monster heeft honger. Wat wil het eten?","Waar is de sok gebleven? Zit hij in zijn buik?","Je mikt hem er zo precies in, recht in de mond!","Mmm, lekker. Wat zou het monster nu willen?"],"words":["hap","erin","eruit","mond","honger","vol","leeg","nog een"],"learn":["grove-motoriek","fijne-motoriek","taal","ontdekken"],"tips":["Gebruik het monster als opruimspel: het monster eet alleen speelgoed dat van de vloer moet.","Laat het monster na afloop staan: dreumesen spelen dit spel graag dagen achter elkaar."],"extenders":["Verstop het monstervoer door de kamer en ga samen op zoek naar eten voor het hongerige monster.","Laat het monster na een flinke maaltijd niezen: kiep de doos om, alles rolt eruit en het voeren begint opnieuw."],"variations":["Kleurenmonster: plak een kleur rond de mond; het monster eet alleen dingen in die kleur.","Dierenmonster: maak er een kikker, een haai of een nijlpaard met een grote bek van.","Brievenbusmonster: een smalle mond waar je kind kaartjes of grote platte deksels in stopt.","Halloween: verf de doos oranje en maak er een hongerige pompoen van."],"themes":[],"canStay":true,"stayTips":"Laat het monster een paar dagen op een vaste plek staan met een mandje monstervoer ernaast: opgerolde sokken, zachte ballen en knuffels. Kijk na het spelen even of er niets kleins in de doos is beland.","pinQuery":"monster voeren doos peuter"},
  {"id":"robot-van-dozen","title":"Een robot van dozen","emoji":"🤖","category":"bouwen","summary":"Stapel dozen op elkaar, pak ze in met glimmende folie en geef je robot knoppen van doppen en antennes van pijpenragers.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[20,40],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"dozen","note":"een grote en een kleinere doos, bijv. een schoenendoos als hoofd"},{"id":"aluminiumfolie"},{"id":"ducttape","note":"of stevig plakband"},{"id":"doppen","note":"een handvol, als knoppen"},{"id":"pijpenragers","note":"2-4 stuks, als antennes"},{"id":"stiften"}],"optional":[{"id":"wc-rollen","note":"als armen en benen"},{"id":"bakjes","note":"als ogen of oren"},{"id":"plakband","note":"rolletjes plakband om de doppen vast te zetten"},{"id":"gekleurd-papier"}],"steps":["Plak de kleppen van de dozen dicht, zet de kleine doos als hoofd op de grote en plak ze aan elkaar met ducttape.","Laat je kind de robot inpakken met aluminiumfolie: scheuren, wikkelen en vastplakken met tape.","Teken samen een gezicht, en op de buik een schermpje met knoppen en metertjes.","Plak doppen op de buik als knoppen, met een rolletje plakband aan de achterkant.","Prik twee gaatjes in het hoofd (dat doe jij), steek er pijpenragers in als antennes en vouw de puntjes om.","Plak kokers als armen aan de zijkant en laat de robot praten: druk op een knop, wat zegt hij dan?"],"ageTips":{"young":"Een driejarige vindt folie scheuren en wikkelen het leukst. Houd het bij één doos en laat je peuter de knoppen plakken waar het wil: elk knopje doet iets anders.","old":"Laat je kleuter eerst een robot tekenen als bouwtekening en die dan nabouwen. Wat kan jouw robot? Bedenk samen knoppen voor opruimen, dansen en tandenpoetsen."},"safety":["Pijpenragers hebben scherpe draadpuntjes: vouw de uiteinden een stukje om.","Doppen zijn klein: houd ze uit de buurt van jongere broertjes of zusjes, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Gaatjes prikken doe jij, bijvoorbeeld met een potlood: houd je andere hand niet achter het karton."],"say":["Biep biep! Ik ben een robot!","Wat gebeurt er als je op deze knop drukt?","Je hebt de hele doos ingepakt, er is bijna geen bruin meer te zien.","Hoe loopt een robot? Laat eens zien!","Hoe voelt de folie: glad, koud of kreukelig?"],"words":["robot","knop","antenne","glimmen","kreukelig","biep","aan","uit"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Kreukels en scheurtjes in de folie maken een robot juist stoerder: perfect hoeft niet.","Geen doppen? Teken knoppen met stift of plak rondjes gekleurd papier: dat is ook veiliger als er kleine kinderen rondlopen."],"extenders":["Maak een afstandsbediening van een klein doosje met getekende knoppen: vooruit, draaien en zwaaien.","Speel robotje: je kind drukt op een knop en jij voert de opdracht uit met een robotstem. Ruil daarna van rol.","Bouw er een rugzak aan van een klein doosje en stop er ‘gereedschap’ in van kokers en ijsstokjes."],"variations":["Robotpak: knip in een grote doos gaten voor hoofd en armen (dat doe jij), zodat je kind zelf de robot is.","Ruimteschip: een lange doos met kokers als raketmotoren en een bedieningspaneel van doppen.","Robotdans: zet muziek aan en dans met stijve armen en kleine stapjes; stop zodra de muziek stopt."],"themes":[],"canStay":true,"stayTips":"Zet de robot op een vaste plek, zodat je kind er de volgende dagen nieuwe knoppen, armen of een rugzak aan kan bouwen. Plak losse doppen meteen weer vast en berg ze op als er kleine broertjes of zusjes rondkruipen.","pinQuery":"robot van dozen knutselen"},
  {"id":"eierdoos-beestjes","title":"Eierdoos-rupsen en kuikentjes","emoji":"🐛","category":"bouwen","summary":"Knip een eierdoos in stroken en kuiltjes, verf ze vrolijk en maak er rupsen met voelsprieten en kuikentjes met een snaveltje van.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,30],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"eierdoos","note":"van karton, schoon en zonder eiresten"},{"id":"plakkaatverf","note":"groen, geel en een paar vrolijke kleuren"},{"id":"penselen","note":"liefst dikke"},{"id":"pijpenragers","note":"voor voelsprieten"},{"id":"stiften","note":"voor ogen en een mondje"},{"id":"schaar","note":"om de eierdoos te knippen (dat doe jij)"}],"optional":[{"id":"gekleurd-papier","note":"oranje, voor snaveltjes en pootjes"},{"id":"veren","note":"als vleugeltjes voor de kuikens"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"knutsellijm"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Knip het deksel van de eierdoos en knip de bodem in de lengte doormidden: zo heb je twee rupsen. Een paar losse kuiltjes worden kuikens.","Leg een knoeimat neer en laat je kind de rupsen groen of in alle kleuren verven, en de kuikens geel.","Laat de verf ±30 minuten drogen en was intussen samen de kwasten uit.","Prik twee gaatjes in het eerste kuiltje (dat doe jij), steek er een stukje pijpenrager door als voelsprieten en vouw de puntjes om.","Teken ogen en een mondje met stift, of plak wiebeloogjes (vanaf 3 jaar).","Geef de kuikens een snaveltje en pootjes van oranje papier, en eventueel een veertje als vleugel."],"ageTips":{"young":"Voor een tweejarige knip jij alles vooraf en houd je het bij verven; de ogen teken jij daarna. Benoem de kleuren en tel samen de bultjes van de rups.","old":"Laat je kleuter de rups in een patroon verven (groen, geel, groen…), zelf snaveltjes knippen en een verhaal bedenken: wat eet deze rups voordat hij een vlinder wordt?"},"safety":["Wiebeloogjes zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Teken bij een tweejarige de ogen met stift.","Pijpenragers hebben scherpe draadpuntjes: knip ze op lengte en vouw de uiteinden om (dat doe jij).","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Hoeveel bultjes heeft de rups? Tel je mee?","Geel! Nog een kuiken!","Wat eet een rups, denk je?","Je hebt elk bultje een andere kleur gegeven, heel precies.","Hoe voelt de eierdoos: ruw of glad?"],"words":["rups","kuiken","voelspriet","snavel","bultje","geel","groen","kruipen"],"learn":["fijne-motoriek","creativiteit","rekenen"],"tips":["Verf op een dienblad: eierdozen zijn klein, dus de rommel blijft op één plek.","Spaar in het voorjaar een paar eierdozen: met Pasen heb je dan meteen een nestje voor de kuikens."],"extenders":["Knip een groot blad uit groen papier en laat je kind er met een perforator gaatjes in ponsen: hier heeft de rups gegeten!","Maak er een familie bij: een lange rups, een middelgrote rups en een babyrupsje van één kuiltje.","Laat de droge beestjes een wandeling maken over tafel en verzin samen waar ze naartoe gaan en wie ze onderweg tegenkomen."],"variations":["Pasen: zet de kuikentjes in een nestje van een halve eierdoos met slierten geknipt geel papier.","Lieveheersbeestjes: verf losse kuiltjes rood en stip er zwarte stippen op met een wattenstaafje.","Rupsverhaal: lees een prentenboek over een rups die steeds meer eet en laat je eierdoosrups meedoen.","Lente: maak een bloemenveld van eierdooskuiltjes in roze, geel en paars op een stuk karton."],"themes":["lente","pasen"],"canStay":false,"pinQuery":"eierdoos rups knutselen"},
  {"id":"dierentuin-bouwen","title":"Een eigen dierentuin bouwen","emoji":"🐘","category":"bouwen","summary":"Bouw hokken van blokken en dozen, zet de speelgoeddieren erin en word samen dierenverzorger: voeren, poetsen en bezoekers rondleiden.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"klein-speelgoed","note":"speelgoeddieren, zoveel als je hebt"},{"id":"duplo","note":"of andere blokken, voor hekken en muurtjes"},{"id":"dozen","note":"een paar schoenendozen of kleine dozen als stal en nachthok"}],"optional":[{"id":"papier","note":"voor bordjes en toegangskaartjes"},{"id":"stiften"},{"id":"schilderstape","note":"voor paden en om de bordjes op te plakken"},{"id":"bakjes","note":"deksels en kuipjes als voerbak en drinkbak"},{"id":"handdoek","note":"een blauwe handdoek als vijver"},{"id":"knuffels","note":"als bezoekers of als heel grote dieren"}],"steps":["Zet alle speelgoeddieren bij elkaar en sorteer ze samen: wie hoort bij wie? De leeuwen bij elkaar, de vogels bij elkaar, de olifanten bij elkaar.","Bouw voor elke groep een hok: een muurtje van blokken, of een liggende doos met de open kant naar voren als stal. Je kind bedenkt wie waar woont.","Leg een blauwe handdoek neer als vijver en maak paden tussen de hokken van schilderstape of een rij blokken.","Teken samen bordjes: je kind tekent het dier, jij schrijft de naam erbij. Plak ze met een stukje tape bij de hokken.","Speel dierenverzorger: vul de voerbakjes, poets de olifant, breng een ziek dier naar de dierenarts en laat knuffels als bezoekers rondlopen.","Laat de dierentuin staan, of ruim op met een spel: het wordt nacht en alle dieren gaan slapen in het nachthok, de doos."],"ageTips":{"young":"Een tweejarige bouwt nog geen hekken die blijven staan: zet jij een paar muurtjes neer en laat je kind de dieren erin zetten, voeren en naar bed brengen. Hoe brult de leeuw?","old":"Laat je kleuter eerst een plattegrond tekenen: waar komen de ingang, de kassa en het restaurant? Maak toegangskaartjes, tel de bezoekers en bedenk samen wat elk dier eet."},"safety":["Kies voor een tweejarige dieren en ‘voer’ die niet door een wc-rolletje passen: alles wat kleiner is, is te klein voor kinderen onder de 3.","Haal nietjes uit de dozen en plak scherpe randen af voordat je kind ermee gaat bouwen."],"say":["Brul! Wie woont er in dit hok?","Past de giraf in dit hok, of is het dak te laag?","Wat eten olifanten, denk je?","Ik zie dat je de leeuwen een extra hoge muur hebt gegeven. Goed bedacht!","Hoeveel dieren wonen er nu in jouw dierentuin?"],"words":["dierentuin","hok","hek","voeren","verzorger","binnen","buiten","naast"],"learn":["creativiteit","taal","rekenen","fijne-motoriek"],"tips":["Weinig speelgoeddieren? Teken dieren op karton, knip ze uit (dat doe jij) en zet ze rechtop met een wasknijper als voetje. Knuffels zijn mooie grote dieren.","Bouw op een groot stuk karton of een speelkleed: dan schuif je de hele dierentuin in één keer aan de kant."],"extenders":["Laat er een nieuw dier aankomen in een doos: een baby-olifant! Welk hok is groot genoeg, of moet er een nieuw hok bij?","Roep dat er een dier is ontsnapt, verstop het ergens in de kamer en laat de verzorger het zoeken en terugbrengen.","Open de dierentuin voor bezoekers: zet knuffels in de rij bij de kassa, verkoop kaartjes en geef een rondleiding.","Laat het gaan regenen of donker worden: welke dieren willen een dak, en hoe bouw je dat?"],"variations":["Boerderij: bouw een stal, een kippenhok en een wei van een groene handdoek voor de boerderijdieren en de tractor.","Zeeaquarium: leg blauwe handdoeken neer als bassins voor vissen, zeehonden en pinguïns, en geef om drie uur een voedershow.","Dinopark: bouw extra hoge hekken voor de dino’s en een vulkaan van een omgekeerde kom onder een rode doek."],"themes":[],"canStay":true,"stayTips":"Bouw de dierentuin in een hoek buiten de looproute, het liefst op een groot stuk karton dat je opzij kunt schuiven: losse blokjes zijn een struikelpartij. ’s Ochtends worden de dieren wakker en kan de verzorger meteen weer voeren.","pinQuery":"dierentuin bouwen blokken peuter"},
  {"id":"dozentunnel","title":"Kruiptunnel van dozen","emoji":"📦","category":"bouwen","summary":"Plak grote dozen aan elkaar tot een tunnel, gooi er een deken over en speel kiekeboe: wie kruipt er aan het eind naar buiten?","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,30],"supervision":2,"soloFrom":2,"cleanupMinutes":5,"noise":2,"energy":3,"places":["vloer"],"materials":[{"id":"dozen","note":"3-4 grote dozen waar je kind doorheen past, bijv. verhuisdozen"},{"id":"ducttape","note":"of brede plakband, om de dozen aan elkaar te plakken"},{"id":"schaar","note":"om de tape op de bodem los te knippen (dat doe jij)"}],"optional":[{"id":"dekens","note":"een deken of laken over de tunnel"},{"id":"zaklamp","note":"met een batterijklepje dat goed vastzit"},{"id":"bal","note":"een paar zachte ballen om door te rollen"},{"id":"knuffels","note":"die aan het eind van de tunnel wachten"}],"steps":["Knip de tape op de bodem van 3-4 grote dozen los (dat doe jij) en haal eventuele nietjes eruit, zodat elke doos aan twee kanten open is.","Leg de dozen in een rij op de vloer, vouw de kleppen naar buiten en plak de dozen met ducttape stevig aan elkaar.","Gooi een deken over een deel van de tunnel: zo is er een licht stuk en een spannend donker stuk.","Kruip zelf als eerste door, of kijk aan het andere eind naar binnen: kiekeboe, waar ben je?","Rol een zachte bal door de tunnel naar je kind en laat die terugrollen, of zet aan het eind een knuffel die zit te wachten.","Leg een zaklamp in het donkere stuk en laat de tunnel een paar dagen staan als je er de ruimte voor hebt."],"ageTips":{"young":"Begin voor een dreumes met een korte tunnel van twee dozen zonder deken, zodat jullie elkaar zien. Lok aan het andere eind met je gezicht of een bal en vier elke keer dat je kind eruit komt: daar ben je!","old":"Een driejarige richt de tunnel graag in: laat je kind knuffels, een kussen en boekjes naar binnen brengen en er een hol of huisje van maken. Wie mag er op bezoek komen?"},"safety":["Houd beide uiteinden open, zodat je kind er altijd zelf uit kan en jij naar binnen kunt kijken.","Plak ruwe randen en losse kleppen af: kleine handjes en knieën gaan er steeds langs. Trek losgeraakte stukjes tape meteen weg, want een dreumes stopt ze in de mond.","Gebruik een stevige zaklamp waarvan het batterijklepje vastzit (met een schroefje of dichtgeplakt): knoopcelbatterijen zijn levensgevaarlijk bij inslikken.","Zet de tunnel niet vlak bij de trap of een deur die openzwaait, en leg geen zware dingen op de dozen."],"say":["Kiekeboe!","Waar ben je? Ik zie je handjes al!","Daar komt de bal. Rol maar terug!","Hoe is het in de tunnel: licht of donker?","Je bent helemaal door het donkere stuk gekropen, ook al was het spannend!"],"words":["tunnel","kruipen","door","binnen","buiten","donker","licht","kiekeboe"],"learn":["grove-motoriek","ontdekken","taal","samen"],"tips":["Bewaar grote dozen plat achter de kast, of vraag ze bij een witgoed- of meubelwinkel: dan staat de tunnel er in vijf minuten.","Zet de tunnel tegen de bank of de muur: dan schuift die minder weg als je kind er wild doorheen kruipt.","Geen grote dozen? Een rij stoelen met een deken eroverheen is ook een tunnel."],"extenders":["Gooi een deken over de hele tunnel en leg er een zaklamp in: nu is het een donkere grot.","Leg een voelpad in de tunnel: een kussen, een handdoek, een stuk kreukelpapier. Hoe voelt elke doos?","Verstop knuffels in de tunnel en laat je kind ze één voor één naar buiten brengen.","Rol ballen, autootjes of knuffels door de tunnel naar elkaar toe: wat komt er aan de andere kant uit?","Bouw de tunnel om: zet er een doos dwars tegenaan als zijgang, of maak er een bocht in."],"variations":["Treintunnel: knip ramen in de zijkanten (dat doe jij), zet knuffels als passagiers erin en rijd tsjoek tsjoek de tunnel door.","Dierenhol: je kind is een konijn dat in het hol woont, jij bent de vos die buiten snuffelt. Snel naar binnen!","Sterrentunnel: prik gaatjes in het dak (dat doe jij): binnen in de donkere tunnel lijken ze net sterren.","Winter: plak witte vellen op de dozen en maak er een iglogang van voor de ijsbeerknuffels."],"themes":[],"canStay":true,"stayTips":"Schuif de tunnel ’s avonds tegen de muur of de bank, zodat niemand erover struikelt. Plak losgeraakte naden even bij voordat je kind weer gaat kruipen, en haal de deken eraf als je er niet bij bent.","pinQuery":"kruiptunnel van dozen peuter"},
  {"id":"tape-wegen","title":"Een stad van tape op de vloer","emoji":"🚦","category":"bouwen","summary":"Plak wegen, kruispunten en parkeervakken van schilderstape op de vloer, zet huizen van doosjes en blokken langs de weg en rijd maar raak.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"schilderstape","note":"1-2 rollen, liefst breed: een strook is meteen een weg"},{"id":"speelgoedautos"}],"optional":[{"id":"verpakkingen","note":"lege doosjes als huizen, flats en winkels"},{"id":"duplo","note":"of andere blokken, voor gebouwen en bruggen"},{"id":"stiften","note":"om ramen en deuren op de doosjes te tekenen"},{"id":"papier","note":"voor verkeersborden en een stoplicht"},{"id":"klein-speelgoed","note":"poppetjes en dieren die oversteken"}],"steps":["Test de tape eerst op een onopvallend plekje: plak een stukje, trek het weer los en kijk of de vloer schoon blijft.","Plak samen een eerste lange weg door de kamer, met een paar bochten. Je kind mag de tape vastdrukken of zelf stukken afscheuren.","Maak er een kruispunt, een rotonde en een doodlopend straatje bij. Plak met korte stukjes een zebrapad en een paar parkeervakken.","Zet huizen langs de weg van lege doosjes en blokken: jullie eigen huis, de bakker, de garage. Teken er ramen en deuren op.","Speel: rijd naar de bakker, parkeer in een vak, stop bij het zebrapad en laat poppetjes oversteken.","Laat de stad een paar dagen liggen en bouw elke dag iets bij. Trek de tape daarna langzaam en schuin los."],"ageTips":{"young":"Een tweejarige plakt nog geen stad, maar rijdt graag: plak jij een brede weg van twee stroken naast elkaar, met een garage van een doos aan het eind. Stukjes tape lostrekken en weer vastdrukken is al een spel.","old":"Laat je kleuter de route bedenken: van ons huis naar school, langs de winkel en het park. Maak verkeersborden van papier, zet nummers bij de parkeervakken en speel taxi met opdrachten."},"safety":["Kleine autootjes passen vaak door een wc-rolletje en zijn dan te klein voor kinderen onder de 3: geef een tweejarige grotere auto’s en kijk ze na op losse wieltjes.","Trek losgeraakte stukjes tape meteen weg: een peuter stopt ze graag in de mond.","Plak geen wegen over een drempel of vlak bij de trap, en houd de looproute vrij: losse autootjes op de vloer zijn een glijpartij."],"say":["Toet toet! Mag ik erlangs?","Stop, een zebrapad! Wie wil er oversteken?","Hoe kom je van de bakker naar de garage? Welke weg neem je?","Je hebt al drie kruispunten gemaakt. Wat een grote stad wordt het!","Gaat de auto naar links of naar rechts?"],"words":["weg","kruispunt","rotonde","parkeren","oversteken","stoppen","links","rechts"],"learn":["creativiteit","fijne-motoriek","taal","rekenen"],"tips":["Schilderstape laat op de meeste harde vloeren geen resten achter, maar haal de tape binnen een paar dagen weg: hoe langer die ligt, hoe vaster die plakt. Op vloerbedekking houdt tape slecht.","Maak een foto van de stad voordat je opruimt: dan kunnen jullie de stad een volgende keer nabouwen."],"extenders":["Zet een stoplicht van papier bij het kruispunt en speel om de beurt verkeersregelaar: stop… en rijden maar!","Bouw een brug of tunnel over de weg van een doos of blokken, of een wasstraat van een doos met stroken papier.","Geef opdrachten: breng de brandweer naar het rode huis, parkeer alle blauwe auto’s bij de bakker.","Plak er een nieuwe wijk bij: een weg onder de tafel door, de gang in of naar de bank.","Laat poppetjes in de huizen wonen en bedenk waar ze heen moeten: naar school, naar de dokter, naar opa en oma."],"variations":["Vliegveld: een lange, brede landingsbaan met strepen in het midden, een verkeerstoren van een koker en een hangar van een doos.","Boerderij: weggetjes naar de wei, een sloot van blauw papier en een stal voor de tractor en de dieren.","Racebaan: één grote lus om de tafel met een start- en finishstreep. Welke auto is het eerst rond?"],"themes":[],"canStay":true,"stayTips":"Plak de stad op een plek waar weinig wordt gelopen, bijvoorbeeld onder de tafel of in een hoek, en parkeer de autootjes ’s avonds in een doos. Haal de tape binnen een paar dagen weg, dan komt die nog makkelijk los.","pinQuery":"tape wegen vloer auto"},
  {"id":"uitvinderskist","title":"De uitvinderskist: bouwen met restjes","emoji":"💡","category":"bouwen","summary":"Een doos vol kokers, doosjes en doppen plus een rol tape: daarmee bouwt je kind robots, raketten en machines die nog niemand ooit heeft gezien.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"verpakkingen","note":"schone lege doosjes in allerlei maten"},{"id":"wc-rollen","note":"wc-rolletjes en keukenrolkokers"},{"id":"schilderstape","note":"scheurt makkelijk met de hand af"}],"optional":[{"id":"dozen","note":"een grote doos als uitvinderskist (of een wasmand)"},{"id":"eierdoos"},{"id":"doppen","note":"als knoppen, wielen en ogen"},{"id":"plakband"},{"id":"kinderschaar","note":"met ronde punt"},{"id":"aluminiumfolie","note":"om te glimmen en te kreukelen"}],"steps":["Vul een grote doos met schoon restmateriaal: kokers, doosjes, eierdozen, doppen, bakjes en deksels. Dat is de uitvinderskist.","Zet de kist bij de tafel of op de vloer, met tape en een kinderschaar erbij. Scheur alvast wat stukken tape af en plak ze aan de tafelrand.","Geef een opdracht om mee te beginnen, bijvoorbeeld: bouw een raket, een robot of een machine die sokken sorteert. Of begin gewoon en kijk wat het wordt.","Laat je kind plakken, stapelen en combineren. Help alleen als je kind erom vraagt, bijvoorbeeld door iets vast te houden terwijl het plakt.","Vraag naar de uitvinding: hoe heet het, wat doet deze knop, hoe werkt het? Laat je kind het voordoen.","Zet de uitvinding op een plank als tentoonstelling en doe wat over is terug in de kist voor de volgende keer."],"ageTips":{"young":"Voor een driejarige is plakken zelf al een uitvinding: scheur de tape vooraf in stukken en plak ze aan de tafelrand. Twee kokers aan elkaar is al een raket!","old":"Laat je kleuter eerst een bouwtekening maken en die daarna nabouwen. Of geef een echte opdracht: een bed voor de beer, een toren zo hoog als de tafel, een machine met drie knoppen."},"safety":["Gebruik alleen schoon restmateriaal: spoel bakjes om, en geen glas, blik met scherpe randen of verpakkingen van schoonmaakmiddel of medicijnen.","Doppen zijn klein: houd ze uit de buurt van jongere broertjes of zusjes, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Dik karton of een koker doorknippen doe jij; je kind knipt met een kinderschaar met ronde punt."],"say":["Wat ben jij aan het uitvinden?","Plak! Vast!","Wat doet dit stuk van je machine?","Het viel steeds om, en toen zette je er een doos onder. Slim bedacht!","Hoe kun je zorgen dat de koker blijft zitten?"],"words":["uitvinding","machine","plakken","vast","los","stevig","bovenop","naast"],"learn":["creativiteit","fijne-motoriek","ontdekken","concentratie"],"tips":["Zet een doos naast de recyclebak en gooi daar een week lang schone kokers, doosjes en doppen in: dan is de uitvinderskist altijd klaar.","Schilderstape kan je kind zelf afscheuren: zo hoeft het niet steeds op jou te wachten en kan het zelfstandig verder.","Bewaar uitvindingen een paar dagen, maak er een foto van en haal ze daarna uit elkaar: terug in de kist voor een nieuwe uitvinding."],"extenders":["Geef een nieuwe opdracht: kan je uitvinding iets vervoeren, iets laten rollen of hoger worden dan de stoel?","Voeg iets nieuws toe aan de kist: aluminiumfolie, rietjes, ijsstokjes of pijpenragers met omgevouwen puntjes.","Laat een knuffel langskomen met een probleem: de beer kan niet slapen, het konijn wil naar de maan. Welke uitvinding helpt?","Houd een uitvindersbeurs: je kind laat de uitvinding zien aan de knuffels of de rest van het gezin en vertelt wat die kan.","Teken samen een gebruiksaanwijzing of een poster met de naam van de uitvinding."],"variations":["Ruimtevaart: bouw raketten van kokers met een neus van een eierdoosbakje en een lanceerplatform van een doos.","Sinterklaas: bouw een pakjesmachine: aan de ene kant gaat er een doosje in, aan de andere kant komt er een pakje uit.","Voertuigen: maak een vrachtwagen, trein of boot van doosjes, met doppen als wielen en een koker als schoorsteen."],"themes":[],"canStay":true,"stayTips":"Laat de uitvinding op een plank of de vensterbank staan, zodat je kind er later aan verder kan bouwen. Bewaar losse doppen en de schaar in een dicht bakje in de kist, buiten bereik van jongere kinderen.","pinQuery":"bouwen met kosteloos materiaal kleuter"},
  {"id":"schoenendooshuisje","title":"Een huisje in een schoenendoos","emoji":"🏠","category":"bouwen","summary":"Zet een schoenendoos rechtop, teken behang en ramen en maak meubels van doosjes en doppen: een eigen huisje voor poppetjes of kleine knuffels.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":3,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"dozen","note":"een schoenendoos; het deksel wordt de tuin"},{"id":"stiften"},{"id":"plakband"},{"id":"klein-speelgoed","note":"poppetjes, diertjes of kleine knuffels als bewoners"}],"optional":[{"id":"verpakkingen","note":"kleine doosjes als bed, kast of bank"},{"id":"doppen","note":"als tafeltje, krukje, lamp of pan"},{"id":"vilt","note":"of stofrestjes, als kleed, dekentje en gordijn"},{"id":"gekleurd-papier","note":"als behang of vloer"},{"id":"lijmstift"},{"id":"kinderschaar"}],"steps":["Zet een schoenendoos rechtop op de lange kant, met de open kant naar je kind toe: dat is het huis. Het deksel wordt de tuin.","Teken samen behang, ramen en een deur op de binnenwanden en een vloer op de bodem. Meer kamers? Plak er de zijkant van een doosje tussen als muur.","Maak meubels van wat er in huis is: een doosje als bed, een dop als tafel, een stukje vilt als kleed of dekentje. Plak ze vast of laat ze los.","Breng de bewoners naar binnen en speel: wie woont er, wat eten ze vanavond, waar slapen ze?","Bouw verder zolang je kind wil: een trap van doosjes, een lamp van een dop, een piepklein schilderijtje aan de muur.","Bewaar het huisje op een plank of kast als jullie klaar zijn, zodat er later weer in gewoond kan worden."],"ageTips":{"young":"Voor een driejarige is inrichten en spelen het leukst. Plak jij de grotere meubels vast en laat je kind tekenen, kleedjes leggen en de poppetjes naar bed brengen.","old":"Laat je kleuter een tweede doos bovenop plakken als verdieping, met een trap van doosjes. Ook leuk: zelf ramen uitknippen (jij maakt het eerste gaatje) en een huisnummer en deurbel tekenen."},"safety":["Doppen en kleine doosjes zijn klein: houd ze uit de buurt van broertjes of zusjes onder de 3, want alles wat door een wc-rolletje past, is te klein voor hen.","Kijk elk doosje na voordat je kind ermee bouwt: geen lucifers, medicijnresten of batterijen erin.","Het eerste gaatje voor een raam maak jij, met de doos plat op tafel en je andere hand niet achter het karton."],"say":["Ding dong! Is er iemand thuis?","Waar gaat de pop vannacht slapen?","Wat moet er nog in de keuken staan, denk je?","Je hebt goed bedacht waar alles moet staan: het bed bij het raam en de tafel in het midden.","Hoe komen ze van beneden naar boven?"],"words":["huis","kamer","bed","tafel","raam","binnen","boven","beneden"],"learn":["creativiteit","fijne-motoriek","taal","concentratie"],"tips":["Plakband of een lijmstift is genoeg: knutsellijm moet drogen, en je kind wil meteen spelen.","Zet een bakje met ‘meubelspul’ bij het huisje: doppen, doosjes, kurken en stofjes. Zo kan je kind steeds iets nieuws maken.","Geen poppetjes? Teken mensjes op karton, knip ze uit (dat doe jij) en plak ze aan een wasknijper, dan blijven ze staan."],"extenders":["Laat er een nieuwe bewoner intrekken: een diertje of knuffeltje dat een eigen kamer nodig heeft.","Geef een feestje in het huisje: een taart van een dop, slingers van papierstrookjes en uitnodigingen voor de buren.","Plak een tweede schoenendoos ernaast of erbovenop: nu is er een buurhuis of een zolder.","Richt de tuin in op het deksel: een zwembad van een dop, bomen van gevouwen groen papier en een hek van ijsstokjes.","Speel verhuizen: pak alle meubels in een doosje, rijd ze met een autootje naar een tweede doos en richt die opnieuw in."],"variations":["Winkeltje of bakkerij: richt de doos in met schappen van stroken karton en kleine boodschappen van papier.","Spookhuis: zwart papier op de wanden, een spinnenweb van wol en spookjes van keukenpapier.","Kerst: zet een kerstboompje van groen papier in de kamer en hang een slinger van stickers aan de muur."],"themes":[],"canStay":true,"stayTips":"Zet het huisje met de bewoners erin op een plank of kast: zo raakt er niets kwijt en staat alles de volgende dag klaar. Doe losse doppen en kleine meubeltjes in een dicht bakje als er jongere kinderen in huis zijn.","pinQuery":"poppenhuis van schoenendoos knutselen"},
  {"id":"bouwkaartjes","title":"Nabouwen met bouwkaartjes","emoji":"🏗️","category":"bouwen","summary":"Teken simpele bouwwerkjes op kaartjes en laat je kind ze precies nabouwen met blokken; daarna draait het om en ontwerpt je kind kaartjes voor jou.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"duplo","note":"of andere blokken, in een paar duidelijke kleuren"},{"id":"papier","note":"2 vellen, in vieren geknipt: 8 kaartjes"},{"id":"stiften","note":"in dezelfde kleuren als de blokken"}],"optional":[{"id":"karton","note":"stevige kaartjes gaan langer mee"},{"id":"enveloppen","note":"om de kaartjes in te bewaren"},{"id":"kleurpotloden"}],"steps":["Knip 2 vellen papier in vieren: zo heb je 8 kaartjes.","Teken op elk kaartje een simpel bouwwerkje van 2-6 blokken, van de zijkant gezien: rechthoekjes in de goede kleur zijn genoeg. Bijvoorbeeld: een toren van rood, geel en blauw, of een trapje.","Leg de kaartjes omgekeerd op een stapel en zet de bak met blokken erbij.","Laat je kind een kaartje omdraaien en het bouwwerk nabouwen: zoek de goede kleuren, in de goede volgorde.","Vergelijk samen: zet het kaartje naast het bouwwerk. Klopt alles? Tel de blokken en wijs de kleuren aan.","Draai de rollen om: je kind bouwt iets en jij tekent het op een leeg kaartje, of je kind tekent een kaartje en jij bouwt het na.","Bewaar de kaartjes in een envelop bij de blokken: dan is het spel de volgende keer zonder voorbereiding klaar."],"ageTips":{"young":"Begin bij een driejarige met torentjes van 2-3 blokken in duidelijke kleuren, en teken de blokken op ware grootte: dan kan je kind een blok op het kaartje leggen om te vergelijken.","old":"Teken voor een kleuter bouwwerkjes met een brug, een poort of een blok dat uitsteekt. Of laat je kind 10 tellen naar een kaartje kijken, draai het om en laat het bouwwerk uit het hoofd nabouwen."},"safety":["Speelt er een broertje of zusje onder de 3 mee? Gebruik dan alleen grote blokken: kleine bouwsteentjes passen door een wc-rolletje en zijn te klein voor kinderen onder de 3."],"say":["Welke kleur moet er onderop?","Rood, geel, blauw. Klaar!","Klopt het? Kijk nog eens naar het kaartje.","Je hebt goed gekeken: zelfs het kleine blokje bovenop klopt.","Nu mag jij een kaartje maken. Lukt het mij om het na te bouwen?"],"words":["onderop","bovenop","naast","hetzelfde","anders","toren","trap","eerst"],"learn":["rekenen","concentratie","fijne-motoriek","samen"],"tips":["Kies stiftkleuren die echt op je blokken lijken: als lichtgroen en donkergroen op het kaartje hetzelfde zijn, raakt een peuter in de war.","Geen tijd om te tekenen? Bouw zelf drie bouwwerkjes, maak er een foto van en laat je kind van de foto nabouwen.","Kaartjes op karton gaan maanden mee: maak er elke keer een paar bij, dan groeit het spel mee met je kind."],"extenders":["Bouw expres een kaartje fout na, met één blok verkeerd, en laat je kind de fout zoeken.","Zet een timer: lukt het om een kaartje na te bouwen voordat de tijd om is?","Leg twee kaartjes naast elkaar en bouw ze allebei: maak er daarna samen één groot bouwwerk van.","Laat een knuffel een bestelling doen: de beer wil een toren met drie rode blokken, de pop een bank met een blauwe leuning."],"variations":["Patroonkaartjes: teken rijen in een patroon (rood, blauw, rood…) en laat je kind ze nabouwen met blokken of doppen.","Plattegrondkaartjes: teken de blokken van bovenaf gezien en laat je kind ze zo op de vloer neerleggen.","Kerst: teken een kerstboom of sneeuwpop van blokken en bouw ze na in groen en wit."],"themes":[],"canStay":false,"pinQuery":"bouwkaarten blokken nabouwen kleuter"},
  {"id":"langste-rij","title":"De langste rij van het huis","emoji":"📏","category":"bouwen","summary":"Leg blokken, auto’s, knuffels en boeken achter elkaar in één lange rij door kamer en gang: hoe ver komen jullie, en hoeveel stappen is dat?","ageMin":2,"ageMax":3,"mess":2,"wet":false,"dirty":false,"prepMinutes":1,"duration":[20,30],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"duplo","note":"of andere blokken, als begin van de rij"}],"optional":[{"id":"speelgoedautos"},{"id":"knuffels"},{"id":"boeken","note":"om plat neer te leggen of rechtop als domino"},{"id":"wc-rollen"},{"id":"schilderstape","note":"voor een start- en een finishstreep"},{"id":"touw","note":"om de rij na te meten"},{"id":"wasmand","note":"om alles weer in op te halen"}],"steps":["Kies samen een begin, bijvoorbeeld bij de bank, en spreek af waar de rij naartoe gaat: naar de deur, door de gang, tot in de keuken.","Begin met de blokken: leg ze één voor één achter elkaar, steeds netjes tegen elkaar aan.","Ga samen op zoek naar meer als de blokken op zijn: autootjes, knuffels, boeken, kokers, schoenen, bekers. Alles mag mee, als het niet breekbaar is.","Leg de rij door de kamer en de gang: om de tafelpoot heen, onder de stoel door, langs de muur.","Meet de rij in stappen: loop er voetje voor voetje naast en tel samen hardop. Hoeveel stappen lang is jullie rij?","Loop de rij af en benoem alles wat erin ligt: blok, auto, beer, boek… Wat ligt er precies in het midden?","Ruim op als een vrachttrein: begin aan het eind, laad alles in de wasmand en breng het terug naar de plek waar het hoort."],"ageTips":{"young":"Een tweejarige legt graag, maar nog niet netjes achter elkaar: leg om de beurt een ding en houd de rij kort, bijvoorbeeld van de bank tot de tafel. Zeg wat je ziet: nog een blok, en nog een!","old":"Laat je driejarige een patroon leggen (blok, auto, blok, auto) of een stuk van groot naar klein sorteren. Meet de rij samen met een touw, of in jouw voeten en die van je kind: wie heeft de grootste stappen?"},"safety":["Een peuter vindt onderweg van alles: houd munten, knikkers, doppen en batterijen uit de rij, want alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Spreek af waar spullen vandaan mogen komen: niet uit het kastje met schoonmaakmiddelen, de medicijnla of de badkamer.","Leg de rij niet over de trap of in de looproute naar de voordeur: met een volle wasmand of in het donker struikel je er zo over."],"say":["Nog een! En nog een!","Hoe ver komt de rij, denk je: tot de deur of nog verder?","Wat leg je hierna: iets groots of iets kleins?","Wat heb je volgehouden! De rij loopt al tot in de gang.","Hoeveel stappen is het? Tel je mee?"],"words":["lang","langer","langst","achter elkaar","rij","begin","eind","tellen"],"learn":["rekenen","grove-motoriek","concentratie","taal"],"tips":["Maak een foto van de hele rij: een lange slinger door het huis ziet er indrukwekkend uit, en die foto laat je kind later trots aan iedereen zien.","Maak van opruimen een spel: wie brengt de meeste spullen terug voordat het liedje is afgelopen?"],"extenders":["Leg een tweede rij ernaast met andere spullen: welke wordt langer?","Rijd een autootje langs de hele rij, of laat een knuffel als koorddanser over de rij lopen.","Verstop een knuffel ergens langs de rij en laat je kind de rij volgen als een spoor tot aan de schat.","Meet de rij opnieuw met iets anders: hoeveel schoenen lang is het, of hoeveel keer de beer?","Zet een stuk van de rij rechtop als domino, met boeken of blokken, en tik het eerste om: hoe ver gaat het?"],"variations":["Kleurenrij: maak een rij met alleen rode spullen, of een regenboogrij van rood naar paars.","Slang of draak: leg de rij in bochten, geef de slang een kop van een knuffel en bedenk samen een naam.","Sokkenrij: leg alle sokken uit de wasmand op een rij en zoek de paren bij elkaar."],"themes":[],"canStay":true,"stayTips":"Laat de rij langs de muur liggen, buiten de looproute en niet op de weg naar de wc of de slaapkamer: daar loop je ’s nachts in het donker. Zet een knuffel aan het eind als wachter; morgen kan de rij verder groeien.","pinQuery":"speelgoed op een rij leggen peuter"},
  {"id":"spaghetti-bouwen","title":"Bouwen met spaghetti en deegballetjes","emoji":"🍝","category":"bouwen","summary":"Prik droge spaghetti in balletjes speeldeeg en bouw driehoeken, kubussen, torens en bruggen: hoe hoog kom je voordat alles inzakt?","ageMin":4,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":2,"duration":[45,50],"supervision":3,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"pasta","note":"droge spaghetti, een flinke handvol"},{"id":"speeldeeg","note":"een bal zo groot als een sinaasappel; wat stugger deeg werkt het best"}],"optional":[{"id":"dienblad","note":"om op te bouwen en het bouwwerk te verplaatsen"},{"id":"boeken","note":"twee stapels om een brug tussen te bouwen"},{"id":"speelgoedautos","note":"om de brug te testen"},{"id":"klein-speelgoed","note":"een poppetje voor boven op de toren"},{"id":"papier","note":"voor een bouwtekening"},{"id":"potlood"}],"steps":["Leg een handvol droge spaghetti op tafel en breek een deel doormidden (dat doe jij): dan heb je lange en korte stokjes.","Rol samen een stuk of twintig balletjes speeldeeg, zo groot als een knikker.","Bouw eerst een driehoek: drie balletjes, drie stokjes. Laat zien hoe je de spaghetti voorzichtig in het deeg prikt, en laat je kind er ook een maken.","Maak daarna een vierkant van vier stokjes. Prik in elke hoek een stokje omhoog en zet er een tweede vierkant op: een kubus! Welke vorm blijft het best staan?","Bouw samen een toren, zo hoog als je kunt. Hoe hoog kom je voordat de toren gaat wiebelen?","Zet het bouwwerk op een dienblad om te bewaren, of ruim op: veeg gebroken stukjes op en doe het deeg in een afgesloten bakje."],"ageTips":{"young":"Een vierjarige raakt snel gefrustreerd als de spaghetti breekt: gebruik korte stukken en grote balletjes, en begin met platte vormen op tafel, zoals een driehoek, vierkant of huisje, voordat je de hoogte in gaat.","old":"Daag je kleuter uit: bouw een brug tussen twee stapels boeken waar een autootje over kan, of een toren die een poppetje kan dragen. Ook leuk: eerst een bouwtekening maken en die nabouwen."},"safety":["Droge spaghetti breekt in kleine, scherpe stukjes: veeg ze meteen op als er jongere broertjes of zusjes rondkruipen. Alles wat door een wc-rolletje past, ook een deegballetje, is te klein voor kinderen onder de 3.","Speeldeeg bevat veel zout: niet opeten, en giftig voor honden. Houd het bouwwerk buiten bereik van huisdieren."],"say":["Prik! Nog een stokje.","Welke vorm blijft het best staan: de driehoek of het vierkant?","Wat denk je: houdt de toren het als we er nog een verdieping op zetten?","De toren zakte in, en jij bedacht meteen een schuin stokje ertussen. Zo wordt het steviger!","Hoe voelt het deeg: zacht, koud of plakkerig?"],"words":["driehoek","vierkant","kubus","stevig","wiebelen","inzakken","breken","hoog"],"learn":["fijne-motoriek","rekenen","ontdekken","concentratie"],"tips":["Deeg dat al wat ouder en stugger is, werkt hier juist beter: het houdt de stokjes steviger vast. Te zacht of plakkerig? Kneed er een beetje bloem door.","Bouw op een dienblad: dan vang je gebroken stukjes op en zet je het bouwwerk in één keer opzij."],"extenders":["Zet er een poppetje of autootje op: hoeveel kan het bouwwerk dragen voordat het inzakt?","Geef een uitdaging: bouw iets met precies tien stokjes, of een huis waar een poppetje in kan staan.","Bouw om de beurt: jij prikt een stokje, je kind prikt een stokje. Bij wie zakt de toren in?","Maak de deegballetjes kleiner en de stokjes langer: lukt het dan nog om hoog te bouwen?","Teken het bouwwerk na op papier: zo heb je meteen een bouwtekening voor de volgende keer."],"variations":["Rietjes en deeg: knip rietjes in stukken als stokjes die niet breken, handig als de spaghetti steeds knapt.","Kerst: bouw een kerstboom van driehoeken op elkaar en prik er rode deegballetjes in als kerstballen.","Iglo: bouw een koepel van korte stokjes en witte deegballetjes en zet er een poppetje in."],"themes":[],"canStay":true,"stayTips":"Zet het bouwwerk op een dienblad hoog op een kast, buiten bereik van huisdieren en kleine kinderen. Het deeg droogt in een dag of twee hard en het bouwwerk wordt steviger: met verse balletjes kun je er later nog een verdieping op zetten.","pinQuery":"bouwen met spaghetti en klei"},
  {"id":"vliegtuigjes","title":"Papieren vliegtuigjes vouwen en vliegen","emoji":"✈️","category":"bouwen","summary":"Vouw samen papieren vliegtuigjes, versier ze en houd een echte vliegshow: welk vliegtuig komt het verst, en wie landt er op de landingsbaan?","ageMin":4,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[45,45],"supervision":1,"soloFrom":5,"cleanupMinutes":2,"noise":2,"energy":2,"places":["tafel","vloer"],"materials":[{"id":"papier","note":"gewoon A4-printpapier, een paar vellen per kind"},{"id":"stiften","note":"om te versieren"},{"id":"schilderstape","note":"voor een startstreep en een landingsbaan"}],"optional":[{"id":"dozen","note":"als hangar of om in te mikken"},{"id":"wasmand","note":"om in te mikken"},{"id":"stickers"},{"id":"plakband","note":"een stukje over de punt"}],"steps":["Vouw een A4 in de lengte dubbel en weer open. Vouw de twee bovenhoeken naar de middenvouw, zodat er een punt ontstaat.","Vouw de schuine randen nog een keer naar het midden, vouw het geheel dubbel langs de middenvouw en vouw aan beide kanten een vleugel omlaag.","Doe het daarna nog een keer, stap voor stap, terwijl je kind op een eigen vel meevouwt. Strijk elke vouw samen stevig aan.","Laat je kind de vliegtuigen versieren: ramen, een piloot, een naam of een nummer op de vleugel.","Plak met schilderstape een startstreep en verderop een landingsbaan op de vloer, bijvoorbeeld in de gang.","Gooi om de beurt vanaf de startstreep: houd het vliegtuig onder de buik vast en gooi het rustig recht vooruit. Wie landt er op de baan?","Zet een doos of wasmand neer als hangar en probeer erin te mikken. Wat werkt beter: hard of zacht gooien?"],"ageTips":{"young":"Een vierjarige kan nog niet alleen vouwen, maar wel helpen: laat je kind de vouwen aanstrijken met de duim en de vliegtuigen versieren. Gooien en erachteraan rennen is het leukste deel.","old":"Laat je vijfjarige zelf vouwen met jou als voorbeeld, stap voor stap. Bedenk samen waarom het ene vliegtuig verder komt dan het andere: is het de punt, zijn het de vleugels of is het het gooien?"},"safety":["Gooi nooit naar gezichten, mensen of dieren: de punt van een papieren vliegtuig kan in een oog prikken. Vouw de punt een stukje om of plak er een stukje tape over.","Laat je kind niet op een stoel of de bank klimmen om hoger te gooien of een vliegtuig van de kast te pakken: dat doe jij."],"say":["Drie, twee, één… vliegen!","Waar denk je dat het vliegtuig gaat landen?","Dat vloog veel verder dan net! Wat deed je anders?","Wat strijk je de vouwen goed aan: zo wordt het vliegtuig stevig.","Hoe moet je gooien: hard, zacht, omhoog of recht vooruit?"],"words":["vouwen","vleugel","punt","vliegen","landen","zweven","ver","dichtbij"],"learn":["fijne-motoriek","grove-motoriek","ontdekken","rekenen"],"tips":["Gewoon printpapier vliegt het best: karton is te zwaar en tijdschriftpapier houdt de vouwen slecht vast.","Vlieg in de gang of maak een vrije baan door de kamer, en zet breekbare dingen even aan de kant.","Duikt het vliegtuig meteen naar beneden of vliegt het scheef? Strijk de vleugels gelijk en buig de achterrand van de vleugels een heel klein beetje omhoog."],"extenders":["Houd een wedstrijd: plak een tapestreepje bij elke landing en zet er een sterretje of de naam bij. Wie verbetert het record?","Maak een poort om doorheen te vliegen: tussen twee stoelen door of onder de tafel door. Lukt het drie keer achter elkaar?","Vouw een ander model, met een stompe neus, brede vleugels of omhoog gevouwen vleugelpuntjes. Welk vliegtuig vliegt het verst?","Speel vliegveld: een knuffel is de verkeerstoren die zegt wanneer je mag opstijgen, en elk vliegtuig vliegt naar een ander land: de bank, de mat, het kussen."],"variations":["Rietjesraket: rol een strook papier om een potlood tot een kokertje, plak de bovenkant dicht, schuif het op een rietje en blaas de raket weg.","Helikopters: knip een strook papier van boven tot de helft in, vouw de twee wiekjes elk een andere kant op en vouw de onderkant een paar keer om. Laat de helikopter van hoog naar beneden dwarrelen.","Vliegtuigpost: teken een boodschap op de vleugel en vlieg het vliegtuig naar iemand anders in de kamer, die het terugvliegt."],"themes":[],"canStay":false,"pinQuery":"papieren vliegtuig vouwen kind"},
  {"id":"bruggen-bouwen","title":"Bruggen bouwen voor autootjes","emoji":"🌉","category":"bouwen","summary":"Leg een brug van papier, karton of blokken tussen twee stapels boeken en test met autootjes: welke brug houdt het, en welke zakt in?","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"boeken","note":"of andere boeken, voor twee stapels die even hoog zijn"},{"id":"papier","note":"een paar A4’tjes"},{"id":"karton","note":"een paar stroken van een cornflakesdoos (dat knip jij)"},{"id":"speelgoedautos"}],"optional":[{"id":"duplo","note":"om een brug of pijler te bouwen, en als lading om te tellen"},{"id":"wc-rollen","note":"als pijler in het midden"},{"id":"plakband"},{"id":"handdoek","note":"een blauwe handdoek als rivier"},{"id":"touw","note":"een kort stuk, voor een ophaalbrug"}],"steps":["Maak twee stapels boeken van dezelfde hoogte, ongeveer 20 cm uit elkaar. Leg er een handdoek tussen als rivier.","Leg een plat vel papier over de rivier en zet er een autootje op. Wat gebeurt er? Plons!","Vouw een tweede vel als een harmonica, steeds heen en weer, en leg het over de rivier met de vouwen van stapel naar stapel.","Leg het platte vel erop als wegdek en zet het autootje er weer op. Houdt de brug het nu?","Probeer ook een strook karton, een opengeknipte koker of een brug van blokken. Welke brug is het sterkst?","Zet er steeds een autootje of blokje bij en tel samen hardop: hoeveel kan de brug dragen voordat die inzakt?","Schuif de stapels verder uit elkaar: de rivier wordt breder. Welke brug haalt de overkant nog?"],"ageTips":{"young":"Voor een driejarige is het plonzen het leukst: laat de auto’s maar door de papieren brug zakken. Doe de harmonica voor en laat je kind voelen hoe anders het gevouwen papier is.","old":"Laat je kleuter eerst voorspellen welke brug het sterkst is en dat daarna testen. Turf op papier hoeveel blokjes elke brug draagt: welke brug wint?"},"safety":["Houd de boekenstapels laag en gebruik geen zware atlassen: een stapel die omvalt, komt hard op vingers en tenen.","Kleine autootjes en blokjes passen vaak door een wc-rolletje: houd ze uit de buurt van broertjes of zusjes onder de 3."],"say":["Plons! De auto ligt in het water.","Wat denk je: houdt deze brug het, of zakt die in?","Hoeveel auto’s staan er nu op? Tel je mee?","Je bleef proberen tot de brug het hield. Dat doen echte bruggenbouwers ook!","Wat is er anders aan het papier nu het gevouwen is?"],"words":["brug","sterk","zwak","dragen","zwaar","licht","inzakken","overkant"],"learn":["ontdekken","rekenen","fijne-motoriek","taal"],"tips":["De harmonicabrug is een echte goocheltruc: laat je kind de truc aan iemand anders in huis voordoen en uitleggen.","Maak beide stapels precies even hoog, desnoods met een extra boekje: op een scheve brug rollen de auto’s er meteen af.","Bouw op een kleed of bij de bank: vallende auto’s en boeken maken dan minder lawaai."],"extenders":["Laat een vrachtwagen met lading over de brug rijden: leg er blokjes op tot de brug inzakt.","Bouw een pijler in het midden van een koker of een stapel blokken en kijk of de papieren brug het nu wel houdt.","Maak een ophaalbrug: plak een strook karton aan één stapel vast, plak een kort touwtje aan het andere eind en trek de brug omhoog.","Laat een rij knuffels of poppetjes tegelijk oversteken: hoeveel passen er op de brug?","Bouw een tweede brug ernaast en houd een race: welke auto is het eerst aan de overkant?"],"variations":["Bekerbrug: zet plastic bekers op een rij als pijlers en leg er stroken karton op, steeds een verdieping hoger.","Sinterklaas: bouw een loopplank van de stoomboot naar de kade, sterk genoeg voor het paard en de Pieten.","Dierenbrug: maak een brug over een ravijn voor de speelgoeddieren, van ijsstokjes of takjes met plakband."],"themes":[],"canStay":false,"pinQuery":"bruggen bouwen papier kleuter"},
  {"id":"bruisvulkaan","title":"Bruisende vulkaan","emoji":"🌋","category":"proefjes","summary":"Giet azijn bij baking soda en kijk hoe er gekleurde schuimlava uit je vulkaan borrelt: elke keer een spannende uitbarsting.","ageMin":2,"ageMax":5,"mess":3,"wet":true,"dirty":true,"prepMinutes":5,"duration":[15,25],"supervision":1,"soloFrom":null,"cleanupMinutes":10,"noise":2,"energy":1,"places":["tafel","vloer","bad"],"materials":[{"id":"baking-soda","note":"±2 el, genoeg voor een paar uitbarstingen"},{"id":"azijn","note":"natuurazijn, ±50 ml per uitbarsting"},{"id":"afwasmiddel","note":"een scheutje, voor dik schuim"},{"id":"kleurstof","note":"rood of oranje, voor echte ‘lava’"},{"id":"plastic-bekers","note":"een smalle beker of klein leeg flesje als krater, plus een beker voor de azijn"},{"id":"opbergbak","note":"een afwasteil of bak met hoge rand die de lava opvangt"}],"optional":[{"id":"pipet","note":"om de azijn druppel voor druppel toe te voegen"},{"id":"speeldeeg","note":"om een berg rond de beker te boetseren"},{"id":"oud-shirt"}],"steps":["Zet de bak op tafel of op de vloer en zet een plastic beker in het midden: dat is de krater.","Schep samen 2 el baking soda in de beker en doe er een scheutje afwasmiddel en een paar druppels kleurstof bij.","Schenk ±50 ml azijn in een tweede beker en geef die aan je kind.","Tel samen af: drie, twee, één… en giet de azijn in één keer in de krater!","Kijk: het schuim bruist omhoog en stroomt over de rand. Nog een keer? Giet er nieuwe azijn bij, of leeg de beker en begin opnieuw.","Spoel na afloop alles door de gootsteen en neem de bak af met een doekje."],"ageTips":{"young":"Geef je peuter een klein bekertje met een bodempje azijn: zelf gieten is het allerleukste. Doe de baking soda en kleurstof er zelf in en houd het bij één woord: bruisen!","old":"Laat je kleuter voorspellen en testen: wat gebeurt er zonder afwasmiddel? En met een klein scheutje of met een hele beker azijn? Of boetseer samen een berg van speeldeeg om de beker en bedenk er een verhaal bij."},"safety":["Azijn prikt in de ogen en in wondjes: spoel bij een spatje meteen met lauw water en laat je kind niet in de ogen wrijven.","Baking soda, azijn en afwasmiddel zijn niet om te eten of te drinken: houd de flessen zelf vast en zet ze na het afmeten buiten bereik.","Kleurstof vlekt op kleding, tafel en voegen, en gemorst schuim maakt de vloer glad: werk in de bak, trek een oud shirt aan en veeg morsen meteen op."],"say":["Wat denk je dat er gebeurt als we de azijn erbij gieten?","Hoor je dat? Het sist en knispert!","Ik zie bubbels over de rand kruipen, net echte lava.","Je goot heel voorzichtig: bijna alles kwam in de krater.","Bruisen! Nog een keer?"],"words":["bruisen","schuim","bubbels","vulkaan","uitbarsting","sissen","overstromen"],"learn":["ontdekken","zintuigen","taal"],"tips":["Een liter natuurazijn en een pak baking soda zijn goedkoop en genoeg voor een hele middag uitbarstingen.","Doe het in de lege badkuip of vlak voor badtijd: de lava spoel je daar zo weg, en je kind kan meteen in bad."],"extenders":["Geef je kind een pipet of theelepel om de azijn beetje bij beetje in de krater te druppelen: dan blijft de vulkaan veel langer borrelen.","Strooi een paar hoopjes baking soda op de bodem van de bak en laat je kind met azijn de geheime bruisplekken opsporen.","Zet een bakje baking soda met een theelepel klaar en laat je kind de krater zelf vullen: hoeveel schepjes zijn er nodig voor een flinke uitbarsting?"],"variations":["Regenboogvulkaan: zet vijf bekertjes met elk een andere kleur naast elkaar in de bak en laat ze om de beurt uitbarsten.","Dinovulkaan: zet plastic dinootjes rond de krater en laat ze op tijd wegvluchten voor de lava.","Halloween: kleur het schuim groen en laat een ‘heksenketel’ overkoken in een grote kom."],"themes":[],"canStay":false,"pinQuery":"bruisende vulkaan proefje kind"},
  {"id":"bruisende-kleuren","title":"Bruisende kleuren met een pipet","emoji":"🧪","category":"proefjes","summary":"Druppel gekleurde azijn op een laagje baking soda en zie het overal bruisen en knisperen in rood, geel en blauw.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"baking-soda","note":"±150 g voor een dun laagje op het dienblad"},{"id":"azijn","note":"±200 ml, verdeeld over 3 potjes"},{"id":"kleurstof","note":"rood, geel en blauw"},{"id":"potjes","note":"3 kleine bakjes of glaasjes"},{"id":"pipet","note":"liefst één per kleur"},{"id":"dienblad","note":"met randje; een ovenschaal kan ook"}],"optional":[{"id":"muffinvorm","note":"om de potjes stevig in te zetten"},{"id":"oud-laken","note":"als knoeimat onder het dienblad"},{"id":"klein-speelgoed","note":"grote plastic diertjes om te begraven en vrij te bruisen"},{"id":"oud-shirt"}],"steps":["Strooi een dun laagje baking soda over het dienblad en strijk het een beetje glad met de bolle kant van een lepel.","Verdeel de azijn over drie potjes en doe in elk potje een paar druppels kleurstof: rood, geel en blauw.","Doe voor hoe de pipet werkt: knijp het bolletje in, steek de punt in de azijn, laat los en knijp hem boven het blad weer leeg.","Laat je kind druppels op de baking soda maken: overal waar een druppel valt, bruist het in kleur.","Druppel samen geel bij blauw of rood bij geel. Welke nieuwe kleur ontstaat er?","Strooi er een nieuw laagje baking soda over als het nergens meer bruist. Klaar? Spoel het dienblad af boven de gootsteen."],"ageTips":{"young":"Een pipet is voor een tweejarige nog lastig. Geef een theelepel om de azijn mee te scheppen en te gieten, en zet maar één kleur tegelijk neer.","old":"Laat je kleuter eerst voorspellen welke kleur er ontstaat als je twee kleuren mengt, en pas daarna druppelen. Of teken met druppels een letter, een lachend gezichtje of een regenboog."},"safety":["Azijn prikt in de ogen: knijp de pipet nooit richting gezichten en spoel bij een spatje meteen met lauw water.","Kleurstof vlekt op kleding, hout en voegen: leg een knoeimat neer en trek een oud shirt aan.","Baking soda en azijn zijn niet om te eten of te drinken: zet de fles azijn na het inschenken buiten bereik."],"say":["Knijpen, loslaten… zie je de azijn in de pipet kruipen?","Hoor je het knisperen als de druppel valt?","Wat denk je dat er gebeurt als geel en blauw elkaar raken?","Ik zie een groene vlek! Hoe komt die daar?","Druppel! Bruis!"],"words":["druppel","knijpen","loslaten","bruisen","mengen","oranje","groen","paars"],"learn":["fijne-motoriek","ontdekken","concentratie"],"tips":["Geen pipet? Een medicijnspuitje, een theelepel of een rietje met je vinger op het gaatje werkt ook.","Zet de potjes in een muffinvorm: dan staan ze stevig en vallen ze minder snel om."],"extenders":["Leg een paar uitsteekvormpjes op de baking soda en laat je kind alleen binnen de vormpjes druppelen: een bruisend hart of een bruisende ster.","Geef opdrachtjes: drie rode druppels in de hoek, een gele rij in het midden. Daarna geeft je kind de opdrachten aan jou.","Wissel van gereedschap: een medicijnspuitje spuit een straal, een theelepel maakt een grote bruisplas en een rietje met een vinger op het gaatje piepkleine druppels."],"variations":["Verstopte schatten: begraaf een paar grote plastic diertjes in een dikker laagje baking soda en bruis ze met de pipet weer vrij.","Bruisende ijsblokjes: meng baking soda met een beetje gekleurd water tot een dikke pap, vries die in een ijsblokjesvorm in en druppel er azijn op.","Winter: strooi een sneeuwpop van baking soda op een donker bord en laat hem met druppels azijn bruisend smelten."],"themes":[],"canStay":false,"pinQuery":"bruisende kleuren pipet peuter"},
  {"id":"drijven-zinken","title":"Drijft het of zinkt het?","emoji":"⛵","category":"proefjes","summary":"Raad eerst en test dan: welke spullen uit huis blijven drijven in een bak water en welke zakken plons naar de bodem?","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":1,"soloFrom":null,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer","tafel","bad"],"materials":[{"id":"opbergbak","note":"of een afwasteil, half vol water"},{"id":"water","note":"lauw"},{"id":"kurken","note":"drijven altijd"},{"id":"lepel","note":"een metalen lepel, die zinkt"},{"id":"fruit","note":"bijv. een appel en een sinaasappel"},{"id":"duplo","note":"een paar grote bouwblokken"},{"id":"aluminiumfolie","note":"een vel van ±30 cm voor een bootje"},{"id":"handdoek","note":"onder de bak en om af te drogen"}],"optional":[{"id":"steentjes","note":"een flinke kiezel die niet door een wc-rolletje past"},{"id":"badspeelgoed"},{"id":"papier","note":"voor een lijstje: drijft of zinkt"}],"steps":["Zet de bak op een handdoek op de vloer of tafel en vul hem half met lauw water.","Verzamel samen een stuk of acht voorwerpen, zoals een kurk, een metalen lepel, een appel, een bouwblok en een grote kiezel.","Pak één voorwerp en vraag eerst: wat denk je, blijft het drijven of zakt het naar de bodem?","Laat je kind het voorwerp in het water leggen en kijk samen of de gok klopte. Leg het daarna op de drijf- of de zinkstapel.","Vouw van aluminiumfolie een bootje en laat het drijven. Hoeveel blokjes kan het dragen voordat het zinkt?","Droog alles af op de handdoek en giet het water weg, of geef de planten er water mee."],"ageTips":{"young":"Voor een tweejarige is plonzen en weer opvissen al een feest. Kies grote, onbreekbare voorwerpen en zeg na elke plons alleen: drijft! of zinkt! Het raden komt later vanzelf.","old":"Laat je kleuter vooraf een lijstje maken met twee rijtjes, drijven en zinken, en een vinkje zetten bij elke goede gok. Ook spannend: drijft een sinaasappel met schil, en zonder schil?"},"safety":["Laat je kind nooit alleen bij de bak water, ook niet bij een laagje: blijf er de hele tijd bij.","Kies voor kinderen onder de 3 alleen grote voorwerpen: alles wat door een wc-rolletje past, is te klein (verstikkingsgevaar).","Dweil gemorst water meteen op: een natte vloer is glad."],"say":["Wat denk je: drijft de appel of zinkt hij?","Plons! Helemaal naar de bodem.","Ik zie dat de kurk steeds weer bovenkomt, ook als je hem onderduwt.","Wat goed dat je eerst nadacht voordat je ging testen.","Drijft! Nog een?"],"words":["drijven","zinken","zwaar","licht","bodem","bovenop","plons","nat"],"learn":["ontdekken","taal","rekenen"],"tips":["Laat je kind zelf voorwerpen zoeken die nat mogen worden: dat is de helft van het plezier.","Doe het proefje in de lege badkuip met een laagje water, vlak voor badtijd: dan mag het lekker spetteren."],"extenders":["Zoek samen een paar twijfelgevallen, zoals een spons, een leeg bekertje of een plastic flesje met een laagje water. Blijven ze drijven als ze vollopen?","Laat de zinkers meevaren: leg de metalen lepel of een grote kiezel in de folieboot. Blijft het bootje drijven?","Geef je kind een vergiet of soeplepel en laat alle zinkers weer van de bodem opvissen: hoeveel vis je er in één keer op?"],"variations":["Fruitschaal-test: probeer een banaan, een citroen, een mandarijn en een stuk komkommer. Wat had je niet verwacht?","Bootjesrace: blaas met een rietje je folieboot naar de overkant van de bak.","Toveren met klei: een bolletje klei zinkt, maar maak je er een bakje van, dan blijft het drijven. Hoe kan dat?"],"themes":[],"canStay":false,"pinQuery":"drijven of zinken proefje peuter"},
  {"id":"dansende-melk","title":"Dansende kleuren in melk","emoji":"🥛","category":"proefjes","summary":"Druppel kleurstof in een laagje melk, raak het aan met een wattenstaafje met afwasmiddel en kijk hoe de kleuren wegschieten en dansen.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":null,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"melk","note":"volle melk, een laagje van ±1 cm"},{"id":"bord","note":"een diep bord of schaaltje"},{"id":"kleurstof","note":"3-4 kleuren"},{"id":"afwasmiddel","note":"een bodempje op een schoteltje"},{"id":"wattenstaafjes","note":"een paar"}],"optional":[{"id":"dienblad","note":"onder het bord, voor gemorste melk"},{"id":"pipet","note":"om de kleurstof te druppelen"},{"id":"koffiefilters","note":"om een afdruk van de kleuren te maken"}],"steps":["Giet een laagje volle melk van ongeveer een centimeter in een diep bord en laat het even stil worden.","Druppel drie of vier druppels kleurstof in verschillende kleuren dicht bij elkaar in het midden. Niet roeren!","Doe een bodempje afwasmiddel op een schoteltje en laat je kind het puntje van een wattenstaafje erin dopen.","Houd het wattenstaafje rustig midden in de melk, tussen de kleuren, en tel tot tien. Kijk hoe de kleuren wegschieten en draaien!","Probeer een andere plek of dop het wattenstaafje opnieuw. Stopt het dansen? Druppel er nieuwe kleuren bij of begin met verse melk.","Giet de melk na afloop weg en was het bord en de handen goed af."],"ageTips":{"young":"Laat je peuter vooral het wattenstaafje erin houden; het druppelen van de kleurstof doe jij. Twee kleuren is genoeg, en zeg wat je ziet: weg! Ze rennen weg!","old":"Laat je kleuter een patroon bedenken, bijvoorbeeld druppels in een cirkel of op een rij, en voorspellen waar de kleuren heen gaan. Vertel daarna: het afwasmiddel duwt het vet in de melk opzij."},"safety":["Deze melk is niet meer om te drinken: giet hem na afloop meteen weg en houd het schoteltje afwasmiddel bij jezelf. Komt er zeep in een oog, spoel dan met lauw water.","Kleurstof vlekt op kleding en tafel: zet het bord op een dienblad en schuif de mouwen omhoog."],"say":["Kijk eens! De kleuren rennen weg van je stokje.","Wat denk je dat er gebeurt als je het wattenstaafje in het midden houdt?","Ik zie rood en blauw door elkaar draaien. Welke kleur wordt het?","Wat houd je je hand goed stil: daardoor blijven de kleuren dansen.","Dans, kleurtjes, dans!"],"words":["druppel","dansen","draaien","wegschieten","melk","zeep","mengen","stil"],"learn":["ontdekken","zintuigen","concentratie"],"tips":["Volle melk werkt het best: hoe meer vet, hoe wilder de kleuren dansen. Melk die net over de datum is, is prima.","Maak een foto van elk bord: elke keer ontstaat er een ander patroon.","Zet het bord op een dienblad met een theedoek eronder: gemorste melk in een vloerkleed ruik je nog dagen."],"extenders":["Laat je kind op een vers bord eerst een wattenstaafje zonder zeep proberen en daarna één met zeep: zie je het verschil?","Kies samen maar twee kleuren, zoals geel en blauw, en kijk of er tijdens het dansen groen ontstaat.","Test andere toverstokjes met een drupje afwasmiddel erop: een vork, een rietje of het puntje van een lepel. Welke laat de kleuren het hardst rennen?"],"variations":["Vergelijk drie borden: volle melk, halfvolle melk en water. Waar dansen de kleuren het wildst?","Oud en nieuw: tel samen af van tien naar nul en steek dan met het wattenstaafje je kleurenvuurwerk af.","Afdrukje: leg na het dansen voorzichtig een koffiefilter op de melk, til hem op en laat hem drogen: een kleurig kunstwerkje."],"themes":[],"canStay":false,"pinQuery":"dansende melk kleurstof proefje"},
  {"id":"lopend-water","title":"Regenboog van lopend water","emoji":"🌈","category":"proefjes","summary":"Zet bekers met gekleurd water op een rij, hang er bruggetjes van keukenpapier tussen en zie het water klimmen en nieuwe kleuren mengen.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":5,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"plastic-bekers","note":"7 doorzichtige bekers of glazen"},{"id":"water"},{"id":"kleurstof","note":"rood, geel en blauw"},{"id":"keukenpapier","note":"6 vellen"}],"optional":[{"id":"dienblad","note":"om de bekers op te zetten, eventueel in een kring"},{"id":"papier","note":"om je voorspelling op te tekenen"},{"id":"kleurpotloden","note":"in dezelfde kleuren als het water"}],"steps":["Zet zeven bekers op een rij. Vul de eerste, derde, vijfde en zevende beker voor driekwart met water; de bekers ertussen blijven leeg.","Laat je kind kleurstof druppelen: rood in de eerste, geel in de derde, blauw in de vijfde en weer rood in de zevende beker.","Vouw zes vellen keukenpapier in de lengte een paar keer dubbel tot stevige repen.","Hang de repen als bruggetjes tussen de bekers: één uiteinde in een volle beker, het andere in de lege beker ernaast.","Kijk na tien minuten: het gekleurde water kruipt omhoog door het papier! Kom daarna elk uur even kijken.","Bekijk na een paar uur of de volgende ochtend de lege bekers: welke nieuwe kleuren zijn er ontstaan?","Gooi het natte papier weg, giet het water in de gootsteen en spoel de bekers om."],"ageTips":{"young":"Voor een driejarige is het lang wachten. Begin met drie bekers (geel, leeg, blauw) en kijk samen elke tien minuten: wordt het al groen?","old":"Laat je kleuter vooraf voorspellen welke kleur er in elke lege beker komt en dat tekenen met kleurpotloden. Leg de tekening na afloop naast de bekers: klopte het?"},"safety":["Kleurstof vlekt op kleding, tafel en vloerkleed: zet de bekers op een dienblad op een plek waar ze uren mogen blijven staan.","Zet de opstelling buiten bereik van jongere broertjes, zusjes en huisdieren, en dweil gemorst water meteen op: een natte vloer is glad."],"say":["Kijk, het rode water klimt omhoog in het papier!","Welke kleur denk je dat er komt als rood en geel elkaar ontmoeten?","Ik zie een groen randje in de lege beker. Waar komt dat vandaan?","Wat ben je geduldig: het water werkt nog hard voor ons.","Kijk! Groen!"],"words":["opzuigen","klimmen","mengen","nat","droog","oranje","paars","wachten"],"learn":["ontdekken","rekenen","taal"],"tips":["Wees niet zuinig met kleurstof (zo’n 10 druppels per beker): hoe feller de kleur, hoe mooier de regenboog.","Start het proefje ’s ochtends of vlak voor bedtijd: dan is er na het spelen of bij het ontbijt een regenboog te zien.","Stevig keukenpapier werkt het best: dun servetpapier zakt in elkaar als het nat wordt."],"extenders":["Houd een race: welk bruggetje is het eerst helemaal gekleurd? Laat je kind een favoriet kiezen en elke tien minuten gaan kijken.","Zet met een stift een streepje op de lege bekers waar het water nu staat, en kom elk uur kijken hoeveel het gestegen is.","Vervang één reep door een ander soort papier, zoals een koffiefilter of een servet: kruipt het water daar sneller of langzamer doorheen?"],"variations":["Regenboogkring: zet zes bekers in een kring (rood, leeg, geel, leeg, blauw, leeg) en maak een complete kleurencirkel.","Bloemen kleuren: zet een witte bloem of een selderijstengel in water met veel kleurstof en bekijk na een dag de blaadjes.","Lente: laat de gekleurde repen keukenpapier drogen en knip er bloemen of vlinders van voor het raam."],"themes":[],"canStay":true,"stayTips":"Bouw de rij bekers meteen op een dienblad op een plek waar hij mag blijven staan, zoals de vensterbank of het aanrecht, buiten bereik van jongere kinderen en huisdieren. Kijk de volgende ochtend samen naar de mengkleuren en ruim daarna alles op.","pinQuery":"lopend water regenboog keukenpapier"},
  {"id":"pepertruc","title":"Pepertruc: de peper rent weg","emoji":"🧂","category":"proefjes","summary":"Strooi peper op water, doop je vinger in afwasmiddel en kijk hoe alle peperpuntjes in een flits naar de rand vluchten.","ageMin":3,"ageMax":5,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"duration":[10,15],"supervision":2,"soloFrom":5,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"bord","note":"een diep bord, liefst wit"},{"id":"water"},{"id":"kruiden","note":"gemalen zwarte peper"},{"id":"afwasmiddel","note":"een druppel op een schoteltje"}],"optional":[{"id":"wattenstaafjes","note":"om het afwasmiddel op te doen in plaats van een vinger"}],"steps":["Vul een diep bord met een laagje water van een paar centimeter en laat het stil worden.","Laat je kind flink wat gemalen peper over het water strooien, tot het vol zwarte puntjes ligt.","Laat je kind eerst een schone, droge vinger in het midden steken. Wat doet de peper?","Doe een druppel afwasmiddel op een schoteltje. Laat je kind de vingertop erin dopen en die weer midden in het water steken.","Kijk hoe de peper in een flits naar de rand vlucht! Raad samen: waarom rent de peper weg?","Spoel het bord om en begin opnieuw met vers water: met zeep erin werkt de truc niet meer."],"ageTips":{"young":"Een driejarige wil de truc steeds opnieuw zien. Zet een paar borden met water en peper klaar, zodat je snel weer kunt toveren, en laat je kind zelf strooien.","old":"Laat je kleuter testen wat nog meer werkt: een vinger met boter, met zout of met shampoo. Wat laat de peper rennen, en wat niet? Vertel daarna: het zeepje breekt het dunne vliesje op het water."},"safety":["Peper prikt in ogen en neus: strooi laag boven het bord en laat je kind niet met peperhanden in de ogen wrijven.","Afwasmiddel hoort niet in de mond: spoel de vinger na elke keer even af onder de kraan."],"say":["Kijk eens, de peper drijft als allemaal kleine bootjes!","Wat denk je dat er gebeurt als je je vinger erin steekt?","Weg! Ze rennen allemaal naar de kant.","Wat zit er nu op je vinger dat er net nog niet op zat?","Wat goed dat je het ook met een schone vinger probeerde. Zo ontdek je het verschil."],"words":["strooien","drijven","wegrennen","rand","midden","zeep","toveren"],"learn":["ontdekken","taal","concentratie"],"tips":["Speel het als goocheltruc met ‘hocus pocus’, en laat je kind de truc daarna zelf aan opa, oma of een vriendje voordoen.","Een wit bord laat de zwarte peper het best zien. Geen peper? Gedroogde oregano of peterselie werkt ook."],"extenders":["Maak een vers bord klaar en prik nu eens aan de rand in plaats van in het midden: waar vlucht de peper dan naartoe?","Strooi op een vers bord een strookje kaneel naast de peper: wie rent er het snelst weg, de bruine of de zwarte puntjes?","Laat je kind de truc opvoeren voor een rij knuffels, met een toverspreuk en een buiging na afloop."],"variations":["Visjes en de haai: de peperpuntjes zijn visjes en de zeepvinger is de haai. Waar zwemmen de visjes naartoe?","Tegentruc: leg na het wegrennen een suikerklontje midden in het water. Komt de peper dan juist naar het midden toe?","Zeepbootje: knip een klein bootje van karton met een inkeping achteraan, zet het op het water en druppel afwasmiddel in de inkeping: het vaart vanzelf weg."],"themes":[],"canStay":false,"pinQuery":"peper water zeep proefje kind"},
  {"id":"lavalamp","title":"Lavalamp in een fles","emoji":"🧴","category":"proefjes","summary":"Water met kleurstof, olie en een stukje bruistablet in een fles: kijk hoe de gekleurde bellen op en neer borrelen, net een echte lavalamp.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":true,"prepMinutes":5,"duration":[10,20],"supervision":1,"soloFrom":null,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"plastic-flesjes","note":"doorzichtig, ±500 ml, etiket eraf"},{"id":"water","note":"±125 ml"},{"id":"kleurstof","note":"een paar druppels"},{"id":"olie","note":"±350 ml zonnebloemolie"},{"id":"bruistablet","note":"een half tablet per keer, in stukjes gebroken"},{"id":"dienblad","note":"om op te werken: olie op tafel is glibberig"}],"optional":[{"id":"trechter","note":"om de olie in de fles te gieten"},{"id":"zaklamp","note":"eronder of erachter, voor een echt lampeffect"},{"id":"zout","note":"als je geen bruistablet hebt"}],"steps":["Zet de fles op het dienblad. Giet er ±125 ml water in (tot een kwart) en laat je kind een paar druppels kleurstof toevoegen.","Vul de fles samen verder met olie tot een paar centimeter onder de rand; met een trechter gaat het makkelijker.","Wacht even en kijk: de olie blijft bovenop drijven en het gekleurde water zakt naar de bodem.","Breek een half bruistablet in een paar stukjes en laat je kind er één in de fles gooien.","Kijk: de gekleurde bellen borrelen naar boven en zakken weer naar beneden. Gestopt? Doe er een nieuw stukje in.","Draai de dop er pas op als het bruisen helemaal gestopt is, en bewaar de fles voor een volgende keer."],"ageTips":{"young":"Een driejarige mag het stukje tablet erin gooien; de olie giet jij en de tabletten houd je bij je. Doe telkens een klein stukje, dan is er vaak iets nieuws te zien.","old":"Laat je kleuter voorspellen en testen: bruist een groot stuk tablet langer dan een klein stukje? Tel samen hoe lang de bellen doorgaan en vergelijk."},"safety":["Bruistabletten zijn medicijnen of vitaminen: houd de verpakking zelf vast en berg hem daarna hoog en buiten bereik op.","Olie en kleurstof vlekken, en olie op de vloer is spiegelglad: werk op een dienblad en veeg morsen meteen op met keukenpapier en een sopje.","Draai de dop niet dicht zolang het nog bruist: er bouwt dan druk op in de fles."],"say":["Kijk, de olie en het water willen niet mengen!","Wat denk je dat er gebeurt als het tabletje erin valt?","Ik zie een rode bel naar boven gaan… en weer naar beneden zakken.","Blub, blub, blub! Nog een stukje?","Wat kijk je goed: jij zag als eerste dat het stopte."],"words":["bubbels","olie","omhoog","omlaag","drijven","zakken","bruisen"],"learn":["ontdekken","zintuigen","taal"],"tips":["Gebruik goedkope zonnebloemolie: de fles kun je dagenlang bewaren en steeds opnieuw laten borrelen met een nieuw stukje tablet.","Geen bruistablet? Strooi 1 tl zout in de fles: er zakken oliebolletjes naar beneden die daarna weer naar boven drijven.","Giet de olie na afloop niet door de gootsteen, maar doe hem in een afgesloten fles bij het restafval of lever hem in bij de inzamelplek voor frituurvet."],"extenders":["Draai de dop erop als het bruisen helemaal gestopt is en laat je kind de fles langzaam kantelen: olie en water maken golven, net een zee.","Zet een vel gekleurd papier of een tekening achter de fles: hoe ziet de lava eruit voor een gele zon of een donkere nacht?","Laat je kind met kleurpotloden de bellen natekenen: grote, kleine, snelle en trage. Lijkt de tekening op de fles?"],"variations":["Lichtshow: doe het grote licht uit en schijn met een zaklamp onder of achter de fles.","Regenbooglampen: maak drie kleine flesjes in verschillende kleuren en zet ze naast elkaar voor het raam.","Kleurenmix: druppel later een tweede kleur in de fles. Zakt de druppel door de olie heen, en welke kleur krijgt het water?"],"themes":[],"canStay":false,"pinQuery":"lavalamp fles olie water kind"},
  {"id":"dansende-rozijnen","title":"Dansende rozijnen","emoji":"🍇","category":"proefjes","summary":"Gooi rozijnen in een glas bruiswater en kijk hoe ze naar de bodem zakken, weer naar boven zweven en op en neer blijven dansen.","ageMin":3,"ageMax":5,"mess":1,"wet":true,"dirty":false,"prepMinutes":2,"duration":[10,15],"supervision":2,"soloFrom":4,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"bruiswater","note":"een vers geopende fles"},{"id":"rozijnen","note":"6-8 stuks"},{"id":"beker","note":"een hoog, doorzichtig glas of plastic beker"}],"optional":[{"id":"water","note":"kraanwater in een tweede glas, om te vergelijken"},{"id":"pasta","note":"stukjes droge spaghetti om ook te laten dansen"}],"steps":["Schenk een hoog glas vol met vers bruiswater en kijk samen naar de belletjes.","Laat je kind vijf tot acht rozijnen één voor één in het glas gooien.","Kijk goed: de rozijnen zakken eerst naar de bodem. Wacht even… daar komen ze weer omhoog!","Bekijk een rozijn van dichtbij: zie je de belletjes die eraan vastplakken? Die tillen hem op als een zwembandje.","Zet een glas kraanwater ernaast en doe daar ook een paar rozijnen in. Wat is het verschil?","Vis de rozijnen er na afloop uit met een lepel. Opeten mag, ze zijn alleen wat zachter geworden."],"ageTips":{"young":"Voor een driejarige is het dansen al spannend genoeg. Houd het bij één glas en zing erbij: op en neer, op en neer!","old":"Laat je kleuter tellen hoeveel rozijnen er tegelijk bovenaan drijven, of kies samen één rozijn en tel hoe vaak hij bovenkomt. Vertel dan: bovenaan knappen de belletjes en zakt hij weer."},"safety":["Gebruik een stevig glas of een doorzichtige plastic beker en zet hem midden op tafel: een omgestoten glas kan breken.","Dweil gemorst bruiswater meteen op: een natte vloer is glad."],"say":["Kijk, de rozijn zakt naar de bodem… en nu komt hij weer omhoog!","Wat zie je allemaal aan de rozijn plakken?","Wat denk je: gaan ze ook dansen in gewoon water?","Op en neer! Op en neer!","Wat kijk je geduldig. Jij zag als eerste dat die kleine rozijn bovenkwam."],"words":["bubbels","omhoog","omlaag","bodem","bovenop","dansen","prik"],"learn":["ontdekken","taal","rekenen"],"tips":["Gebruik een vers geopende fles: hoe meer prik, hoe langer de rozijnen dansen. Na een kwartier is de prik er meestal uit.","Een hoog, smal glas werkt het best: dan hebben de rozijnen een lange dansvloer en zie je alles goed."],"extenders":["Geef elke rozijn een naam en houd een wedstrijdje: wie komt het eerst weer boven?","Schenk er wat vers bruiswater bij als het dansen trager wordt: komen de rozijnen weer in actie?","Zet een tweede glas bruiswater klaar en test wat er nog meer danst: een ontbijtringetje, een maïskorrel of een halve rozijn."],"variations":["Dansende spaghetti: breek droge spaghetti in stukjes van 2 cm en kijk of die ook gaan dansen.","Zonder prik: doe 1 tl baking soda in een glas water, giet er een scheutje azijn bij en gooi er rozijnen in.","Rozijnendisco: zet muziek op en dans mee. Gaat de rozijn omhoog, dan sta jij op; zakt hij, dan ga je zitten."],"themes":[],"canStay":false,"pinQuery":"dansende rozijnen bruiswater proefje"},
  {"id":"tuinkers-eierkoppen","title":"Eierkoppen met tuinkershaar","emoji":"🥚","category":"proefjes","summary":"Teken een gezichtje op een lege eierschaal, zaai er tuinkers in en kijk hoe je eierkop in een week een groene bos haar krijgt.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"eieren","note":"lege schalen van gekookte eitjes, alleen het kapje eraf"},{"id":"watten","note":"een paar wattenbolletjes per ei"},{"id":"tuinkers","note":"een zakje zaadjes"},{"id":"stiften","note":"om een gezichtje te tekenen"},{"id":"eierdoos","note":"als standaard voor de eierkoppen"},{"id":"water"}],"optional":[{"id":"plantenspuit","note":"om de watten vochtig te houden"},{"id":"kinderschaar","note":"kleuters knippen het haar zelf"},{"id":"potgrond","note":"in plaats van watten"}],"steps":["Bewaar een paar lege schalen van gekookte eitjes: tik alleen het kapje eraf, eet het ei op en spoel de schaal om met warm water.","Zet de schalen in de eierdoos en laat je kind er met stiften een gezichtje op tekenen.","Vul elke schaal met wattenbolletjes en maak ze goed nat met 2-3 el water.","Strooi een flinke snuf tuinkerszaadjes op de natte watten en druk ze zachtjes aan.","Zet de eierkoppen op een lichte vensterbank en houd de watten elke dag vochtig.","Kijk elke dag even: na 1-2 dagen zie je kiempjes, na ongeveer een week heeft je eierkop een flinke bos haar.","Knip het haar af en eet het op een boterham met ei of kaas."],"ageTips":{"young":"Een eierschaal is voor een tweejarige erg breekbaar: gebruik dan een vakje van de eierdoos als kopje. Zaadjes strooien en water geven met een theelepel kan je peuter prima zelf.","old":"Laat je kleuter elke dag een tekening van de eierkop maken in een groeiboekje. Hoeveel dagen duurt het tot de eerste blaadjes? En welk kapsel knip je straks?"},"safety":["Ei-allergie in huis? Gebruik dan vakjes van de eierdoos of lege bakjes in plaats van eierschalen.","Werk je met schalen van rauwe eieren, spoel ze dan goed om met heet water en was daarna ieders handen: op rauw ei kunnen bacteriën (salmonella) zitten.","Een kapotte eierschaal heeft scherpe randjes: gooi gebroken schalen meteen weg."],"say":["Kijk, piepkleine zaadjes! Wat zou eruit groeien?","Nat maken. Druppel, druppel!","Ik zie witte worteltjes! Gisteren waren die er nog niet.","Wat zorg je goed voor je eierkop: je geeft hem elke dag water.","Hoe zal jouw eierkop eruitzien met lang haar?"],"words":["zaadje","kiemen","groeien","wortel","blaadje","knippen","haar"],"learn":["ontdekken","fijne-motoriek","creativiteit","taal"],"tips":["Spaar een paar dagen lang de schalen van gekookte eitjes en spoel ze meteen om, dan gaan ze niet ruiken.","Geen watten? Een prop nat keukenpapier of een schepje potgrond werkt net zo goed.","Draai de eierkoppen elke dag een kwartslag: tuinkers groeit naar het licht toe en anders krijgt je eierkop een scheve kuif."],"extenders":["Maak een lijfje voor elke eierkop: zet hem op een wc-rolletje en laat je kind er kleren, armen en een naam op tekenen.","Teken samen verschillende gezichten: een blije, een boze en een slaperige eierkop. Wie krijgt straks het wildste haar?","Zet één eierkop in een donkere kast en één op de vensterbank, en vergelijk elke ochtend: welke wordt groener, welke langer?"],"variations":["Pasen: zet de eierkoppen als groene versiering op de paastafel, met een zelfgemaakt kuikentje erbij.","Kapsalon: strooi de zaadjes alleen in een smalle strook voor een hanenkam, of aan één kant voor een scheiding.","Lente: zaai tuinkers op nat keukenpapier in de vorm van de eerste letter van de naam van je kind."],"themes":["lente","pasen"],"canStay":true,"stayTips":"Laat de eierkoppen in de eierdoos op een lichte vensterbank staan, buiten bereik van jongere kinderen en huisdieren. Geef elke ochtend samen een theelepel water en kijk wat er gegroeid is.","pinQuery":"eierkoppen tuinkers haar knutselen"},
  {"id":"vogelvoer-dennenappels","title":"Vogelvoer-dennenappels voor bij het raam","emoji":"🐦","category":"proefjes","summary":"Smeer een dennenappel in met pindakaas, rol hem door vogelzaad en hang hem bij het raam: daarna kijk je vanuit binnen wie er komt snoepen.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"dennenappels","note":"grote, open exemplaren, eerder verzameld"},{"id":"pindakaas","note":"liefst zonder zout; bij een pinda-allergie reuzel of vet"},{"id":"vogelzaad","note":"of havermout met ongezouten zaden"},{"id":"touw","note":"±30 cm per dennenappel"},{"id":"ijsstokjes","note":"om mee te smeren"},{"id":"bord","note":"om het vogelzaad op uit te strooien"}],"optional":[{"id":"zip-zakjes","note":"om de dennenappel in het zaad te schudden (minder rommel)"},{"id":"oud-laken","note":"als knoeimat"},{"id":"oud-shirt"},{"id":"wc-rollen","note":"in plaats van een dennenappel"}],"steps":["Knoop een touw van ongeveer 30 cm stevig om de bovenste schubben van de dennenappel. Dat doe jij.","Doe 3-4 el pindakaas in een kommetje en strooi het vogelzaad uit op een bord.","Laat je kind de dennenappel met een ijsstokje insmeren: tussen de schubben mag de pindakaas er lekker dik in.","Rol de dennenappel door het vogelzaad en druk het zaad met je handen goed aan.","Hang hem buiten bij het raam, aan een tak, de balkonrand of een haakje, buiten bereik van katten. Dat doe jij.","Ga samen binnen op de uitkijk zitten: welke vogels komen er eten? Tel ze en geef ze een naam."],"ageTips":{"young":"Een tweejarige smeert het liefst met de handen: prima, dat voelt lekker. Doe het zaad in een diepvrieszakje en laat je peuter de dennenappel erin schudden.","old":"Laat je kleuter een turflijst maken: teken een mees, een merel en een mus en zet een streepje bij elke vogel die je ziet. Wie komt er het vaakst?"},"safety":["Pinda-allergie in huis? Gebruik dan reuzel of vet in plaats van pindakaas en was na afloop handen, tafel en spullen goed.","Vogelzaad is niet om te eten: zaden en hele pinda’s kunnen in de luchtpijp schieten. Hele noten en pinda’s zijn niet geschikt voor kinderen onder de 4."],"say":["Smeer, smeer! Helemaal plakkerig!","Hoe voelt de dennenappel: glad of stekelig?","Ik zie dat je pindakaas tussen alle schubben hebt gestopt. Daar smullen de vogels van.","Welke vogel denk je dat als eerste komt eten?","Sst… kijk, daar is een mees! Wat doet hij?"],"words":["dennenappel","plakkerig","smeren","zaadjes","vogel","mees","pikken"],"learn":["fijne-motoriek","zintuigen","ontdekken","taal"],"tips":["Leg een knoeimat of krant neer en trek een oud shirt aan: vet geeft vlekken en vogelzaad rolt overal heen. Met een kruimeldief is het zo opgeruimd.","Geen dennenappels? Smeer een wc-rolletje in, rol het door het zaad en schuif het over een tak of rijg er een touwtje door.","Hang het voer op een plek waar katten niet bij kunnen en vervang het als het gaat schimmelen. Vogels hebben het vooral nodig bij vorst en sneeuw."],"extenders":["Maak er een tweede bij met een ander jasje, zoals havermout of alleen zonnebloempitten, en kijk later welke het eerst leeg is.","Bouw een vogelkijkhut bij het raam: een stoel, een deken over jullie hoofd en een verrekijker van twee wc-rolletjes.","Doe het geluid en het loopje na van elke vogel die komt: hoe huppelt een merel en hoe tjilpt een mus?"],"variations":["Vetkoekjes: meng gesmolten vet met vogelzaad, giet het in uitsteekvormpjes op bakpapier, leg er een lusje touw in en laat het opstijven in de koelkast. Het smelten doe jij.","Kerst: hang een paar dennenappels met een strikje als versiering in een boom bij het raam.","Vogelboekje: maak een foto van elke vogel die komt eten en zoek samen de naam op."],"themes":["winter"],"canStay":true,"stayTips":"Hang de dennenappels buiten bereik van katten en kijk elke dag samen hoeveel er al is opgegeten. Vervang ze als ze leeg zijn of gaan schimmelen, en bewaar het vogelzaad in een dichte pot hoog in de kast.","pinQuery":"dennenappel vogelvoer pindakaas kind"},
  {"id":"bootjes-lading","title":"Hoeveel lading draagt jouw bootje?","emoji":"🚢","category":"proefjes","summary":"Vouw bootjes van aluminiumfolie, laad ze blokje voor blokje vol en tel tot ze zinken: welke vorm draagt de meeste lading?","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":3,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"aluminiumfolie","note":"een paar vellen van ±30 x 30 cm"},{"id":"opbergbak","note":"een ondiepe bak of afwasteil"},{"id":"water","note":"een laagje van ±5 cm"},{"id":"duplo","note":"of andere blokjes van dezelfde maat, als lading"},{"id":"handdoek","note":"onder de bak en om af te drogen"}],"optional":[{"id":"papier","note":"voor een scorebord"},{"id":"potlood"},{"id":"knopen","note":"of doppen: kleinere lading om te tellen"},{"id":"klein-speelgoed","note":"diertjes als passagiers"},{"id":"rietjes","note":"om het bootje vooruit te blazen"}],"steps":["Zet de bak op een handdoek op tafel of op de vloer en doe er een laagje water van ongeveer 5 cm in.","Vouw samen een bootje: leg een vel aluminiumfolie plat, zet de randen rondom omhoog en knijp de hoekjes dicht.","Laat het bootje drijven en leg er één voor één blokjes in. Tel hardop mee!","Kijk hoe het bootje dieper en dieper zakt, tot het water over de rand loopt. Plons! Hoeveel blokjes waren het?","Vouw een nieuw bootje in een andere vorm: plat en breed, smal en hoog, of met een dubbele bodem. Raad eerst: draagt dit bootje meer of minder?","Houd de scores bij met een streepje per blokje op papier en kijk welk bootje de kampioen is.","Droog de blokjes af op de handdoek, strijk de folie glad voor een volgende keer en giet het water weg."],"ageTips":{"young":"Vouw voor een driejarige het bootje alvast voor en laat je kind vooral laden, tellen tot drie of vijf en het zinken beleven. Plons mag zo vaak als je kind wil.","old":"Laat je kleuter eerst een bootje ontwerpen op papier en voorspellen hoeveel blokjes erin passen, en dan testen. Hoe kun je hetzelfde bootje verbeteren zodat het er twee meer draagt?"},"safety":["Laat een driejarige nooit alleen bij de bak water, ook niet bij een laagje. Vanaf een jaar of 4 kun je in dezelfde ruimte iets anders doen, als je om de paar minuten even kijkt.","Gebruik je kleinere lading zoals knopen of doppen, houd die dan buiten bereik van jongere broertjes en zusjes: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3.","Dweil gemorst water direct op: een natte vloer is glad."],"say":["Hoeveel blokjes passen erop, denk je?","Nog eentje durven? Voorzichtig…","Plons! Hoe kwam dat, denk je?","Je hebt het bootje breder gemaakt en nu draagt het er meer. Slim bedacht!","Eén, twee, drie… nog een!"],"words":["drijven","zinken","lading","zwaar","licht","breed","smal","omslaan"],"learn":["ontdekken","rekenen","fijne-motoriek","concentratie"],"tips":["Gebruik één soort lading van dezelfde maat: dan kun je eerlijk vergelijken welk bootje het sterkst is.","Een laagje water van 5 cm is genoeg: het bootje drijft net zo goed en er spat veel minder over de rand."],"extenders":["Maak storm: laat je kind met een lepel golven maken of blazen. Welk bootje blijft met lading het langst drijven?","Verdeel de lading anders: leg alle blokjes eens in het midden, dan aan één kant en dan verspreid over de bodem. Wat gebeurt er?","Zet een record op papier en daag je kind uit het te verbreken met een nieuw ontwerp.","Bouw een catamaran: knijp twee bootjes aan elkaar vast met een strook folie en test of ze samen meer dragen dan elk apart.","Speel vrachtschipper: laad een diertje en twee blokjes in en blaas het bootje met een rietje naar de haven aan de overkant."],"variations":["Bakjesboten: test welke lege bakjes, eierdozen of melkpakken de meeste lading dragen.","Piratenschip: maak een zeil van een rietje en een stukje papier en vervoer ‘goudschatten’ van doppen.","Vlot van rietjes: plak een rij rietjes met plakband aan elkaar en tel hoeveel blokjes het vlot draagt.","Badtijd: neem de folieboten mee in bad en laad ze met badspeeltjes. Blijf er wel de hele tijd bij."],"themes":[],"canStay":false,"pinQuery":"aluminiumfolie bootje proefje kind"},
  {"id":"natuurmandala","title":"Mandala leggen met natuurschatten","emoji":"🍁","category":"proefjes","summary":"Leg kastanjes, blaadjes en takjes in steeds grotere kringen om een middelpunt: een rustig herfstkunstwerk dat dagenlang kan blijven groeien.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"kastanjes","note":"en eikels, eerder samen verzameld"},{"id":"bladeren","note":"in verschillende kleuren en vormen"},{"id":"dienblad","note":"of een groot stuk karton, dan kun je de mandala verplaatsen"}],"optional":[{"id":"takjes","note":"als zonnestralen"},{"id":"dennenappels","note":"mooi als middelpunt"},{"id":"steentjes"},{"id":"schelpen"},{"id":"bloemen","note":"blaadjes van uitgebloeide snijbloemen"},{"id":"muffinvorm","note":"om de schatten per soort in te sorteren"}],"steps":["Kieper de verzamelde natuurschatten uit en sorteer ze samen per soort in een muffinvorm of op hoopjes: kastanjes, blaadjes, takjes, steentjes.","Leg in het midden van het dienblad iets bijzonders: een dennenappel, een mooi blad of de grootste kastanje.","Leg er een kring omheen van één soort, bijvoorbeeld allemaal kastanjes, zo dicht mogelijk naast elkaar.","Maak daaromheen een nieuwe ring van iets anders: blaadjes met de punt naar buiten, of takjes als zonnestralen.","Ga zo door, ring na ring, zo groot als je kind wil. Probeer ook een patroon: kastanje, blad, kastanje, blad.","Bekijk het kunstwerk samen van bovenaf en maak er een foto van. Laat het liggen, of veeg alles terug in de sorteerbakjes voor een nieuwe mandala."],"ageTips":{"young":"Een driejarige legt het liefst rijtjes en hoopjes. Zet een beker of bord in het midden: als je kind de kastanjes langs de rand legt, wordt het vanzelf een kring.","old":"Laat je kleuter een patroon bedenken en volhouden, of een spiegelmandala maken: links precies hetzelfde als rechts. Tel samen per ring hoeveel schatten er nodig waren: welke ring heeft er het meest?"},"safety":["Kastanjes en eikels zijn giftig bij opeten: houd ze uit de mond. Ze zijn ook klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3, dus let op jongere broertjes en zusjes.","Laat paddenstoelen en bessen buiten: sommige zijn giftig, en ze zien er soms uit als iets lekkers.","Was na het spelen samen de handen: aan natuurschatten zit vaak zand of aarde."],"say":["Wat leg jij in het midden?","Rondje! Nog een kastanje.","Ik zie een ring van bruine kastanjes en daaromheen gele blaadjes.","Hoe voelt deze kastanje: glad of ruw? En dit blad?","Wat werk je geduldig: elke kastanje ligt precies naast de vorige."],"words":["kring","rondom","patroon","midden","glad","ruw","stekelig","herfst"],"learn":["rekenen","creativiteit","concentratie","zintuigen"],"tips":["Leg de mandala op een donkere handdoek of zwart papier: de kleuren springen er dan uit en kastanjes rollen minder snel weg.","Een mandala hoeft niet perfect rond te worden: een slinger, een spiraal of een zon is net zo mooi. Laat je kind vrij leggen.","Bewaar de natuurschatten in een doos of mandje: zo heb je de hele herfst een kant-en-klaar spel."],"extenders":["Speel ‘wat is er weg?’: je kind doet de ogen dicht, jij haalt één schat weg, en je kind raadt wat er mist.","Leg om de beurt: jij legt één ding, je kind legt er één, en zo groeit de mandala samen verder.","Geef een nieuwe regel voor de volgende ring: alleen gele dingen, alleen dingen die kriebelen, of precies tien stuks.","Zoek in huis extra schatten voor een buitenste ring: knopen, doppen, wasknijpers of theelepeltjes."],"variations":["Lente: leg een bloemenmandala van bloemblaadjes en jonge blaadjes.","Zomer: maak een strandmandala van schelpen en steentjes op een laagje zand in een bak.","Natuurgezicht: leg geen kringen maar een gezicht, een egel of een uil van natuurschatten.","Keukenmandala: leg ringen van droge pasta, rijst en ontbijtringetjes op een donker bord."],"themes":["herfst"],"canStay":true,"stayTips":"Leg de mandala op een dienblad of groot karton en zet hem hoog op een kast of vensterbank, buiten bereik van kleine broertjes en zusjes en huisdieren. Bladeren verdrogen en krullen in een paar dagen: kijk samen hoe ze veranderen en vervang ze door nieuwe.","pinQuery":"natuurmandala kastanjes bladeren kind"},
  {"id":"pasta-rijgen","title":"Pastaketting rijgen","emoji":"📿","category":"motoriek","summary":"Rijg penne of rigatoni aan een touw tot een ketting of armband: goed voor handige vingers én een cadeautje om trots op te zijn.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,25],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"pasta","note":"penne of rigatoni: hoe groter het gat, hoe makkelijker"},{"id":"touw","note":"of wol: ±70 cm voor een ketting, ±25 cm voor een armband"},{"id":"plakband","note":"om het puntje van het touw stijf te maken"}],"optional":[{"id":"schoenveter","note":"heeft al een hard puntje: makkelijk voor beginners"},{"id":"pijpenragers","note":"stijf en makkelijk om op te oefenen; puntjes omvouwen"},{"id":"kleurstof","note":"om de pasta vooraf te kleuren (zie tips)"},{"id":"zip-zakjes","note":"om de pasta in te kleuren"}],"steps":["Knip een touw van ±70 cm voor een ketting of ±25 cm voor een armband. Draai plakband strak om één uiteinde: dat is je ‘naald’.","Knoop aan het andere uiteinde een stuk pasta vast, dan glijdt de rest er niet af.","Doe de pasta in een bakje en laat je kind rijgen: puntje in het gat, doorschuiven en de volgende!","Bedenk samen een patroon, bijvoorbeeld penne-rigatoni-penne, of rood-geel-rood als je gekleurde pasta hebt.","Knoop de uiteinden stevig aan elkaar als het touw bijna vol is (dat doe jij) en knip het plakbandpuntje eraf.","Geef de ketting cadeau of hang hem op. Draagt je kind hem zelf, doe hem dan af voor het slapen."],"ageTips":{"young":"Een tweejarige rijgt het makkelijkst met rigatoni op een schoenveter of pijpenrager. Houd jij het touw rechtop vast; je peuter doet de pasta op het puntje en laat hem naar beneden zakken.","old":"Laat je kleuter een patroon bedenken en volhouden, de stukjes tellen of de pasta zelf kleuren. Hang er een hartje of letter van karton aan voor wie de ketting krijgt."},"safety":["Droge pasta past door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Blijf bij je peuter en ruim gevallen stukjes direct op.","Een ketting kan verstrikt raken (wurggevaar): laat je kind hem nooit zonder toezicht om de nek dragen en doe hem af voor het slapen en bij het klimmen."],"say":["Erin… en doorschuiven! Nog een!","Ik zie dat je het touw goed strak houdt. Zo glijdt de pasta er makkelijk op.","Hoeveel stukjes zitten er al aan je ketting? Zullen we tellen?","Wat komt er nu in jouw patroon: een dunne of een dikke?","Wat heb jij lang volgehouden, wat een geduld!"],"words":["rijgen","gat","door","touw","ketting","patroon","lang","kort"],"learn":["fijne-motoriek","concentratie","rekenen","creativiteit"],"tips":["Gekleurde pasta: schud 200 g pasta met 1 tl azijn en een paar druppels kleurstof in een ritszakje, spreid uit op bakpapier en laat 1-2 uur drogen.","Bewaar een half afgemaakte ketting met de pasta in een ritszakje: morgen gewoon verder rijgen."],"extenders":["Geef iets nieuws om te rijgen: stukjes rietje, een ringetje van een wc-rol of een kartonnen hartje met een gat erin.","Meet tussendoor: is de ketting al zo lang als je arm? Rijg door tot hij precies om de lievelingsknuffel past.","Doe een wedstrijdje met twee touwtjes: wie rijgt het eerst tien stukjes? Tel hardop mee."],"variations":["Moederdag: rijg een ketting voor mama of oma en hang er een hartje van karton aan.","Armband: vijf of zes stukjes op een kort touwtje, snel af en net zo trots om te geven.","Rups: rijg pasta op een pijpenrager, buig hem in een bocht en teken met stift een gezichtje op het eerste stukje.","Kerst: rijg rood en groen gekleurde pasta tot een slinger voor in de kerstboom."],"themes":["moederdag","cadeau"],"canStay":true,"stayTips":"Laat het plakbandpuntje aan het touw zitten en bewaar de halve ketting met de pasta in een ritszakje, hoog en buiten bereik van kinderen onder de 3. De volgende dag rijgt je kind gewoon verder.","pinQuery":"pasta ketting rijgen peuter"},
  {"id":"spaghetti-prikken","title":"Spaghetti prikken in een vergiet","emoji":"🍝","category":"motoriek","summary":"Prik droge spaghetti of pijpenragers door de gaatjes van een omgekeerd vergiet en schuif er ontbijtringetjes overheen: een rustig prikspel voor kleine vingers.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"vergiet","note":"omgekeerd op tafel; liefst met gaatjes waar een sliert net door past"},{"id":"pasta","note":"droge spaghetti, in halve slierten gebroken"},{"id":"ontbijtgranen","note":"ontbijtringetjes om over de slierten te schuiven"}],"optional":[{"id":"pijpenragers","note":"zachter en steviger voor dreumesen; puntjes omvouwen"},{"id":"dienblad","note":"onder het vergiet, dan rollen de ringetjes niet weg"}],"steps":["Zet een vergiet ondersteboven op een dienblad of op tafel.","Breek een paar slierten droge spaghetti doormidden en leg ze in een bakje naast het vergiet.","Laat zien hoe je een sliert door een gaatje prikt. Nu jij: hoeveel slierten passen erin?","Geef ontbijtringetjes als het vergiet vol staat, en laat je kind ze één voor één over een sliert schuiven.","Trek alles er weer uit en begin opnieuw: eruit halen is net zo leuk als erin stoppen."],"ageTips":{"young":"Geef een dreumes van 1 liever pijpenragers met omgevouwen puntjes: die breken niet en zijn makkelijker vast te pakken. Prikken en eruit trekken is uitdaging genoeg; de ringetjes komen later.","old":"Een driejarige kan tellen hoeveel ringetjes er op één sliert passen, gekleurde pijpenragers op kleur sorteren of penne over de slierten rijgen. Wie bouwt de hoogste toren van ringetjes?"},"safety":["Droge spaghetti breekt in harde, scherpe stukjes. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: ruim gebroken stukjes meteen op en blijf erbij.","In pijpenragers zit ijzerdraad met een scherp puntje: vouw beide uiteinden een stukje om.","Ontbijtringetjes mogen opgegeten worden, maar laat je kind dan rechtop zitten en blijf erbij."],"say":["Prik! Nog een!","Ik zie dat je heel goed mikt op dat kleine gaatje.","Waar gaat deze sliert naartoe: bovenop of aan de zijkant?","Wat heb je geduldig geprikt, het vergiet lijkt wel een egel!","Hoe voelt de pijpenrager: zacht of kriebelig?"],"words":["prikken","gaatje","erin","eruit","lang","vol","ringetje","bovenop"],"learn":["fijne-motoriek","concentratie","ontdekken"],"tips":["Zet het vergiet op een dienblad: gevallen ringetjes blijven dan binnen handbereik en rollen niet onder de bank.","Geen vergiet? Prik met een pen gaatjes in een omgekeerde schoenendoos (dat doe jij)."],"extenders":["Maak er een egel van: plak een getekend gezichtje op het vergiet en geef de egel zo veel mogelijk stekels.","Geef een nieuwe uitdaging: prik alleen in de gaatjes van de bovenste rij, of maak een rondje langs de rand.","Voer de ringetjes aan een knuffel: schuif ze één voor één van de sliert af in een bakje voor de beer. Hap!"],"variations":["Taart: prik de slierten als kaarsjes in een bal speeldeeg of eetbaar havermoutdeeg en zing ‘Lang zal ze leven’.","Doos: prik grotere gaten in een schoenendoos en laat je kind er rietjes of pijpenragers in steken.","Kleuren: gebruik pijpenragers in verschillende kleuren en zet ze per kleur bij elkaar."],"themes":[],"canStay":false,"pinQuery":"spaghetti prikken vergiet dreumes"},
  {"id":"wasknijpers","title":"Wasknijper-figuren: leeuw, egel en zon","emoji":"🦁","category":"motoriek","summary":"Knijp wasknijpers op de rand van een papieren bordje tot een leeuw met manen, een egel of een zon: knijpen maakt kleine vingers sterk.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":1,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"wasknijpers","note":"10-20 stuks; liefst met een niet te stugge veer"},{"id":"papieren-bordjes","note":"of een rondje karton"},{"id":"stiften","note":"om een gezicht te tekenen"}],"optional":[{"id":"waskrijt","note":"om het bordje geel of oranje te kleuren"},{"id":"karton","note":"voor een egel: knip een druppelvorm uit"},{"id":"bladeren","note":"om tussen de stekels van de egel te knijpen"}],"steps":["Kies samen wat je maakt: een leeuw, een zon of een egel. Teken met stift een gezicht in het midden van het bordje.","Kleur het bordje eventueel geel of oranje met waskrijt. Voor een egel knip je een druppelvorm uit karton (dat doe jij).","Laat zien hoe een knijper werkt: knijpen, openhouden, over de rand schuiven en loslaten.","Knijp samen de knijpers rondom de rand: manen voor de leeuw, stralen voor de zon, stekels op de rug van de egel.","Haal ze er weer af en begin opnieuw, of tel hoeveel knijpers er rondom passen."],"ageTips":{"young":"Voor een tweejarige is een knijper openknijpen echt zwaar werk. Zoek de slapste knijpers uit, houd jij het bordje vast en begin met drie knijpers. Knijpers eraf halen is ook al knap.","old":"Laat je kleuter een kleurpatroon maken (geel, oranje, geel…), tellen hoeveel knijpers er passen of een eigen dier bedenken: een spin met acht poten of een krab met scharen."},"safety":["Knijpers knijpen ook in vingertjes, neusjes en oorlelletjes: laat ze niet aan het gezicht hangen.","Gooi kapotte knijpers meteen weg: het losse veertje is klein en scherp, en alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Knijp… open… en los!","Ik zie dat je duim en je wijsvinger samen hard werken.","Hoeveel stralen heeft jouw zon al?","Wat heb je goed doorgezet: die knijper was stug!","Wat voor dier zou jij nog kunnen maken met knijpers?"],"words":["knijpen","open","dicht","rand","rondom","manen","stekels","stralen"],"learn":["fijne-motoriek","rekenen","creativiteit"],"tips":["Test de knijpers eerst zelf: sommige zijn veel stugger dan andere. Leg de makkelijkste apart voor je kind.","Bewaar bordjes en knijpers samen in een zak: een kant-en-klaar spelletje voor onderweg of bij opa en oma."],"extenders":["Verstop de knijpers in de kamer en laat je kind ze één voor één zoeken en terugknijpen op het bordje.","Knijp ze ergens anders op: de rand van een mandje, een doos of de mouw van jouw trui. Hoeveel passen er?","Gebruik een knijper als tangetje en pak er propjes papier of wattenbolletjes mee op voor in een bakje."],"variations":["Herfst: knip een egel uit bruin karton, knijp er stekels op en steek een blaadje achter een van de knijpers.","Zomer: maak een gele zon met knijpers als stralen en hang hem voor het raam.","Kleurenspel: kleur de rand van het bordje in vakjes en zoek een knijper in dezelfde kleur.","Bloem of vis: knijpers als bloemblaadjes rond een hartje, of als vinnen en staart aan een kartonnen vis."],"themes":["herfst","zomer"],"canStay":false,"pinQuery":"wasknijpers papieren bordje leeuw"},
  {"id":"kleuren-sorteren","title":"Sorteren op kleur in een muffinvorm","emoji":"🌈","category":"motoriek","summary":"Leg in elk vakje van een muffinvorm een gekleurd papiertje en zoek samen uit wat waar hoort: met je handen, een lepel of een knijper.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"muffinvorm","note":"of een eierdoos of losse bakjes"},{"id":"gekleurd-papier","note":"een rondje per vakje, in de kleuren van je spullen"},{"id":"duplo","note":"of andere grote spulletjes in verschillende kleuren"}],"optional":[{"id":"pompons","note":"pas vanaf 3 jaar"},{"id":"doppen","note":"kleine doppen pas vanaf 3 jaar"},{"id":"wasknijpers","note":"als tangetje voor kleuters"},{"id":"lepel","note":"om mee te scheppen"}],"steps":["Knip rondjes gekleurd papier en leg er één onderin elk vakje van de muffinvorm, bijvoorbeeld rood, geel, blauw en groen.","Doe alle spulletjes door elkaar in een kom: duplo, of vanaf 3 jaar ook pompons en doppen.","Pak er samen één uit: welke kleur is dit? Waar woont rood?","Laat je kind alles sorteren met de handen. Gaat dat makkelijk? Probeer dan een lepel of een wasknijper als tangetje.","Kijk samen naar de vakjes: waar zitten de meeste? Gooi alles terug in de kom en begin opnieuw."],"ageTips":{"young":"Begin bij een tweejarige met twee kleuren en grote spullen, en leg in elk vakje alvast één voorbeeld. Benoem steeds de kleur: rood! Nog een rode!","old":"Laat je kleuter sorteren met een wasknijper als tang, of op twee dingen tegelijk: rood én groot. Tel daarna per vakje: van welke kleur heb je er het meest?"},"safety":["Pompons, kleine doppen en kralen passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Geef je peuter duplo of andere grote spullen.","Tel na afloop of alle kleine spulletjes terug zijn in het bakje, zeker als er een jonger broertje of zusje rondkruipt."],"say":["Rood! Waar woont rood?","Ik zie dat je alle gele blokjes al bij elkaar hebt gezet.","Hoe weet jij dat deze bij blauw hoort?","Van welke kleur hebben we de meeste, denk je?","Met een wasknijper pakken is lastig, en jij blijft het proberen!"],"words":["rood","geel","blauw","groen","hetzelfde","sorteren","meer","minder"],"learn":["rekenen","fijne-motoriek","taal","concentratie"],"tips":["Passen je spullen niet in de vakjes? Sorteer dan in kommen of schoenendozen met een gekleurd vel erin.","Bewaar de muffinvorm met de papiertjes en spulletjes in een zak: een snel spelletje voor een regenachtige ochtend."],"extenders":["Sorteer expres een paar keer fout en laat je kind de foutjes zoeken: hé, wat doet die blauwe bij rood?","Leg een nieuwe kleur in een leeg vakje en ga samen op jacht door de kamer naar spullen die erbij passen.","Gooi om de beurt een dobbelsteen: zoveel ogen, zoveel spulletjes mag je sorteren. Wie heeft het eerst een vakje vol?"],"variations":["Op maat: sorteer groot en klein, of zwaar en licht, in twee bakken.","Herfst: sorteer verzamelde blaadjes op kleur in bakjes: groen, geel, oranje en bruin.","Opruimspel: laat je kind speelgoed per kleur terugbrengen naar de bakken."],"themes":[],"canStay":false,"pinQuery":"kleuren sorteren muffinvorm peuter"},
  {"id":"plakbandweb","title":"Redden uit het plakbandweb","emoji":"🕸️","category":"motoriek","summary":"Plak schilderstape kriskras over een wasmand vol speelgoed en laat je kind de gevangen diertjes één voor één bevrijden.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["vloer"],"materials":[{"id":"schilderstape","note":"of plakband, één rol"},{"id":"wasmand","note":"of een doos zonder deksel"},{"id":"klein-speelgoed","note":"of knuffels; voor kinderen onder de 3 groter dan een wc-rolletje"}],"optional":[{"id":"wasknijpers","note":"als vistang voor kleuters"},{"id":"pijpenragers","note":"om een spin van te buigen"}],"steps":["Leg speelgoed of knuffels onderin een wasmand of doos.","Plak lange stroken schilderstape kriskras over de opening, van rand naar rand. Laat genoeg ruimte voor een kinderhand.","Vertel erbij: oh nee, de diertjes zitten gevangen in het web! Wie helpt ze eruit?","Laat je kind de diertjes tussen de stroken door eruit halen, of de tape lostrekken: allebei goed.","Zet de geredde diertjes op een rij en tel samen: hoeveel zijn er al vrij?","Prop de tape samen tot een grote bal en gooi hem in de prullenbak."],"ageTips":{"young":"Plak voor een dreumes maar een paar stroken, ver uit elkaar, en gebruik knuffels of grote blokken die makkelijk te pakken zijn. Lostrekken is voor je dreumes net zo leuk als redden.","old":"Maak het web dichter en laat je kleuter vissen met een wasknijper als tang, zonder de tape te raken. Of speel tegen de klok: hoeveel diertjes red je in één minuut?"},"safety":["Propjes tape belanden bij een dreumes snel in de mond (verstikkingsgevaar): gooi losgetrokken stroken direct weg.","Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: verstop voor je dreumes of peuter alleen grote speeltjes en knuffels."],"say":["Trek! Daar is de eend!","Wie zit er nog gevangen in het web?","Ik zie dat je je hand heel voorzichtig tussen de stroken door steekt.","Hoe voelt de tape: plakkerig of glad?","Wat ben jij een goede redder: je blijft het gewoon proberen!"],"words":["plakkerig","trekken","onder","tussen","door","vast","los","bevrijden"],"learn":["fijne-motoriek","concentratie","taal","ontdekken"],"tips":["Schilderstape is fijner dan plakband: het plakt minder hard aan kleine vingers en trekt makkelijk los van de wasmand.","Geen wasmand? Plak het web tussen de poten van een stoel of over een la."],"extenders":["Plak een nieuw web als alle diertjes vrij zijn: in een andere richting, in twee lagen of met nog maar één klein gaatje.","Wissel van rol: je kind stopt de diertjes terug en plakt een web voor jou. Lukt het jou om ze te redden?","Breng elk gered diertje naar een veilige plek in huis: de beer naar de bank, de auto naar de garage onder de tafel."],"variations":["Halloween: buig een spin van een pijpenrager, zet hem op het web en red de diertjes voor hij terugkomt!","Muffinvorm-web (vanaf 3 jaar): plak tape over de vakjes van een muffinvorm met in elk vakje een kleine verrassing.","Garage: zet speelgoedautootjes in een doos en laat ze door het web naar buiten rijden."],"themes":["halloween"],"canStay":false,"pinQuery":"speelgoed redden tape wasmand"},
  {"id":"plakband-lostrekken","title":"Plakbandjes lostrekken","emoji":"✋","category":"motoriek","summary":"Plak stroken schilderstape op tafel, raam of vloer en laat je kind ze lostrekken: simpel, stil en heerlijk voor kleine vingertjes.","ageMin":1,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[5,15],"supervision":2,"soloFrom":3,"cleanupMinutes":1,"noise":1,"energy":1,"places":["tafel","vloer","muur"],"materials":[{"id":"schilderstape","note":"liefst in een paar kleuren"}],"optional":[{"id":"papier","note":"om de losgetrokken stroken op te plakken"},{"id":"stiften","note":"om de tape in te kleuren of figuurtjes op te tekenen"},{"id":"speelgoedautos","note":"om over een tapeweg te laten rijden"}],"steps":["Plak 10-15 stroken schilderstape op het tafelblad, het raam of de vloer: rechte lijnen, kruisjes of een zonnetje.","Vouw aan elke strook een puntje om, plakkant op plakkant: zo kan je kind het makkelijk vastpakken.","Laat zien hoe je aan het puntje trekt. Nu jij!","Benoem wat je ziet: een lange gele strook, een korte blauwe, een kruisje.","Plak de losgetrokken stroken samen op een vel papier: een kunstwerk van tape."],"ageTips":{"young":"Plak voor een dreumes van 1 een paar korte, brede stroken laag op de vloer of het raam, met een groot omgevouwen puntje. Trek de eerste samen los.","old":"Een driejarige kan in een vaste volgorde lostrekken (eerst alle rode), zelf stukjes tape afscheuren en opplakken, of eerst met een autootje over de tapeweg rijden."},"safety":["Een propje tape is voor een dreumes zo in de mond (verstikkingsgevaar): verzamel losgetrokken stroken meteen op een vel papier of in de prullenbak.","Plak geen tape in de buurt van stopcontacten en snoeren: daar wil je je kind niet laten peuteren en trekken."],"say":["Trek! Los!","Ik zie een lange gele streep. Kun jij hem vinden?","Hoor je dat? Krrrt, zegt de tape.","Hoe voelt de plakkant aan je vinger?","Wat zet jij goed door, die laatste zat echt vast!"],"words":["trekken","los","plakkerig","lang","kort","streep","kruis","puntje"],"learn":["fijne-motoriek","taal","zintuigen","concentratie"],"tips":["Haal de tape dezelfde dag weg van ramen, deuren en lak: hoe langer hij zit, hoe vaster hij gaat plakken.","Geen gekleurde tape? Kleur gewone schilderstape met stift, dan kun je toch kleuren benoemen."],"extenders":["Leg een plaatje uit een folder onder een paar stroken: wat komt er tevoorschijn als alles los is?","Plak de stroken kriskras over elkaar heen, zodat je kind moet zoeken welke bovenop zit.","Verhuis het spel: plak nieuwe stroken op de deur, de koelkast of de mouw van jouw trui."],"variations":["Tapeweg: plak een weg op de vloer, rijd er met autootjes over en trek hem daarna samen los.","Knuffelredding: plak een knuffel ‘vast’ op tafel onder een paar stroken en laat je kind hem bevrijden.","Raamkunst: plak een huis of zon op het raam en trek de stroken er een voor een weer af."],"themes":[],"canStay":false,"pinQuery":"plakband lostrekken dreumes motoriek"},
  {"id":"rijgkaarten","title":"Rijgkaarten maken","emoji":"🧵","category":"motoriek","summary":"Knip een vorm uit karton, pons er gaatjes in en rijg er een veter doorheen: een rustig rijgspel dat je steeds opnieuw kunt doen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"karton","note":"bijv. van een cornflakesdoos: dun karton is makkelijk te ponsen"},{"id":"perforator","note":"voor de gaatjes"},{"id":"schoenveter","note":"of touw van ±60 cm met plakband om het puntje"},{"id":"stiften","note":"om de vorm te tekenen en te versieren"}],"optional":[{"id":"touw","note":"of wol, als je geen veter hebt"},{"id":"plakband","note":"om het puntje van het touw stijf te maken"},{"id":"stickers","note":"om de kaart te versieren"},{"id":"kinderschaar","note":"voor kleuters die zelf willen knippen"}],"steps":["Teken een grote, eenvoudige vorm op het karton, zoals een appel, vis, hart of auto, en knip hem uit (dat doe jij).","Pons rondom gaatjes in de rand, ongeveer 2-3 cm uit elkaar. Laat je kind ook eens ponsen: met twee handen flink drukken!","Laat je kind de vorm versieren met stift of stickers.","Knoop de veter vast aan het eerste gaatje. Gebruik je touw? Draai dan plakband strak om het losse puntje.","Rijg samen: door een gaatje naar achteren, door het volgende weer naar voren. Zeg erbij: erin… en eruit!","Trek de veter eruit als je helemaal rond bent en begin opnieuw, of knoop hem vast en hang de kaart op."],"ageTips":{"young":"Maak voor een driejarige maar 6-8 gaten en gebruik een veter met een hard puntje. Het maakt niet uit hoe je kind rijgt: kriskras is ook rijgen.","old":"Laat je kleuter zelf de vorm tekenen, uitknippen met een kinderschaar (jij knipt de lastige stukjes) en ponsen. Of nummer de gaatjes en rijg ze in de goede volgorde, net als verbind-de-stippen."},"safety":["Veters en touw kunnen om de nek verstrikt raken (wurggevaar): houd ze kort, hooguit ±60 cm, en berg ze op na het spelen.","De rondjes uit de perforator zijn klein: veeg ze op als er een broertje of zusje onder de 3 rondkruipt. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Erin… en eruit!","Welk gaatje komt nu, denk je?","Ik zie dat je de veter helemaal doortrekt tot hij strak zit.","Wat werk je geconcentreerd: je bent al halverwege de vis!","Voel je hoe de veter door het gaatje glijdt?"],"words":["rijgen","gaatje","voor","achter","door","rondom","veter","strak"],"learn":["fijne-motoriek","concentratie","creativiteit"],"tips":["Plak een strook plakband over de rand voordat je ponst: dan scheuren de gaatjes minder snel uit.","Gebruik de voorkant van een oude verpakking of ansichtkaart: dan staat er meteen een vrolijk plaatje op."],"extenders":["Geef een tweede veter in een andere kleur en rijg samen een patroon: rood door het ene gaatje, blauw door het volgende.","Maak er een verhaal van: de veter is een muis die door de gaatjes het huis in en uit kruipt. Waar gaat de muis nu heen?","Rijg eens kriskras over de hele kaart, als een spinnenweb, en hang er daarna een spin van papier in."],"variations":["Papieren bordje: pons gaatjes rondom en rijg er een zon met stralen of een spinnenweb van.","Herfst: knip een groot blad, een appel of een paddenstoel uit en rijg met bruin of oranje touw.","Kerst: knip een kerstboom uit en rijg er een rood lint doorheen als slinger."],"themes":[],"canStay":false,"pinQuery":"rijgkaarten karton zelf maken"},
  {"id":"pijpenrager-figuurtjes","title":"Pijpenrager-figuurtjes en ringen","emoji":"🐛","category":"motoriek","summary":"Buig, draai en krul pijpenragers tot ringen, brilletjes en beestjes en rijg er grote kralen op: lekker frunniken voor handige handjes.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"pijpenragers","note":"een bosje in verschillende kleuren"},{"id":"kralen","note":"grote houten kralen met een flink gat"}],"optional":[{"id":"pasta","note":"penne om te rijgen, als je geen kralen hebt"},{"id":"rietjes","note":"in stukjes geknipt om te rijgen"},{"id":"schaar","note":"een oude, om pijpenragers door te knippen"}],"steps":["Vouw de puntjes van elke pijpenrager een klein stukje om, zodat het ijzerdraadje niet prikt. Knip er een paar doormidden (dat doe jij).","Laat je kind eerst vrij buigen, draaien en krullen. Wat wordt het: een slang, een slak of een bloem?","Maak samen een ring: draai een halve pijpenrager om de vinger van je kind en draai de uiteinden in elkaar.","Rijg grote kralen op een pijpenrager. Buig het ene eind om, dan glijden ze er niet af.","Buig de pijpenrager met kralen tot een rups of armband, of draai vier halve pijpenragers in het midden samen tot een spin met acht poten.","Bewaar de figuurtjes in een doosje: morgen buig je ze gewoon om tot iets nieuws."],"ageTips":{"young":"Voor een driejarige zijn halve pijpenragers handiger dan hele. Kies kralen met grote gaten en laat het buigen vooral vrij: een kronkel is ook een kunstwerk.","old":"Laat je kleuter een brilletje maken: twee rondjes om een stift gedraaid, een bruggetje ertussen en pootjes voor achter de oren. Of buig samen letters en cijfers: welke letter lukt jou?"},"safety":["In pijpenragers zit ijzerdraad met scherpe puntjes: vouw alle uiteinden om, zeker bij een ring of brilletje (vingers en ogen).","Kralen passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Berg ze hoog op als er jongere kinderen in huis zijn."],"say":["Draai, draai, draai… een krul!","Wat kun jij van deze kronkel maken?","Ik zie dat je de kraal precies over het puntje schuift.","Hoe voelt een pijpenrager: zacht of kriebelig?","Wat heb je lang geprobeerd, en nu staat je spin op acht poten!"],"words":["buigen","draaien","krul","rond","recht","kronkel","rijgen","kriebelig"],"learn":["fijne-motoriek","creativiteit","concentratie"],"tips":["Pijpenragers gaan lang mee: buig ze na het spelen recht en bewaar ze met de kralen in een potje.","Geen kralen? Rijg stukjes rietje of penne: licht en makkelijk, en het gat is lekker groot."],"extenders":["Buig om de beurt iets voor, zoals een hart, een spiraal of een zigzag. Kan de ander het nabuigen?","Draai alle pijpenragers aan elkaar tot één lange slang en leg hem door de kamer: hoe lang wordt hij?","Maak van een doosje een huisje voor de figuurtjes en speel er een verhaaltje mee: de rups gaat op bezoek bij de spin."],"variations":["Kerst: draai een rode en een witte pijpenrager in elkaar en buig er een zuurstok of ster van voor in de boom.","Bloemenperk: buig bloemen met rondjes als blaadjes en prik ze in een bal speeldeeg.","Pasen: buig een paashaas met lange oren of een kuikentje en zet het in een eierdoos."],"themes":[],"canStay":false,"pinQuery":"pijpenragers figuurtjes buigen kind"},
  {"id":"was-ophangen","title":"De was ophangen","emoji":"🧦","category":"motoriek","summary":"Span een waslijn tussen twee stoelen en hang samen sokjes en poppenkleren op met wasknijpers: knijpen, paren zoeken en tellen in één.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":2,"places":["vloer"],"materials":[{"id":"touw","note":"±1,5 meter, als waslijn"},{"id":"stoelen","note":"twee, ruim een meter uit elkaar"},{"id":"wasknijpers","note":"10-20 stuks"},{"id":"sokken","note":"of poppenkleertjes, washandjes en kleine doekjes"}],"optional":[{"id":"wasmand","note":"voor de schone ‘was’"},{"id":"poppen","note":"om na het ophangen weer aan te kleden"}],"steps":["Zet twee stoelen ruim een meter uit elkaar en knoop een touw strak van stoelpoot naar stoelpoot, net onder de zitting: laag genoeg om bij te kunnen.","Doe de ‘was’ in een wasmand en zet de knijpers in een bakje ernaast.","Laat zien hoe het werkt: sok over het touw, knijper erop. Nu jij!","Zoek samen de paren: waar is de andere sok met streepjes? Hang ze naast elkaar.","Hang de was op kleur of van klein naar groot, en tel hoeveel knijpers je nodig hebt.","Haal alles eraf als de was ‘droog’ is, vouw samen op en ruim het touw meteen weg."],"ageTips":{"young":"Geef een tweejarige grote washandjes of doekjes en de slapste knijpers, en hang jij het eerste stuk op. Alleen over het touw hangen, zonder knijper, is ook al goed.","old":"Laat je kleuter in een patroon ophangen (sok, washandje, sok…), paren zoeken met de ogen dicht door alleen te voelen, of een poppenwasserette beginnen met een prijslijst."},"safety":["Een gespannen touw is een wurg- en struikelgevaar: hang het laag, niet in een looproute, en haal het direct weg na het spelen.","Knijpers knijpen ook in vingertjes en oorlelletjes: laat ze niet aan neus, oren of lippen hangen."],"say":["Sok… knijper… vast!","Waar is de andere sok met stippen?","Ik zie dat je de knijper helemaal openhoudt voor je hem loslaat.","Welke sok is het grootst: die van papa of die van jou?","Wat heb jij hard gewerkt, de hele was hangt!"],"words":["ophangen","knijpen","paar","hetzelfde","groot","klein","waslijn","eraf"],"learn":["fijne-motoriek","rekenen","taal"],"tips":["Echt helpen kan ook: laat je kind na de echte was sokken en washandjes aangeven of zelf aan het droogrek hangen.","Gebruik oude sokken van het hele gezin: grote en kleine door elkaar maken sorteren en vergelijken extra leuk."],"extenders":["Laat een knuffel bestellingen doen: je kind haalt precies het gevraagde van de lijn, zoals de rode sok of het kleinste washandje.","Laat het waaien: wapper met een tijdschrift of blaas hard. Blijft alles hangen, of zijn er extra knijpers nodig?","Zet een paar poppen of knuffels klaar die nieuwe kleren nodig hebben: haal de ‘droge’ was van de lijn en kleed ze aan."],"variations":["Poppenwas: was eerst poppenkleertjes in een sopje (dat wordt wel nat) en hang ze dan op.","Kunstlijn: hang de tekeningen van deze week aan de lijn, als een echte tentoonstelling.","Kleurenlijn: hang eerst alleen rode dingen op, dan alleen blauwe."],"themes":[],"canStay":false,"pinQuery":"was ophangen wasknijpers peuter spel"},
  {"id":"uitpakfeest","title":"Uitpakfeest: pakjes openscheuren","emoji":"🎁","category":"motoriek","summary":"Pak bekend speelgoed in met krant en plakband en laat je kind alles openscheuren: een feestje vol verrassingen en een goede oefening voor pakjesavond.","ageMin":1,"ageMax":3,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["vloer"],"materials":[{"id":"klein-speelgoed","note":"of knuffels en blokken die je kind al kent; groter dan een wc-rolletje"},{"id":"kranten","note":"of inpakpapier, keukenpapier of oude tekeningen"},{"id":"plakband","note":"hoe meer plakband, hoe spannender"}],"optional":[{"id":"dozen","note":"een doosje in een doos maakt het extra spannend"},{"id":"stoffen-tas","note":"als ‘zak van Sinterklaas’"},{"id":"wasmand","note":"om het papier in te mikken"},{"id":"muziek","note":"voor het pakjesspel"}],"steps":["Pak 5-8 bekende speeltjes in met krant of papier. Varieer: één los gevouwen, één met veel plakband, één in een doosje.","Leg de pakjes in een zak of wasmand en ga er samen bij zitten.","Laat je kind een pakje kiezen. Voel en schud eerst: wat zou erin zitten?","Scheur een klein randje los als je kind niet weet waar te beginnen, en laat de rest zelf doen.","Vier elke vondst: daar is beer! Speel er even mee voordat het volgende pakje aan de beurt is.","Prop het papier samen tot ballen en mik ze in de wasmand: opruimen is ook een spel."],"ageTips":{"young":"Pak voor een dreumes van 1 losjes in met één laag zacht papier zonder plakband, of stop het speeltje in een papieren zakje. Scheur alvast een beginnetje.","old":"Een driejarige kan raden wat erin zit door te voelen, de pakjes tellen en zelf een pakje inpakken voor een knuffel of voor jou. Of speel het pakjesspel: uitpakken zolang de muziek speelt."},"safety":["Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3: pak alleen grote speeltjes in.","Ruim snippers papier en propjes plakband meteen op: een dreumes stopt ze graag in de mond.","Pak niet in met plastic zakken of huishoudfolie: gevaarlijk als het over neus en mond komt."],"say":["Scheur! Wat is het?","Wat zou erin zitten? Schud maar eens.","Ik hoor iets rammelen… jij ook?","Hoe voelt het pakje: zacht, hard of rond?","Wat zoek je slim naar een randje om te beginnen!"],"words":["uitpakken","scheuren","pakje","verrassing","zacht","hard","rammelen","open"],"learn":["fijne-motoriek","zintuigen","taal","samen"],"tips":["Pak in terwijl je kind slaapt, of laat je kind juist meehelpen door stukjes plakband aan te geven.","Oude kranten, folders en tekeningen zijn prima inpakpapier, en dezelfde speeltjes kun je steeds opnieuw inpakken."],"extenders":["Verstop de laatste pakjes in de kamer, onder een kussen of achter het gordijn: eerst zoeken, dan uitpakken!","Leg de uitgepakte speeltjes op een rij, pak er stiekem één weer in en laat je kind raden welke er weg is.","Laat je kind na het uitpakken elk speeltje naar huis brengen: de beer naar het bed, de auto naar de speelgoedbak."],"variations":["Sinterklaas: stop de pakjes in een kussensloop als zak van Sinterklaas, zing een liedje en oefen voor pakjesavond.","Kerst: leg de pakjes onder de kerstboom en pak er samen één per dag uit.","Verjaardag: laat een knuffel jarig zijn: pakjes uitpakken, ‘dank je wel’ zeggen en samen zingen.","Lagenpakje: pak een speeltje in, en dat pakje weer, en weer: hoeveel lagen kom je tegen?"],"themes":["sinterklaas","kerst","verjaardag"],"canStay":false,"pinQuery":"pakjes uitpakken spel dreumes"},
  {"id":"stickers-op-lijnen","title":"Stickers plakken op lijnen","emoji":"⭐","category":"motoriek","summary":"Jij tekent lijnen, je kind plakt er stickers op: sticker na sticker langs een golf, een zigzag of de eerste letter van de naam.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[10,20],"supervision":2,"soloFrom":3,"cleanupMinutes":1,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"stickers","note":"ronde stippenstickers werken het best"},{"id":"papier","note":"A4 of groter"},{"id":"stiften","note":"een dikke, donkere stift voor de lijnen"}],"optional":[{"id":"groot-papier","note":"voor lange lijnen op tafel of de vloer"},{"id":"schilderstape","note":"om het vel vast te plakken"}],"steps":["Teken met een dikke stift een paar lijnen op een vel: een rechte, een golf, een zigzag en een grote cirkel.","Plak het vel met schilderstape vast op tafel, dan schuift het niet weg.","Trek bij het stickervel alvast het restpapier rond de stickers weg: dan steken ze uit en zijn ze makkelijker te pakken.","Laat zien hoe je een sticker met duim en wijsvinger lostrekt en precies op de lijn plakt.","Volg samen de lijn, sticker na sticker, als stapstenen. Waar gaat de golf naartoe?","Zet de datum op het vel en bewaar het: over een paar maanden zie je hoeveel preciezer je kind plakt."],"ageTips":{"young":"Begin bij een tweejarige met één korte, dikke rechte lijn en grote stickers. Plakt je peuter ernaast? Prima: het gaat om het lostrekken en plakken.","old":"Teken voor je kleuter de eerste letter van de naam, cijfers of een doolhof en plak in een patroon (rood, geel, rood…). Hoeveel stickers passen er op de cirkel?"},"safety":["Stickers en snippers restpapier zijn klein en blijven makkelijk plakken in een mond of keel: blijf bij je peuter en ruim losse stickers direct op."],"say":["Plak! Nog een!","Ik zie dat je precies op de golf plakt.","Waar gaat de lijn naartoe: omhoog of omlaag?","Hoeveel stickers passen er op de cirkel, denk je?","Wat kijk je goed waar je plakt, je neemt echt de tijd."],"words":["lijn","golf","zigzag","rondje","op","naast","omhoog","omlaag"],"learn":["fijne-motoriek","concentratie","rekenen","taal"],"tips":["Ronde stippenstickers vind je goedkoop in de kantoorboekhandel en ze zijn perfect voor kleine vingers.","Geen stickers? Teken stipjes op stukjes schilderstape en laat je kind die op de lijnen plakken."],"extenders":["Teken tussendoor nieuwe lijnen erbij: een trap, een slakkenhuis of een dak op een huis.","Spreek per lijn een kleur af: groene stickers op de golf, rode op de zigzag.","Hang het vel aan de deur of het raam: plakken op een rechtop hangend vel is een nieuwe uitdaging voor kleine vingers."],"variations":["Kerst: teken een kerstboom en plak stickers als ballen langs de takken.","Herfst: teken een kale boom en plak gele en oranje stickers als blaadjes.","Stickerweg: teken een lange slingerweg op groot papier, plak hem vol en laat er daarna een autootje over rijden."],"themes":[],"canStay":false,"pinQuery":"stickers plakken op lijnen peuter"},
  {"id":"bestekla-sorteren","title":"De bestekla sorteren","emoji":"🥄","category":"motoriek","summary":"Gooi lepels en vorken door elkaar in een kom en laat je peuter alles terugsorteren: echt keukenwerk dat kleine handen lang bezighoudt.","ageMin":2,"ageMax":3,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[20,30],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["keuken","vloer","tafel"],"materials":[{"id":"lepel","note":"eetlepels, theelepels en een paar houten lepels"},{"id":"vork","note":"gewone vorken; messen leg je weg"},{"id":"kom","note":"een grote kom of bak om alles door elkaar in te doen"},{"id":"muffinvorm","note":"of de lege bestekbak uit de la, of een paar bakjes"}],"optional":[{"id":"handdoek","note":"in de kom en onder de muffinvorm: dat dempt het gekletter"},{"id":"kinderservies","note":"onbreekbare bordjes om daarna de tafel te dekken"},{"id":"plastic-bekers","note":"om lepels rechtop in te zetten, zoals in een bestekpot"}],"steps":["Haal de messen, de kaasschaaf en andere scherpe dingen uit de bestekla en leg ze hoog weg.","Doe de lepels en vorken door elkaar in een grote kom en zet de lege bestekbak of een muffinvorm ernaast.","Leg in elk vak alvast één voorbeeld: een vork hier, een grote lepel daar, een theelepel ernaast.","Laat je peuter alles één voor één sorteren. Benoem wat je ziet: een vork met prikkers, een grote lepel, een kleintje.","Kijk samen of alles klopt. Ligt er een vork tussen de lepels? Vraag: hoort die hier? En laat je kind het zelf verbeteren.","Gooi alles weer door elkaar en begin opnieuw: herhalen is voor een peuter juist het leukste.","Dek tot slot samen de tafel: bij elk bord een vork en een lepel. Wat overblijft, gaat terug in de la."],"ageTips":{"young":"Begin bij een tweejarige met twee soorten die goed van elkaar verschillen, zoals grote lepels en vorken, en twee vakken. Alles erin en eruit doen hoort er ook bij: dat is op deze leeftijd precies goed.","old":"Een driejarige kan ook op grootte sorteren (theelepel, eetlepel, opscheplepel), per vak tellen of de tafel dekken voor het hele gezin: hoeveel vorken hebben we nodig?"},"safety":["Haal alle messen en scherpe dingen (kaasschaaf, schilmesje, kurkentrekker) uit de la voordat je kind erbij komt, en bewaar ze buiten bereik.","Laat je kind met vorken zitten in plaats van rondlopen: wie valt met een vork in de hand, kan zich lelijk prikken, ook in het gezicht.","Laat je peuter bij het tafeldekken alleen bestek en onbreekbare bordjes neerleggen; glazen en porselein zet jij neer."],"say":["Lepel! Nog een lepel!","Ik zie een grote lepel en een kleine lepel. Waar moet de kleine naartoe?","Hoe weet jij dat dit een vork is?","Je zocht net zo lang tot de laatste vork in het goede vak lag.","Hoeveel vorken hebben we nodig als we met z’n drieën eten?"],"words":["lepel","vork","groot","klein","hetzelfde","sorteren","erin","tellen"],"learn":["rekenen","fijne-motoriek","concentratie","taal"],"tips":["Sorteer vlak voor het eten: dan is de tafel dekken meteen de afsluiting. Vanaf 3 jaar kan dit prima op de keukenvloer terwijl jij kookt.","Heeft het bestek op de grond gelegen of in de mond gezeten? Doe het na afloop even in de vaatwasser of een sopje."],"extenders":["Voeg nieuw keukengerei toe, zoals een garde, een pollepel of een spatel, en vraag: waar moet die wonen?","Leg een theedoek over de kom: kan je kind op de tast een vork vinden, zonder te kijken?","Zet een rij bekers neer en laat je kind in elke beker precies één lepel zetten, of precies drie.","Leg alle lepels op een rij van groot naar klein, als een trap. Waar past de theelepel?","Laat je kind de tafel dekken voor de knuffels: één bord, één lepel en één vork per knuffel."],"variations":["Echt klusje: laat je peuter het schone bestek uit de vaatwasser in de la sorteren (de messen haal jij er eerst uit).","Sokkenmand: sorteer een mand schone sokken en zoek samen de paren bij elkaar.","Boodschappen: laat je kind na het boodschappen doen de pakken, blikken en groente sorteren. Wat moet in de koelkast?"],"themes":[],"canStay":false,"pinQuery":"bestek sorteren peuter keuken"},
  {"id":"bakjeskast","title":"De bakjeskast: deksels zoeken en stapelen","emoji":"🥡","category":"motoriek","summary":"Uitpakken, stapelen, in elkaar schuiven en het goede deksel zoeken: de kast met plastic bakjes is voor een dreumes één grote puzzel.","ageMin":1,"ageMax":3,"mess":2,"wet":false,"dirty":false,"prepMinutes":2,"duration":[15,30],"supervision":2,"soloFrom":2,"cleanupMinutes":5,"noise":2,"energy":1,"places":["keuken","vloer"],"materials":[{"id":"potjes","note":"plastic bakjes met deksel in allerlei maten, geen glas"},{"id":"bakjes","note":"lege boterkuipjes en yoghurtbekers om in elkaar te zetten"}],"optional":[{"id":"plastic-bekers","note":"of maatbekers die in elkaar passen"},{"id":"duplo","note":"een groot blok om te verstoppen"},{"id":"lepel","note":"een houten lepel om op te trommelen"},{"id":"sokken","note":"een opgerolde sok om in een bakje te stoppen"}],"steps":["Kijk de la of kast met bakjes even na: haal glas, kleine dopjes en doosjes folie met een scherpe kartelrand eruit.","Zet je kind voor de open la, of kiep alle bakjes en deksels op een kleed op de keukenvloer.","Laat je dreumes eerst alles zelf uitpakken, omgooien, rammelen en bekijken: dat is al het eerste spel.","Laat zien hoe een klein bakje in een groot bakje past, en hoe je er een toren van bouwt.","Zoek samen deksels bij de bakjes: past deze? Nee? Probeer een andere. Draai het deksel ook eens om.","Verstop een blok onder een omgekeerd bakje en laat je kind het zoeken.","Ruim samen op: je kind geeft de bakjes één voor één aan en jij zet ze terug in de la."],"ageTips":{"young":"Een dreumes van 1 vindt uitpakken, omgooien en erop slaan al spannend genoeg. Geef vooral grote, lichte bakjes en een paar deksels die makkelijk passen, en benoem: open, dicht, erin!","old":"Een driejarige kan alle bakjes van groot naar klein in elkaar zetten, bij elk bakje het goede deksel zoeken of raden onder welk van drie bakjes het blok zit."},"safety":["Kijk de la na voordat je kind erbij komt: geen glazen bakjes, geen kleine dopjes die door een wc-rolletje passen en geen doosjes folie met een scherpe kartelrand.","Haal bakjes met een barst of een scherpe breukrand eruit: daar kan je kind zich aan snijden.","Laat je kind spelen uit de buurt van het fornuis en de oven als jij kookt, en zet een kinderslot op de kastjes met schoonmaakmiddelen."],"say":["Open! Dicht!","Past dit deksel? Probeer maar!","Ik zie een hoge toren. Hoe hoog kan die nog worden?","Je draaide het deksel net zo lang tot het paste. Goed volgehouden!","Waar is het blok gebleven? Onder welk bakje?"],"words":["open","dicht","erin","eruit","deksel","groot","klein","passen"],"learn":["fijne-motoriek","ontdekken","rekenen","concentratie"],"tips":["Maak er een vaste bakjesla van: één lage la of kast die je kind altijd leeg mag halen. Dan blijven de andere kastjes dicht en weet je kind precies waar het mag spelen.","Speel op een kleed of handdoek: de bakjes glijden minder weg en het klettert minder."],"extenders":["Leg er nieuwe dingen bij om in te stoppen: een opgerolde sok, een houten lepel of een paar blokken. Wat past erin, wat niet?","Stop een blok in een dicht bakje en schud: hoor je het? Laat je kind het deksel eraf halen.","Bouw samen een toren van omgekeerde bakjes en laat je kind de toren omgooien. Nog een keer, nu hoger!","Geef een houten lepel: nu zijn de bakjes trommels. Welke klinkt hard, welke zacht?","Zet de bakjes op een rij van groot naar klein en laat je kind er een treintje van maken."],"variations":["Pannenkast: zoek bij elke pan het goede deksel (alleen koude pannen, ver van het fornuis).","Schroefdoppen: vanaf 3 jaar lege plastic flesjes en potjes met een schroefdop: open draaien en weer dicht.","Verjaardag: stapel de bakjes tot een taart, zet er een wc-rolletje als kaars op en zing samen ‘Lang zal ze leven’."],"themes":[],"canStay":false,"pinQuery":"plastic bakjes deksels dreumes spel"},
  {"id":"sjaaltjesdoos","title":"Sjaaltjes trekken uit een doos","emoji":"🧣","category":"motoriek","summary":"Trek, trek, en er komt maar geen eind aan: aan elkaar geknoopte sjaaltjes uit een lege tissuedoos trekken is voor een dreumes pure toverij.","ageMin":1,"ageMax":2,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[15,20],"supervision":2,"soloFrom":null,"cleanupMinutes":2,"noise":1,"energy":1,"places":["vloer"],"materials":[{"id":"doekjes","note":"5-8 dunne sjaaltjes, hydrofiele doeken of zakdoeken"},{"id":"verpakkingen","note":"een lege tissuedoos, het plastic randje eruit"}],"optional":[{"id":"knuffels","note":"een kleine knuffel als verrassing onderin"},{"id":"wc-rollen","note":"een keukenrolkoker om de sliert doorheen te trekken"},{"id":"muziek","note":"om daarna met de sjaaltjes te dansen"}],"steps":["Haal het plastic randje uit een lege tissuedoos en knoop 5-8 sjaaltjes of doeken met kleine knoopjes aan elkaar tot een lange sliert.","Prop de sliert losjes in de doos en laat alleen een puntje uit de opening steken.","Laat je dreumes aan het puntje trekken: er komt steeds meer uit! Noem bij elk nieuw sjaaltje de kleur.","Prop de sjaaltjes samen terug: jij houdt de doos vast, je kind duwt ze erin. En dan weer trekken!","Speel tussendoor kiekeboe: leg een sjaaltje over je hoofd of over een knuffel en trek het er samen af.","Knoop er één los en gooi het omhoog: kijk hoe het langzaam naar beneden zweeft. Kun je het vangen?","Maak na afloop alle knopen los en berg de sjaaltjes en de doos op, buiten bereik van je kind."],"ageTips":{"young":"Een dreumes van 1 trekt vooral graag. Prop de sjaaltjes niet te strak in de doos, zodat ze er makkelijk uit glijden, en stop ze zelf terug met een spannend ‘en… weg!’.","old":"Een tweejarige kan de sjaaltjes zelf terugstoppen (lastiger dan het lijkt), de kleuren benoemen en tellen: één, twee, drie sjaaltjes. Ruil ook eens: je peuter stopt ze erin en jij trekt."},"safety":["Een lange sliert van stof kan om de nek raken: speel alleen als je erbij bent en maak de knopen los zodra het spel klaar is. Nooit mee in bed of in de box.","Haal het plastic randje uit de tissuedoos: een dreumes trekt het er zo uit en stopt het in de mond.","Gebruik geen sjaaltjes met kraaltjes, pailletten of franjes waar je kind kleine stukjes af kan trekken."],"say":["Trek! Nog meer!","Wat komt er nu? Een rood sjaaltje!","Waar ben ik? Kiekeboe!","Wat trek je goed door, er komt geen eind aan!","Voel eens: zacht, hè?"],"words":["trekken","erin","eruit","zacht","lang","kiekeboe","weg","daar"],"learn":["fijne-motoriek","ontdekken","taal","zintuigen"],"tips":["Een lege doos van billendoekjes met klepje werkt ook: klepje open, klepje dicht is voor een dreumes een spelletje op zich.","Geen sjaaltjes? Knip een oud T-shirt in repen of gebruik washandjes en theedoeken."],"extenders":["Knoop er een nieuw sjaaltje of een washandje tussen: een andere kleur of een ander gevoel maakt het weer spannend.","Stop een knuffel als laatste in de doos: wat komt er na het laatste sjaaltje tevoorschijn?","Trek de sliert door een keukenrolkoker en laat je kind er aan de andere kant aan trekken.","Zet muziek aan en dans samen met de sjaaltjes: zwaaien, omhoog gooien en vangen.","Verstop een speeltje onder een sjaaltje op de vloer en laat je dreumes het zoeken."],"variations":["Voeldoos: knoop doekjes van verschillende stof aan elkaar, zoals zijde, badstof, vilt en ribfluweel.","Regenboog: knoop sjaaltjes in de kleuren van de regenboog aan elkaar en benoem ze samen.","Kerst: pak de tissuedoos in als cadeautje en trek er rode, groene en witte doekjes uit."],"themes":[],"canStay":false,"pinQuery":"sjaaltjes tissuedoos dreumes spel"},
  {"id":"weven-karton","title":"Weven op een kartonnen weefraam","emoji":"🧶","category":"motoriek","summary":"Span touw om een stuk karton en weef er wol, lint en stroken papier doorheen: over, onder, over, onder, tot er een eigen kleedje ontstaat.","ageMin":4,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[45,50],"supervision":3,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"karton","note":"±20 x 25 cm, liefst dik (verhuisdoos of achterkant van een schrijfblok)"},{"id":"touw","note":"stevig touw voor de schering, plus restjes wol en lint om mee te weven"},{"id":"schaar","note":"voor de inkepingen (dat doe jij)"},{"id":"plakband","note":"om begin en eind van het touw vast te plakken"},{"id":"gekleurd-papier","note":"om stroken van ±2 cm breed van te knippen"}],"optional":[{"id":"kinderschaar","note":"om zelf stroken te knippen"},{"id":"crepepapier","note":"in stroken: kreukelt mooi"},{"id":"vilt","note":"stofrestjes in repen"},{"id":"ijsstokjes","note":"als weefnaald: wikkel de wol eromheen"},{"id":"veren","note":"en andere schatten om ertussen te steken"}],"steps":["Knip in de boven- en onderkant van het karton 8-10 inkepingen van 1 cm diep, ±2 cm uit elkaar (dat doe jij).","Plak het touw achterop vast en wikkel het om het karton, telkens door de volgende inkeping boven en onder. Plak het eind ook vast: dat is de schering.","Zoek samen weefspullen bij elkaar: restjes wol en lint, repen stof, crêpepapier. Je kleuter knipt zelf stroken papier met de kinderschaar.","Laat zien hoe het werkt: over de eerste draad, onder de tweede, over, onder… tot de overkant. Zeg het hardop als een liedje.","Begin de volgende rij andersom: waar je eerst over ging, ga je nu onder. Duw elke rij met je vingers omlaag tegen de vorige.","Laat je kind steeds zelf kiezen wat erin gaat: een strook papier, een stuk lint, een draad wol. Uitsteken mag, het hoeft niet netjes.","Laat het werkje op het karton zitten als schilderijtje, of knip de draden achterop los en knoop de uiteinden twee aan twee vast (dat doe jij)."],"ageTips":{"young":"Maak voor een vierjarige minder inkepingen die verder uit elkaar liggen (bijv. 6, ±3 cm uit elkaar) en begin met brede stroken papier: stevig en makkelijk te weven. Wol komt later.","old":"Een vijfjarige kan een patroon bedenken (rood, blauw, rood, blauw), met een ijsstokje als weefnaald wol weven of zelf de schering opspannen. Ook leuk: weef een kleedje voor een knuffel."},"safety":["Lange draden wol en touw kunnen om de nek raken: knip ze niet langer dan een armlengte en laat geen losse draden rondslingeren als er een jonger broertje of zusje rondkruipt.","Knip de inkepingen zelf met een gewone schaar; je kleuter knipt alleen stroken papier met een kinderschaar met ronde punt."],"say":["Over, onder, over, onder!","Waar gaat deze strook nu: over of onder de draad?","Ik zie dat je elke rij goed omlaag duwt. Zo wordt het een stevig kleedje.","Welke kleur kies je hierna?","Je bleef proberen tot de draad erdoor was. Dat is echt weven!"],"words":["over","onder","draad","rij","weven","patroon","strook","stevig"],"learn":["fijne-motoriek","concentratie","rekenen","creativiteit"],"tips":["Wikkel een stukje plakband om het uiteinde van de wol: dan prik je veel makkelijker tussen de draden door.","Doe alle weefspullen in een schoenendoos naast het weefraam: dan kiest je kind zelf en is opruimen in één keer klaar."],"extenders":["Leg er nieuwe weefschatten bij: een veer, een strook aluminiumfolie, een rietje of een takje. Wat past ertussen?","Bedenk samen een patroon en maak het af: twee rijen geel, één rij blauw, en dan weer opnieuw.","Weef om de beurt een rij: jij kiest de kleur voor je kind, je kind kiest de kleur voor jou.","Geef een ijsstokje als weefnaald: wikkel de wol eromheen en schuif het stokje over en onder de draden.","Maak er samen een verhaal bij: wordt het een vliegend tapijt, een dekentje voor de pop of een vlag voor een kasteel?"],"variations":["Bordje weven: knip een oneven aantal inkepingen rond een papieren bordje, span de draden over het midden en weef in een rondje: een zon of een spinnenweb.","Herfst: weef met bladeren, gras, veertjes en takjes die je eerder buiten hebt verzameld.","Groot weven: span touw tussen de poten van een omgekeerde stoel of een wasrek en weef er samen sjaals en repen stof doorheen.","Papierweven: knip sneden in een dubbelgevouwen vel papier en vlecht er stroken in een andere kleur doorheen: een eigen onderlegger voor aan tafel."],"themes":[],"canStay":true,"stayTips":"Laat het weefraam met een bakje weefspullen op een plank of kast liggen: er kan niets uitdrogen of omvallen. Wikkel losse draden om het karton, zodat er geen lange slierten rondslingeren.","pinQuery":"weven karton weefraam kind"},
  {"id":"figuren-leggen","title":"Figuren leggen met papieren vormen","emoji":"🔺","category":"motoriek","summary":"Een stapel papieren rondjes, vierkanten, driehoeken en stroken wordt een huis, een robot of een raket: schuiven, leggen en steeds opnieuw beginnen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"gekleurd-papier","note":"3-4 vellen in verschillende kleuren"},{"id":"schaar","note":"voor jou: knip 4 lagen tegelijk, dat gaat snel"},{"id":"papier","note":"of karton, als ondergrond om op te leggen en te plakken"},{"id":"lijmstift","note":"om het lievelingsfiguur op te plakken"}],"optional":[{"id":"stiften","note":"om ogen, ramen of wielen bij te tekenen"},{"id":"kinderschaar","note":"voor kleuters die zelf stroken en vierkanten knippen"},{"id":"potlood","note":"om de omtrek van een figuur na te tekenen"},{"id":"enveloppen","note":"om de vormen in te bewaren"}],"steps":["Vouw een vel gekleurd papier in vieren en knip door alle lagen tegelijk: stroken, vierkanten, rondjes en driehoeken (een vierkant schuin doormidden). Doe dat met 3-4 kleuren.","Leg alle vormen door elkaar op tafel en benoem ze samen: rondje, vierkant, driehoek, strook. Welke is groot, welke klein?","Leg zelf een eenvoudig voorbeeld, zoals een huis van een vierkant met een driehoek erop. Kan je kind het namaken?","Laat je kind daarna vrij leggen: een robot, een raket, een poes, een bloem. Vraag wat het wordt, maar geef geen opdracht.","Schuif alles weer door elkaar en begin opnieuw: leggen, bekijken, vertellen en weer omgooien.","Plak aan het eind het lievelingsfiguur op een vel papier en laat je kind er met stift ogen, wielen of een lucht bij tekenen.","Bewaar de losse vormen in een envelop voor de volgende keer."],"ageTips":{"young":"Geef een driejarige grote vormen in twee of drie soorten en leg samen eerst een huis, een zon (een rondje met stroken) en een treintje. Benoem steeds de vorm: driehoek, dak!","old":"Een kleuter kan een voorbeeld precies namaken, zelf vormen knippen of een hele straat leggen met huizen, bomen en een auto. Of tel samen: hoeveel driehoeken heeft je raket?"},"safety":["Knip de vormen zelf met een gewone schaar; je kleuter knipt alleen met een kinderschaar met ronde punt.","De dop van de lijmstift past door een wc-rolletje: zet de dop meteen terug en leg de lijmstift hoog weg als er een jonger broertje of zusje rondkruipt."],"say":["Driehoek! Dat wordt het dak.","Wat wordt dit? Vertel eens.","Ik zie twee rondjes naast elkaar. Zijn dat ogen of wielen?","Je schoof het dak net zo lang tot het precies paste.","Wat gebeurt er als je de driehoek omdraait?"],"words":["rondje","vierkant","driehoek","strook","punt","naast","bovenop","omdraaien"],"learn":["rekenen","fijne-motoriek","creativiteit","concentratie"],"tips":["Leg een vel zwart papier of een donkere theedoek als ondergrond: de kleuren springen eruit en de vormen glijden minder weg.","Maak een foto van elk figuur voordat het weer omgegooid wordt: zo heb je een boekje vol robots en raketten, zonder te plakken.","Knip de vormen een keer uit karton van een cornflakesdoos: die zijn steviger en gaan veel langer mee."],"extenders":["Leg een figuur op een vel papier, trek de buitenrand om met potlood en haal de vormen weg: kan je kind de omtrek weer precies vullen?","Speel ‘wat is er veranderd?’: je kind kijkt naar een figuur en doet de ogen dicht, jij pakt één vorm weg of verschuift er een.","Geef een opdracht met een getal: maak iets met precies vijf vormen, of iets van alleen rondjes.","Leg om de beurt één vorm: samen maken jullie een figuur waarvan niemand weet wat het wordt.","Leg een figuur half en laat je kind raden wat het wordt en het afmaken."],"variations":["Kerst: leg een kerstboom van groene driehoeken met rondjes als ballen en een ster bovenop.","Herfst: knip bladvormen uit bruin, rood en oranje papier en leg er een boom, een egel of een uil mee.","Vilt: knip de vormen uit vilt en leg ze op een oude deken of een groot stuk vilt: dan blijven ze beter liggen.","Spiegelen: leg een halve vlinder of een half gezicht en laat je kind de andere helft precies hetzelfde leggen."],"themes":[],"canStay":false,"pinQuery":"vormen leggen papier kleuter"},
  {"id":"rammelaars","title":"Rammelaars maken van lege flesjes","emoji":"🎶","category":"muziek","summary":"Vul lege flesjes met rijst of pasta, plak de dop goed dicht en ontdek samen hoe elke vulling anders klinkt.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["tafel","vloer"],"materials":[{"id":"plastic-flesjes","note":"kleine flesjes met dop, vanbinnen goed droog"},{"id":"rijst","note":"2-3 el per flesje"},{"id":"pasta","note":"een handje penne of macaroni"},{"id":"ducttape","note":"om de dop rondom dicht te plakken"}],"optional":[{"id":"trechter","note":"om te vullen zonder te morsen"},{"id":"stickers","note":"om te versieren"},{"id":"touw","note":"korte lintjes (max. 15 cm) om de flessenhals, voor een feestelijk tintje"}],"steps":["Spoel de flesjes om en laat ze helemaal drogen, anders plakt de vulling aan de binnenkant.","Zet kommetjes met rijst en pasta klaar en laat je kind met een lepel en een trechter de flesjes vullen. Een kwart vol is genoeg.","Draai de dop er stevig op en plak hem rondom dicht met een paar lagen ducttape. Dat doe jij.","Schud samen: hoe klinkt rijst en hoe klinkt pasta? Welke klinkt hard en welke zacht?","Versier de flesjes met stickers en zet een liedje op: schud mee op de maat!","Controleer de flesjes voor elk gebruik op scheurtjes en een losse dop, en bewaar ze bij het speelgoed."],"ageTips":{"young":"Een dreumes vult nog niet zelf: maak de rammelaars vooraf en laat je kind vooral schudden, rollen en luisteren. In een doorzichtig flesje zie je de rijst ook nog dansen.","old":"Laat je kleuter raden wat erin zit door alleen te luisteren: plak een paar flesjes helemaal af met tape. Of zet ze op een rij van zacht naar hard."},"safety":["Rijst, pasta en de dop zelf zijn te klein voor kinderen onder de 3 (alles wat door een wc-rolletje past): plak de dop rondom vast en vul de flesjes zelf als je dreumes alles in de mond stopt.","Controleer de rammelaar voor elk gebruik op scheurtjes en een losse dop, en gooi een kapot flesje meteen weg.","Gebruik alleen plastic flesjes, geen glazen potjes: die breken als ze vallen."],"say":["Schud, schud! Hoor je dat?","Hoe klinkt de rijst? En hoe klinkt de pasta?","Wat denk je: welke klinkt het hardst?","Ik hoor dat je heel zachtjes schudt… en nu heel hard!","Wat schud je goed op de maat mee!"],"words":["schudden","hard","zacht","snel","langzaam","rammelen","luisteren"],"learn":["zintuigen","fijne-motoriek","ontdekken"],"tips":["Kleine flesjes van drinkyoghurt of sap passen het best in kleine handjes.","Vul de flesjes boven een dienblad of grote bak: gemorste rijst schud je zo terug in het kommetje."],"extenders":["Vul nog een flesje met iets nieuws, zoals linzen, ontbijtringetjes of een propje aluminiumfolie. Welke klinkt het hardst?","Speel stop en start: schud zolang de muziek speelt en bevries zodra hij stopt.","Verstop je achter de bank of een deur en schud: hoort je kind waar het geluid vandaan komt?"],"variations":["Carnaval: maak een hele rammelband en loop schuddend in optocht door de kamer.","Koningsdag: versier de flesjes met oranje en rood-wit-blauwe tape en lintjes.","Geluidsmemory: maak steeds twee flesjes met dezelfde vulling en plak ze af. Welke twee klinken hetzelfde?"],"themes":["carnaval","koningsdag"],"canStay":false,"pinQuery":"rammelaar maken fles rijst peuter"},
  {"id":"pannenorkest","title":"Pannenorkest en dozentrommel","emoji":"🥁","category":"muziek","summary":"Pannen, deksels en een doos worden een complete band: trommel samen hard en zacht, snel en langzaam, en ontdek hoe alles anders klinkt.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[10,20],"supervision":2,"soloFrom":2,"cleanupMinutes":2,"noise":3,"energy":2,"places":["vloer","keuken"],"materials":[{"id":"pan","note":"een paar pannen en deksels, koud uit de kast"},{"id":"lepel","note":"houten lepels als trommelstokken"},{"id":"dozen","note":"een stevige doos als trommel"}],"optional":[{"id":"muziek","note":"om op mee te spelen"},{"id":"plastic-bekers","note":"omgekeerd klinken ze weer anders"}],"steps":["Zet een paar pannen, deksels en een stevige doos ondersteboven op de vloer en geef je kind twee houten lepels.","Ontdek samen: hoe klinkt de grote pan, en hoe klinkt het kleine deksel? En de doos?","Speel eerst hard en daarna heel zacht, als een muisje. Dan snel als regen en langzaam als een olifant.","Speel om de beurt: jij tikt een ritme (tik-tik-boem) en je kind speelt het na. Daarna mag je kind voorspelen.","Zet een liedje op en speel samen mee. Stopt de muziek? Dan stoppen jullie ook!","Ruim samen op door alles op te stapelen: past het kleine deksel op de grote pan?"],"ageTips":{"young":"Een dreumes slaat eerst vooral hard: geniet ervan en doe mee. Houten lepels zijn lichter en zachter dan metalen, en ondersteboven op de vloer staan de pannen stevig.","old":"Laat je kleuter dirigent zijn: armen omhoog is hard spelen, armen omlaag is zacht. Of trommel de lettergrepen van ieders naam: Sa-ra, Bram, Mo-ham-med."},"safety":["Gebruik alleen koude pannen uit de kast, nooit van het fornuis, en houd glazen deksels erbuiten: die kunnen breken.","Een metalen pan klinkt heel hard voor kleine oortjes: speel niet vlak bij het hoofd en wissel af met de zachtere doos."],"say":["Boem! Boem! Hoor je dat?","Welke klinkt het hardst: de pan of de doos?","Kun je ook heel zachtjes spelen, als een muisje?","Ik hoor dat je precies mijn ritme nadoet: tik-tik-boem!","Wat blijf je goed op de maat, ook als het liedje sneller gaat."],"words":["hard","zacht","snel","langzaam","boem","trommel","stil"],"learn":["zintuigen","samen","grove-motoriek","taal"],"tips":["Leg een oude handdoek of deken onder de pannen: dat dempt het geluid voor de buren en spaart je vloer.","Een kastje op kindhoogte met plastic bakjes, een pan en houten lepels is een gratis muziekhoek."],"extenders":["Wissel van trommelstok: een garde, een plastic lepel of gewoon je handen. Hoe klinkt de pan nu?","Leg een theedoek over een pan en trommel opnieuw: klinkt hij nu zachter of doffer?","Speel raad de pan: je kind doet de ogen dicht, jij tikt op één pan, en je kind wijst aan welke het was."],"variations":["Sinterklaas: tik met zachte lepeltjes het paard op het dak na op een doos en zing ‘Hoor de wind waait door de bomen’.","Onweer: begin met tikken met één vinger, dan twee, dan de hele hand, en eindig met een donderslag op de pan.","Fanfare: marcheer met een pan en een lepel door de kamer, en wissel om de beurt van instrument."],"themes":[],"canStay":false,"pinQuery":"pannen trommelen peuter muziek"},
  {"id":"doosgitaar","title":"Gitaar van een doos","emoji":"🎸","category":"muziek","summary":"Span elastiekjes om een open doos, plak er een koker aan als hals en tokkel: ontdek samen welke snaar hoog en welke laag klinkt.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":2,"soloFrom":4,"cleanupMinutes":2,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"dozen","note":"een stevige doos zonder deksel, bijv. een schoenendoos"},{"id":"elastiekjes","note":"4-6 stuks, liefst dikke én dunne"},{"id":"wc-rollen","note":"een keukenrolkoker als hals"},{"id":"ducttape","note":"om de hals vast te plakken"}],"optional":[{"id":"potlood","note":"als ‘brug’ onder de elastiekjes: dan klinkt het luider"},{"id":"stiften","note":"om te versieren"},{"id":"stickers"}],"steps":["Plak een keukenrolkoker met ducttape tegen de korte kant van de doos: dat is de hals van je gitaar.","Span 4-6 elastiekjes in de lengte om de open doos, dik en dun door elkaar. Dat doe jij.","Schuif een potlood dwars onder de elastiekjes, vlak bij één rand: dan klinkt je gitaar luider.","Tokkel samen: klinkt een dik elastiek hoog of laag? En een dun?","Versier de gitaar met stiften of stickers en geef een concertje met je lievelingsliedje.","Bewaar de gitaar hoog op de kast: losse elastiekjes zijn gevaarlijk voor kleine broertjes of zusjes."],"ageTips":{"young":"Voor een driejarige is elastiekjes spannen te lastig en ze schieten snel weg. Span ze zelf en laat je kind tokkelen en plukken. Benoem: hoog, laag, hard, zacht.","old":"Laat je kleuter de elastiekjes ordenen van laag naar hoog, of ontdekken wat er gebeurt als je een elastiek strakker trekt. Lukt het om samen ‘Vader Jacob’ te tokkelen?"},"safety":["Elastiekjes kunnen terugschieten in de ogen: span ze zelf en laat je kind tokkelen zonder ze ver uit te rekken.","Elastiekjes zijn klein en passen door een wc-rolletje: bewaar de gitaar en losse elastiekjes buiten bereik van kinderen onder de 3.","Gooi een uitgedroogd of geknapt elastiekje meteen weg en vervang het."],"say":["Tok! Hoor je dat?","Welke klinkt hoger: het dikke of het dunne elastiek?","Wat gebeurt er als je het elastiek strakker trekt?","Ik zie het elastiek trillen. Voel je het ook met je vinger?","Wat tokkel je geduldig, alle elastiekjes om de beurt."],"words":["tokkelen","trillen","hoog","laag","strak","slap","dik","dun"],"learn":["zintuigen","ontdekken","fijne-motoriek","creativiteit"],"tips":["Een tissuedoos met een gat in het midden is al een kant-en-klare gitaar: span de elastiekjes over het gat.","Een stevige doos klinkt beter dan dun karton: een schoenendoos werkt prima, een cornflakesdoos zakt in."],"extenders":["Schuif het potlood naar een andere plek onder de elastiekjes: klinkt de gitaar nu hoger of lager?","Speel raad de snaar: je kind doet de ogen dicht en jij tokkelt. Was het de dikke of de dunne?","Zet een liedje op en tokkel mee: snel bij snelle muziek en heel zacht bij een slaapliedje."],"variations":["Klankproef: span hetzelfde elastiek om een plastic bakje, een doos en een pan. Welke klinkt het hardst?","Bandje: speel samen met de rammelaars en het pannenorkest en geef een concert voor de knuffels.","Mini-harp: span elastiekjes over een leeg boterkuipje en tokkel met één vinger een slaapliedje."],"themes":[],"canStay":false,"pinQuery":"doos gitaar elastiekjes knutselen"},
  {"id":"regenstok","title":"Regenstok maken","emoji":"☔","category":"muziek","summary":"Draai aluminiumfolie in een koker, doe er rijst in en plak hem dicht: als je de stok langzaam omdraait, hoor je het zachtjes regenen.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"wc-rollen","note":"een keukenrolkoker, of twee kokers aan elkaar geplakt"},{"id":"aluminiumfolie","note":"2 vellen van ±50 cm"},{"id":"rijst","note":"±3 el"},{"id":"karton","note":"voor twee rondjes om de uiteinden dicht te maken"},{"id":"ducttape","note":"of andere stevige tape"}],"optional":[{"id":"trechter","note":"om de rijst erin te gieten"},{"id":"stiften","note":"om te versieren"},{"id":"stickers"}],"steps":["Trek op karton een rondje om de opening van de koker, knip het iets groter uit en plak er één kant mee dicht. Dat doe jij.","Scheur twee lange vellen aluminiumfolie af en laat je kind ze tot lange slierten draaien en kreukelen.","Draai de slierten tot een spiraal, als een veer, en duw ze in de koker: dat worden trapjes waar de rijst langs valt.","Laat je kind ±3 el rijst in de koker scheppen; met een trechter gaat het makkelijker.","Plak de andere kant dicht met een tweede rondje karton en een paar lagen tape, helemaal rondom.","Versier de regenstok met stiften of stickers en draai hem langzaam om: hoor je de regen?"],"ageTips":{"young":"Een driejarige kan prima folie kreukelen en rijst scheppen. Het dichtplakken doe jij; daarna mag je kind vooral luisteren: langzaam draaien is motregen, snel is een stortbui.","old":"Laat je kleuter testen: hoe klinkt de stok met rijst, met pasta of met linzen? En met meer of minder folie? Maak er twee en vergelijk."},"safety":["Plak de uiteinden met meerdere lagen tape dicht en controleer ze regelmatig: losse rijst is voor kinderen onder de 3 een verstikkingsgevaar.","Geef de regenstok niet aan jongere broertjes of zusjes die erop bijten: het karton wordt dan zacht en scheurt open."],"say":["Ssst… hoor je de regen?","Wat gebeurt er als je hem heel langzaam omdraait? En heel snel?","Ik hoor eerst zachte druppels en daarna een hele bui!","Wat heb je die folie goed gedraaid: het lijkt wel een slang.","Is het nu motregen of een onweersbui?"],"words":["regen","druppels","kreukelen","draaien","zachtjes","omdraaien","luisteren"],"learn":["fijne-motoriek","zintuigen","concentratie"],"tips":["Hoe langer de koker, hoe langer het regent: plak twee of drie kokers met tape aan elkaar.","Geen trechter? Rol een vel papier tot een puntzak en knip het puntje eraf."],"extenders":["Tel samen hoe lang het regent na één keer omdraaien. Lukt het om de bui langer te laten duren door heel langzaam te draaien?","Rol de regenstok over de vloer naar elkaar toe: hoe klinkt de regen als hij rolt?","Wieg samen een knuffel in slaap: draai de regenstok zo langzaam mogelijk, als een zachte nachtregen."],"variations":["Herfst: versier de regenstok met gescheurde bladeren of paraplu’s en speel er een herfstbui mee.","Weerverhaal: vertel over de zon, een wolkje en een bui, en laat je kind op het juiste moment de regen maken.","Liedje: zing ‘Het regent, het zegent’ en laat de regenstok meespelen."],"themes":[],"canStay":false,"pinQuery":"regenstok maken keukenrol rijst"},
  {"id":"danslinten","title":"Danslinten maken","emoji":"💃","category":"muziek","summary":"Maak zwierige linten van crêpepapier aan een handvat en dans op muziek: zwaai rondjes, golven en slingers door de kamer.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":2,"energy":3,"places":["vloer"],"materials":[{"id":"crepepapier","note":"of lint, stroken van ±3 cm breed en 50 cm lang"},{"id":"wc-rollen","note":"als handvat (of een ijsstokje)"},{"id":"plakband","note":"om de stroken vast te maken"},{"id":"muziek","note":"vrolijke muziek"}],"optional":[{"id":"papieren-bordjes","note":"de rand van een bordje als ring om vast te houden"},{"id":"stiften","note":"om het handvat te versieren"},{"id":"kinderschaar","note":"kleuters knippen de stroken zelf"}],"steps":["Knip crêpepapier in stroken van ongeveer 3 cm breed en 50 cm lang, in een paar kleuren.","Plak 3-5 stroken met flinke stukken plakband aan de binnenkant van een wc-rolletje: dat is het handvat.","Versier het handvat eventueel met stiften.","Zet vrolijke muziek op en dans samen: zwaai de linten hoog, laag, in rondjes en in golven.","Speel stopdans: als de muziek stopt, blijft iedereen stokstijf staan en hangen de linten slap naar beneden.","Bewaar de danslinten na afloop op een vaste plek, buiten bereik van het bedje."],"ageTips":{"young":"Een dreumes houdt een dik wc-rolletje of de rand van een papieren bordje makkelijker vast dan een ijsstokje. Dans samen, op de arm of aan de hand, en benoem: omhoog, omlaag, rondje!","old":"Laat je kleuter een eigen dans bedenken en die aan jou leren: eerst drie rondjes, dan een golf… Of teken met het lint een letter of cijfer in de lucht."},"safety":["Wurggevaar: houd de linten kort (±50 cm), nooit om de nek, en ruim ze op voor het slapen. Crêpepapier scheurt makkelijk en is daardoor veiliger dan stevig lint.","Zorg voor ruimte: schuif de salontafel opzij en dans niet op sokken op een gladde vloer.","Crêpepapier geeft kleur af als het nat wordt: laat je dreumes er niet op sabbelen."],"say":["Zwaai, zwaai! Omhoog!","Kun je het lint heel langzaam laten bewegen, als een slang?","Ik zie je lint rondjes draaien boven je hoofd.","Wat doe je goed je best om stil te staan als de muziek stopt!","Welke kleur lint wil jij vandaag?"],"words":["zwaaien","draaien","omhoog","omlaag","rondje","golf","stilstaan"],"learn":["grove-motoriek","creativiteit","concentratie"],"tips":["Knip de dichtgevouwen rol crêpepapier in plakken van 3 cm: zo heb je in één keer een hele bos lange stroken.","Stroken van een oud laken of T-shirt gaan langer mee dan crêpepapier en kunnen gewoon in de was."],"extenders":["Speel spiegeldans: jij zwaait iets voor, je kind doet het precies na, en daarna andersom.","Wissel steeds van muziek: een snel liedje, een mars, een slaapliedje. Kan het lint meedoen?","Geef je kind een tweede lint voor de andere hand: lukt het om met twee linten tegelijk rondjes te draaien?"],"variations":["Koningsdag: maak oranje en rood-wit-blauwe linten en houd een optocht door de kamer.","Carnaval: verkleed je, pak je linten en loop met z’n allen een polonaise door het huis.","Weerdans: dans zachtjes als een briesje en wild als een storm. Wie bedenkt het volgende weer?","Kleurendans: maak een lint in elke kleur; roep een kleur en alleen dat lint mag dansen."],"themes":["koningsdag","carnaval"],"canStay":false,"pinQuery":"danslinten maken crêpepapier peuter"},
  {"id":"ballontennis","title":"Ballontennis met bordjesrackets","emoji":"🎈","category":"muziek","summary":"Maak rackets van papieren bordjes en houd samen een ballon in de lucht: een rustig balspel dat binnen prima kan.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,20],"supervision":1,"soloFrom":null,"cleanupMinutes":1,"noise":2,"energy":3,"places":["vloer"],"materials":[{"id":"papieren-bordjes","note":"1 per racket, liefst stevige"},{"id":"ijsstokjes","note":"2 per racket, als handvat"},{"id":"ducttape","note":"om de stokjes stevig vast te plakken"},{"id":"ballonnen","note":"niet te hard opgeblazen (door jou)"}],"optional":[{"id":"stiften","note":"om een gezicht op het racket te tekenen"},{"id":"stickers"}],"steps":["Blaas een ballon op, niet te hard, en knoop hem goed dicht. Dat doe jij.","Plak twee ijsstokjes met ducttape tegen de onderkant van een papieren bordje: dat is het handvat.","Laat je kind het racket versieren met een gezichtje of stickers.","Tik de ballon met het racket omhoog. Lukt het om hem in de lucht te houden zonder dat hij de grond raakt?","Speel samen over en weer, of tel hoe vaak het lukt om hem achter elkaar te raken.","Laat na afloop de lucht uit de ballon of berg hem hoog op, en gooi een geknapte ballon meteen weg."],"ageTips":{"young":"Voor een tweejarige gaat een ballon fijn langzaam, maar een racket is nog lastig. Laat je kind eerst met de handen tikken, of houd het racket samen vast.","old":"Tel samen hoe vaak je de ballon hoog kunt houden en probeer je record te verbeteren. Of zet een stoel in het midden als net en speel een echte wedstrijd."},"safety":["Ballonnen alleen onder toezicht: gooi een kapotte ballon of een los stukje meteen weg, want dat is een groot verstikkingsgevaar. Laat een kind onder de 8 nooit zelf een ballon opblazen.","Ruim breekbare spullen en de salontafel opzij: wie naar de ballon kijkt, ziet niet waar hij loopt."],"say":["Tik! Omhoog!","Hoe lang kun je hem in de lucht houden?","Ik zie dat je goed naar de ballon blijft kijken.","Wat denk je: valt een ballon snel of langzaam?","Je bleef het proberen, en nu lukte het al vijf keer achter elkaar!"],"words":["omhoog","tikken","zweven","vallen","langzaam","hooghouden","racket"],"learn":["grove-motoriek","concentratie","samen","rekenen"],"tips":["Een ballon die niet te hard is opgeblazen, knapt minder snel en is fijner om mee te spelen.","Geen papieren bordjes? Een opgerolde krant of gewoon je hand werkt ook."],"extenders":["Zet een wasmand of doos neer als doel: wie tikt de ballon erin?","Maak het lastiger: tik met je andere hand, sta op één been of speel zittend op de grond.","Noem bij elke tik een dier of een kleur: de ballon blijft in de lucht zolang jullie nog iets weten."],"variations":["Verjaardag: speel na het feest met de ballonnen van de versiering en houd ze allemaal tegelijk in de lucht.","Zonder racket: houd de ballon hoog met alleen je hoofd, je knie of je elleboog.","Muziekballon: houd de ballon hoog zolang de muziek speelt. Stopt de muziek, dan vang je hem."],"themes":[],"canStay":false,"pinQuery":"ballon tennis papieren bordje racket"},
  {"id":"hindernisbaan","title":"Hindernisbaan door de kamer","emoji":"🤸","category":"muziek","summary":"Bouw met kussens, stoelen en een deken een hindernisbaan door de kamer: kruipen, klimmen, balanceren en mikken in één avontuur.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,25],"supervision":1,"soloFrom":4,"cleanupMinutes":10,"noise":3,"energy":3,"places":["vloer"],"materials":[{"id":"dekens","note":"kussens om overheen te klimmen en een deken als tunnel"},{"id":"stoelen","note":"2-3 stuks voor de tunnel"},{"id":"schilderstape","note":"voor een lijn om over te balanceren"},{"id":"wasmand","note":"om in te mikken"},{"id":"bal","note":"of een paar opgerolde sokken"}],"optional":[{"id":"knuffels","note":"om onderweg te redden"},{"id":"dozen","note":"een open doos als tunnel"},{"id":"muziek","note":"voor een swingende baan"}],"steps":["Schuif de salontafel opzij en bouw samen een route: een tunnel van een deken over twee stoelen, een berg van kussens en een tapelijn op de vloer.","Zet aan het eind een wasmand neer, met een bal of een paar opgerolde sokken ernaast.","Doe het eerst zelf voor: kruip door de tunnel, klim over de kussens, loop over de lijn en gooi de bal in de mand.","Laat je kind de baan afleggen. Moedig aan en benoem wat je ziet: door, over, onder, langs.","Verander de baan na een paar rondjes: de kussens verder uit elkaar, de lijn zigzag of de mand verder weg.","Ruim samen op: wie brengt de kussens terug naar de bank?"],"ageTips":{"young":"Voor een dreumes is kruipen door de tunnel en over één kussen al een avontuur. Houd de baan kort en laag, ga zelf aan de andere kant van de tunnel zitten en roep: kiekeboe!","old":"Laat je kleuter zelf de route bedenken en tekenen, en neem de tijd op met de stopwatch van je telefoon. Wie kan het snelst, of juist zo langzaam mogelijk?"},"safety":["Bouw op een zachte ondergrond en houd de baan laag: niet over tafels klimmen of van stoelen springen.","Speel op blote voeten of antislipsokken: op gewone sokken glijdt je kind snel uit.","Zet de stoelen voor de tunnel stevig neer, met de rugleuning tegen de bank of de muur, zodat ze niet kunnen omvallen."],"say":["Door de tunnel… kiekeboe!","Hoe kom je over de kussenberg? Klim je of kruip je?","Ik zie dat je je armen wijd houdt op de lijn. Zo blijf je in evenwicht!","Welke hindernis zullen we er nog bij bouwen?","Wat heb je goed doorgezet: de hele baan tot het eind!"],"words":["door","over","onder","langs","klimmen","kruipen","springen","evenwicht"],"learn":["grove-motoriek","taal","creativiteit"],"tips":["Een hindernisbaan is ideaal op een regendag of als je kind stuiterig is: na een paar rondjes is de ergste energie eruit.","Gebruik schilderstape voor de lijnen op de vloer: dat laat meestal geen lijmresten achter."],"extenders":["Geef iets mee om te vervoeren: een knuffel onder de arm, een bal op een lepel of een boek op het hoofd.","Roep bij elke hindernis een nieuwe opdracht: achteruit kruipen, drie keer springen of zo stil als een muis.","Wissel van rol: je kind wordt de trainer en vertelt jou hoe je door de baan moet."],"variations":["Dierenbaan: kruip als een poes door de tunnel, spring als een kikker over de kussens en waggel als een pinguïn over de lijn.","Reddingsmissie: verstop knuffels langs de route en breng ze één voor één naar de veilige wasmand.","Sinterklaas: maak een dakenroute van kussens en laat je kind een cadeautje in de schoorsteen (de wasmand) gooien."],"themes":[],"canStay":false,"pinQuery":"hindernisbaan binnen kussens peuter"},
  {"id":"tapelijnen","title":"Balanceren op tapelijnen","emoji":"👣","category":"muziek","summary":"Plak rechte lijnen, zigzaglijnen en golven van schilderstape op de vloer en balanceer, spring en rijd er samen overheen.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[10,25],"supervision":2,"soloFrom":2,"cleanupMinutes":5,"noise":2,"energy":3,"places":["vloer"],"materials":[{"id":"schilderstape","note":"een rol, liefst in een opvallende kleur"}],"optional":[{"id":"speelgoedautos","note":"om over de lijnen te laten rijden"},{"id":"knuffels","note":"om op je hoofd te balanceren"},{"id":"stiften","note":"om cijfers op de hinkelbaan te schrijven"},{"id":"muziek"}],"steps":["Plak met schilderstape een paar lijnen op de vloer: een rechte lijn, een zigzag, een golf en een grote cirkel.","Loop eerst zelf voor: voetje voor voetje over de rechte lijn, met je armen wijd als een koorddanser.","Laat je kind de lijnen volgen: gewoon lopen, op de tenen, zijwaarts, achteruit of als een dier.","Plak voor oudere kinderen een hinkelbaan met vakken en schrijf er met stift cijfers in.","Laat speelgoedautootjes over de lijnen rijden: de zigzag is een bergweg, de cirkel een rotonde.","Laat de tape een paar dagen liggen voor nieuwe spelletjes en trek hem daarna langzaam los."],"ageTips":{"young":"Een dreumes loopt nog niet netjes op een lijn: houd een handje vast en maak de lijn breder met twee stroken naast elkaar, of laat je kind ernaast kruipen met een autootje.","old":"Laat je kleuter van lijn naar lijn springen, hinkelen op één been of met een knuffel op het hoofd balanceren. Ook leuk: zelf een nieuw parcours bedenken en plakken."},"safety":["Balanceer op blote voeten of antislipsokken: op gewone sokken glijdt je kind op laminaat of tegels snel uit.","Trek losgeraakte stukjes tape meteen weg: een dreumes stopt ze zo in de mond.","Plak geen lijnen over een drempel of vlak bij de trap, en houd ze weg bij scherpe tafelhoeken."],"say":["Voetje, voetje, op de lijn!","Kun je ook achteruit over de lijn lopen?","Ik zie dat je je armen uitsteekt om niet te vallen.","Welke lijn vind je het moeilijkst: de rechte of de zigzag?","Wat blijf je goed proberen, ook als je er even afstapt!"],"words":["rechtdoor","zigzag","golf","rondje","evenwicht","tenen","springen","achteruit"],"learn":["grove-motoriek","concentratie","rekenen"],"tips":["Test de tape eerst op een onopvallend plekje: op de meeste vloeren laat schilderstape geen resten achter, op sommige vloerkleden wel.","Plak de lijnen in de gang: daar kom je toch langs, en de woonkamer blijft vrij."],"extenders":["Leg obstakels op de lijn: een knuffel om overheen te stappen of een kussen om omheen te lopen.","Speel stoplicht: bij groen loop je over de lijn, bij oranje sluip je en bij rood sta je stil.","Plak er een nieuwe lijn bij, zoals een spiraal, een trap of een kronkelweg naar de bank."],"variations":["Letterpad: plak een grote letter, bijvoorbeeld de eerste letter van de naam van je kind, en loop hem samen na.","Muzieklijnen: zet muziek op en beweeg langs de lijnen, snel als de muziek snel is en langzaam als hij langzaam is.","Autostad: plak een hele stad met wegen, een rotonde en een parkeergarage onder de tafel."],"themes":[],"canStay":true,"stayTips":"Plak de lijnen buiten de looproute en kijk elke ochtend of er losse stukjes zijn die een dreumes in de mond kan stoppen. Trek de tape na een paar dagen langzaam los, zodat er geen lijmresten achterblijven.","pinQuery":"tape lijnen vloer balanceren peuter"},
  {"id":"sokkenballen","title":"Sokkenballen gooien en mikken","emoji":"🎯","category":"muziek","summary":"Rol sokken op tot zachte ballen en mik ze vanaf steeds verdere lijnen in de wasmand: gooien, tellen en scoren zonder dat er iets breekt.","ageMin":1,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[15,45],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":3,"places":["vloer"],"materials":[{"id":"sokken","note":"10-20 paar, schoon uit de was of de la"},{"id":"wasmand","note":"als doel"},{"id":"schilderstape","note":"voor drie gooilijnen op de vloer"}],"optional":[{"id":"plastic-bekers","note":"voor een bekertoren om omver te gooien"},{"id":"papier","note":"om de punten te turven"},{"id":"potlood"},{"id":"knuffels","note":"als doelwit op de bank"},{"id":"dekens","note":"over twee stoelen als net"}],"steps":["Kieper een stapel schone sokken op de vloer en zoek samen de paren bij elkaar.","Rol elk paar op tot een bal: leg de sokken op elkaar, rol ze op vanaf de teen en trek de boord over de bal heen.","Zet de wasmand tegen de muur en plak met schilderstape drie lijnen op de vloer: dichtbij, verder en ver weg.","Gooi om de beurt vanaf de eerste lijn. Raak? Dan mag je een lijn naar achteren.","Tel na elke ronde de ballen in de mand. Vanaf de verste lijn telt een bal voor drie punten: turf ze op papier.","Bouw een toren van plastic bekers en probeer hem met een sokkenbal om te gooien. Wie zet hem weer op?","Ruim op met een laatste mikronde: gooi alle sokkenballen in de wasmand en breng ze naar de goede la."],"ageTips":{"young":"Een dreumes gooit nog niet gericht: zet de wasmand vlak voor je kind en laat de ballen erin stoppen, omkiepen en opnieuw vullen. Rol de sokken zelf op en laat je kind ze uit je hand pakken.","old":"Laat je kleuter zelf de punten turven en optellen, of een parcours bedenken met doelen die meer punten opleveren: de wasmand is 1 punt, een schoenendoos 3. Ook lastig: gooien met de andere hand."},"safety":["Speel op blote voeten of antislipsokken en maak een stuk vloer vrij: op gewone sokken glijdt je kind op een gladde vloer snel uit.","Speel uit de buurt van de trap, lampen, planten en de tv: ook een zachte bal kan iets omgooien.","Trek losgeraakte stukjes tape meteen weg: een dreumes stopt ze zo in de mond."],"say":["Gooi! Raak!","Hoeveel sokkenballen liggen er al in de mand?","Bijna! Wat kun je anders doen: hoger gooien of zachter?","Ik zie dat je eerst goed mikt voordat je gooit.","Welke sok hoort hierbij? Waar is het maatje?"],"words":["gooien","mikken","raak","mis","dichtbij","ver weg","paar","punten"],"learn":["grove-motoriek","rekenen","samen","concentratie"],"tips":["Combineer het met de was: na het spelen liggen alle sokken opgerold in de la.","Geen schilderstape? Leg een sjaal, een springtouw of een rij boeken neer als gooilijn.","Binnen zijn sokken beter dan ballen: ze stuiteren niet weg en gooien niets kapot."],"extenders":["Maak het doel beweeglijk: jij houdt de wasmand vast en loopt langzaam heen en weer.","Gooi op een nieuwe manier: met de andere hand, achterstevoren tussen je benen door, of met je ogen dicht.","Hang een deken over twee stoelen als net en gooi de sokkenballen eroverheen naar elkaar: sokkentennis!","Zet een rij knuffels op de bank en probeer ze er één voor één af te gooien.","Zet een timer van één minuut: hoeveel ballen krijg je in de mand voordat hij afgaat?"],"variations":["Winter: rol witte sokken op, bouw een fort van kussens en houd binnen een sneeuwballengevecht.","Sokkenkegelen: zet lege flesjes of wc-rollen op een rij en rol de sokkenballen ertegenaan.","Vangen: gooi elkaar de sokkenbal toe en tel hoe vaak jullie hem vangen zonder dat hij valt."],"themes":[],"canStay":false,"pinQuery":"sokkenballen mikspel peuter binnen"},
  {"id":"beweegdobbelsteen","title":"De beweegdobbelsteen","emoji":"🎲","category":"muziek","summary":"Gooi een grote dobbelsteen met op elke kant een opdracht en spring, kruip, draai of stamp wat bovenop ligt: lekker bewegen in de kamer.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[20,45],"supervision":1,"soloFrom":4,"cleanupMinutes":2,"noise":3,"energy":3,"places":["vloer"],"materials":[{"id":"dozen","note":"een zo vierkant mogelijke doos, bijv. een tissuedoos of een klein verhuisdoosje"},{"id":"papier","note":"om op de zes kanten te plakken"},{"id":"plakband"},{"id":"stiften"}],"optional":[{"id":"dobbelsteen","note":"een gewone, om te gooien hoe vaak je de opdracht doet"},{"id":"muziek","note":"voor de dans-kant en het bevriesspel"},{"id":"knuffels","note":"om mee te doen of op je hoofd te balanceren"}],"steps":["Plak op elke kant van de doos een stuk papier en teken er een opdracht op met een simpel plaatje: springen, kruipen, draaien, klappen, stampen en dansen.","Maak een stuk vloer vrij: schuif de salontafel opzij en zet breekbare spullen weg.","Gooi de dobbelsteen om de beurt over de vloer. Wat ligt er bovenop? Dat doen jullie allebei!","Tel samen hoe vaak: spring vijf keer als een kikker, stamp tien keer als een olifant, draai drie rondjes.","Draai de rollen om: nu gooit je kind en moet jij de opdracht doen, zo gek als je kunt.","Sluit af met een rustige ronde: doe alles superlangzaam, als een slak, en eindig liggend op de vloer als een slapende kat."],"ageTips":{"young":"Een tweejarige kan nog geen stippen tellen: houd het bij duidelijke plaatjes en doe alles voor. Gooi de grote doos samen, benoem wat er bovenop ligt (de kikker!) en spring samen een paar keer.","old":"Laat je kleuter een eigen dobbelsteen ontwerpen en tekenen, en gooi er een gewone dobbelsteen bij voor hoe vaak je het moet doen. Tellen, bewegen en volhouden in één."},"safety":["Speel op blote voeten of antislipsokken en ruim een stuk vloer leeg: draaien en springen op gewone sokken eindigt snel in uitglijden.","Draaien maakt duizelig: houd het bij drie tot vijf rondjes en stop als je kind wankelt. Blijf uit de buurt van tafelhoeken en de trap."],"say":["Gooien maar! Wat ligt er bovenop?","Kikker! Spring, spring, spring!","Hoeveel keer moeten we stampen? Tel je mee?","Ik zie dat je heel hoog springt en toch netjes landt.","Welke opdracht zou jij erop tekenen?"],"words":["springen","kruipen","draaien","klappen","stampen","snel","langzaam","stil"],"learn":["grove-motoriek","rekenen","taal","samen"],"tips":["Woon je boven iemand? Teken dan rustige opdrachten: sluipen, kruipen, zwaaien en op één been staan in plaats van stampen en springen.","Bewaar de dobbelsteen bij de speelgoedkist: handig voor een regenmiddag, of om vlak voor het eten nog even energie kwijt te raken.","Geen vierkante doos? Gebruik een gewone dobbelsteen en teken op een vel papier wat elk aantal stippen betekent."],"extenders":["Gooi er een gewone dobbelsteen bij: het aantal stippen is hoe vaak je de opdracht doet.","Zet muziek aan en doe elke opdracht tot de muziek stopt: dan bevriezen jullie als een standbeeld.","Plak een verrassingskant over een oude opdracht heen, zoals ‘knuffel iemand’ of ‘ren naar de deur en terug’.","Maak het moeilijker: doe de opdracht op je tenen, achteruit of met een knuffel op je hoofd."],"variations":["Dierendobbelsteen: zes dieren op de kanten (kikker, olifant, slang, vogel, poes en kangoeroe), en beweeg zoals dat dier.","Opruimdobbelsteen: op elke kant een soort speelgoed, zoals blokken, knuffels of boekjes. Gooi en ruim op wat er bovenop ligt.","Gezichtendobbelsteen: blij, boos, verdrietig, verbaasd, bang en slaperig. Trek het gezicht en praat over wanneer je je zo voelt."],"themes":[],"canStay":false,"pinQuery":"beweegdobbelsteen peuter zelf maken"},
  {"id":"fruitgezichtjes","title":"Fruitgezichtjes en fruitdieren","emoji":"🍓","category":"eetbaar","summary":"Leg samen grappige gezichten en dieren van stukjes fruit en groente op een bord, en eet je kunstwerk daarna lekker op.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"fruit","note":"bijv. banaan, appel, mandarijn, kiwi en bessen"},{"id":"groente","note":"bijv. komkommer, paprika en cherrytomaatjes"},{"id":"bord","note":"een groot bord als ‘gezicht’"},{"id":"mes","note":"voor jou, om alles in stukjes te snijden"}],"optional":[{"id":"brood","note":"een cracker of rijstwafel als ondergrond"},{"id":"beleg","note":"roomkaas als lijm op de cracker"},{"id":"kaas","note":"geraspte kaas als haar"},{"id":"muffinvorm","note":"om de stukjes per soort in te doen"}],"steps":["Snijd fruit en groente in kleine stukjes en zet ze per soort in kommetjes klaar. Druiven en cherrytomaatjes snijd je in de lengte in vieren.","Leg een groot bord of een cracker voor je kind neer: dat wordt het gezicht.","Bedenk samen wat de ogen, de neus en de mond worden. Laat je kind zelf kiezen en leggen.","Maak er haar, oren of een hoed bij, bijvoorbeeld van reepjes paprika of een plakje appel.","Bewonder het gezicht, geef het een naam en… smakelijk eten!"],"ageTips":{"young":"Snijd voor een dreumes alles in kleine, zachte stukjes en leg zelf alvast een rond gezicht van plakjes komkommer neer. Laat je kind er ogen op leggen en benoem: oog, neus, mond… hap!","old":"Laat je kleuter een heel dier of een fruittuin leggen, met een verhaal erbij. Of maak een patroon: banaan, aardbei, banaan… wat komt er hierna?"},"safety":["Snijd druiven en cherrytomaatjes in de lengte in vieren, en geef dreumesen geen harde stukjes rauwe appel of wortel: rasp ze of snijd ze in dunne plakjes.","Laat je kind rechtop aan tafel zitten tijdens het eten en niet rondlopen met eten in de mond: zo verslikt het zich minder snel.","Allergie? Let op met kiwi en aardbei bij gevoelige kinderen, en met roomkaas (melk) of crackers (gluten)."],"say":["Wat wordt dit? Een oog of een neus?","Ik zie twee ogen van aardbei en een mond van banaan. Wat een vrolijk gezicht!","Ruik eens aan de mandarijn. Ruikt hij zoet of fris?","Hap! Daar gaat de neus!","Wat een goed idee om paprika als haar te gebruiken."],"words":["oog","neus","mond","rond","zoet","zuur","sappig","haar"],"learn":["creativiteit","fijne-motoriek","taal","zintuigen"],"tips":["Gebruik het fruit dat al in huis is: als ontbijt of tussendoortje eten kinderen zo vaak meer fruit en groente.","Zet de stukjes in een muffinvorm, elk vakje een soort: overzichtelijk en makkelijk pakken."],"extenders":["Vraag om een ander gevoel: maak nu een boos gezicht, een verdrietig gezicht of een verbaasd gezicht.","Leg een gezicht van iemand uit huis: wie heeft er krullen van geraspte wortel en een bril van plakjes komkommer?","Speel ‘wat mist er?’: je kind doet de ogen dicht en jij eet stiekem de neus op. Wat is er weg?"],"variations":["Fruitrups: leg plakjes banaan en kiwi om en om op een rij, met een aardbei als kop.","Koningsdag: maak een oranje gezicht van mandarijn, wortel en meloen.","Halloween: maak bananenspookjes met oogjes van bessen, of een pompoengezicht van partjes mandarijn.","Regenboogbord: leg het fruit op kleur in een boog: rood, oranje, geel, groen en blauw."],"themes":[],"canStay":false,"pinQuery":"fruit gezichtjes bord kind"},
  {"id":"koekjes-versieren","title":"Koekjes versieren","emoji":"🍪","category":"eetbaar","summary":"Smeer gekleurd glazuur op koekjes en strooi er spikkels over: smeren, strooien en snoepen in één.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"koekjes","note":"biscuitjes of zelfgebakken koekjes, ±15 stuks"},{"id":"poedersuiker","note":"±100 g"},{"id":"water","note":"±1 el, plus een paar druppels"},{"id":"kleurstof","note":"2-3 kleuren"},{"id":"hagelslag","note":"of spikkels"},{"id":"kom","note":"een kommetje per kleur glazuur"},{"id":"lepel","note":"theelepels om te roeren en te smeren"}],"optional":[{"id":"dienblad","note":"om op te werken: gevallen spikkels schud je zo terug"},{"id":"zip-zakjes","note":"als spuitzakje, met een piepklein puntje eraf"},{"id":"bakpapier","note":"om de koekjes op te laten drogen"},{"id":"oud-shirt"}],"steps":["Roer 100 g poedersuiker met 1 el water in een kom. Voeg druppel voor druppel meer water toe tot het glazuur dik is als tandpasta.","Verdeel het glazuur over een paar kommetjes en laat je kind in elk kommetje een druppel kleurstof roeren.","Zet de spikkels en hagelslag in schaaltjes klaar en leg de koekjes op een dienblad.","Laat je kind met de bolle kant van een theelepel glazuur op een koekje smeren en er meteen spikkels over strooien.","Leg de versierde koekjes op bakpapier en laat ze ongeveer een uur drogen. Eentje meteen opeten mag natuurlijk ook.","Bewaar de droge koekjes in een trommel; ze blijven een paar dagen lekker."],"ageTips":{"young":"Een tweejarige strooit vooral, en dat mag. Smeer zelf alvast wat glazuur op een paar koekjes en geef een klein bakje spikkels: een deel gaat in de mond, en dat is prima.","old":"Laat je kleuter vooraf een ontwerp bedenken: een gezichtje, een patroon of een letter. Met een diepvrieszakje met een piepklein puntje eraf spuit je echte lijntjes."},"safety":["Allergie: koekjes bevatten vaak gluten, melk en ei, en spikkels soms sporen van noten. Lees de verpakking als er een kind met een allergie meedoet.","Kleurstof vlekt op kleding en tafel: trek een oud shirt aan en werk op een dienblad of afwasbaar tafelkleed.","Gebruik voor kinderen onder de 3 gewone hagelslag en geen harde suikerparels: die zijn klein en hard."],"say":["Strooi, strooi! Kijk eens hoeveel spikkels!","Hoe voelt het glazuur: dik of dun? Plakkerig?","Ik zie dat je eerst roze hebt gesmeerd en daarna gele spikkels. Wat een vrolijk koekje.","Voor wie maak je dit koekje?","Wat werk je geduldig: helemaal tot aan de randjes."],"words":["smeren","strooien","zoet","plakkerig","spikkels","glazuur","dik","dun"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Maak het glazuur liever te dik dan te dun: dun glazuur loopt van het koekje af. Een extra tl poedersuiker maakt het weer dikker.","Werk op een dienblad met een rand: spikkels die ernaast vallen, schud je zo terug in het bakje."],"extenders":["Druppel een tweede kleur glazuur op een nat koekje en trek er met een ijsstokje strepen doorheen: een marmerkoekje.","Bouw een koekjestoren: stapel drie versierde koekjes met een klodder glazuur ertussen. Hoe hoog durf je?","Open een koekjeswinkel: leg de versierde koekjes op een bord en verkoop ze aan de knuffels of aan jou."],"variations":["Sinterklaas: versier speculaasjes of letterkoekjes met de eerste letter van ieders naam.","Kerst: smeer groen glazuur op stervormige koekjes en strooi er gekleurde spikkels op als kerstballen.","Verjaardag: versier samen traktatiekoekjes met de leeftijd van de jarige erop.","Gezichtjes: maak elkaar na op een koekje. Wie is wie?"],"themes":["sinterklaas","kerst","verjaardag"],"canStay":false,"pinQuery":"koekjes versieren glazuur peuter"},
  {"id":"kruidnoten-bakken","title":"Kruidnoten bakken","emoji":"🥣","category":"eetbaar","summary":"Kneed samen een geurig deeg met speculaaskruiden, rol knikkergrote balletjes en bak je eigen kruidnoten voor Sinterklaas.","ageMin":2,"ageMax":5,"mess":3,"wet":false,"dirty":false,"prepMinutes":10,"duration":[20,35],"supervision":1,"soloFrom":null,"cleanupMinutes":10,"noise":1,"energy":1,"places":["keuken","tafel"],"materials":[{"id":"zelfrijzend-bakmeel","note":"125 g"},{"id":"basterdsuiker","note":"60 g"},{"id":"boter","note":"50 g, zacht (op kamertemperatuur)"},{"id":"melk","note":"2-3 el"},{"id":"kruiden","note":"1-2 tl speculaaskruiden"},{"id":"zout","note":"een snufje"},{"id":"kom","note":"een grote mengkom"},{"id":"bakpapier","note":"voor op de bakplaat"},{"id":"oven","note":"180 °C; de oven is voor jou"}],"optional":[{"id":"oud-shirt","note":"of een schort"},{"id":"zip-zakjes","note":"om kruidnoten in uit te delen"}],"steps":["Zet de oven aan op 180 °C en leg bakpapier op de bakplaat. Dat doe jij.","Weeg samen af: 125 g zelfrijzend bakmeel, 60 g basterdsuiker, 1-2 tl speculaaskruiden en een snufje zout. Laat je kind alles in de kom schudden.","Doe er 50 g zachte boter en 2 el melk bij en kneed met je handen tot een soepel deeg. Te droog? Nog een scheutje melk erbij.","Rol samen knikkergrote balletjes en leg ze met wat ruimte ertussen op de bakplaat. Tel maar mee!","Schuif de bakplaat in de oven (dat doe jij) en bak de kruidnoten ±15 minuten, tot ze goudbruin zijn.","Laat ze afkoelen op de bakplaat: dan worden ze knapperig. Bewaar ze in een trommel of pot."],"ageTips":{"young":"Weeg voor een tweejarige alles vooraf af in bakjes: dan hoeft je peuter alleen te gooien, kneden en rollen. Halveer het recept voor een kleine, overzichtelijke portie; scheve balletjes zijn net zo lekker.","old":"Laat je kleuter zelf afwegen en de cijfers op de weegschaal aflezen. Leg de balletjes in rijtjes van tien en tel samen hoeveel kruidnoten het worden."},"safety":["De oven en de hete bakplaat zijn voor jou: laat je kind op afstand blijven als de ovendeur opengaat.","Niet van het rauwe deeg snoepen: rauwe bloem kan bacteriën bevatten.","Kruidnoten zijn klein, rond en hard: breek ze voor jonge kinderen doormidden en laat ze aan tafel zittend eten.","Allergie: dit recept bevat gluten en melk. Gebruik bij een melkallergie plantaardige boter en plantaardige melk."],"say":["Rollen, rollen… een balletje!","Ruik eens aan de speculaaskruiden. Waar doet dat je aan denken?","Hoe voelt het deeg: plakkerig, droog of zacht?","Ik zie een hele rij balletjes. Zullen we tellen hoeveel het er zijn?","Wat heb je goed geholpen: jij hebt alles zelf in de kom gedaan."],"words":["afwegen","kneden","rollen","balletje","ruiken","knapperig","warm","afkoelen"],"learn":["fijne-motoriek","rekenen","zintuigen","samen"],"tips":["Weeg alles af voordat je je kind erbij roept: dan blijft het leukste werk over en hoeft er niet lang gewacht te worden.","Plakt het deeg aan de handjes? Een beetje bakmeel op de handen helpt.","In een goed gesloten trommel of pot blijven kruidnoten een paar weken lekker."],"extenders":["Leg de balletjes samen in een vorm op de bakplaat, zoals een hart, een lachend gezicht of een lange rups.","Zing tijdens het bakken sinterklaasliedjes: hoeveel liedjes duurt het voordat de kruidnoten klaar zijn?","Speel na het afkoelen bekertje raden: verstop een kruidnoot onder een van drie bekers, schuif ze rond en laat je kind raden waar hij zit."],"variations":["Traktatie: doe een handje kruidnoten in een zakje met een strik en geef ze aan opa, oma of de buren.","Chocoladekruidnoten: doop de afgekoelde kruidnoten half in gesmolten chocolade. Het smelten doe jij.","Vormpjes: rol het deeg uit en steek er kleine sterretjes of letters uit. Bak ze iets korter, ±10 minuten."],"themes":["sinterklaas"],"canStay":false,"pinQuery":"kruidnoten bakken met kinderen"},
  {"id":"boterhamkunst","title":"Boterhamkunst met vormpjes","emoji":"🍞","category":"eetbaar","summary":"Steek vormpjes uit een boterham, gebruik beleg als lijm en versier je brood met gezichtjes van fruit, groente en hagelslag.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[10,20],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"brood","note":"een paar boterhammen of wraps"},{"id":"uitsteekvormpjes","note":"liefst grote, simpele vormen (hart, ster, rondje)"},{"id":"beleg","note":"roomkaas, smeerkaas of jam als ‘lijm’"},{"id":"fruit","note":"in kleine stukjes, bijv. banaan en bessen"},{"id":"groente","note":"bijv. reepjes komkommer, paprika en wortel"},{"id":"hagelslag","note":"voor haar of spikkels"},{"id":"mes","note":"voor jou om te snijden; je kind smeert met een botermes"}],"optional":[{"id":"deegroller","note":"om het brood eerst plat te rollen"},{"id":"kaas","note":"geraspte kaas als haar"}],"steps":["Snijd groente en fruit in kleine stukjes en zet alles in kommetjes klaar: dat is je ‘verfdoos’.","Laat je kind een vormpje kiezen en uit een boterham steken: stevig drukken en een beetje heen en weer wiebelen.","Smeer samen een laagje roomkaas of jam op de vorm; dat is de lijm.","Versier de boterham met ogen van bessen, een mond van paprika en haar van hagelslag of kaas.","Bekijk het kunstwerk samen, bedenk een naam en… opeten!"],"ageTips":{"young":"Voor een tweejarige is uitsteken nog lastig: druk het vormpje samen in het brood, of steek zelf alvast een paar vormen uit. Smeren gaat makkelijker met de bolle kant van een lepel.","old":"Laat je kleuter een heel tafereel op een bord maken: een huis van brood, een zon van kaas en bloemen van komkommer. Of leg samen de eerste letter van de eigen naam met reepjes groente."},"safety":["Allergie: brood bevat gluten, roomkaas melk en sommige smeersels noten of pinda. Kies beleg dat past bij alle kinderen aan tafel.","Snijd druiven en cherrytomaatjes in de lengte in vieren, en harde groente zoals wortel voor jonge kinderen in dunne reepjes of geraspt.","Metalen uitsteekvormpjes hebben één scherpe kant: laat je kind op de omgerolde bovenrand drukken."],"say":["Druk, druk… en eruit! Een hartje!","Wat wordt dit, denk je? Een poes of een monster?","Ik zie dat je de bessen heel precies als oogjes hebt neergelegd.","Hoe smaakt de komkommer: fris of zoet?","Smeer, smeer, tot aan de randjes!"],"words":["uitsteken","smeren","hartje","ster","rondje","bovenop","plakkerig"],"learn":["fijne-motoriek","creativiteit","rekenen","taal"],"tips":["Rol de boterham eerst plat met een deegroller: dan gaat uitsteken veel makkelijker en blijft de vorm heel.","Gooi de randjes niet weg: maak er tosti’s, wentelteefjes of broodkruim van."],"extenders":["Speel restaurant: jij bestelt en je kind maakt het. Eén ster met een lachend gezicht, graag!","Maak iets van de restjes: leg met de randjes een huisje, een slang of een zon rondom op het bord.","Snijd een versierde boterham in vier stukken (dat doe jij) en laat je kind de puzzel weer in elkaar leggen voor de eerste hap."],"variations":["Sinterklaas: snijd of steek een letter uit en strooi er hagelslag over: een chocoladeletter van brood.","Kerst: steek boompjes of sterren uit en versier ze met reepjes paprika als slingers.","Verjaardag: stapel drie rondjes brood met beleg ertussen tot een boterhamtaart en zet er een rietje als kaarsje in."],"themes":[],"canStay":false,"pinQuery":"boterham uitsteken vormpjes kinderen"},
  {"id":"fruitijsjes","title":"Fruitijsjes maken","emoji":"🍦","category":"eetbaar","summary":"Prak fruit met yoghurt, schep het in vormpjes en vries het in: zelfgemaakte ijsjes waarbij je kind proeft, ruikt en kleuren ontdekt.","ageMin":1,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[10,20],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"fruit","note":"±250 g zacht fruit, bijv. aardbeien, banaan, mango of bessen"},{"id":"yoghurt","note":"±250 g, bijv. Griekse yoghurt"},{"id":"ijsvormpjes","note":"of bekertjes met een ijsstokje erin"},{"id":"vork","note":"om te prakken"},{"id":"kom","note":"om in te prakken en te roeren"},{"id":"vriezer"}],"optional":[{"id":"blender","note":"voor een gladder ijsje"},{"id":"ijsblokjesvorm","note":"voor mini-ijsjes voor een dreumes"},{"id":"huishoudfolie","note":"over de bekertjes, zodat het stokje rechtop blijft"},{"id":"ijsstokjes","note":"als je met bekertjes werkt"}],"steps":["Was het fruit en snijd het in stukjes. Laat je kind de zachte stukjes, zoals banaan en aardbei, met een vork fijnprakken in een kom.","Roer er ongeveer evenveel yoghurt door. Wil je het heel glad, pureer het dan met de blender; dat doe jij.","Proef samen een likje: zoet genoeg? Een extra stukje rijpe banaan maakt het zoeter, zonder suiker.","Schep het mengsel in de ijsvormpjes en zet de stokjes erin. Morsen mag, aflikken ook!","Zet de vormpjes minstens 4 uur in de vriezer, of een nacht.","Houd een vormpje even onder de warme kraan: dan glijdt het ijsje er zo uit."],"ageTips":{"young":"Voor een dreumes is een ijsje op een stokje vaak te groot en te koud. Vries het mengsel in een ijsblokjesvorm in en geef één blokje in een kommetje. Prakken met de handen mag ook!","old":"Laat je kleuter een eigen recept bedenken en tekenen: welk fruit, hoeveel lepels yoghurt? Na het invriezen proef je samen of het recept geslaagd is."},"safety":["Allergie: yoghurt bevat melk. Gebruik bij een melkallergie alleen fruit of een plantaardige yoghurt.","Prak of pureer alles goed voor een dreumes: hele bessen of harde stukjes in het ijs kunnen in de keel schieten.","Een ijsje dat net uit de vriezer komt, kan aan lippen of tong vastvriezen: laat het eerst een minuutje liggen."],"say":["Prak, prak! Kijk, de banaan wordt zacht.","Welke kleur krijgt het als we de aardbeien erbij doen?","Ruik eens: ruikt het naar aardbei of naar banaan?","Wat denk je dat er in de vriezer gebeurt?","Brr, koud! Hoe voelt het op je tong?"],"words":["prakken","zacht","koud","bevroren","smelten","zoet","zuur","roze"],"learn":["zintuigen","fijne-motoriek","taal","ontdekken"],"tips":["Overrijp fruit of een zak diepvriesfruit is goedkoop en perfect voor ijsjes.","Geen ijsvormpjes? Gebruik plastic bekertjes, span er huishoudfolie over en prik het stokje erdoor: dan blijft het rechtop staan.","Laat je kind het ijsje aan tafel eten met een slabbetje of oud shirt aan: smeltend fruitijs druppelt en vlekt."],"extenders":["Doe een proefspelletje: je kind doet de ogen dicht en proeft een likje. Is het aardbei of banaan?","Maak twee kommetjes in een andere kleur, zoals roze aardbei en gele banaan, en laat je kind kiezen welke kleur in welk vormpje gaat.","Teken tijdens het wachten samen een ijskaart: welke smaken zijn er, en wie krijgt straks welk ijsje?"],"variations":["Streepjesijs: vul de vormpjes laag voor laag met verschillende kleuren en vries elke laag een uurtje aan.","Sapijsjes: vries puur appelsap of geperst sinaasappelsap in, lekker verkoelend op een warme dag.","Koningsdag: maak oranje ijsjes van mango, sinaasappel en een beetje wortelsap.","Monsterijsjes: pureer banaan met een handje verse spinazie: knalgroen, en je proeft het bijna niet."],"themes":["zomer"],"canStay":false,"pinQuery":"fruitijsjes maken yoghurt kinderen"},
  {"id":"minipizzas","title":"Mini-pizza’s beleggen","emoji":"🍕","category":"eetbaar","summary":"Smeer saus op een wrap of pitabroodje, strooi kaas en leg een gezichtje van groente: zelfgemaakte pizza’s die je kind trots opeet.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":10,"duration":[15,25],"supervision":2,"soloFrom":null,"cleanupMinutes":10,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"brood","note":"kleine wraps, pitabroodjes of halve bolletjes"},{"id":"tomatensaus","note":"±1 el per pizza"},{"id":"kaas","note":"geraspt"},{"id":"groente","note":"bijv. paprika, champignons, maïs en cherrytomaatjes"},{"id":"bakpapier","note":"voor op de bakplaat"},{"id":"oven","note":"200 °C; de oven is voor jou"},{"id":"lepel","note":"om de saus te smeren"}],"optional":[{"id":"uitsteekvormpjes","note":"om sterretjes uit plakjes paprika of kaas te steken"},{"id":"oud-shirt","note":"tomatensaus vlekt"}],"steps":["Verwarm de oven voor op 200 °C en leg bakpapier op de bakplaat. Dat doe jij.","Snijd de groente in kleine stukjes en zet alles met de kaas in kommetjes klaar. Cherrytomaatjes snijd je in vieren.","Leg voor je kind een wrap of pitabroodje neer en laat het met de bolle kant van een lepel tomatensaus uitsmeren.","Laat je kind de pizza beleggen: kaas strooien en een gezichtje, bloem of patroon leggen met de groente.","Schuif de pizza’s in de oven en bak ze 8-10 minuten, tot de kaas gesmolten is. Kijk samen door het ovenraampje.","Laat de pizza’s een paar minuten afkoelen voordat je ze in stukken snijdt: gesmolten kaas is heet."],"ageTips":{"young":"Een tweejarige strooit vooral kaas, en heel veel. Geef kleine bakjes met grote, zachte stukjes groente en laat het patroon los: elke pizza is goed.","old":"Laat je kleuter een pizza bedenken voor iemand anders in huis: wat vindt die lekker? Of verdeel de pizza in vier vakken met elk een ander beleg en tel de stukjes."},"safety":["De oven, de hete bakplaat en gesmolten kaas zijn heet: haal de pizza’s er zelf uit en laat ze eerst afkoelen.","Allergie: wraps en pitabroodjes bevatten gluten, kaas bevat melk. Er zijn glutenvrije wraps en kaas zonder melk.","Snijd cherrytomaatjes in de lengte in vieren: heel zijn ze een verstikkingsgevaar."],"say":["Smeer, smeer! Helemaal tot de rand.","Wat leg jij op je pizza? Wat worden de ogen?","Ruik je dat? De kaas smelt in de oven.","Kijk door het raampje: wat gebeurt er met de kaas?","Je hebt je pizza helemaal zelf belegd. Hoe gaat hij heten?"],"words":["smeren","strooien","smelten","heet","rond","kaas","plakjes"],"learn":["fijne-motoriek","creativiteit","zintuigen"],"tips":["Gebruik restjes uit de koelkast, zoals een halve paprika of een stukje kaas: zo is het meteen een avondmaaltijd.","Trek je kind een oud shirt aan: tomatensaus vlekt, en kleine handen smeren graag met hun vingers."],"extenders":["Teken tijdens het bakken een menukaart of een pizzadoos van papier, met de naam van elke pizza erop.","Laat je kind ook een piepkleine pizza voor een knuffel maken, op een rondje uitgestoken brood.","Leg het beleg in een patroon langs de rand, als een klok: paprika, maïs, paprika… wat komt er hierna?"],"variations":["Halloween: maak een mummiepizza met reepjes kaas als verband en twee plakjes paprika als ogen.","Koningsdag: beleg de pizza met alles wat oranje is, zoals oranje paprika, geraspte wortel en cheddar.","Fruitpizza: smeer roomkaas op een cracker en beleg die met fruit; die hoeft niet eens de oven in."],"themes":[],"canStay":false,"pinQuery":"mini pizza wraps kinderen"},
  {"id":"boontjes-doppen","title":"Boontjes afhalen en erwtjes doppen","emoji":"🥬","category":"eetbaar","summary":"Knak de puntjes van sperziebonen, wip erwtjes uit hun peul en tel wat je vindt: echte keukenhulp die kleine handjes lang bezighoudt.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"groente","note":"±500 g sperziebonen, peultjes of doperwten in de peul, of een mix"},{"id":"kom","note":"drie: een voor de groente, een voor de goede stukjes en een voor het afval"}],"optional":[{"id":"dienblad","note":"met een randje: weggerolde erwtjes blijven erop liggen"},{"id":"muffinvorm","note":"om erwtjes in te tellen en te sorteren"},{"id":"vergiet","note":"om de groente samen te wassen"}],"steps":["Zet je kind aan tafel met drie kommen: een met de groente, een lege voor de goede stukjes en een voor de puntjes en lege peulen.","Doe voor hoe afhalen gaat: knak bij een sperzieboon aan beide kanten het puntje eraf en gooi het in de afvalkom.","Laat je kind zelf afhalen: knak, knak, in de kom! Trek bij peultjes het draadje mee als dat er is.","Dop de erwtjes: druk met je duim op de naad van de peul tot hij openspringt, en schuif de erwtjes er met je duim uit.","Tel de erwtjes in elke peul: wie vindt de peul met de meeste?","Was de groente samen in een vergiet onder de kraan en doe alles in de pan.","Kook de groente (dat doe jij) en eet samen op wat je kind heeft gedopt. De lege peulen en puntjes gaan in de groenbak."],"ageTips":{"young":"Begin met een driejarige bij peultjes of sperziebonen: puntjes eraf knakken lukt al goed. Maak bij doperwten de peul alvast een stukje open, dan schuift je kind de erwtjes er zelf uit.","old":"Laat je kleuter de erwtjes per peul tellen en de peulen op een rij leggen van weinig naar veel. Of weeg samen af: hoeveel gram heb je gedopt, en is dat genoeg voor iedereen?"},"safety":["Kleine, ronde en harde rauwe erwtjes geven verstikkingsgevaar voor kinderen onder de 4. Laat je kind ze niet rauw snoepen en geef liever gekookte erwtjes om te proeven, voor een peuter even platgedrukt.","Rauwe sperziebonen zijn niet om te eten: ze bevatten een stof die pas verdwijnt als je ze kookt. Kook ze altijd een paar minuten.","Laat je kind zitten tijdens het doppen en proeven: wie rondloopt met eten in de mond, verslikt zich sneller.","Koken doe jij: houd je kind uit de buurt van de pan met kokend water."],"say":["Knak! Daar gaat het puntje.","Hoeveel erwtjes zitten er in deze peul, denk je?","Ruik eens aan de open peul: hoe ruikt dat?","Ik zie dat je heel precies alleen het puntje eraf knakt.","Je hebt al een halve kom vol. Wat werk jij goed door!"],"words":["peul","erwt","boon","knakken","doppen","groen","glad","rond"],"learn":["fijne-motoriek","rekenen","concentratie","zintuigen"],"tips":["Werk op een dienblad met een randje: weggerolde erwtjes blijven er dan op liggen.","Doperwten in de peul zijn er vooral in juni en juli; peultjes en sperziebonen koop je het hele jaar.","Laat je kind doppen terwijl jij kookt: groente die je zelf hebt gedopt, smaakt aan tafel vaak ineens veel lekkerder."],"extenders":["Maak er een groentewinkel van: je kind schept de gedopte erwtjes in bakjes en verkoopt ze aan jou.","Geef een telopdracht: zoek een peul met precies vijf erwtjes, of leg de peulen op een rij van weinig naar veel.","Leg met de lege peulen en puntjes een gezicht, een zon of een bloem op het dienblad.","Doe er een nieuwe klus bij: champignons schoonmaken met een stukje keukenpapier.","Sorteer de erwtjes in een muffinvorm: grote en kleine, of tien in elk vakje."],"variations":["Zomer: dop tuinbonen. De grote bonen liggen in een zacht, donzig bedje. Eet tuinbonen alleen gekookt.","Winter: pel mandarijnen en tel de partjes. Hoeveel zitten er in elke mandarijn?","Kruidentuin: pluk de blaadjes van takjes peterselie, dille of tijm voor in de soep of de saus."],"themes":["zomer"],"canStay":false,"pinQuery":"kind erwtjes doppen keuken"},
  {"id":"zelf-snijden","title":"Snijden als een echte kok","emoji":"🍌","category":"eetbaar","summary":"Met een botermes en een eigen snijplank snijdt je kind banaan, aardbei en komkommer in stukjes voor een fruitsalade: echt koken, net als de groten.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[20,45],"supervision":1,"soloFrom":null,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel","keuken"],"materials":[{"id":"kindermes","note":"een botermes of kindermes met afgeronde punt, liefst met kartelrand"},{"id":"snijplank"},{"id":"fruit","note":"zacht en rijp: banaan, aardbei, kiwi (jij schilt), peer of meloen"},{"id":"groente","note":"komkommer, champignons of een gekookte aardappel van gisteren"},{"id":"kom","note":"voor de fruitsalade"},{"id":"handdoek","note":"een vochtige theedoek onder de snijplank, zodat de plank niet wegschuift"}],"optional":[{"id":"uitsteekvormpjes","note":"om figuurtjes uit plakken meloen of komkommer te steken"},{"id":"oud-shirt","note":"of een schort, voor de plakkerige vingers"},{"id":"bord","note":"om de stukjes op te leggen of op te dienen"}],"steps":["Zet je kind aan tafel met een snijplank, een botermes en een kom. Leg een vochtige theedoek onder de snijplank, dan schuift de plank niet weg.","Maak alles snijklaar: pel de banaan, schil de kiwi en snijd komkommer en aardappel in de lengte doormidden, zodat ze plat liggen.","Doe het langzaam voor: houd het fruit vast met je vingertoppen naar binnen gekruld en zaag met het mes heen en weer.","Begin met iets zachts: laat je kind plakjes banaan snijden, dan aardbeien, kiwi en meloen, en doe alles in de kom.","Roer de fruitsalade om en zet de kom in de koelkast voor het toetje.","Ga door met groente voor het avondeten: plakjes komkommer, champignons in vieren of blokjes gekookte aardappel.","Eet samen op wat je kind heeft gesneden en doe snijplank en mes daarna samen in de afwas."],"ageTips":{"young":"Een tweejarige zaagt het liefst door een gepelde banaan of een gekookte aardappel. Geef één zacht ding tegelijk en snijd de eerste keer hand over hand: jouw hand om de hand van je kind.","old":"Leer je kleuter de klauwgreep (vingertoppen naar binnen gekruld, weg van het mes) en de brug (duim en vingers aan weerszijden, snijden onder het bruggetje door). Een vijfjarige snijdt zo ook reepjes paprika en plakjes courgette."},"safety":["Gebruik alleen een botermes of kindermes met afgeronde punt. Scherpe messen gebruik jij, en die liggen buiten bereik.","Leg ronde dingen eerst plat: halveer komkommer, aardappel en kiwi zelf in de lengte, zodat er niets wegrolt onder het mes.","Druiven en cherrytomaatjes snijd jij in de lengte in vieren: hele zijn een verstikkingsgevaar en ze zijn te glad voor kleine handjes.","Spreek af: mes neer als je iets anders doet, zoals proeven, praten of opstaan. Blijf er de hele tijd bij."],"say":["Zaag, zaag… doormidden!","Hoe voelt de banaan als je erdoor snijdt: zacht of hard?","Ik zie dat je je vingers netjes bij het mes vandaan houdt.","In hoeveel stukjes heb je deze aardbei gesneden?","Wat doen we nog meer in de fruitsalade?"],"words":["snijden","plakje","stukje","doormidden","zacht","stevig","sappig","mes neer"],"learn":["fijne-motoriek","concentratie","rekenen","zintuigen"],"tips":["Een kindermes met kartelrand snijdt makkelijker dan een gewoon botermes: minder kracht nodig, dus minder uitschieten.","Plan het vlak voor het eten: je kind snijdt het toetje of de groente en schept trots op voor iedereen aan tafel.","Kies zacht en rijp fruit: een harde peer of appel is te lastig voor een botermes en zorgt alleen voor frustratie."],"extenders":["Geef een nieuwe snijopdracht: plakjes, blokjes of precies doormidden. Lukt het om een aardbei in vier stukjes te snijden?","Steek met uitsteekvormpjes figuurtjes uit plakken meloen of komkommer.","Leg de stukjes in een patroon op een bord, banaan, aardbei, banaan…, en eet het patroon daarna op.","Open een restaurant: je kind snijdt een bordje voor elk gezinslid en vraagt wat iedereen wil.","Doe er een nieuwe uitdaging bij, zoals een stuk meloen in blokjes of een gekookte wortel in plakjes."],"variations":["Kaasplankje: snijd blokjes kaas en komkommer voor een verjaardag of een feestje.","Soep: laat je kind courgette, champignons en een gekookte aardappel in stukjes snijden voor in de soep; het koken doe jij.","Koningsdag: maak een oranje fruitsalade van mandarijn, meloen en sinaasappel.","Bananensushi: besmeer een wrap met roomkaas of pindakaas (let op allergie), rol er een banaan in en snijd er plakjes van."],"themes":[],"canStay":false,"pinQuery":"peuter leert snijden kindermes"},
  {"id":"kroon-maken","title":"Een kroon voor koning of koningin","emoji":"👑","category":"fantasie","summary":"Knip een kartonnen strook met punten, versier hem met stickers en glimmende foliejuwelen en zet hem op maat: klaar voor de kroning!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"karton","note":"een strook van ±10 cm hoog en ±60 cm lang, bijv. twee stroken van een cornflakesdoos"},{"id":"aluminiumfolie","note":"voor glimmende juwelen"},{"id":"stickers"},{"id":"nietmachine","note":"om de kroon op maat te maken (dat doe jij)"},{"id":"plakband"}],"optional":[{"id":"stiften","note":"of waskrijt, om te kleuren"},{"id":"gekleurd-papier","note":"geel, om de kroon mee te beplakken"},{"id":"lijmstift"},{"id":"kinderschaar","note":"voor kleuters die zelf de punten knippen"}],"steps":["Meet met een strook papier om het hoofd van je kind hoe lang de kroon moet worden en tel er 3 cm bij op.","Knip een strook karton van ±10 cm hoog op die lengte. Plak zo nodig twee stroken aan elkaar.","Teken een zigzaglijn over de bovenkant en knip de punten uit. Dat doe jij; een kleuter knipt zelf langs de lijn.","Laat je kind de kroon versieren met stickers en stift. Voor een gouden kroon plak je er eerst geel papier op.","Maak juwelen: scheur stukjes folie af, frommel ze tot propjes, druk ze plat en plak ze vast met een rolletje plakband.","Zet de kroon om het hoofd op maat met twee nietjes en plak de nietjes aan de binnenkant af.","Houd een echte kroning: laat je kind op een ‘troon’ zitten en zet de kroon plechtig op."],"ageTips":{"young":"Voor een tweejarige knip jij de kroon vooraf uit. Stickers plakken en folie frommelen is voor je peuter het hele feest: hoe meer, hoe beter.","old":"Laat je kleuter zelf punten tekenen en knippen, en een patroon maken: rood, blauw, rood, blauw. Hoeveel punten heeft jouw kroon?"},"safety":["Zet de nietjes met de gladde kant naar binnen en plak er een stukje plakband over, zodat er niets in het voorhoofd prikt.","Foliepropjes en stickers zijn klein: plak ze bij een tweejarige stevig vast en ruim losse stukjes meteen op. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Welke kleur juwelen moeten er op jouw kroon?","Kijk, de folie glimt als je hem beweegt!","Je drukt elke sticker heel stevig vast. Wat werk je precies.","Wat zou jij doen als je een dag koning of koningin was?","Kroon op! Hoera!"],"words":["kroon","punt","glimmen","juweel","koning","koningin","hoog"],"learn":["fijne-motoriek","creativiteit","taal"],"tips":["Plak de juwelen met plakband in plaats van lijm: dan kan de kroon meteen op en hoef je niets af te wassen.","Knip een paar kronen tegelijk uit en bewaar ze plat: handig voor een verjaardag of een regenachtige middag."],"extenders":["Maak er een scepter bij van een keukenrolkoker met folie, en een mantel van een handdoek of deken.","Geef je kind de macht: met de kroon op deelt je kind opdrachten uit (spring, klap, buig!) en jij voert ze uit.","Knip kleine kroontjes voor de knuffels en laat je kind ze versieren: elke knuffel wordt prins of prinses."],"variations":["Koningsdag: een oranje kroon met een rood-wit-blauw vlaggetje op de hoogste punt.","Verjaardag: zet het nieuwe leeftijdsgetal groot op de voorkant en plak op elke punt een papieren kaarsje.","Carnaval: maak er een prinsenkroon van met veertjes, of een bloemenkrans van gekleurde papieren bloemen.","Herfst: plak bladeren op een kartonnen strook voor een kroon van de koning van het bos."],"themes":["koningsdag","verjaardag","carnaval"],"canStay":false,"pinQuery":"kroon maken karton kind"},
  {"id":"sokpoppen","title":"Sokpoppen maken","emoji":"🧦","category":"fantasie","summary":"Tover een oude sok om tot een praatpop met ogen, wollen haar en een vilten tong, en speel daarna samen een voorstelling.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[15,30],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"sokken","note":"een effen sok per pop"},{"id":"knutsellijm","note":"witte hobbylijm, of textiellijm als je die hebt"},{"id":"vilt","note":"rood of roze voor de tong, wit voor de ogen"},{"id":"touw","note":"wol in een vrolijke kleur, voor het haar"},{"id":"stiften","note":"voor pupillen en wangetjes"}],"optional":[{"id":"karton","note":"om in de sok te schuiven tijdens het plakken"},{"id":"wiebeloogjes","note":"alleen vanaf 3 jaar"},{"id":"pompons","note":"als neus, alleen vanaf 3 jaar"},{"id":"kinderschaar","note":"voor kleuters die zelf vilt knippen"}],"steps":["Doe de sok om je hand: vingers in de teen, duim in de hiel. Laat zien hoe de mond open en dicht gaat.","Schuif een stuk karton in de sok, zodat de lijm niet doorlekt naar de andere kant.","Knip een tong van rood vilt (dat doe jij) en laat je kind die met knutsellijm in de mond plakken.","Plak ogen van wit vilt boven op de kop en teken er samen pupillen op.","Knip wol in stukjes van ±10 cm en laat je kind het haar bovenop plakken.","Laat de pop een paar uur drogen, liefst een nacht, voordat hij om een hand mag.","Speel een voorstelling: de rugleuning van de bank is het podium. Wat heeft de sok te vertellen?"],"ageTips":{"young":"Voor een tweejarige teken jij de ogen met stift en houd je het bij een tong en wat haar. Laat de pop meteen praten: een pratende sok is voor je peuter al magisch.","old":"Laat je kleuter zelf vilt knippen, een naam en een stemmetje bedenken, en met twee poppen een gesprekje spelen: wie is er boos, en hoe maken ze het weer goed?"},"safety":["Wiebeloogjes, pompons en knopen zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Teken bij een tweejarige de ogen of gebruik grote rondjes vilt.","Trek na het drogen even aan ogen, neus en haar: zit iets los, plak het opnieuw voordat de pop in een peutermondje belandt."],"say":["Hallo! Ik ben Sok. Hoe heet jij?","Hap! Hap!","Wat zou jouw pop het liefst eten?","Je hebt het haar plukje voor plukje vastgeplakt. Wat werk je geduldig.","Is je pop vandaag blij of boos? Hoe klinkt dat?"],"words":["sok","mond","open","dicht","haar","tong","praten","fluisteren"],"learn":["creativiteit","taal","fijne-motoriek","samen"],"tips":["Haast? Teken ogen en wangetjes met stift en speel meteen; plakken kan morgen.","Maak ook een pop voor jezelf: twee poppen die met elkaar praten, maken het spel meteen echt.","Zet de sokpop in bij lastige momenten: een sok die meehelpt met tandenpoetsen of opruimen, werkt vaak wonderen."],"extenders":["Interview de sokpop: hoe heet je, wat eet je graag, waar woon je? Je kind antwoordt met de popstem.","Geef de pop een opdracht: een liedje zingen, de knuffels gedag zeggen of een boekje voorlezen.","Maak samen een bedje of huisje van een schoenendoos waar de sokpop mag slapen."],"variations":["Dierensok: een slang met een lange tong, een draak met vilten stekels op de rug of een hond met flaporen.","Familie: maak een pop voor elk gezinslid, met dezelfde haarkleur als het echte gezinslid.","Papieren zakje: geen losse sok? Een boterhamzakje met een getekend gezicht is ook een handpop.","Monsterfeest: drie ogen, wild haar en een tong met stippen."],"themes":[],"canStay":false,"pinQuery":"sokpoppen maken met kinderen"},
  {"id":"poppenkast","title":"Poppenkast van een grote doos","emoji":"🎭","category":"fantasie","summary":"Een grote doos met een raam en een theedoek als gordijn wordt een echt theater, waar knuffels en sokpoppen hun eigen voorstelling geven.","ageMin":3,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":15,"duration":[20,40],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":1,"places":["vloer"],"materials":[{"id":"dozen","note":"een grote doos waar je kind achter kan zitten, bijv. een verhuisdoos"},{"id":"mes","note":"of een hobbymes, om het raam uit te snijden (dat doe jij)"},{"id":"handdoek","note":"twee theedoeken als gordijn"},{"id":"ducttape","note":"om het gordijn en losse flappen vast te zetten"},{"id":"stiften","note":"om de doos te versieren"}],"optional":[{"id":"gekleurd-papier","note":"voor sterren, een dak of de naam van het theater"},{"id":"lijmstift"},{"id":"knuffels","note":"als spelers"},{"id":"sokken","note":"voor sokpoppen"}],"steps":["Zet de doos rechtop en teken een groot raam van ±40 bij 30 cm, op ooghoogte van je zittende kind.","Snijd het raam uit en haal ook de achterkant weg, zodat je kind erachter kan zitten. Dat doe jij, terwijl je kind ergens anders speelt.","Plak twee theedoeken met ducttape aan de binnenkant boven het raam: een gordijn dat open en dicht kan.","Laat je kind de voorkant versieren met stiften en gekleurd papier: sterren, een dak, de naam van het theater.","Kies samen de spelers, zoals knuffels, sokpoppen of poppetjes, en bedenk wie er vandaag optreedt.","Geef om de beurt een voorstelling: de een speelt achter de kast, de ander is publiek en klapt na afloop."],"ageTips":{"young":"Een driejarige speelt vooral kiekeboe met het gordijn en laat een knuffel zwaaien. Speel zelf eerst iets kleins voor, zoals de beer die zijn bal kwijt is. Wie helpt zoeken?","old":"Laat je kleuter een verhaal bedenken met een begin, een probleem en een einde, toegangskaartjes tekenen en een bordje maken: ‘Vandaag voorstelling!’"},"safety":["Snijd het raam als je kind niet naast je staat, snijd van je af en berg het mes meteen op.","Een grote doos valt makkelijk om: zet hem tegen de muur of de bank, of leg een paar zware boeken onderin."],"say":["Gordijn open… daar komt de beer!","Wie komt er vandaag op bezoek in de poppenkast?","Wat gebeurt er als de krokodil de beer tegenkomt?","Je hebt het verhaal helemaal tot het einde gespeeld. Wat een doorzetter!","Klappen! Bravo!"],"words":["gordijn","open","dicht","voorstelling","publiek","klappen","achter","voor"],"learn":["creativiteit","taal","samen"],"tips":["Geen grote doos? Hang een laken over de rugleuning van de bank of over een omgedraaide tafel: je kind speelt erachter.","Laat de poppenkast een paar dagen staan: kinderen spelen hun voorstelling graag vaker, steeds een beetje anders."],"extenders":["Laat het publiek meedoen: jij roept namens de knuffels ‘pas op, achter je!’ en de pop moet gaan zoeken.","Geef de spelers nieuwe spullen: een lepel als toverstaf, een washandje als deken, een sok als slang.","Zet een zaklamp als spotlicht op een stapel boeken en doe het grote licht uit voor de volgende voorstelling."],"variations":["Sinterklaas: speel met knuffels de aankomst van de boot, of het paard dat over de daken loopt.","Dierengeluiden: alleen dieren uit de speelgoedkist, en het publiek raadt welk dier er piept, blaft of brult.","Sprookjes: speel Roodkapje of de drie biggetjes na met wat er in huis is.","Minitheater: plak gezichtjes van papier op wc-rolletjes en speel in een schoenendoos op tafel."],"themes":[],"canStay":true,"stayTips":"Zet de poppenkast tegen de muur of de bank, met een paar zware boeken onderin, zodat hij niet omvalt. Leg de spelers in een mand ernaast: dan kan de volgende voorstelling meteen beginnen.","pinQuery":"poppenkast maken van doos"},
  {"id":"schaduwtheater","title":"Schaduwtheater met een zaklamp","emoji":"🔦","category":"fantasie","summary":"Knip figuren uit karton, zet ze op een stokje en laat ze in het licht van de zaklamp als grote schaduwen over de muur dansen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[20,30],"supervision":1,"soloFrom":4,"cleanupMinutes":2,"noise":1,"energy":1,"places":["muur","tafel"],"materials":[{"id":"karton","note":"dun karton, bijv. van een cornflakesdoos"},{"id":"ijsstokjes","note":"of rietjes, één per figuur"},{"id":"plakband"},{"id":"potlood"},{"id":"zaklamp","note":"of het lampje van je telefoon"}],"optional":[{"id":"dekens","note":"een wit laken, als je geen lichte muur hebt"},{"id":"wasknijpers","note":"om het laken op te hangen"},{"id":"kinderschaar","note":"voor kleuters die zelf grote vormen knippen"},{"id":"vloeipapier","note":"voor gekleurde raampjes in de figuren"}],"steps":["Teken samen een paar eenvoudige figuren van ±15 cm op karton: een kat, een huis, een maan, een spookje.","Knip de figuren uit (dat doe jij; een kleuter knipt grote vormen zelf) en plak elk figuur met plakband op een ijsstokje.","Maak de kamer donker en kies een lichte, lege muur, of hang met wasknijpers een wit laken over een wasrek.","Zet de zaklamp op een stapel boeken of op tafel, met het licht op de muur gericht.","Houd de figuren tussen de lamp en de muur. Dicht bij de lamp wordt de schaduw groot, dicht bij de muur klein en scherp.","Vertel samen een verhaal en laat je kind de figuren bewegen, praten en verstoppen."],"ageTips":{"young":"Een driejarige vindt het donker soms spannend: laat een klein lampje aan en begin met handschaduwen en een knuffel. Jij vertelt, je peuter beweegt de figuren.","old":"Laat je kleuter zelf figuren tekenen en knippen, en een verhaal met een begin, een probleem en een einde bedenken. Maak er kaartjes bij voor het publiek."},"safety":["Schijn niet met de zaklamp of het telefoonlampje recht in elkaars ogen: zet de lamp vast neer in plaats van ermee te zwaaien.","Ruim speelgoed en snoeren van de vloer voordat je de kamer donker maakt, zodat niemand struikelt."],"say":["Kijk, de kat wordt groter en groter!","Wat gebeurt er als je de maan dichter bij de lamp houdt?","Boe! Een spookje!","Je houdt het stokje heel stil, daardoor is de schaduw mooi scherp.","Waar is de schaduw gebleven als de lamp uit is?"],"words":["schaduw","licht","donker","groot","klein","dichtbij","ver weg","scherp"],"learn":["ontdekken","creativiteit","taal","fijne-motoriek"],"tips":["Speel aan het eind van de middag in de herfst of winter: dan is het vroeg donker en hoef je niets voor de ramen te hangen.","Bewaar de figuren in een envelop: zo heb je een kant-en-klaar theater voor de volgende keer."],"extenders":["Haal spullen uit huis en kijk welke schaduw ze maken: een vergiet geeft sterretjes, een vork een hekje. Wat is het gekst?","Speel raad de schaduw: houd stiekem iets voor de lamp en laat je kind raden wat het is. Daarna andersom.","Ga zelf met je rug naar de lamp in het licht staan en maak je schaduw zo groot als een reus of zo klein als een muis."],"variations":["Halloween: spookjes, vleermuizen en een maan met een gezicht.","Winter: een sneeuwpop en een ster, en sneeuwvlokken die langzaam naar beneden dwarrelen.","Handschaduwen: maak met je handen een konijn, een hond of een vogel die wegvliegt.","Kleur: knip een raampje in een figuur en plak er vloeipapier over: een gekleurde schaduw!"],"themes":["halloween","winter"],"canStay":false,"pinQuery":"schaduwtheater zaklamp kinderen"},
  {"id":"dierenmaskers","title":"Dierenmaskers van papieren bordjes","emoji":"🦁","category":"fantasie","summary":"Verf een papieren bordje, plak er oren en een snuit op en houd het masker aan een stokje voor je gezicht: brul als een leeuw!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":true,"prepMinutes":5,"duration":[15,30],"supervision":2,"soloFrom":3,"cleanupMinutes":10,"noise":2,"energy":2,"places":["tafel","vloer"],"materials":[{"id":"papieren-bordjes","note":"één per masker"},{"id":"potlood"},{"id":"plakkaatverf","note":"of waskrijt en stiften als het minder vies mag"},{"id":"penselen"},{"id":"gekleurd-papier","note":"voor oren, snuit en manen"},{"id":"lijmstift"},{"id":"ijsstokjes","note":"als handvat"},{"id":"ducttape","note":"of stevig plakband, om het stokje vast te zetten"}],"optional":[{"id":"pijpenragers","note":"als snorharen"},{"id":"touw","note":"wol, voor manen of haar"},{"id":"veren","note":"voor een vogel- of uilenmasker"},{"id":"oud-shirt"},{"id":"oud-laken","note":"als knoeimat"}],"steps":["Houd het bordje voor het gezicht van je kind en zet met potlood twee stipjes waar de ogen komen.","Knip de ooggaten uit, ruim 3 cm groot. Dat doe jij: prik eerst een gaatje met de punt van de schaar.","Kies samen een dier en verf het bordje: geel voor een leeuw, roze voor een varken, grijs voor een muis.","Knip oren en een snuit uit gekleurd papier en laat je kind ze vastplakken. Voor een leeuw: stroken rondom als manen.","Laat de verf ±30 minuten drogen en plak dan een ijsstokje met ducttape aan de onderkant.","Speel ermee: raad welk dier er achter het masker zit, maak het geluid en houd een dierenoptocht door de kamer."],"ageTips":{"young":"Veel tweejarigen schrikken van iets vlak voor hun gezicht. Houd het masker eerst zelf op, speel kiekeboe en laat je peuter kiezen: voor het gezicht of gewoon in de hand.","old":"Laat je kleuter zelf een dier ontwerpen: welke oren, welke kleur, snorharen of veren? Laat de oren zelf knippen en bedenk samen een geluid en een loopje."},"safety":["Met een masker voor de ogen zie je minder: niet rennen, klimmen of traplopen met het masker op.","Pijpenragers hebben scherpe draadpuntjes: vouw de uiteinden een stukje om voordat ze als snorharen op het masker gaan.","Plakkaatverf kan vlekken op kleding en tafel: kies afwasbare kinderverf en trek een oud shirt aan."],"say":["Wie zit er achter dat masker? Is het een leeuw?","Kiekeboe!","Hoe klinkt jouw dier: brult het, piept het of knort het?","Je hebt het hele bordje geel gemaakt, tot in de randjes.","Welk dier wil jij vandaag zijn, en wat eet dat dier?"],"words":["masker","oren","snuit","snorharen","brullen","piepen","knorren","kiekeboe"],"learn":["creativiteit","fijne-motoriek","taal"],"tips":["Minder rommel: kleur het bordje met waskrijt in plaats van verf, dan kan het masker meteen gebruikt worden.","Maak een masker voor jezelf mee: samen een dierenfamilie spelen is veel leuker dan alleen."],"extenders":["Bouw een dierentuin: elk dier krijgt een hok onder de tafel of achter de bank, en de verzorger brengt eten.","Vertel een verhaal waarin de dieren om de beurt opduiken: hoort je kind het eigen dier, dan springt het tevoorschijn met masker en geluid.","Doe het masker even omlaag en beweeg als het dier: sluipen als een kat, waggelen als een eend, springen als een kikker."],"variations":["Carnaval: maak voor iedereen in huis een masker en houd een optocht op muziek.","Halloween: een zwarte kat, een vleermuis of een uil met veren.","Boerderij: een kip met veren, een varken met een snuit van een eierdoos-kuiltje of een koe met vlekken.","Herfst: een vos of een egel met echte bladeren als vacht."],"themes":["carnaval","halloween"],"canStay":false,"pinQuery":"dierenmaskers papieren bordjes kind"},
  {"id":"superheldencape","title":"Superheldencape zonder naaien","emoji":"🦸","category":"fantasie","summary":"Knip van een oud T-shirt een cape, plak er een eigen superheldenteken op en ga samen op reddingsmissie door de kamer.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[20,40],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["tafel","vloer"],"materials":[{"id":"oud-shirt","note":"een groot T-shirt van een volwassene, of een oude kussensloop"},{"id":"vilt","note":"of gekleurd papier, voor het superheldenteken"},{"id":"knutsellijm","note":"of textiellijm; voor papier werkt plakband ook"},{"id":"wasknijpers","note":"twee, om de cape los op de schouders vast te zetten"},{"id":"potlood"}],"optional":[{"id":"kinderschaar","note":"voor kleuters die zelf het teken knippen"},{"id":"aluminiumfolie","note":"voor een glimmende bliksem of ster"},{"id":"stiften"}],"steps":["Leg het T-shirt plat neer en knip de mouwen eraf (dat doe jij).","Knip langs de zijnaden en over de schoudernaden, zodat je het achterpand als één grote lap overhoudt.","Knip de cape op lengte: hij moet boven de knieholtes van je kind eindigen. Knip de onderkant recht, rond of met punten.","Laat je kind een teken kiezen, zoals een bliksem, een ster, een hart of de eerste letter van de naam, en teken het op vilt.","Knip het teken uit, plak het midden op de cape en laat het ±1 uur plat drogen.","Zet de cape met twee wasknijpers vast op de schouders van het shirt van je kind.","Bedenk samen een superheldennaam en een superkracht, en ga op missie: welke knuffels moeten er gered worden?"],"ageTips":{"young":"Een driejarige wil vooral snel een cape om. Knip jij de cape vooraf en laat je peuter het teken kleuren; opplakken kan straks.","old":"Laat je kleuter het teken zelf ontwerpen en knippen, en een missie met drie opdrachten bedenken: vlieg naar de keuken, red de beer, tel tot tien."},"safety":["Maak de cape nooit vast met een knoop of koord om de nek: blijft hij ergens achter haken, dan trekt hij de keel dicht. Wasknijpers schieten vanzelf los.","Doe de cape af bij klimmen (bank, trap, klimrek), in het autostoeltje en voor het slapen.","Superhelden vliegen over de vloer: rennen met gestrekte armen mag, springen van de bank of de trap niet."],"say":["Wat is jouw superkracht?","Zwiep! Daar vliegt de superheld!","Je hebt zelf een teken bedacht dat niemand anders heeft.","Wie moet er vandaag gered worden?","Hoe voelt het als je cape achter je aan wappert?"],"words":["cape","superheld","sterk","snel","vliegen","redden","zwiep"],"learn":["creativiteit","grove-motoriek","taal"],"tips":["Meteen spelen? Een kussensloop of oude handdoek met twee wasknijpers op de schouders is in één minuut een cape.","T-shirtstof rafelt niet: je hoeft de randen niet te zomen."],"extenders":["Verzin een nieuwe superkracht en test hem meteen: supersterk (een kussen sjouwen), supersnel (vijf blokken opruimen) of onzichtbaar (verstoppen).","Maak een geheim hoofdkwartier onder de tafel, met een pan als alarmbel: als jij erop slaat, begint de volgende missie.","Geef een knuffel een cape van een washandje met een wasknijper: nu heeft je superheld een hulpje."],"variations":["Carnaval: maak er een tovenaarscape van met sterren en een maan van aluminiumfolie.","Verjaardag: maak capes voor alle feestgangers met de eerste letter van hun naam en speel een superheldenspeurtocht.","Reddingsmissie: verstop knuffels door het huis; elke geredde knuffel krijgt een pleister of een medaille van papier.","Superheldenmasker: knip een oogmasker van vilt of karton en houd het aan een ijsstokje voor je gezicht."],"themes":["carnaval","verjaardag"],"canStay":false,"pinQuery":"superheldencape maken oud t-shirt"},
  {"id":"winkeltje","title":"Winkeltje spelen met zelfgemaakt geld","emoji":"🛒","category":"fantasie","summary":"Zet lege verpakkingen op een rij, teken samen geld en prijskaartjes en speel om de beurt winkelier en klant.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":10,"duration":[20,40],"supervision":1,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer","tafel"],"materials":[{"id":"verpakkingen","note":"8-10 lege doosjes, pakken en bakjes, omgespoeld"},{"id":"papier","note":"voor munten en briefjes"},{"id":"stiften"},{"id":"kinderschaar","note":"om het geld uit te knippen"},{"id":"schilderstape","note":"voor prijskaartjes"}],"optional":[{"id":"dozen","note":"als kassa, met een gleuf erin"},{"id":"wasmand","note":"als winkelmandje"},{"id":"stoffen-tas","note":"als boodschappentas"},{"id":"fruit","note":"echt fruit om te verkopen"}],"steps":["Zet 8-10 lege verpakkingen op een rij op de bank of een lage tafel: dat is het winkelschap.","Teken samen geld: rondjes als munten en rechthoeken als briefjes, met 1, 2 of 5 stippen erop. Knip ze uit.","Plak op elk product een stukje schilderstape als prijskaartje en teken er 1, 2 of 3 stippen op.","Maak een kassa van een doos met een gleuf (die snijd jij), of gebruik een bakje.","Speel om de beurt winkelier en klant: zeg goedemorgen, kies iets, betaal en tel samen de stippen af.","Ruil van rol en ruim samen op: alle munten in de kassa, alle producten terug op het schap."],"ageTips":{"young":"Geef een driejarige alleen munten met één stip en laat elk product één of twee munten kosten. Speel zelf eerst de klant: om de beurt praten is al de helft van het spel.","old":"Laat je kleuter zelf prijzen bedenken en cijfers op de kaartjes schrijven, en oefen met wisselgeld: je betaalt vijf, het kost drie. Wat krijg je terug?"},"safety":["Gebruik geen verpakkingen van schoonmaakmiddel, vaatwastabletten of medicijnen: zo blijft duidelijk dat die nooit speelgoed zijn.","Laat blikjes en glazen potjes weg: scherpe randen en scherven horen niet in een speelwinkel."],"say":["Goedemorgen! Wat mag het zijn?","Dit pak kost drie munten. Tel je mee?","Hoeveel munten heb je nog over?","Wat goed dat je wacht tot je aan de beurt bent.","Alsjeblieft! Dankjewel!"],"words":["kopen","betalen","munt","duur","goedkoop","meer","minder","alsjeblieft"],"learn":["rekenen","taal","samen"],"tips":["Bewaar een week lang lege verpakkingen in een doos: dan heb je een volle winkel zonder iets te kopen.","Echte appels en mandarijnen maken het extra echt; de ‘boodschappen’ gaan daarna gewoon de fruitschaal in."],"extenders":["Geef de klant een boodschappenlijstje met tekeningetjes (een appel, een melkpak, twee doosjes) en laat je kind alles bij elkaar zoeken.","Maak een scanner van een blokje of een wc-rolletje: piep! Elk product moet eerst langs de kassa.","Begin een bezorgdienst: de winkelier brengt bestellingen in de wasmand naar de knuffels op de bank."],"variations":["Groenteman: verkoop echte groente en fruit en weeg alles op de keukenweegschaal.","IJssalon: plastic bekers met propjes papier als bolletjes; elk bolletje kost één munt.","Bakkerij: bak broodjes en taartjes van speeldeeg en verkoop ze in de winkel.","Sinterklaas: maak een speelgoedwinkel en pak de gekochte cadeautjes samen in krantenpapier in."],"themes":[],"canStay":true,"stayTips":"Laat de winkel een paar dagen op een lage kast of in een hoekje staan en bewaar het geld in een envelop in de kassa, zodat het niet zoekraakt. Vul de winkel tussendoor aan met nieuwe lege verpakkingen, maar nooit van schoonmaakmiddel of medicijnen.","pinQuery":"winkeltje spelen lege verpakkingen"},
  {"id":"knuffeldokter","title":"Dokter spelen voor knuffels","emoji":"🩹","category":"fantasie","summary":"Open de knuffelpraktijk: luister naar hartjes, plak pleisters, wikkel verband om en schrijf een recept voor de zieke beer.","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["vloer"],"materials":[{"id":"knuffels","note":"een paar ‘zieke’ patiënten"},{"id":"pleisters","note":"of stukjes schilderstape met een getekend hartje"},{"id":"keukenpapier","note":"in stroken, als verband"},{"id":"schilderstape","note":"om het verband vast te plakken"},{"id":"dozen","note":"een schoenendoos als dokterstas"}],"optional":[{"id":"wc-rollen","note":"als stethoscoop of kijker"},{"id":"papier","note":"voor recepten en afsprakenkaartjes"},{"id":"stiften"},{"id":"lepel","note":"voor ‘medicijn’ van lucht"}],"steps":["Maak een dokterstas: teken een hartje op een schoenendoos en vul hem met pleisters, stroken keukenpapier en schilderstape.","Zet de zieke knuffels op een rij in de wachtkamer, bijvoorbeeld op de bank.","Roep de eerste patiënt binnen en vraag samen: waar doet het pijn?","Laat je kind onderzoeken: luisteren met een wc-rolletje, in de oren kijken, voelen aan de buik.","Wikkel verband van keukenpapier om een poot en plak het vast, of plak een pleister op de pijnlijke plek.","Teken een recept, zoals twee knuffels per dag en vroeg naar bed. Daarna mag de volgende patiënt komen."],"ageTips":{"young":"Voor je tweejarige is één knuffel met een paar pleisters genoeg: plakken en weer lostrekken is al spannend. Benoem de lichaamsdelen: poot, oor, buik.","old":"Laat je kleuter een wachtkamer met nummertjes maken, afsprakenkaartjes tekenen en zelf het recept schrijven. Speel ook eens dierenarts of tandarts."},"safety":["Gebruik nooit echte medicijnen, pillen, zalf of een injectiespuit met naald, en vertel erbij dat echte medicijnen alleen van jou of de dokter komen.","Speel je ook dokter op elkaar: wikkel nooit verband of touw om de nek, en stop niets in neus of oren, ook geen wattenstaafje.","Pleisterpapiertjes zijn klein en glad: ruim ze meteen op als er ook een dreumes rondloopt."],"say":["Ach, beer heeft pijn aan zijn poot. Wat moeten we doen?","Au! Pleister erop!","Luister… hoor je zijn hartje? Boem, boem.","Wat zorg jij voorzichtig voor je knuffel.","Wat deed de dokter toen jij er was?"],"words":["pijn","beter","pleister","verband","luisteren","voorzichtig","dokter","buik"],"learn":["taal","fijne-motoriek","creativiteit","samen"],"tips":["Gebruik het spel om een echt doktersbezoek of een prik voor te bereiden: speel samen na wat er gaat gebeuren.","Spaar je pleisters: stukjes schilderstape met een getekend hartje werken net zo goed en zijn veel goedkoper."],"extenders":["Laat er een nieuwe patiënt aankomen met de ambulance: een knuffel in een wasmand die je kind voorzichtig naar de praktijk duwt.","Laat een knuffel bellen met een blokje als telefoon: mijn oor doet pijn! De dokter maakt een afspraak en schrijft die op.","Maak de patiënten beter: haal na een poosje het verband eraf, geef een sticker als beloning en zwaai ze uit."],"variations":["Dierenarts: alle dieren uit de speelgoedkist krijgen een hok van een doos en een eigen etensbakje.","Tandarts: tel de tanden van een knuffel en poets ze met een oude tandenborstel.","Ziekenhuis: maak bedjes van schoenendozen met een theedoek als deken.","Consultatiebureau: weeg en meet de knuffels en zet het met streepjes op hun eigen kaart."],"themes":[],"canStay":false,"pinQuery":"dokter spelen knuffels peuter"},
  {"id":"eigen-boekje","title":"Mijn eigen boekje maken","emoji":"📖","category":"fantasie","summary":"Vouw een boekje, laat je kind tekenen en plakken, en schrijf erbij wat het vertelt: een eigen verhaal om steeds weer voor te lezen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,30],"supervision":1,"soloFrom":4,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"papier","note":"3 vellen A4"},{"id":"nietmachine","note":"om de rug vast te zetten (dat doe jij)"},{"id":"kleurpotloden","note":"of stiften en waskrijt"},{"id":"potlood","note":"of pen, om op te schrijven wat je kind vertelt"}],"optional":[{"id":"tijdschriften","note":"om plaatjes uit te knippen"},{"id":"lijmstift"},{"id":"kinderschaar"},{"id":"gekleurd-papier","note":"voor een stevige kaft"},{"id":"stickers"}],"steps":["Leg 3 vellen A4 op elkaar en vouw ze samen dubbel: zo heb je een boekje van 12 bladzijden.","Zet twee nietjes in de vouw (dat doe jij). Voor een stevige kaft vouw je er eerst een vel gekleurd papier omheen.","Kies samen een onderwerp: ik, mijn dag, onze kat, wat ik leuk vind of een verzonnen avontuur.","Laat je kind per bladzijde tekenen, of plaatjes uit tijdschriften knippen en opplakken.","Vraag wat er op de bladzijde gebeurt en schrijf het onder de tekening op, precies zoals je kind het zegt.","Maak samen de kaft met een titel, een tekening en ‘geschreven door…’, en lees het boekje daarna samen voor."],"ageTips":{"young":"Een driejarige vertelt vaak één zin per plaatje, en dat is genoeg. Maak een boekje van één vel (4 bladzijden) en laat stickers en plaatjes het werk doen.","old":"Laat je kleuter eerst het verhaal plannen: wat gebeurt er eerst, dan en op het eind? Laat de titel naschrijven en bladzijdenummers erop zetten."},"safety":["De nietmachine is voor jou: houd de vingers van je kind uit de buurt bij het nieten en plak uitstekende nietpuntjes af.","Kies vooraf zelf een paar tijdschriften en folders, zodat er geen enge of ongeschikte plaatjes tussen zitten."],"say":["Wat gebeurt er op deze bladzijde?","En toen? Wat gebeurde er daarna?","Ik schrijf precies op wat jij zegt.","Je hebt aan elke bladzijde gewerkt. Wat een doorzetter!","Klaar! Lezen?"],"words":["boek","bladzijde","kaft","titel","verhaal","schrijver","eerst","daarna"],"learn":["taal","creativiteit","concentratie","fijne-motoriek"],"tips":["Werk in een paar keer: elke dag één bladzijde houdt het leuk, en het verhaal groeit vanzelf.","Zet het boekje tussen de echte boeken en lees het voor het slapengaan voor: kinderen zijn enorm trots op hun eigen boek."],"extenders":["Maak een bladzijde met een flapje: plak een papiertje als deurtje over een tekening. Wat zit erachter?","Verstop op elke bladzijde een klein muisje of sterretje dat de lezer moet zoeken.","Laat je kind het boekje voorlezen aan een rij knuffels, met stemmetjes en omslaan op het goede moment."],"variations":["Cadeau: een boekje voor opa en oma, ‘Wat ik met oma doe’, met tekeningen of foto’s.","Telboek: op elke bladzijde één ding meer, van 1 zon tot 10 stippen.","Voelboek: plak op elke bladzijde iets anders om te voelen, zoals watten, aluminiumfolie, vilt of noppenfolie.","Herfst: een bladerenboek met op elke bladzijde een geplakt blad en wat je kind erover vertelt."],"themes":["cadeau"],"canStay":true,"stayTips":"Bewaar het boekje met een paar potloden in een map of la op kindhoogte; de nietmachine houd je bij jezelf. Maak elke dag een bladzijde en lees het boekje aan het eind van de dag samen voor.","pinQuery":"zelf boekje maken kind tekenen"},
  {"id":"post-voor-opa-en-oma","title":"Post maken voor opa en oma","emoji":"💌","category":"fantasie","summary":"Maak samen een kaart, versier de envelop met een zelfgemaakte postzegel en breng hem naar de brievenbus: opa en oma krijgen echte post!","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[15,25],"supervision":1,"soloFrom":3,"cleanupMinutes":2,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"karton","note":"of een stevig vel papier, dubbelgevouwen als kaart"},{"id":"waskrijt","note":"of stiften en kleurpotloden"},{"id":"enveloppen","note":"één die groot genoeg is voor de kaart"},{"id":"stickers","note":"een grote sticker als ‘postzegel’"},{"id":"potlood","note":"of pen, voor het adres en de tekst (dat doe jij)"}],"optional":[{"id":"tijdschriften","note":"om plaatjes uit te knippen"},{"id":"lijmstift"},{"id":"gekleurd-papier"}],"steps":["Vouw een stuk karton of stevig papier dubbel tot een kaart die in de envelop past.","Laat je kind de voorkant tekenen, kleuren of beplakken met plaatjes.","Vraag wat je kind tegen opa en oma wil zeggen en schrijf het binnenin op, precies zoals je kind het zegt. Je kind zet er een krabbel onder.","Versier samen de envelop met stickers en tekeningen; een sticker rechtsboven is de postzegel.","Schrijf het adres erop (dat doe jij) en plak er een echte postzegel op, of geef de post de volgende keer zelf aan opa en oma.","Loop samen naar de brievenbus en laat je kind de envelop erin doen. Over een paar dagen ligt hij bij opa en oma op de mat!"],"ageTips":{"young":"Voor een tweejarige is krassen en stickers plakken genoeg; schrijf jij op wat je peuter over de tekening vertelt. Laat je peuter de envelop zelf in de brievenbus duwen.","old":"Laat je kleuter de eigen naam schrijven of naschrijven, ‘opa’ en ‘oma’ op de envelop zetten en een vraag bedenken, zodat er ook post terugkomt."},"safety":["Geef je kind op weg naar de brievenbus een hand bij de stoep en bij het oversteken.","Het klepje van een brievenbus kan op kleine vingers dichtklappen: houd jij het open terwijl je kind de post erin laat vallen."],"say":["Wat wil je tegen opa en oma zeggen?","Plak! De postzegel zit erop.","Je hebt heel lang en geconcentreerd aan je tekening gewerkt.","Wat denk je dat oma zegt als ze de envelop openmaakt?","Hoe komt de brief eigenlijk bij opa en oma, denk je?"],"words":["kaart","envelop","postzegel","brievenbus","adres","versturen","opa","oma"],"learn":["taal","fijne-motoriek","creativiteit"],"tips":["Maak meteen een paar kaarten en bewaar ze voor verjaardagen of als bedankje.","Vraag opa en oma om terug te schrijven: zelf post krijgen is voor een kind net zo spannend als versturen."],"extenders":["Doe er een kleine verrassing bij: een getekende handomtrek, een geknipt hartje of een plat geperst blaadje.","Ontwerp een eigen postzegel: teken op een klein vierkantje een plaatje en plak het naast de echte postzegel.","Maak meteen nog een kaart voor iemand anders, zoals de buren, de juf of een vriendje."],"variations":["Kerst: een kerstkaart met een boom van gescheurde groene papiertjes en sterren van stickers.","Verjaardag: een kaart met een taart en papieren kaarsjes die je kind telt en opplakt.","Thuispostbode: maak een brievenbus van een schoenendoos en stuur elkaar in huis briefjes en tekeningen.","Ver weg: maak een foto van de kaart en stuur die alvast vooruit; de echte post komt een paar dagen later."],"themes":["cadeau","kerst","verjaardag"],"canStay":false,"pinQuery":"kaartje maken opa oma peuter"},
  {"id":"sinterklaasmijter","title":"Mijter en staf voor Sinterklaas","emoji":"🎁","category":"fantasie","summary":"Knip een rode mijter met een geel kruis en maak een glimmende staf van kokers en folie: zo speel je zelf Sinterklaas.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,30],"supervision":1,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"gekleurd-papier","note":"rood voor de mijter (een A4’tje) en geel voor het kruis en de hoofdband"},{"id":"lijmstift"},{"id":"nietmachine","note":"om de band op maat te maken (dat doe jij)"},{"id":"wc-rollen","note":"2-3 keukenrolkokers voor de staf"},{"id":"aluminiumfolie"},{"id":"plakband"}],"optional":[{"id":"karton","note":"om achter de mijter te plakken als hij slap is"},{"id":"stickers","note":"als juwelen"},{"id":"kinderschaar"}],"steps":["Knip van geel papier een strook van ±5 cm breed die om het hoofd van je kind past, plus 3 cm extra.","Teken op rood papier een mijter van ±20 cm breed en ±28 cm hoog, met een punt bovenin. Knip hem uit (dat doe jij).","Laat je kind een kruis van twee gele stroken op de mijter plakken en versieren met stickers of platgedrukte propjes folie.","Zet de mijter met twee nietjes op de gele band, maak de band op maat en plak de nietjes aan de binnenkant af.","Plak 2-3 keukenrolkokers met plakband achter elkaar tot een lange staf en wikkel die samen met je kind in aluminiumfolie.","Draai een sliert folie tot een dikke slang, buig er een krul van en plak die bovenop de staf.","Zet de mijter op, pak de staf en zing samen een sinterklaasliedje."],"ageTips":{"young":"Voor een tweejarige knip jij alles vooraf. Het kruis opplakken en folie om de staf frommelen kan je peuter zelf; benoem samen rood, geel en glimmend.","old":"Laat je kleuter de mijter zelf natekenen en knippen, en speel daarna Sinterklaas met een groot boek: wat staat er over jou in het boek van de Sint?"},"safety":["Zet de nietjes met de gladde kant naar binnen en plak ze af, zodat er niets in het voorhoofd prikt.","Losse propjes folie en stickers zijn klein voor een tweejarige: plak ze stevig vast en ruim losse stukjes op. Alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Rood en geel! Plak!","Hoe hoog wordt jouw mijter? Hoger dan je hoofd?","Kijk, de staf glimt als het licht erop valt.","Je hebt de folie helemaal om de staf gewikkeld, zonder op te geven.","Wat zou Sinterklaas allemaal in zijn grote boek schrijven?"],"words":["mijter","staf","krul","kruis","rood","geel","glimmen","Sinterklaas"],"learn":["fijne-motoriek","creativiteit","taal"],"tips":["Geen rood papier? Kleur een wit vel helemaal rood met waskrijt; dat is meteen een mooie klus voor je kind.","Plak een stuk karton achter de mijter als hij slap wordt: dan blijft hij mooi rechtop staan."],"extenders":["Knip een baard van een papieren bordje met franje aan de onderkant, en houd hem met een ijsstokje voor de kin.","Speel schoen zetten: zet een schoen bij de bank, en je kind stopt er als Sint stiekem een tekening of een knuffeltje in.","Bouw een stoomboot van een doos of wasmand en laat de Sint met mijter en staf aankomen terwijl jullie ‘Zie ginds komt de stoomboot’ zingen."],"variations":["Pietenmuts: een platte muts van een papieren bordje met een veertje erop.","Sinterklaasavond: maak voor iedereen in huis een mijter en loop op sinterklaasliedjes een optocht door de kamer.","Het grote boek: maak een boek van gevouwen papier met een rode kaft en schrijf er samen in wat je kind goed kan."],"themes":["sinterklaas"],"canStay":false,"pinQuery":"sinterklaas mijter knutselen peuter"},
  {"id":"krantenhoed","title":"Krantenhoed vouwen","emoji":"📰","category":"fantasie","summary":"Vouw samen van één krantenpagina een klassieke hoed, versier hem met stickers en stift en houd een optocht door de kamer.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[10,20],"supervision":1,"soloFrom":5,"cleanupMinutes":2,"noise":2,"energy":1,"places":["tafel"],"materials":[{"id":"kranten","note":"één losse pagina per hoed"},{"id":"plakband"},{"id":"stickers"},{"id":"stiften"}],"optional":[{"id":"veren","note":"als pluim"},{"id":"crepepapier","note":"stroken als pluim of lint"},{"id":"gekleurd-papier"}],"steps":["Leg een krantenpagina neer en vouw hem doormidden, met de vouw bovenaan. Hij is nu ongeveer 30 cm breed.","Vouw de twee bovenhoeken schuin naar beneden, tot ze in het midden tegen elkaar komen. Onderaan blijft een rand over.","Vouw de onderrand aan de voorkant omhoog over de driehoeken. Draai de hoed om en doe hetzelfde aan de achterkant.","Vouw de uitstekende hoekjes van de rand om en plak ze vast met plakband.","Laat je kind de hoed versieren met stickers, stift en een pluim van een veer of crêpepapier.","Doe de hoed open, zet hem op en houd een optocht door de kamer op muziek."],"ageTips":{"young":"Bij een driejarige vouw jij en strijkt je peuter elke vouw plat met de hand, als een strijkijzer. Versieren is voor je peuter het echte werk.","old":"Laat je kleuter meevouwen op een eigen vel: jij doet elke stap voor, je kleuter doet hem na. Tel daarna samen de driehoeken in de hoed."},"safety":["Zakt de hoed over de ogen, dan ziet je kind de tafelrand of de trap niet: maak hem kleiner met een extra vouw of een stukje plakband aan de achterkant.","Drukinkt geeft wat af: laat je kind niet op de krant sabbelen en was na afloop de handen."],"say":["Eerst de hoekjes naar het midden. Strijk je mee?","Kijk, er komt een driehoek!","Je vouwt heel precies, de randjes liggen netjes op elkaar.","Wat voor hoed wordt het: van een soldaat, een piraat of een koning?","Hoed op! Optocht!"],"words":["vouwen","hoek","driehoek","rand","omdraaien","plat","hoed","optocht"],"learn":["fijne-motoriek","rekenen","concentratie"],"tips":["Is je krant groot? Knip de pagina eerst bij tot ongeveer 30 bij 40 cm, anders zakt de hoed over de schouders.","Pakpapier of een groot vel tekenpapier werkt ook en geeft geen inkt af."],"extenders":["Vouw kleine hoedjes van een halve krantenpagina voor de knuffels en zet ze op een rij voor de optocht.","Zing samen ‘Een hoedje van papier’ en zet bij elk ‘hoedje’ de hoed op en weer af.","Open een hoedenwinkel: zet de hoeden op omgekeerde bekers en laat je kind ze aan jou verkopen en passen."],"variations":["Koningsdag: oranje stickers en een pluim van oranje crêpepapier.","Carnaval: maak er een piratenhoed van met een doodshoofd van wit papier, of een soldatenhoed met een veer.","Bootje: met een paar extra vouwen wordt de hoed een bootje dat even in bad kan varen.","Verjaardag: vouw voor elk kind op het feestje een hoed en laat iedereen een eigen hoed versieren."],"themes":["carnaval","koningsdag"],"canStay":false,"pinQuery":"krantenhoed vouwen kind"},
  {"id":"verrekijker-safari","title":"Verrekijker maken en op safari in huis","emoji":"🦒","category":"fantasie","summary":"Plak twee wc-rolletjes aan elkaar tot een verrekijker en ga op safari: welke dieren zitten er verstopt achter de bank of onder de tafel?","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":10,"duration":[15,30],"supervision":2,"soloFrom":3,"cleanupMinutes":2,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"wc-rollen","note":"twee per verrekijker"},{"id":"plakband","note":"of schilderstape"},{"id":"stiften","note":"of stickers, om te versieren"},{"id":"knuffels","note":"of grote speelgoeddieren, 5-10 stuks om te verstoppen"}],"optional":[{"id":"gekleurd-papier","note":"om de rolletjes mee te beplakken"},{"id":"lijmstift"},{"id":"touw","note":"voor een kort koordje (alleen voor kleuters)"},{"id":"perforator","note":"voor de gaatjes van het koordje"},{"id":"wasmand","note":"als dierentuin voor de gevonden dieren"}],"steps":["Leg twee wc-rolletjes naast elkaar en plak ze stevig aan elkaar met een paar stroken plakband.","Laat je kind de verrekijker versieren met stift, stickers of gekleurd papier.","Verstop intussen 5-10 knuffels of speelgoeddieren in de kamer, half zichtbaar en op de hoogte van je kind.","Ga op safari: sluip door de kamer en kijk door de verrekijker. Wat zie je?","Zeg hardop wat je vindt en waar: een leeuw achter de bank, een beer onder de tafel!","Breng elk gevonden dier naar de dierentuin, zoals een mand of doos, en tel ze aan het eind samen."],"ageTips":{"young":"Verstop voor je tweejarige drie grote knuffels die half te zien zijn, en zoek samen. Laat het koordje weg en benoem de plek: achter, onder, op.","old":"Teken samen een schatkaart van de kamer met kruisjes, of geef aanwijzingen: de olifant zit onder iets zachts. Daarna verstopt je kleuter de dieren voor jou."},"safety":["Een koordje om de nek is een wurggevaar: laat het weg bij een tweejarige, houd het kort voor kleuters en doe de kijker af bij klimmen en slapen.","Verstop niets bij stopcontacten, medicijnen of schoonmaakmiddelen, en niet zo hoog dat je kind moet klimmen.","Speelgoeddiertjes die door een wc-rolletje passen, zijn te klein voor kinderen onder de 3: kies grote knuffels als je peuter meezoekt."],"say":["Ik zie, ik zie… iets met lange oren!","Waar zou de olifant zich verstopt hebben?","Sst… sluipen!","Je blijft zoeken tot je hem vindt. Wat ben jij een goede speurder.","Hoeveel dieren hebben we al gevonden?"],"words":["zoeken","sluipen","verstopt","achter","onder","bovenop","dichtbij","ver weg"],"learn":["taal","grove-motoriek","rekenen","fijne-motoriek"],"tips":["Speel het daarna andersom: je kind verstopt en jij zoekt. Peuters verstoppen vaak steeds op dezelfde plek, en dat is precies goed.","Bewaar de verrekijker bij het raam: zo kijk je samen naar vogels, wolken en de vuilniswagen."],"extenders":["Help met warm en koud: hoe dichter bij het dier, hoe warmer. Gloeiend heet!","Verstop de dieren een tweede keer, maar nu lastiger: alleen een staartje zichtbaar onder een kussen of achter het gordijn.","Doe zachtjes het geluid van een verstopt dier na: kan je kind het op het geluid vinden?"],"variations":["Vogelsafari: kijk door het raam naar vogels en tel hoeveel je er ziet.","Nachtsafari: maak de kamer donker en zoek de dieren met een zaklamp.","Kleurensafari: zoek alleen dingen in één kleur, bijvoorbeeld alles wat groen is.","Herfst: verstop dennenappels en bladeren voor een eekhoornsafari."],"themes":[],"canStay":false,"pinQuery":"verrekijker wc rollen knutselen"},
  {"id":"knuffelpicknick","title":"Theevisite en picknick voor de knuffels","emoji":"☕","category":"fantasie","summary":"Spreid een kleed uit, zet de knuffels in een kring en schenk ‘thee’ van water: je kind geeft het gezelligste feestje van de dag.","ageMin":2,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":3,"duration":[20,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"knuffels","note":"3-6 gasten: knuffels of poppen"},{"id":"oud-laken","note":"of een tafelzeil als picknickkleed: dat mag nat worden"},{"id":"kinderservies","note":"een bordje en bekertje per gast, plus een theepotje of klein kannetje"},{"id":"water","note":"koud kraanwater als ‘thee’, steeds een half glas (±100 ml)"},{"id":"koekjes","note":"of rijstwafels, in stukjes gebroken"}],"optional":[{"id":"ontbijtgranen","note":"ontbijtringetjes om te verdelen en te tellen"},{"id":"papier","note":"voor uitnodigingen"},{"id":"stiften"},{"id":"kom","note":"met een laagje water als afwasteiltje"},{"id":"sponsjes","note":"voor de afwas"},{"id":"handdoek","note":"een theedoek om af te drogen"}],"steps":["Leg een oud laken of tafelzeil op de vloer als picknickkleed en zet de knuffels en poppen er in een kring omheen.","Laat je kind dekken: een bordje en een bekertje voor elke gast. Tel samen of er genoeg zijn.","Doe koud water in het theepotje of kannetje, niet meer dan een half glas (±100 ml): dat is de thee. Is het op, dan komt je kind bij jou bijvullen.","Laat je kind inschenken en de koekjes verdelen: één voor beer, één voor pop… en eentje voor jou?","Kom op visite: klop aan, vraag om thee met suiker en praat over wat de knuffels vandaag allemaal hebben gedaan.","Doe na afloop samen de afwas in een kom met een laagje water, droog af met een theedoek en dweil gemorste thee meteen op."],"ageTips":{"young":"Een tweejarige vindt inschenken en uitdelen het allerleukst. Kies twee of drie gasten, doe maar een heel klein beetje water in het kannetje en benoem wat je kind doet: schenken, vol, op!","old":"Laat je kleuter eerst uitnodigingen tekenen en rondbrengen, naamkaartjes neerleggen en een menu bedenken. Wie zit naast wie, en wie wil er nog een kopje?"},"safety":["Schenk alleen koud kraanwater als thee, nooit echte thee of water uit de waterkoker: een omgestoten kopje heet water geeft al een ernstige brandwond.","Laat je kind zitten tijdens het eten en drinken: rondlopen, rennen of liggen met een koekje in de mond geeft kans op verslikken.","Gemorst water maakt een harde vloer glad: houd de picknick op het laken of tafelzeil en dweil natte plekken meteen op.","Speelt er een vriendje of vriendinnetje mee? Vraag dan eerst naar allergieën (gluten, melk, ei, noten) voordat je koekjes uitdeelt."],"say":["Wil je nog een kopje thee, beer?","Schenken… stop! Vol!","Hoeveel koekjes hebben we nodig voor alle gasten?","Wat schenk je voorzichtig in: er gaat bijna niets naast.","Waar zouden de knuffels het over hebben, denk je?"],"words":["inschenken","vol","leeg","kopje","proost","alsjeblieft","dankjewel","genoeg"],"learn":["taal","samen","fijne-motoriek","rekenen"],"tips":["Moet je koken? Leg het picknickkleed in de keuken of vlak bij je neer: dan komt je kind bij jou bijvullen en blijf jij in de buurt.","Breek koekjes in stukjes of gebruik ontbijtringetjes: dan is er genoeg om eerlijk te verdelen, zonder dat je kind de hele trommel leegeet."],"extenders":["Laat een nieuwe gast aanbellen: jij komt met een knuffel die nog niet aan de beurt was, en er moeten een extra bordje en bekertje bij.","Geef elke knuffel een eigen wens: beer wil twee koekjes, konijn alleen water en pop thee met melk. Weet je kind nog wie wat wilde?","Maak er een verjaardag van: de pop is jarig, zing een liedje en pak een blokje in als cadeautje.","Laat je kind uitnodigingen tekenen en bij alle knuffels in huis bezorgen: wie komt er nog meer op het feest?","Verhuis de picknick naar het ‘bos’ onder de tafel: alles moet worden ingepakt, meegedragen en opnieuw gedekt."],"variations":["Zomer: een strandpicknick op een badlaken, met zonnebrillen en zonnehoedjes voor de knuffels.","Koningsdag: een oranje theefeest met een oranje kleed, oranje bekertjes en een papieren kroon voor de koningsknuffel.","Kampeerpicknick: in de hut onder de tafel, met een zaklamp als kampvuur.","Ontbijt op bed: breng de knuffels hun ontbijt in bed, op een dienblad met een bordje en een bekertje."],"themes":[],"canStay":false,"pinQuery":"picknick met knuffels peuter"},
  {"id":"knuffelklas","title":"Juf of meester spelen voor de knuffels","emoji":"🏫","category":"fantasie","summary":"Zet de knuffels in de klas, plak een papieren schoolbord op de deur en laat je kind lesgeven: namen afroepen, kring, tekenen en voorlezen.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":4,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":2,"noise":2,"energy":2,"places":["muur","vloer"],"materials":[{"id":"knuffels","note":"4-8 leerlingen, eventueel aangevuld met poppen"},{"id":"groot-papier","note":"een groot vel of een stuk oud behang als schoolbord"},{"id":"schilderstape","note":"om het bord op een deur of muur te plakken"},{"id":"stiften","note":"afwasbare stiften of waskrijt"},{"id":"boeken","note":"een paar prentenboeken om voor te lezen"}],"optional":[{"id":"dekens","note":"kussens als zitplekken in de kring"},{"id":"papier","note":"voor werkjes en huiswerk"},{"id":"stickers","note":"als beloning voor goed werk"},{"id":"pan","note":"een pannendeksel en een houten lepel als schoolbel"},{"id":"fruit","note":"voor het fruitmoment in de kring"}],"steps":["Plak een groot vel papier met schilderstape op een deur of muur, op de hoogte van je kind: dat is het schoolbord.","Zet de knuffels in een kring op kussens of in een rij tegen de bank, en geef samen elke leerling een naam.","Laat je kind de schoolbel luiden met een pannendeksel en een houten lepel, en de namen afroepen. Jij doet de stemmen: ja juf, ja meester!","Begin met de kring: je kind vraagt elke knuffel wat die gisteren heeft gedaan, en jij antwoordt met een knuffelstem.","Ga naar het bord: je kind geeft les met rondjes en strepen, cijfers of letters. Laat een knuffel naar voren komen om het ook te proberen.","Lees samen een prentenboek voor aan de klas: je kind laat de plaatjes zien, jij doet de knuffels die antwoord geven. Daarna is het speelkwartier!","Sluit de schooldag af met de bel, zwaai de leerlingen uit en laat het lokaal staan voor morgen."],"ageTips":{"young":"Een driejarige speelt vooral na wat er op de opvang of peuterspeelzaal gebeurt: liedjes, fruit eten, handen wassen. Wees zelf eerst de juf of meester en wissel dan van rol. Twee of drie knuffels zijn genoeg.","old":"Laat je kleuter een dagritme tekenen met plaatjes (kring, werken, buiten spelen, eten) en zich eraan houden. Of laat elke leerling om de beurt iets vertellen, en houd met streepjes bij wie al aan de beurt was."},"safety":["Gymles in de klas? Over kussens springen en rollen op de vloer mag, springen van de bank, de tafel of de trap niet.","Stiftdoppen zijn klein: laat je kind er niet op kauwen en ruim ze op als er een broertje of zusje onder de 3 rondloopt."],"say":["Goedemorgen, klas! Is iedereen er?","Ja juf! Ja meester!","Wat ga je de knuffels vandaag leren?","Konijn steekt een poot op. Wat zou konijn willen vragen?","Wat leg je dat geduldig uit: nu snapt beer het ook!"],"words":["juf","meester","klas","kring","beurt","vinger opsteken","luisteren","schoolbord"],"learn":["taal","samen","creativiteit"],"tips":["Fijn als voorbereiding op de basisschool: speel samen na hoe het afscheid nemen, de kring en het ophalen gaan.","Geen groot papier? Plak een opengevouwen doos op de deur, of gebruik de achterkant van oud behang."],"extenders":["Geef een gymles: alle knuffels moeten huppelen, rollen en over een kussen springen, en de juf of meester doet het voor.","Laat de klas een werkje maken: je kind tekent voor elke knuffel een vel en kijkt alles daarna na met een krul of sticker.","Breng een nieuwe leerling: jij komt met een verlegen knuffel die de klas nog niet kent. Hoe helpt de juf of meester?","Kom als ouder op een tienminutengesprek: vraag hoe het met beer gaat en wat beer deze week heeft geleerd.","Speel een verjaardag in de klas: een knuffel trakteert, de klas zingt en de jarige krijgt een kroon van papier."],"variations":["Muziekles: pannen, deksels en rammelaars voor iedereen, met de juf of meester als dirigent.","Zwemles: de knuffels zwemmen baantjes op een blauwe handdoek en krijgen een diploma van papier.","Sinterklaas: de klas oefent sinterklaasliedjes, maakt een tekening voor de Sint en zet samen de schoen.","Dansschool: zet muziek aan en leer de knuffels een dansje: stap, klap, draai."],"themes":[],"canStay":true,"stayTips":"Laat het bord op de deur hangen en zet de knuffels in een rij tegen de muur, zodat niemand erover struikelt. Morgen begint de les gewoon weer met de bel.","pinQuery":"schooltje spelen met knuffels"},
  {"id":"kapsalon","title":"Kapsalon voor poppen en knuffels","emoji":"💇","category":"fantasie","summary":"Natspuiten, kammen, ‘knippen’ met twee vingers en föhnen met een koker: in deze kapsalon gaat elke klant met een nieuw kapsel naar huis.","ageMin":3,"ageMax":5,"mess":2,"wet":true,"dirty":false,"prepMinutes":4,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":1,"places":["tafel","vloer"],"materials":[{"id":"poppen","note":"liefst met haar dat nat mag, plus een paar knuffels"},{"id":"borstels","note":"een paar haarborstels en kammen, schoongemaakt"},{"id":"plantenspuit","note":"een schone, die nooit schoonmaakmiddel heeft bevat"},{"id":"water","note":"lauw kraanwater voor in de plantenspuit"},{"id":"handdoek","note":"een handdoek onder de stoel en een theedoek als kapmantel"},{"id":"spiegel","note":"een handspiegel of de spiegel in de gang"}],"optional":[{"id":"wc-rollen","note":"een keukenrolkoker als föhn"},{"id":"wasknijpers","note":"als haarspeldjes"},{"id":"elastiekjes","note":"voor staartjes, liever pas voor kleuters"},{"id":"papier","note":"voor een prijslijst en een afsprakenboek"},{"id":"stiften"},{"id":"stoelen","note":"een kappersstoel en een rijtje stoelen als wachtkamer"}],"steps":["Richt de kapsalon in: een stoel of kruk voor de klant, een spiegel ernaast en een handdoek eronder tegen de spetters.","Leg de borstels en kammen klaar en vul de plantenspuit met lauw kraanwater. Spuit eerst samen op je hand: zo voelt het.","Laat de eerste klant plaatsnemen, sla een theedoek om als kapmantel en vraag: wat mag het vandaag zijn?","Laat je kind het haar natspuiten, kammen en borstelen, en knippen met twee vingers als schaar: knip, knip!","Föhn samen het haar droog met een keukenrolkoker (brrrrr!) en houd de klant de spiegel voor: tevreden?","Laat de klant afrekenen en een nieuwe afspraak maken, en roep dan de volgende klant uit de wachtkamer.","Zet de natte klanten na afloop op een handdoek te drogen en veeg natte plekken op de vloer meteen op."],"ageTips":{"young":"Een driejarige vindt spuiten en kammen het allerleukst: geef één pop met lang haar en één kam, en laat de rest nog even weg. Laat je kind eerst op een handdoek oefenen met spuiten.","old":"Laat je kleuter een prijslijst tekenen (kammen 1 munt, föhnen 2 munten), een afsprakenboek bijhouden en vlechten proberen: drie strengen, om en om over elkaar."},"safety":["Leg alle scharen weg en spreek af dat er in deze kapsalon alleen met twee vingers wordt geknipt: kinderen knippen anders zo een pluk haar uit een pop, bij zichzelf of bij een broertje of zusje.","Gebruik een plantenspuit die nooit schoonmaakmiddel of plantenvoeding heeft bevat, vul hem alleen met kraanwater en spreek af: niet in gezichten spuiten.","Water op een harde vloer is glad: leg een handdoek onder de kappersstoel en veeg natte plekken meteen op.","Elastiekjes kunnen terugschieten in een oog en zijn klein: gebruik liever wasknijpers als speldjes, en ruim elastiekjes op als er een kind onder de 3 rondloopt."],"say":["Goedemiddag! Wat mag het vandaag zijn?","Spuit, spuit! Nat!","Hoe wil je het haar van pop: kort, lang of met vlechtjes?","Wat kam je voorzichtig: pop zegt niet één keer au.","Hoe voelt het haar nu het nat is? En als het weer droog is?"],"words":["kammen","borstelen","nat","droog","lang","kort","krullen","spiegel"],"learn":["fijne-motoriek","taal","creativiteit","samen"],"tips":["Speel het vlak voor badtijd op de badkamervloer: natte poppen en spetters maken dan niet uit.","Knuffels worden snel muf als ze nat worden: geef ze alleen een paar spuitjes, of kam en föhn ze zonder water."],"extenders":["Kom zelf als klant met een speciale wens: staartjes met wasknijpers, haar dat omhoog staat als een egel of een scheiding in het midden.","Voeg een wasbeurt toe: een kom met een laagje lauw water en een washandje. Daarna moet alles opnieuw gekamd en geföhnd worden.","Zet de knuffels als wachtende klanten op een rij stoelen, elk met een tijdschrift: je kind haalt ze één voor één op. Wie is de volgende?","Open er een nagelsalon naast: lak de nagels van de poppen met een penseel en een beetje water, en blaas ze samen droog."],"variations":["Carnaval: geef de klanten een gek feestkapsel met wasknijpers, een sjaaltje en een papieren kroon.","Trimsalon: de knuffeldieren worden geborsteld, gewassen en krijgen een strik van crêpepapier.","Badkapper: in bad wast en kamt je kind het eigen haar of dat van een badpop, met jou ernaast."],"themes":[],"canStay":false,"pinQuery":"kapper spelen poppen kind"},
  {"id":"postbode","title":"Postbode spelen door het hele huis","emoji":"📬","category":"fantasie","summary":"Plak brievenbussen op de deuren, maak een stapel post en laat je kind bezorgen: elke brief moet naar de bus met hetzelfde plaatje.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["tafel","muur"],"materials":[{"id":"enveloppen","note":"4-5 als brievenbus en een stapel voor de post, of zelf gevouwen"},{"id":"schilderstape","note":"om de brievenbussen op de deuren te plakken"},{"id":"papier","note":"voor brieven en tekeningen"},{"id":"stiften"},{"id":"stickers","note":"als postzegels"},{"id":"stoffen-tas","note":"als postzak"}],"optional":[{"id":"dozen","note":"schoenendozen met een gleuf (die snijd jij) als stevige brievenbus"},{"id":"kranten","note":"om pakjes in te pakken"},{"id":"duplo","note":"blokjes om als pakje te versturen"},{"id":"knuffels","note":"als bewoners die post krijgen"},{"id":"zaklamp","note":"voor de avondronde"}],"steps":["Plak op 4-5 deuren een open envelop met schilderstape, op de hoogte van je kind: de brievenbussen. Een schoenendoos met een gleuf kan ook.","Teken op elke brievenbus wie daar woont: een poppetje bij jouw slaapkamer, een beer bij de knuffels, een vis bij het bad, een pan in de keuken.","Maak samen de post: tekeningen, briefjes en gevouwen kaartjes. Teken op elke brief hetzelfde plaatje als op de bus waar die naartoe moet.","Plak op elke brief een sticker als postzegel en stop alle post in de postzak.","Laat je kind de post rondbrengen: kijk naar het plaatje, zoek de goede deur en doe de brief in de bus. Ding dong, de post is er!","Haal samen de post weer op, maak de brieven open en vertel wat erin staat. Schrijf of teken terug, en de postbode kan weer op pad."],"ageTips":{"young":"Maak voor een driejarige maar drie brievenbussen met heel verschillende plaatjes, zoals een zon, een hart en een auto, en loop de eerste ronde samen. Ook lege enveloppen bezorgen is al feest.","old":"Gebruik letters of cijfers als adres: de eerste letter van elke naam, of huisnummer 1 tot en met 5. Laat je kleuter zelf post maken voor iedereen en een eigen postzegel ontwerpen."},"safety":["Spreek af dat de post alleen binnen wordt bezorgd en hang geen brievenbus aan de voordeur: anders wil de postbode zo naar buiten om ook de buren post te brengen.","Zet het traphekje dicht of laat de route over de trap weg: met een volle postzak kijkt je kind niet goed naar de treden.","Plak de brievenbussen op deuren die openblijven, of op de muur ernaast: een deur die snel dichtgaat, klemt makkelijk kleine vingers."],"say":["Ding dong, de post is er!","Voor wie is deze brief? Welk plaatje zie je?","Post! In de bus!","Wat kijk je goed: elke brief zit in de goede bus.","Wat zou er in deze envelop zitten, denk je?"],"words":["brief","envelop","postzegel","brievenbus","adres","bezorgen","voor jou","openmaken"],"learn":["taal","rekenen","grove-motoriek","samen"],"tips":["Bewaar lege enveloppen en reclamepost in een doos: dan is de postzak altijd vol. Haal echte post met namen en adressen er wel uit.","Moet jij even iets anders doen? Geef je kleuter een volle postzak voor alle kamers: dan is de postbode wel even onderweg."],"extenders":["Stop post zonder plaatje in de zak: de postbode moet aanbellen en vragen of de brief voor die kamer is.","Verstuur pakjes: pak een blokje of een knuffel in krantenpapier in, plak er het goede plaatje op en laat het bezorgen.","Teken opdrachten in de brieven: drie stippen betekent drie keer springen, een hartje betekent beer een kusje geven. De postbode ‘leest’ de brief en doet het.","Open een postkantoor op een stoel: eerst alle post op plaatje sorteren in stapeltjes, pas daarna gaat de postbode op pad.","Maak een avondronde: doe de grote lampen uit en laat de post bezorgen met een zaklamp."],"variations":["Sinterklaas: speel Pietenpost en bezorg verlanglijstjes en tekeningen voor de Sint bij de schoen.","Kerst: maak kerstkaarten voor iedereen in huis en bezorg er in de week voor kerst elke dag eentje.","Pakketbezorger: grote dozen met speelgoed gaan met een wasmand als bestelbus door het huis."],"themes":[],"canStay":true,"stayTips":"Laat de brievenbussen een paar dagen aan de deuren hangen en leg de postzak met papier, enveloppen en stickers op een vaste plek. Dan kan je kind de volgende ochtend zelf weer post rondbrengen.","pinQuery":"postbode spelen brievenbus peuter"},
  {"id":"kantoortje","title":"Kantoortje spelen met een oud toetsenbord","emoji":"💼","category":"fantasie","summary":"Een oud toetsenbord, een stapel papier, enveloppen en stickers: aan een eigen bureau typt je kind brieven, plakt postzegels en neemt de telefoon op.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":5,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["tafel"],"materials":[{"id":"oud-toetsenbord","note":"met het snoer eraf geknipt; een oude rekenmachine of speelgoedtelefoon kan ook"},{"id":"papier","note":"een stapel oud printpapier"},{"id":"enveloppen","note":"oude enveloppen zijn prima"},{"id":"stickers","note":"als postzegels en stempels"},{"id":"potlood","note":"of een paar stiften"},{"id":"plakband"},{"id":"perforator","note":"om gaatjes te maken"}],"optional":[{"id":"wasknijpers","note":"als paperclips"},{"id":"dozen","note":"een schoenendoos als archiefkast"},{"id":"stoffen-tas","note":"als aktetas"},{"id":"schilderstape","note":"voor naambordjes en etiketten"}],"steps":["Richt aan tafel een bureau in: een oud toetsenbord, een stapel papier, enveloppen, een potlood en een bakje met stickers.","Bedenk samen wat voor kantoor het is: een postkantoor, een bank, een reisbureau of jouw eigen werk.","Laat je kind typen op het toetsenbord en brieven schrijven: krabbels, tekeningen of een paar letters die jij voordoet.","Vouw de brieven, stop ze in een envelop en plak er een sticker op als postzegel. Gaatjes maken met de perforator mag ook.","Bel op met de speelgoedtelefoon of je hand als hoorn: jij bent een klant met een vraag, je kind maakt een afspraak en tekent die op.","Berg alles op in het archief, een doos waarin de brieven per kleur of soort komen. Morgen gaat het kantoor weer open."],"ageTips":{"young":"Een driejarige wil vooral echt werk doen zoals jij: typen, stickers plakken en dingen in enveloppen stoppen. Geef een paar grote enveloppen en laat brieven gewoon krabbels zijn.","old":"Laat je kleuter de eigen naam onder elke brief zetten, met turfstreepjes bijhouden wie er heeft gebeld en de post sorteren op kleur of grootte."},"safety":["Knip het snoer van het toetsenbord eraf (dat doe jij) en haal batterijen uit oude rekenmachines en telefoons: vooral knoopcelbatterijen zijn levensgevaarlijk bij inslikken. Gebruik geen oude mobiele telefoon.","Toetsjes van een oud toetsenbord kunnen loskomen en zijn klein: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Houd het toetsenbord weg bij jongere broertjes en zusjes.","De kartelrand van een plakbandhouder is scherp: scheur zelf een paar stukjes af en plak ze alvast op de rand van de tafel."],"say":["Tring tring! Met wie spreek ik?","Tik, tik, tik! Typen maar!","Wat staat er in deze brief? Lees je hem aan mij voor?","Wat werk je geconcentreerd. Is die brief al klaar om te versturen?","Voor wie is deze envelop, en welke postzegel past erbij?"],"words":["typen","brief","envelop","bellen","afspraak","stempel","opbergen","postzegel"],"learn":["fijne-motoriek","taal","creativiteit","concentratie"],"tips":["Veeg een oud toetsenbord eerst af met een vochtig doekje: er zitten vaak veel stof en kruimels in.","Werk je thuis? Zet het kantoortje naast jouw werkplek: jullie werken allebei, en om de zoveel tijd is er samen koffiepauze met een beker water."],"extenders":["Bel op als klant met een opdracht: maak een brief voor beer met drie stickers erop en breng die naar de knuffels.","Bouw een kopieerapparaat van een doos met een gleuf: elke tekening die erin gaat, moet nog een keer worden nagetekend als kopie.","Breng post binnen: oude reclamepost of enveloppen met een tekeningetje erin, die geopend, gelezen en beantwoord moeten worden.","Houd een vergadering: zet de knuffels rond de tafel en laat je kind vertellen wat er vandaag allemaal moet gebeuren."],"variations":["Bank: tel papieren munten en briefjes, stop ze in enveloppen en betaal de knuffels uit.","Reisbureau: knip plaatjes van stranden en bergen uit folders en verkoop reizen met een zelfgetekend kaartje.","Gemeentehuis: maak paspoorten voor alle knuffels, met een tekening en een sticker als stempel.","Sinterklaas: werk op het Pietenkantoor en beantwoord de verlanglijstjes en brieven voor de Sint."],"themes":[],"canStay":true,"stayTips":"Laat het kantoortje op een hoek van de tafel of een eigen tafeltje staan, met alle losse spullen in één doos. Zo gaat het kantoor morgen in een paar tellen weer open.","pinQuery":"kantoortje spelen kind thuis"},
  {"id":"verkleedkist","title":"Verkleedkist en modeshow","emoji":"🎩","category":"fantasie","summary":"Vul een doos met oude kleren, hoeden en tassen, plak een catwalk op de vloer en zet de muziek aan: tijd voor de grote modeshow!","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":5,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"verkleedkleren","note":"oude hemden, een rok, een colbert, hoeden, tassen, handschoenen en een zonnebril"},{"id":"dozen","note":"een grote doos als verkleedkist, of een wasmand"},{"id":"spiegel","note":"een grote spiegel op de hoogte van je kind"},{"id":"muziek","note":"vrolijke muziek voor de modeshow"}],"optional":[{"id":"schilderstape","note":"om een catwalk op de vloer te plakken"},{"id":"zaklamp","note":"als schijnwerper"},{"id":"knuffels","note":"als publiek"},{"id":"stoelen","note":"een rij stoelen voor het publiek"}],"steps":["Doe een stapel verkleedkleren in een grote doos of wasmand: oude hemden, een rok, een colbert, hoeden, tassen, handschoenen en een zonnebril.","Zet een spiegel stevig tegen de muur op de hoogte van je kind en laat je kind de kist ontdekken: wat past er, wat zit er raar?","Help met knopen en ritsen en vraag: wie ben je nu? Een koningin, een brandweerman, een opa op weg naar de markt?","Plak met schilderstape een lange catwalk op de vloer en zet de knuffels en een paar stoelen erlangs als publiek.","Zet de muziek aan: je kind loopt over de catwalk, draait, zwaait en poseert. Jij bent de presentator: en daar komt… de piraat!","Ruim samen op: alles terug in de kist, de hoeden bovenop. Geef de kist een vaste plek, dan kan het morgen weer."],"ageTips":{"young":"Een tweejarige vindt hoeden, tassen en grote schoenen het leukst: makkelijk aan en uit, en meteen te zien in de spiegel. Laat lastige knopen en ritsen nog weg en speel kiekeboe met een hoed.","old":"Laat je kleuter een outfit samenstellen bij een opdracht (iets voor de regen, iets voor een feest, alles in één kleur) en de presentatie zelf doen: wie ben je en waar ga je naartoe?"},"safety":["Haal koorden, riemen, kettingen, stropdassen en lange sjaals uit de kist: om de nek is dat wurggevaar, zeker als je kind alleen speelt.","Lange rokken, grote schoenen en hakken geven struikelgevaar: rol te lange pijpen op en loop met grote schoenen niet de trap op of af.","Zet een losse spiegel stevig vast of gebruik een spiegel die aan de muur hangt: een omvallende spiegel kan breken.","Speelt er een tweejarige mee? Haal kleren met losse kraaltjes, pailletten of knoopjes eruit: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3."],"say":["Wie ben jij vandaag?","Hoed op! Hoed af!","En daar komt… de koningin van de woonkamer!","Wat heb je goed bedacht: een regenjas met een zonnebril, voor als de zon gaat schijnen.","Hoe loopt een piraat? En hoe loopt een opa met een zware tas?"],"words":["hoed","jas","groot","klein","aantrekken","uittrekken","spiegel","draaien"],"learn":["creativiteit","taal","fijne-motoriek","grove-motoriek"],"tips":["Nog geen verkleedkist? Pak gewoon wat uit je eigen kast: een colbert, een hoed, een grote tas en oude schoenen zijn altijd favoriet. De kringloopwinkel vult de rest goedkoop aan.","Pak niet alles tegelijk uit: houd de helft achter en ruil na een paar weken om, dan voelt de kist weer nieuw."],"extenders":["Geef een opdracht voor de volgende ronde: iets roods, iets voor de regen of iets voor op een feestje.","Draai de rollen om: je kind kleedt jou of een knuffel aan, en jij loopt over de catwalk.","Doe het licht uit en gebruik een zaklamp als schijnwerper: elk model krijgt applaus van het publiek.","Laat bij elke outfit een kort toneelstukje spelen: waar ga je naartoe in deze kleren? Speel dat stukje samen na.","Speel snel-verkleden: hoeveel dingen trek je aan voordat de muziek stopt? En hoe snel is alles weer uit?"],"variations":["Carnaval: kies samen een kostuum uit de kist, maak er een kroon of masker bij en houd een optocht door de kamer.","Beroepenkist: alleen kleren voor beroepen, zoals een schort voor de bakker, een helm voor de bouwvakker en een witte blouse voor de dokter.","Weerkist: kleren voor elk weer. Jij roept het weerbericht (regen! zon! sneeuw!) en je kind kleedt zich snel om.","Toneelvoorstelling: de modeshow wordt een toneelstuk, met een laken over twee stoelen als gordijn."],"themes":["carnaval"],"canStay":true,"stayTips":"Geef de kist een vaste plek met de spiegel ernaast, dan kan je kind er zelf weer in duiken. Haal de catwalk van tape na een paar dagen van de vloer, dan laat de tape nog makkelijk los.","pinQuery":"verkleedhoek verkleedkist peuter"},
  {"id":"wasmandboot","title":"Op reis in de wasmandboot","emoji":"🚢","category":"fantasie","summary":"Een lege wasmand op een deken wordt een boot op zee: knuffels aan boord, reistas mee, en wie roept als eerste ‘land in zicht’?","ageMin":2,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":2,"places":["vloer"],"materials":[{"id":"wasmand","note":"een stevige, lege wasmand of een grote doos als boot"},{"id":"dekens","note":"een (blauwe) deken als zee, een laken voor de golven en een paar kussens als eilanden"},{"id":"knuffels","note":"als passagiers en bemanning"}],"optional":[{"id":"wc-rollen","note":"als verrekijker"},{"id":"stoffen-tas","note":"als reistas"},{"id":"vergiet","note":"om vissen uit de zee te scheppen"},{"id":"sokken","note":"opgerold als vissen"},{"id":"papier","note":"voor een schatkaart"},{"id":"stiften"},{"id":"zaklamp","note":"als vuurtoren"}],"steps":["Leg een grote, liefst blauwe deken op de vloer: dat is de zee. Zet een lege wasmand of grote doos in het midden: de boot.","Laat je kind de passagiers kiezen en een reistas inpakken: welke knuffels mogen mee, en wat neem je mee op reis?","Laat je kind instappen, haal samen het anker op en vaar weg. Vertel het reisverhaal: de zon schijnt, de meeuwen krijsen, daar springt een dolfijn!","Maak golven door de mand zachtjes heen en weer te wiegen en met een laken langs de boot te wapperen. Storm op zee: houd je goed vast!","Leg kussens neer als eilanden en roep: land in zicht! Laat je kind aan land gaan en ontdekken wie er op het eiland woont.","Vaar terug naar huis, meer aan bij de bank en laat de boot liggen voor de volgende reis."],"ageTips":{"young":"Een tweejarige vindt in- en uitstappen, wiegen en kiekeboe over de rand al een hele reis. Houd het verhaal kort (zon, golf, vis!) en neem één lievelingsknuffel mee.","old":"Laat je kleuter de kapitein zijn: een schatkaart tekenen, de koers bepalen en een logboek bijhouden met tekeningetjes van alles wat jullie onderweg tegenkomen."},"safety":["Duw of trek je de boot met je kind erin? Doe dat langzaam over vloerbedekking of een kleed, en nooit in de buurt van de trap: een kantelende mand geeft een harde val.","Kies een stevige mand zonder gebroken randen, want kapot plastic is scherp. Laat je kind niet op de rand staan: dan kiept de mand om.","Leg geen deken of deksel over de mand of doos zolang je kind erin zit.","Leg de kussen-eilanden op een kleed en niet op een gladde vloer: ze schuiven weg als je kind erop springt."],"say":["Land in zicht!","Waar varen we vandaag naartoe?","Golf! Wiebel, wiebel!","Wat stuur je goed door de storm, kapitein.","Wat zie je door je verrekijker? Is het een walvis of een eiland?"],"words":["boot","zee","golf","storm","eiland","kapitein","anker","ver weg"],"learn":["taal","creativiteit","grove-motoriek","samen"],"tips":["Lees vooraf een prentenboek over een boot, de zee of piraten: dan heeft je kind meteen ideeën voor het reisverhaal.","Geen wasmand vrij? Een grote doos, een stevig kussen of de bank is net zo goed een boot."],"extenders":["Verander de reis: de boot wordt een raket naar de maan, een trein naar oma of een duikboot naar de bodem van de zee.","Laat een knuffel overboord vallen: je kind moet de drenkeling redden met een vergiet of door zelf ‘in zee’ te springen.","Ga vissen: gooi opgerolde sokken als vissen in de zee en schep ze op met een vergiet. Tel samen de vangst.","Verstop een schat op een van de eilanden en teken een schatkaart met een kruis: waar moet de kapitein zoeken?","Bouw een haven: blokken als kade, een zaklamp als vuurtoren en een tweede boot voor een knuffel die ook mee wil."],"variations":["Piratenschip: een vlag van een theedoek, een ooglapje van papier en een schat van aluminiumfolie.","Raket: een doos als raket met aftellen (10, 9, 8…) en een landing op een maan van kussens.","Winter: een reis naar de Noordpool, met een witte deken als ijs en ijsberen als passagiers.","Zomer: een vakantiereis met zonnebril en zonnehoed, en een handdoek als strand op het eiland."],"themes":[],"canStay":true,"stayTips":"Laat de boot met de deken-zee een paar dagen in een hoek liggen en schuif hem ’s avonds tegen de muur, zodat niemand erover struikelt. De verrekijker en de reistas blijven gewoon aan boord.","pinQuery":"wasmand boot spelen peuter"},
  {"id":"kookcafe","title":"Soep koken en restaurantje spelen","emoji":"🍲","category":"fantasie","summary":"Roeren in een pan vol droge pasta, opscheppen en opdienen met een menukaart: je kind is de kok van het gezelligste restaurant in huis.","ageMin":2,"ageMax":5,"mess":2,"wet":false,"dirty":false,"prepMinutes":3,"duration":[20,45],"supervision":2,"soloFrom":3,"cleanupMinutes":5,"noise":2,"energy":1,"places":["vloer","tafel"],"materials":[{"id":"pan","note":"een pan met deksel, of twee"},{"id":"lepel","note":"houten lepels en een soeplepel"},{"id":"kom","note":"een paar kommen voor de ingrediënten"},{"id":"pasta","note":"grote soorten, zoals rigatoni of vlinderpasta"},{"id":"kinderservies","note":"bordjes en bekertjes om op te dienen"}],"optional":[{"id":"ontbijtgranen","note":"ontbijtringetjes als ‘erwtjes’"},{"id":"groente","note":"een paar hele aardappelen voor in de soep"},{"id":"duplo","note":"grote blokken als soepballen voor de jongsten"},{"id":"papier","note":"voor een menukaart"},{"id":"stiften"},{"id":"oud-laken","note":"als knoeimat onder het keukentje"},{"id":"knuffels","note":"als gasten"}],"steps":["Zet een keukentje klaar op de vloer of aan tafel, ver van het echte fornuis: een pan, een paar houten lepels, kommen en het speelservies.","Doe de ingrediënten in losse kommen: grote droge pasta, ontbijtringetjes, en voor een jonge peuter hele aardappelen of duploblokken.","Laat je kind soep koken: scheppen, roeren, overdoen en het deksel erop. Pruttel, pruttel!","Teken samen een menukaart met plaatjes, zoals soep, pasta en taart. Ga daarna aan tafel zitten en bestel.","Laat je kind opscheppen en opdienen. Proef net alsof, blaas omdat het heet is en geef de kok een compliment.","Reken af met een papieren muntje en ruim samen op: de pasta gaat terug in een aparte speelpot."],"ageTips":{"young":"Een tweejarige vindt scheppen en overdoen het allerleukst: geef één pan, een grote lepel en grote dingen zoals duploblokken of hele aardappelen. Blijf dichtbij zodra er pasta bij is.","old":"Laat je kleuter een menukaart met prijzen maken, bestellingen opschrijven met tekeningetjes en precies tellen: soep met vijf pasta’s en drie ringetjes, alstublieft!"},"safety":["Droge pasta en ontbijtringetjes passen door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Blijf bij een tweejarige binnen handbereik, of kook alleen met grote dingen.","Zet het speelkeukentje op afstand van het echte fornuis en de oven, en spreek af dat echte pannen op het vuur alleen voor jou zijn.","Ongekookte pasta is hard en niet om te eten: spreek af dat de kok alleen net alsof proeft."],"say":["Pruttel, pruttel! Wat ruikt dat lekker!","Roeren! Rond en rond!","Wat zit er allemaal in deze soep?","Wat schep je zorgvuldig op: er valt bijna niets naast.","Mag ik de soep van de dag, met extra veel pasta?"],"words":["roeren","scheppen","heet","vol","leeg","lekker","bestellen","opdienen"],"learn":["fijne-motoriek","taal","rekenen","samen"],"tips":["Moet jij echt koken? Zet het keukentje op de keukenvloer bij jou in de buurt, maar uit de looproute met hete pannen: dan kookt je kind gewoon mee.","Bewaar de speelpasta in een eigen pot en leg een oud laken onder het keukentje: losgeschoten pasta schud je zo in één keer bij elkaar."],"extenders":["Kom met een moeilijke bestelling: soep met precies drie ringetjes en twee pasta’s, of soep zonder iets ronds.","Zet de knuffels aan tafel, elk met een eigen bestelling: de ober onthoudt alles of tekent het op een briefje.","Geef een zeef of vergiet erbij: zeef de soep tot alleen de grote pasta overblijft, of vis alle ringetjes eruit.","Open een bezorgdienst: de soep gaat in een bakje met deksel naar een knuffel in een andere kamer.","Laat de kok een toetje maken: een taart van een omgekeerde kom met pasta’s als kaarsjes, en zing er een liedje bij."],"variations":["Pannenkoekenhuis: bak pannenkoeken van rondjes karton en draai ze om met een spatel.","Pizzeria: rondjes karton als pizza, met beleg van snippers gekleurd papier.","Herfst: kook een herfstsoep van kastanjes, dennenappels en bladeren. Alleen vanaf 3 jaar: kastanjes zijn klein en niet om te eten.","Sinterklaas: een pepernotenbakkerij met ontbijtringetjes als pepernoten, verkocht per zakje."],"themes":[],"canStay":false,"pinQuery":"restaurantje spelen peuter menukaart"},
  {"id":"bibliotheek-spelen","title":"Bibliotheek spelen met je eigen boeken","emoji":"📚","category":"fantasie","summary":"Sorteer de prentenboeken, maak pasjes voor alle knuffels en open de bieb: je kind leent uit, stempelt met stickers en leest voor in de leeshoek.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":3,"duration":[30,45],"supervision":3,"soloFrom":3,"cleanupMinutes":5,"noise":1,"energy":1,"places":["vloer"],"materials":[{"id":"boeken","note":"10-20 prentenboeken uit de eigen kast"},{"id":"papier","note":"in kleine stukjes, voor bibliotheekpasjes"},{"id":"stiften"},{"id":"stickers","note":"als stempel bij het uitlenen"},{"id":"knuffels","note":"als bezoekers"}],"optional":[{"id":"dekens","note":"kussens en een plaid voor de leeshoek"},{"id":"dozen","note":"als boekenbakken per soort"},{"id":"mandje","note":"als inleverbak"},{"id":"oud-toetsenbord","note":"als computer op de balie"},{"id":"zaklamp","note":"voor een voorleesuurtje in het donker"}],"steps":["Haal samen 10-20 prentenboeken uit de kast en leg ze op de vloer.","Sorteer de boeken: alle dierenboeken bij elkaar, alle boeken met auto’s, of op kleur van de kaft. Zet ze rechtop tegen de bank of in dozen.","Maak bibliotheekpasjes van stukjes papier: een pasje voor elke knuffel en elk gezinslid, met een naam of tekening erop.","Richt de balie in op een krukje of stoel: een vel stickers als stempel en een mandje om boeken in te leveren.","Kom als eerste bezoeker: kies een boek, laat je pasje zien en laat je kind een sticker als stempel geven. Tot volgende week!","Houd een voorleesuurtje in de leeshoek: je kind ‘leest’ een boek voor aan de knuffels, aan de hand van de plaatjes.","Breng aan het eind de geleende boeken terug en laat de bieb staan voor morgen."],"ageTips":{"young":"Sorteer voor een driejarige op iets wat je meteen ziet, zoals dieren of de kleur van de kaft, en houd het bij 8-10 boeken. Stickers plakken op het pasje is al het hoogtepunt.","old":"Laat je kleuter etiketten tekenen voor elke bak (een dier, een auto, een kasteel), de eigen naam op het pasje schrijven en met turfstreepjes bijhouden hoeveel boeken er zijn uitgeleend."},"safety":["Laat je kind geen boeken van hoge planken pakken door te klimmen: zet de bieb op de vloer en maak een boekenkast vast aan de muur, zodat die niet kan omvallen.","Stapel boeken niet hoger dan de knie van je kind: een omvallende stapel zware boeken komt hard op voeten en vingers terecht."],"say":["Sst, in de bieb fluisteren we.","Mag ik dit boek lenen?","Sticker! Klaar!","In welke bak hoort dit boek, denk je?","Wat vertel je dat spannend: de knuffels luisteren allemaal."],"words":["lenen","terugbrengen","pasje","fluisteren","voorlezen","kaft","bladzijde","boekenkast"],"learn":["taal","rekenen","concentratie","samen"],"tips":["Gebruik je eigen boeken en geen echte bibliotheekboeken: stickers en stempels komen er zo op terecht.","Ga ook eens samen naar de echte bibliotheek: daar zie je hoe de balie, de pasjes en het inleveren werken, en voor kinderen is een pasje meestal gratis."],"extenders":["Breng een stapel ingeleverde boeken: je kind zet ze allemaal terug op de goede plek, bij de dieren, de auto’s of de kleuren.","Vraag als bezoeker naar een heel bepaald boek: een boek met een beer, iets geels op de kaft of het dikste boek van de bieb.","Laat een knuffel te laat inleveren: die moet een boete betalen, zoals een liedje zingen of het boek nog één keer laten voorlezen.","Doe de gordijnen dicht en houd een zaklamp-voorleesuurtje: alleen het boek is verlicht.","Laat je kind een eigen boek maken voor de bieb: twee gevouwen vellen met tekeningen en een sticker als bibliotheekcode."],"variations":["Boekwinkel: verkoop de boeken voor papieren munten en pak ze in met een vel krant.","Kinderboekenweek: maak elke dag een andere boekentafel rond het thema van dat jaar.","Winter: een knusse leeshoek in een hut van dekens, met kussens en een zaklamp."],"themes":[],"canStay":true,"stayTips":"Laat de bieb een paar dagen in een hoek staan: boeken rechtop tegen de muur of in dozen, de balie ernaast. Leg ’s avonds losse boeken op een stapel, dan trapt niemand erop en glijdt er niemand over uit.","pinQuery":"bibliotheek spelen thuis kleuter"},
  {"id":"eigen-museum","title":"Mijn eigen museum","emoji":"🏛️","category":"fantasie","summary":"Verzamel schatten uit huis, stal ze uit op een dienblad met kaartjes erbij en open het museum: je kind is de gids die alles uitlegt.","ageMin":3,"ageMax":5,"mess":1,"wet":false,"dirty":false,"prepMinutes":2,"duration":[30,45],"supervision":2,"soloFrom":4,"cleanupMinutes":5,"noise":2,"energy":2,"places":["tafel","vloer"],"materials":[{"id":"dienblad","note":"of een lage plank, de vensterbank of een schoenendoos op z’n kant"},{"id":"klein-speelgoed","note":"lievelingsspeelgoed, autootjes en poppetjes"},{"id":"schelpen","note":"of andere natuurschatten, zoals een mooi blad of een dennenappel"},{"id":"papier","note":"in kleine stukjes, voor naamkaartjes en toegangskaartjes"},{"id":"stiften"}],"optional":[{"id":"steentjes","note":"mooie stenen uit de verzameldoos"},{"id":"dozen","note":"schoenendozen als vitrines"},{"id":"schilderstape","note":"voor een lijn op de vloer: tot hier en niet verder"},{"id":"zaklamp","note":"voor een museumnacht"},{"id":"knuffels","note":"als bezoekers"}],"steps":["Kies samen een plek voor het museum: een dienblad, een lage plank, de vensterbank of een schoenendoos op z’n kant.","Ga op schattenjacht in huis: een lievelingsautootje, een schelp, een mooie steen, een oude tekening. Spreek af waar je kind wel en niet mag zoeken.","Laat je kind de schatten uitstallen: wat komt vooraan, wat hoort bij elkaar? Sorteer bijvoorbeeld op kleur, op soort of op grootte.","Maak bij elke schat een naamkaartje: jij schrijft op wat je kind vertelt (deze schelp komt van het strand bij oma), je kind tekent erbij.","Teken toegangskaartjes en plak een lijn van schilderstape voor het museum: tot hier en niet verder, en niet aankomen!","Open het museum: je kind is de gids en geeft een rondleiding aan jou en de knuffels. Stel vragen als een nieuwsgierige bezoeker."],"ageTips":{"young":"Houd het voor een driejarige bij vijf tot acht schatten. Maak de kaartjes zelf en laat je kind bij de rondleiding vertellen wat elke schat is en waar die vandaan komt.","old":"Laat je kleuter het museum indelen in zalen (dieren, natuur, voertuigen), de kaartjes nummeren en een plattegrond tekenen. Of verkoop toegangskaartjes voor een papieren muntje."},"safety":["Spreek af waar wel gezocht mag worden: niet in de medicijnkast of bij het wasmiddel en de vaatwastabletten, en geen batterijen, magneten of gereedschap in het museum.","Steentjes, schelpjes en klein speelgoed passen vaak door een wc-rolletje: alles wat door een wc-rolletje past, is te klein voor kinderen onder de 3. Zet het museum hoog als er een jonger broertje of zusje is.","Laat breekbare spullen zoals glas en porselein weg: kies samen schatten die tegen een stootje kunnen."],"say":["Welkom in het museum! Mag ik een kaartje?","Wat is dit voor schat? Waar komt die vandaan?","Kijken, niet aankomen!","Wat heb je goed nagedacht over wat bij elkaar hoort.","Wat is de oudste schat in jouw museum, denk je?"],"words":["museum","schat","gids","kaartje","oud","nieuw","bijzonder","tentoonstelling"],"learn":["taal","rekenen","creativiteit","concentratie"],"tips":["Maak een foto van elke opstelling voordat je opruimt: zo groeit er vanzelf een eigen museumboekje.","Ga daarna eens naar een echt museum met een kinderroute: thuis wil je kind dan vaak nog meer gids zijn."],"extenders":["Open een nieuwe zaal: een dierenzaal, een zaal met alleen rode dingen of een zaal voor de allerkleinste schatten.","Haal stiekem één schat weg terwijl de gids de ogen dichtdoet: wat mist er in het museum?","Kom als bezoeker met lastige vragen: wat is het zwaarste ding? En het zachtste? Laat je kind het opzoeken en uitleggen.","Maak een museumwinkel: tekeningen van de schatten als ansichtkaarten, te koop voor één papieren muntje.","Speel museumnacht: lichten uit, en de gids geeft een rondleiding met de zaklamp."],"variations":["Herfstmuseum: kastanjes, eikels, bladeren en dennenappels, van klein naar groot. Kastanjes en eikels zijn niet om te eten.","Dinomuseum: speelgoeddino’s met ‘fossielen’ van afdrukken in speeldeeg en een kaartje bij elke dino.","Kunstmuseum: hang de tekeningen van je kind op met schilderstape en verzin samen bij elk werk een titel.","Zomer: een strandmuseum met schelpen, zand in een potje en vakantiefoto’s."],"themes":[],"canStay":true,"stayTips":"Laat het museum een paar dagen staan op een plek waar het niet in de weg staat, zoals de vensterbank of een plank. Is er een broertje of zusje onder de 3, zet het dan ’s avonds hoog, en open de volgende dag een nieuwe zaal.","pinQuery":"museum spelen thuis kind"},
];
